{"command":"mkdir -p /workspace/src /workspace/tools; cat > /workspace/tools/gen_tables.py <<'EOF'
#!/usr/bin/env python3
"""Generate src/langtab.c from observed reference listings in ref/."""
import os, sys, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
REF = os.path.join(ROOT, 'ref')

def rd(name):
    with open(os.path.join(REF, name), encoding='utf-8') as f:
        return f.read().split('\n')

def cstr(s):
    if s is None:
        return 'NULL'
    out = '"'
    for ch in s:
        if ch == '"': out += '\\"'
        elif ch == '\\': out += '\\\\'
        elif ch == '\n': out += '\\n'
        elif ch == '\t': out += '\\t'
        else: out += ch
    return out + '"'

def cid(s):
    return re.sub(r'[^A-Za-z0-9_]', lambda m: '_%02x' % ord(m.group(0)), s)

# language order from maps.txt
order = []
for line in rd('maps.txt'):
    if not line.strip(): continue
    order.append(line.split(' ')[0])

enabled = {}
for line in rd('languages.txt'):
    if not line.strip(): continue
    if line.endswith(' [disabled]'):
        enabled[line[:-len(' [disabled]')]] = False
    else:
        enabled[line] = True

versions = {}
for line in rd('versions.txt'):
    if not line.strip(): continue
    m = re.match(r'^(\S+) parser/(\S+): (\d+)\.(\d+)', line)
    versions[m.group(1)] = (int(m.group(3)), int(m.group(4)))

# kinds in definition order
kinds_order = {}
cur = None
for line in rd('kinds-order.txt'):
    if not line: continue
    if line.startswith('    '):
        letter = line[4]
        kinds_order[cur].append(letter)
    else:
        cur = line.replace(' [disabled]', '')
        kinds_order[cur] = []

kinds_full = {}
for line in rd('kinds-full.txt'):
    if not line or line.startswith('#'): continue
    lang, letter, name, en, refonly, nroles, master, ver, desc = line.split('\t')
    kinds_full.setdefault(lang, {})[letter] = dict(name=name, enabled=(en=='yes'), refonly=(refonly=='yes'),
                                                   nroles=int(nroles), master=(None if master=='NONE' else master),
                                                   ver=int(ver), desc=desc)

roles = {}
for line in rd('roles.txt'):
    if not line or line.startswith('#'): continue
    lang, kind, name, en, ver, desc = line.split('\t')
    letter = kind.split('/')[0]
    roles.setdefault(lang, {}).setdefault(letter, []).append(dict(name=name, enabled=(en=='on'), ver=int(ver), desc=desc))

fields = {}
for line in rd('fields.txt'):
    if not line or line.startswith('#'): continue
    letter, name, en, lang, jstype, fixed, op, ver, desc = line.split('\t')
    if lang == 'NONE': continue
    fields.setdefault(lang, []).append(dict(name=name, enabled=(en=='yes'), jstype=jstype, op=op, ver=int(ver), desc=desc))

extras = {}
for line in rd('extras.txt'):
    if not line or line.startswith('#'): continue
    letter, name, en, lang, fixed, ver, desc = line.split('\t')
    if lang == 'NONE': continue
    extras.setdefault(lang, []).append(dict(name=name, enabled=(en=='yes'), ver=int(ver), desc=desc))

params = {}
for line in rd('params.txt'):
    if not line or line.startswith('#'): continue
    lang, name, desc = line.split('\t')
    params.setdefault(lang, []).append(dict(name=name, desc=desc))

aliases = {}
for line in rd('aliases.txt'):
    if not line or line.startswith('#'): continue
    lang, alias = line.split('\t')
    aliases.setdefault(lang, []).append(alias)

exts = {}
for line in rd('map-ext.txt'):
    if not line or line.startswith('#'): continue
    m = re.match(r'^(\S+)\s+(\S+)$', line)
    exts.setdefault(m.group(1), []).append(m.group(2))

pats = {}
for line in rd('map-pat.txt'):
    if not line or line.startswith('#'): continue
    m = re.match(r'^(\S+)\s+(\S+)$', line)
    pats.setdefault(m.group(1), []).append(m.group(2))

# maps.txt gives the ordering of extensions+patterns combined per language (as printed)
maps_line = {}
for line in rd('maps.txt'):
    if not line.strip(): continue
    parts = line.split()
    maps_line[parts[0]] = parts[1:]

rexprs = {}
for line in rd('map-rexprs.txt'):
    if not line or line.startswith('#'): continue
    m = re.match(r'^(\S+)\s+(\S+)\s+(\S+)$', line)
    rexprs.setdefault(m.group(1), []).append((m.group(2), m.group(3)=='insensitive'))

subparsers = {}
for line in rd('subparsers.txt'):
    if not line or line.startswith('#'): continue
    name, base, direction = line.split('\t')
    d = {'base <> sub {bidirectional}': 'SUBPARSER_BI', 'base <= sub {dedicated}': 'SUBPARSER_BASE_RUNS_SUB',
         'base => sub {shared}': 'SUBPARSER_SUB_RUNS_BASE'}[direction]
    subparsers.setdefault(name, []).append((base, d))

nulltag = set()
for lang in order:
    p = os.path.join(REF, 'desc', lang + '.txt')
    if os.path.exists(p):
        if 'allow null tags: yes' in open(p).read():
            nulltag.add(lang)

out = []
w = out.append
w('/* Generated by tools/gen_tables.py from observed behaviour. Do not edit. */')
w('#include "lang.h"')
w('')
for lang in order:
    L = cid(lang)
    # roles
    for letter in kinds_order[lang]:
        rl = roles.get(lang, {}).get(letter, [])
        if rl:
            w('static roleDef roles_%s_%s[] = {' % (L, cid(letter)))
            for r in rl:
                w('  { %s, %s, %s, %d },' % (cstr(r['name']), cstr(r['desc']), 'true' if r['enabled'] else 'false', r['ver']))
            w('};')
    if kinds_order[lang]:
        w('static kindDef kinds_%s[] = {' % L)
        for letter in kinds_order[lang]:
            k = kinds_full[lang][letter]
            rl = roles.get(lang, {}).get(letter, [])
            assert len(rl) == k['nroles'], (lang, letter)
            w('  { %s, %s, %s, %s, %s, %d, %s, %s, %d },' % (
                cstr(letter), cstr(k['name']), cstr(k['desc']),
                'true' if k['enabled'] else 'false', 'true' if k['refonly'] else 'false',
                len(rl), ('roles_%s_%s' % (L, cid(letter))) if rl else 'NULL',
                cstr(k['master']), k['ver']))
        w('};')
    if fields.get(lang):
        w('static fieldDef fields_%s[] = {' % L)
        for f in fields[lang]:
            w('  { %s, %s, %s, %s, %s, %d },' % (cstr(f['name']), cstr(f['desc']), 'true' if f['enabled'] else 'false', cstr(f['jstype']), cstr(f['op']), f['ver']))
        w('};')
    if extras.get(lang):
        w('static extraDef extras_%s[] = {' % L)
        for e in extras[lang]:
            w('  { %s, %s, %s, %d },' % (cstr(e['name']), cstr(e['desc']), 'true' if e['enabled'] else 'false', e['ver']))
        w('};')
    if params.get(lang):
        w('static paramDef params_%s[] = {' % L)
        for p in params[lang]:
            w('  { %s, %s },' % (cstr(p['name']), cstr(p['desc'])))
        w('};')
    for kind, tab in (('exts', exts), ('pats', pats), ('aliases', aliases)):
        if tab.get(lang):
            w('static const char *%s_%s[] = { %s, NULL };' % (kind, L, ', '.join(cstr(x) for x in tab[lang])))
    if rexprs.get(lang):
        w('static rexprDef rexprs_%s[] = { %s };' % (L, ', '.join('{ %s, %s }' % (cstr(r), 'true' if ic else 'false') for r, ic in rexprs[lang])))
    if subparsers.get(lang):
        w('static subparserDef subparsers_%s[] = { %s };' % (L, ', '.join('{ %s, %s }' % (cstr(b), d) for b, d in subparsers[lang])))
    w('')

w('langDef LangTable[] = {')
for lang in order:
    L = cid(lang)
    v = versions.get(lang, (0, 0))
    w('  { %s, %s, %d, %d,' % (cstr(lang), 'true' if enabled[lang] else 'false', v[0], v[1]))
    w('    %d, %s,' % (len(kinds_order[lang]), ('kinds_%s' % L) if kinds_order[lang] else 'NULL'))
    w('    %d, %s,' % (len(fields.get(lang, [])), ('fields_%s' % L) if fields.get(lang) else 'NULL'))
    w('    %d, %s,' % (len(extras.get(lang, [])), ('extras_%s' % L) if extras.get(lang) else 'NULL'))
    w('    %d, %s,' % (len(params.get(lang, [])), ('params_%s' % L) if params.get(lang) else 'NULL'))
    w('    %s, %s, %s,' % (('exts_%s' % L) if exts.get(lang) else 'NULL', ('pats_%s' % L) if pats.get(lang) else 'NULL', ('aliases_%s' % L) if aliases.get(lang) else 'NULL'))
    w('    %d, %s,' % (len(rexprs.get(lang, [])), ('rexprs_%s' % L) if rexprs.get(lang) else 'NULL'))
    w('    %d, %s,' % (len(subparsers.get(lang, [])), ('subparsers_%s' % L) if subparsers.get(lang) else 'NULL'))
    w('    %s, NULL },' % ('true' if lang in nulltag else 'false'))
w('};')
w('const int LangTableCount = %d;' % len(order))
w('')
# order of exts/patterns in --list-maps output
w('/* --list-maps order per language */')
w('const char *LangMapsOrder[] = {')
for lang in order:
    w('  %s,' % cstr(' '.join(maps_line[lang])))
w('};')

open(os.path.join(ROOT, 'src', 'langtab.c'), 'w').write('\n'.join(out) + '\n')
print('generated', len(order), 'languages')
EOF
echo ok"}

