void *xcalloc(size_t n, size_t sz) { void *p = calloc(n ? n : 1, sz ? sz : 1); if (!p) error_fatal("out of memory"); return p; }
void *xrealloc(void *p, size_t n) { p = realloc(p, n ? n : 1); if (!p) error_fatal("out of memory"); return p; }
char *xstrdup(const char *s) { size_t n = strlen(s); char *r = xmalloc(n + 1); memcpy(r, s, n + 1); return r; }
char *xstrndup(const char *s, size_t n) { char *r = xmalloc(n + 1); memcpy(r, s, n); r[n] = 0; return r; }
char *xstrupper(const char *s) { char *r = xstrdup(s); for (char *p = r; *p; p++) *p = toupper((unsigned char)*p); return r; }
char *xstrlower(const char *s) { char *r = xstrdup(s); for (char *p = r; *p; p++) *p = tolower((unsigned char)*p); return r; }

vString *vsNew(void) { vString *v = xmalloc(sizeof *v); v->cap = 64; v->len = 0; v->buf = xmalloc(v->cap); v->buf[0] = 0; return v; }
