void vsCatN(vString *v, const char *s, size_t n) { vsEnsure(v, n); memcpy(v->buf + v->len, s, n); v->len += n; v->buf[v->len] = 0; }
void vsCat(vString *v, const char *s) { vsCatN(v, s, strlen(s)); }
void vsCatV(vString *v, const vString *o) { vsCatN(v, o->buf, o->len); }
void vsPrintf(vString *v, const char *fmt, ...) {
