cat > src/read.c <<'EOF'
#include "read.h"
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <sys/stat.h>

inputFile File;

static void computeLineStarts(void) {
    size_t cap = 128, n = 0;
    File.lineStarts = xmalloc(cap * sizeof(size_t));
    File.lineStarts[n++] = 0;
    for (size_t i = 0; i < File.size; i++) {
        if (File.buf[i] == '\n') {
            if (n == cap) { cap *= 2; File.lineStarts = xrealloc(File.lineStarts, cap * sizeof(size_t)); }
            File.lineStarts[n++] = i + 1;
        }
    }
    File.nlines = n;
}

bool openInputFile(const char *fileName, int langIndex, const char *buffer, size_t bufsize) {
    memset(&File, 0, sizeof File);
    File.name = xstrdup(fileName);
    if (buffer) {
        File.buf = xmalloc(bufsize + 1);
        memcpy(File.buf, buffer, bufsize);
        File.size = bufsize;
    } else {
        FILE *fp = fopen(fileName, "rb");
        if (!fp) {
            error_warning_perror("cannot open input file \"%s\"", fileName);
            free(File.name); File.name = NULL;
            return false;
        }
        size_t cap = 65536, n = 0;
        char *buf = xmalloc(cap + 1);
        for (;;) {
            size_t r = fread(buf + n, 1, cap - n, fp);
            n += r;
            if (n == cap) { cap *= 2; buf = xrealloc(buf, cap + 1); }
            if (r == 0) break;
        }
        fclose(fp);
        File.buf = buf;
        File.size = n;
    }
    File.buf[File.size] = 0;
    File.pos = 0;
    File.lineNumber = 0;
    File.newLine = true;
    File.ungetIdx = 0;
    File.langIndex = langIndex;
    File.areaStart = 0;
    File.areaEnd = File.size;
    computeLineStarts();
    return true;
}

void closeInputFile(void) {
    free(File.name); File.name = NULL;
    free(File.buf); File.buf = NULL;
    free(File.lineStarts); File.lineStarts = NULL;
    File.size = 0;
}

static int rawGetc(void) {
    if (File.pos >= File.areaEnd) return EOF;
    return (unsigned char)File.buf[File.pos++];
}

int getcFromInputFile(void) {
    if (File.ungetIdx > 0) return File.ungetBuf[--File.ungetIdx];
    int c;
    for (;;) {
        if (File.newLine) {
            File.newLine = false;
            File.lineNumber++;
        }
        c = rawGetc();
        if (c == EOF) { return EOF; }
        if (c == '\n') { File.newLine = true; return c; }
        if (c == '\r') {
            if (File.pos < File.areaEnd && File.buf[File.pos] == '\n') {
                File.pos++;
                File.newLine = true;
            }
            return '\n';
        }
        return c;
    }
}

void ungetcToInputFile(int c) {
    if (File.ungetIdx < (int)(sizeof File.ungetBuf / sizeof File.ungetBuf[0]))
        File.ungetBuf[File.ungetIdx++] = c;
}

int peekcFromInputFile(void) {
    int c = getcFromInputFile();
    if (c != EOF) ungetcToInputFile(c);
    return c;
}

static vString *lineBuf = NULL;
const unsigned char *readLineFromInputFile(void) {
    if (!lineBuf) lineBuf = vsNew();
    vsClear(lineBuf);
    int c = getcFromInputFile();
    if (c == EOF) return NULL;
    while (c != EOF && c != '\n') {
        vsPut(lineBuf, c);
        c = getcFromInputFile();
    }
    return (const unsigned char *)vsValue(lineBuf);
}

unsigned long getInputLineNumber(void) { return File.lineNumber ? File.lineNumber : 1; }
unsigned long getInputLastLineNumber(void) {
    /* line number of the last line (count lines as ctags does: number of lines incl. partial) */
    return File.nlines ? (File.lineStarts[File.nlines-1] >= File.size && File.nlines > 1 ? File.nlines - 1 : File.nlines) : 1;
}
size_t getInputLineStart(unsigned long line) {
    if (line == 0) line = 1;
    if (line > File.nlines) return File.size;
    return File.lineStarts[line - 1];
}
long getInputFilePosition(void) { return (long)getInputLineStart(getInputLineNumber()); }
long getInputFileOffset(void) { return (long)File.pos - File.ungetIdx; }
const char *getInputFileName(void) { return File.name; }
int getInputLanguage(void) { return File.langIndex; }
void setInputLanguage(int lang) { File.langIndex = lang; }
bool isInputLanguage(int lang) { return File.langIndex == lang; }
const char *getInputFileContents(size_t *size) { if (size) *size = File.size; return File.buf; }

const char *getInputLineRaw(unsigned long line, size_t *len) {
    if (line == 0) line = 1;
    if (line > File.nlines) { if (len) *len = 0; return ""; }
    size_t start = File.lineStarts[line - 1];
    size_t end = (line < File.nlines) ? File.lineStarts[line] : File.size;
    if (end > start && File.buf[end-1] == '\n') end--;
    if (len) *len = end - start;
    return File.buf + start;
}

unsigned long getInputLineNumberForOffset(size_t off) {
    /* binary search */
    size_t lo = 0, hi = File.nlines;
    while (lo + 1 < hi) {
        size_t mid = (lo + hi) / 2;
        if (File.lineStarts[mid] <= off) lo = mid; else hi = mid;
    }
    return lo + 1;
}

void skipToCharacterInInputFile(int c0) {
    int c;
    do { c = getcFromInputFile(); } while (c != EOF && c != c0);
}

void saveInputState(inputState *s) {
    s->pos = File.pos; s->lineNumber = File.lineNumber; s->newLine = File.newLine;
    s->ungetIdx = File.ungetIdx; memcpy(s->ungetBuf, File.ungetBuf, sizeof s->ungetBuf);
    s->areaStart = File.areaStart; s->areaEnd = File.areaEnd; s->langIndex = File.langIndex;
}
void restoreInputState(const inputState *s) {
    File.pos = s->pos; File.lineNumber = s->lineNumber; File.newLine = s->newLine;
    File.ungetIdx = s->ungetIdx; memcpy(File.ungetBuf, s->ungetBuf, sizeof File.ungetBuf);
    File.areaStart = s->areaStart; File.areaEnd = s->areaEnd; File.langIndex = s->langIndex;
}
void setInputArea(size_t start, size_t end) {
    if (end > File.size) end = File.size;
    File.areaStart = start; File.areaEnd = end; File.pos = start;
    File.ungetIdx = 0;
    File.lineNumber = getInputLineNumberForOffset(start);
    File.newLine = false;
}
EOF
echo ok"}

