#include <sys/stat.h>

ptrArray *Langs = NULL;
int CurrentLang = -1;

typedef struct { regex_t re; char *pattern; bool icase; } rexprEntry;
typedef struct { int parentKind; int childKind; char *sep; } scopeSep;

parserObject *getParser(int lang) { return (parserObject *)paItem(Langs, lang); }
langDef *getLangDef(int lang) { return getParser(lang)->def; }

static parserDefinition *findImpl(const char *name) {
    for (int i = 0; ParserImpls[i]; i++)
        if (strcmp(ParserImpls[i]->name, name) == 0) return ParserImpls[i];
    return NULL;
}

static parserObject *newParserObject(langDef *src) {
    parserObject *p = xcalloc(1, sizeof *p);
    p->def = xmalloc(sizeof(langDef));
    *p->def = *src;
    /* copy kinds so they are mutable/growable */
    p->kindsCap = src->nkinds + 8;
    kindDef *kinds = xcalloc(p->kindsCap, sizeof(kindDef));
    for (int i = 0; i < src->nkinds; i++) {
        kinds[i] = src->kinds[i];
        if (kinds[i].nroles) {
            roleDef *r = xmalloc(kinds[i].nroles * sizeof(roleDef));
            memcpy(r, kinds[i].roles, kinds[i].nroles * sizeof(roleDef));
            kinds[i].roles = r;
        }
    }
    p->def->kinds = kinds;
    if (src->nfields) { fieldDef *f = xmalloc(src->nfields * sizeof(fieldDef)); memcpy(f, src->fields, src->nfields * sizeof(fieldDef)); p->def->fields = f; }
    if (src->nextras) { extraDef *e = xmalloc(src->nextras * sizeof(extraDef)); memcpy(e, src->extras, src->nextras * sizeof(extraDef)); p->def->extras = e; }
    p->exts = saNew(); p->pats = saNew(); p->aliases = saNew();
    if (src->exts) for (const char **e = src->exts; *e; e++) saAdd(p->exts, *e);
    if (src->patterns) for (const char **e = src->patterns; *e; e++) saAdd(p->pats, *e);
    if (src->aliases) for (const char **e = src->aliases; *e; e++) saAdd(p->aliases, *e);
    p->rexprs = paNew(NULL);
    for (int i = 0; i < src->nrexprs; i++) {
        rexprEntry *re = xcalloc(1, sizeof *re);
        re->pattern = xstrdup(src->rexprs[i].pattern);
        re->icase = src->rexprs[i].icase;
        regcomp(&re->re, re->pattern, REG_EXTENDED | (re->icase ? REG_ICASE : 0));
        paAdd(p->rexprs, re);
    }
    p->regexPatterns = paNew(NULL);
    p->mlinePatterns = paNew(NULL);
    p->mtables = paNew(NULL);
    p->scopeSeps = paNew(NULL);
    p->paramNames = saNew(); p->paramValues = saNew();
    p->baseLang = -1;
    p->pretendOf = -1;
    return p;
}

void initializeParsing(void) {
    Langs = paNew(NULL);
    for (int i = 0; i < LangTableCount; i++) {
        parserObject *p = newParserObject(&LangTable[i]);
        p->impl = findImpl(p->def->name);
        if (p->impl && p->impl->allowNullTag) p->def->allowNullTag = true;
        paAdd(Langs, p);
    }
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (p->def->nsubparsers) {
            int b = getNamedLanguageFull(p->def->subparsers[0].base, 0, true);
            p->baseLang = b;
        }
    }
}

int getNamedLanguageFull(const char *name, size_t len, bool allowDisabled) {
    (void)allowDisabled;
    if (len == 0) len = strlen(name);
    for (int i = 0; i < LANG_COUNT; i++) {
        const char *n = getLangDef(i)->name;
        if (strlen(n) == len && strncasecmp(n, name, len) == 0) return i;
    }
    return -1;
}
int getNamedLanguage(const char *name, size_t len) { return getNamedLanguageFull(name, len, false); }

const char *getLanguageName(int lang) { return getLangDef(lang)->name; }
const char *getLanguageNameOrNONE(int lang) { return lang >= 0 ? getLangDef(lang)->name : "NONE"; }
bool isLanguageEnabled(int lang) { return getLangDef(lang)->enabled; }
bool isLanguageVisible(int lang) { return true; }
int getBaseLanguage(int lang) { return getParser(lang)->baseLang; }

static bool warnedCargo = false, warnedTOML = false;
static void warnCargo(void) { if (!warnedCargo) { warnedCargo = true; error_warning("Enabling Cargo subparser may enable TOML parser."); } }
static void warnTOML(void) { if (!warnedTOML) { warnedTOML = true; error_warning("The current implementation of the TOML parser is broken."); } }

void enableLanguage(int lang, bool state) {
    langDef *d = getLangDef(lang);
    if (strcmp(d->name, "Cargo") == 0) { if (state) warnCargo(); }
    else if (strcmp(d->name, "TOML") == 0) { if (!state) warnCargo(); warnTOML(); }
    d->enabled = state;
}
void enableLanguages(bool state) {
    for (int i = 0; i < LANG_COUNT; i++) {
        if (strcmp(getLangDef(i)->name, "Unknown") == 0) continue;
        enableLanguage(i, state);
    }
}

int getLanguageKindCount(int lang) { return getLangDef(lang)->nkinds; }
kindDef *getLanguageKind(int lang, int kindIndex) {
    if (kindIndex < 0) return NULL;
    return &getLangDef(lang)->kinds[kindIndex];
}
bool isLanguageKindEnabled(int lang, int kindIndex) {
    kindDef *k = getLanguageKind(lang, kindIndex);
    return k ? k->enabled : false;
}
bool isLanguageRefOnlyKind(int lang, int kindIndex) {
    kindDef *k = getLanguageKind(lang, kindIndex);
    return k ? k->refonly : false;
}
int getKindIndexByLetter(int lang, char letter) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nkinds; i++) if (d->kinds[i].letter[0] == letter) return i;
    return -1;
}
int getKindIndexByName(int lang, const char *name) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nkinds; i++) if (strcmp(d->kinds[i].name, name) == 0) return i;
    return -1;
}
int getRoleIndexByName(int lang, int kindIndex, const char *name) {
    kindDef *k = getLanguageKind(lang, kindIndex);
    if (!k) return -1;
    for (int i = 0; i < k->nroles; i++) if (strcmp(k->roles[i].name, name) == 0) return i;
    return -1;
}
roleDef *getLanguageRole(int lang, int kindIndex, int roleIndex) {
    kindDef *k = getLanguageKind(lang, kindIndex);
    if (!k || roleIndex < 0 || roleIndex >= k->nroles) return NULL;
    return &k->roles[roleIndex];
}
bool isLanguageRoleEnabled(int lang, int kindIndex, int roleIndex) {
    roleDef *r = getLanguageRole(lang, kindIndex, roleIndex);
    return r ? r->enabled : false;
}
int getLangFieldIndexByName(int lang, const char *name) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nfields; i++) if (strcmp(d->fields[i].name, name) == 0) return i;
    return -1;
}
bool isLangFieldEnabled(int lang, int fieldIndex) {
    langDef *d = getLangDef(lang);
    if (fieldIndex < 0 || fieldIndex >= d->nfields) return false;
    return d->fields[fieldIndex].enabled;
}
int getLangExtraIndexByName(int lang, const char *name) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nextras; i++) if (strcmp(d->extras[i].name, name) == 0) return i;
    return -1;
}
bool isLangExtraEnabled(int lang, int extraIndex) {
    langDef *d = getLangDef(lang);
    if (extraIndex < 0 || extraIndex >= d->nextras) return false;
    return d->extras[extraIndex].enabled;
}
bool isXtagEnabled(int xtag) { return Option.extras[xtag]; }
bool isFieldEnabled(int field) { return Option.fields[field]; }
void enableKind(int lang, int kindIndex, bool state) { kindDef *k = getLanguageKind(lang, kindIndex); if (k) k->enabled = state; }
void enableRole(int lang, int kindIndex, int roleIndex, bool state) { roleDef *r = getLanguageRole(lang, kindIndex, roleIndex); if (r) r->enabled = state; }

const char *getLanguageVersionString(int lang) {
    static char buf[32];
    langDef *d = getLangDef(lang);
    snprintf(buf, sizeof buf, "%d.%d", d->verCurrent, d->verAge);
    return buf;
}

/* ---- user defined languages / kinds ---- */
int defineLanguage(const char *name) {
    langDef tmp; memset(&tmp, 0, sizeof tmp);
    tmp.name = xstrdup(name);
    tmp.enabled = true;
    parserObject *p = newParserObject(&tmp);
    p->isUserDefined = true;
    p->impl = NULL;
    paAdd(Langs, p);
    return LANG_COUNT - 1;
}

int defineKind(int lang, char letter, const char *name, const char *desc, bool enabled, bool refonly) {
    parserObject *p = getParser(lang);
    langDef *d = p->def;
    if (d->nkinds + 1 > p->kindsCap) {
        p->kindsCap = p->kindsCap * 2 + 4;
        d->kinds = xrealloc(d->kinds, p->kindsCap * sizeof(kindDef));
    }
    kindDef *k = &d->kinds[d->nkinds];
    memset(k, 0, sizeof *k);
    char *l = xmalloc(2); l[0] = letter; l[1] = 0;
    k->letter = l; k->name = xstrdup(name); k->desc = xstrdup(desc); k->enabled = enabled; k->refonly = refonly;
    return d->nkinds++;
}
int defineField(int lang, const char *name, const char *desc) {
    langDef *d = getLangDef(lang);
    d->fields = xrealloc((void*)d->fields, (d->nfields + 1) * sizeof(fieldDef));
    fieldDef *f = &d->fields[d->nfields];
    f->name = xstrdup(name); f->desc = xstrdup(desc); f->enabled = false; f->jstype = "s--"; f->op = "--"; f->version = 0;
    return d->nfields++;
}
int defineExtra(int lang, const char *name, const char *desc) {
    langDef *d = getLangDef(lang);
    d->extras = xrealloc((void*)d->extras, (d->nextras + 1) * sizeof(extraDef));
    extraDef *e = &d->extras[d->nextras];
    e->name = xstrdup(name); e->desc = xstrdup(desc); e->enabled = false; e->version = 0;
    return d->nextras++;
}
int defineRole(int lang, int kindIndex, const char *name, const char *desc) {
    kindDef *k = getLanguageKind(lang, kindIndex);
    k->roles = xrealloc(k->roles, (k->nroles + 1) * sizeof(roleDef));
    roleDef *r = &k->roles[k->nroles];
    r->name = xstrdup(name); r->desc = xstrdup(desc); r->enabled = true; r->version = 0;
    return k->nroles++;
}

/* ---- maps ---- */
void addLanguageExtensionMap(int lang, const char *ext, bool exclusive) {
    if (exclusive) {
        for (int i = 0; i < LANG_COUNT; i++) {
            parserObject *p = getParser(i);
            int idx;
            while ((idx = saIndex(p->exts, ext)) >= 0) saRemove(p->exts, idx);
        }
    }
    saAdd(getParser(lang)->exts, ext);
}
void addLanguagePatternMap(int lang, const char *pat, bool exclusive) {
    if (exclusive) {
        for (int i = 0; i < LANG_COUNT; i++) {
            parserObject *p = getParser(i);
            int idx;
            while ((idx = saIndex(p->pats, pat)) >= 0) saRemove(p->pats, idx);
        }
    }
    saAdd(getParser(lang)->pats, pat);
}
void removeLanguageExtensionMap(int lang, const char *ext) {
    parserObject *p = getParser(lang);
    int idx;
    while ((idx = saIndex(p->exts, ext)) >= 0) saRemove(p->exts, idx);
}
void removeLanguagePatternMap(int lang, const char *pat) {
    parserObject *p = getParser(lang);
    int idx;
    while ((idx = saIndex(p->pats, pat)) >= 0) saRemove(p->pats, idx);
}
void clearLanguageMap(int lang) { saClear(getParser(lang)->exts); saClear(getParser(lang)->pats); }
void installLanguageMapDefault(int lang) {
    parserObject *p = getParser(lang);
    clearLanguageMap(lang);
    if (lang < LangTableCount) {
        langDef *src = &LangTable[lang];
        if (src->exts) for (const char **e = src->exts; *e; e++) saAdd(p->exts, *e);
        if (src->patterns) for (const char **e = src->patterns; *e; e++) saAdd(p->pats, *e);
    }
}
void addLanguageAlias(int lang, const char *alias) { saAdd(getParser(lang)->aliases, alias); }
void clearLanguageAliases(int lang) { saClear(getParser(lang)->aliases); }
void installLanguageAliasesDefault(int lang) {
    parserObject *p = getParser(lang);
    saClear(p->aliases);
    if (lang < LangTableCount && LangTable[lang].aliases)
        for (const char **e = LangTable[lang].aliases; *e; e++) saAdd(p->aliases, *e);
}

/* parse option suffix "--kinds-<LANG>" -> lang index */
int langFromOptionSuffix(const char *option, const char *prefix, const char **rest, bool warnOnly, bool allowAll) {
    const char *name = option + strlen(prefix);
    size_t len = strlen(name);
    const char *dot = strchr(name, '.');
    if (rest) { *rest = NULL; if (dot) { len = dot - name; *rest = dot + 1; } }
    if (allowAll && len == 3 && strncmp(name, "all", 3) == 0) return -2;
    int lang = getNamedLanguageFull(name, len, true);
    return lang;
}

/* ---- scope separators ---- */
void setLanguageScopeSeparator(int lang, int parentKind, int childKind, const char *sep) {
    parserObject *p = getParser(lang);
    for (size_t i = 0; i < paCount(p->scopeSeps); i++) {
        scopeSep *s = paItem(p->scopeSeps, i);
        if (s->parentKind == parentKind && s->childKind == childKind) { free(s->sep); s->sep = xstrdup(sep); return; }
    }
    scopeSep *s = xmalloc(sizeof *s);
    s->parentKind = parentKind; s->childKind = childKind; s->sep = xstrdup(sep);
    paAdd(p->scopeSeps, s);
}
/* KIND_WILDCARD = -4 */
const char *getScopeSeparator(int lang, int parentKind, int childKind) {
    parserObject *p = getParser(lang);
    const char *best = NULL;
    int bestScore = -1;
    for (size_t i = 0; i < paCount(p->scopeSeps); i++) {
        scopeSep *s = paItem(p->scopeSeps, i);
        int score = 0;
        if (s->childKind == childKind) score += 2; else if (s->childKind != -4) continue;
        if (s->parentKind == parentKind) score += 1; else if (s->parentKind != -4) continue;
        if (score > bestScore) { bestScore = score; best = s->sep; }
    }
    if (best) return best;
    if (parentKind == -5) return "";  /* root separator default: none */
    return ".";
}

/* ---- params ---- */
const char *getParamValue(int lang, const char *name) {
    parserObject *p = getParser(lang);
    int i = saIndex(p->paramNames, name);
    return i >= 0 ? saItem(p->paramValues, i) : NULL;
}

/* ---- language detection ---- */
static bool fileMatchesPattern(const char *base, const char *pat) {
    return stringMatch(base, pat, false);
}
static bool fileMatchesRexpr(const char *path, rexprEntry *re) {
    return regexec(&re->re, path, 0, NULL, 0) == 0;
}

typedef struct { int lang; } candidate;

static int nominateByPattern(const char *base, const char *path, candidate *cands) {
    int n = 0;
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (!p->def->enabled) continue;
        bool hit = false;
        for (size_t j = 0; j < saCount(p->pats) && !hit; j++)
            if (fileMatchesPattern(base, saItem(p->pats, j))) hit = true;
        for (size_t j = 0; j < paCount(p->rexprs) && !hit; j++)
            if (fileMatchesRexpr(path, paItem(p->rexprs, j))) hit = true;
        if (hit) cands[n++].lang = i;
    }
    return n;
}
static int nominateByExtension(const char *ext, candidate *cands) {
    int n = 0;
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (!p->def->enabled) continue;
        for (size_t j = 0; j < saCount(p->exts); j++)
            if (strcmp(saItem(p->exts, j), ext) == 0) { cands[n++].lang = i; break; }
    }
    return n;
}

static char *readFileHead(const char *fileName, size_t max, size_t *outSize) {
    FILE *fp = fopen(fileName, "rb");
    if (!fp) return NULL;
    char *buf = xmalloc(max + 1);
    size_t n = fread(buf, 1, max, fp);
    fclose(fp);
    buf[n] = 0;
    if (outSize) *outSize = n;
    return buf;
}
static char *readWholeFile(const char *fileName, size_t *outSize) {
    FILE *fp = fopen(fileName, "rb");
    if (!fp) return NULL;
    size_t cap = 65536, n = 0;
    char *buf = xmalloc(cap + 1);
    for (;;) {
        size_t r = fread(buf + n, 1, cap - n, fp);
        n += r;
        if (n == cap) { cap *= 2; buf = xrealloc(buf, cap + 1); }
        if (r == 0) break;
    }
    fclose(fp);
    buf[n] = 0;
    if (outSize) *outSize = n;
    return buf;
}

static int pickBySelector(candidate *cands, int n, const char *fileName, const char *content, size_t size) {
    int langs[16];
    for (int i = 0; i < n && i < 16; i++) langs[i] = cands[i].lang;
    char *buf = NULL;
    size_t sz = size;
    const char *c = content;
    if (!c) { buf = readWholeFile(fileName, &sz); c = buf; }
    int r = -1;
    if (c) r = selectLanguageAmongCandidates(c, sz, langs, n);
    free(buf);
    return r;
}

static int resolveCandidates(candidate *cands, int n, const char *fileName, const char *content, size_t size) {
    if (n == 1) return cands[0].lang;
    int r = pickBySelector(cands, n, fileName, content, size);
    if (r >= 0) return r;
    return cands[0].lang;
}

int getLanguageForFilenameAndContents(const char *fileName, const char *content, size_t size) {
    const char *base = baseFilename(fileName);
    candidate cands[64];
    int n = nominateByPattern(base, fileName, cands);
    if (n > 0) return resolveCandidates(cands, n, fileName, content, size);
    const char *ext = fileExtension(base);
    n = nominateByExtension(ext, cands);
    if (n > 0) return resolveCandidates(cands, n, fileName, content, size);
    return -1;
}
int getLanguageForFilename(const char *fileName, bool checkContents) {
    (void)checkContents;
    return getLanguageForFilenameAndContents(fileName, NULL, 0);
}

/* match interpreter / mode name to language name or alias */
static int getLanguageByNameOrAlias(const char *name) {
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (!p->def->enabled) continue;
        if (strcasecmp(p->def->name, name) == 0) return i;
    }
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (!p->def->enabled) continue;
        for (size_t j = 0; j < saCount(p->aliases); j++)
            if (stringMatch(name, saItem(p->aliases, j), false)) return i;
    }
    return -1;
}

static int languageFromShebang(const char *content) {
    if (!(content[0] == '#' && content[1] == '!')) return -1;
    const char *p = content + 2;
    while (*p == ' ' || *p == '\t') p++;
    /* first word */
    const char *s = p;
    while (*p && !isspace((unsigned char)*p)) p++;
    char *word = xstrndup(s, p - s);
    char *interp = baseFilename(word);
    if (strcmp(interp, "env") == 0) {
        /* next word, skipping options like -S? (not supported by ctags: env -S -> NONE) */
        while (*p == ' ' || *p == '\t') p++;
        s = p;
        while (*p && !isspace((unsigned char)*p)) p++;
        free(word);
        word = xstrndup(s, p - s);
        interp = baseFilename(word);
    }
    int lang = -1;
    if (*interp) {
        lang = getLanguageByNameOrAlias(interp);
    }
    free(word);
    return lang;
}

/* emacs: -*- mode: NAME -*- or -*- NAME -*- in first line */
static int languageFromEmacsModeline(const char *line) {
    const char *s = strstr(line, "-*-");
    if (!s) return -1;
    s += 3;
    const char *e = strstr(s, "-*-");
    if (!e) return -1;
    char *spec = xstrndup(s, e - s);
    char *t = strTrim(spec);
    int lang = -1;
    const char *m = strstr(t, "mode:");
    if (m) {
        m += 5;
        while (*m == ' ' || *m == '\t') m++;
        const char *q = m;
        while (*q && *q != ';' && !isspace((unsigned char)*q)) q++;
        char *name = xstrndup(m, q - m);
        if (*name) lang = getLanguageByNameOrAlias(name);
        free(name);
    } else {
        if (!strchr(t, ':')) {
            const char *q = t;
            while (*q && *q != ';' && !isspace((unsigned char)*q)) q++;
            char *name = xstrndup(t, q - t);
            if (*name) lang = getLanguageByNameOrAlias(name);
            free(name);
        }
    }
    free(spec);
    return lang;
}

/* emacs local variables block at the end: "mode: NAME" */
static int languageFromEmacsLocalVariables(const char *content, size_t size) {
    /* look in last 3000 bytes */
    size_t start = size > 3000 ? size - 3000 : 0;
    const char *lv = NULL, *p = content + start;
    while ((p = strstr(p, "Local Variables:")) != NULL) { lv = p; p += 16; }
    if (!lv) return -1;
    const char *m = strstr(lv, "mode:");
    if (!m) return -1;
    m += 5;
    while (*m == ' ' || *m == '\t') m++;
    const char *q = m;
    while (*q && !isspace((unsigned char)*q) && *q != ';') q++;
    char *name = xstrndup(m, q - m);
    int lang = *name ? getLanguageByNameOrAlias(name) : -1;
    free(name);
    return lang;
}

/* vim modeline: "vim: set ft=NAME" / "vim:ft=NAME" / "filetype=" / "syntax=" in last lines */
static int languageFromVimModeline(const char *content, size_t size) {
    size_t start = size > 3000 ? size - 3000 : 0;
    const char *p = content + start;
    int lang = -1;
    const char *hit;
    const char *keys[] = { "vim:", "vi:", "ex:", NULL };
    for (int k = 0; keys[k]; k++) {
        const char *q = p;
        while ((hit = strstr(q, keys[k])) != NULL) {
            const char *r = hit + strlen(keys[k]);
            const char *eol = strchr(r, '\n'); if (!eol) eol = r + strlen(r);
            const char *fts[] = { "filetype=", "ft=", "syntax=", NULL };
            for (int f = 0; fts[f]; f++) {
                const char *ft = strstr(r, fts[f]);
                if (ft && ft < eol) {
                    ft += strlen(fts[f]);
                    const char *e = ft;
                    while (*e && (isalnum((unsigned char)*e) || *e == '_' || *e == '-' || *e == '+' || *e == '#')) e++;
                    char *name = xstrndup(ft, e - ft);
                    int l = *name ? getLanguageByNameOrAlias(name) : -1;
                    free(name);
                    if (l >= 0) lang = l;
                    break;
                }
            }
            q = r;
        }
    }
    return lang;
}

static int tasteLanguage(const char *fileName, bool eager, const char *content, size_t size) {
    char *buf = NULL;
    size_t sz = size;
    const char *c = content;
    if (!c) { buf = readWholeFile(fileName, &sz); c = buf; }
    if (!c) return -1;
    int lang = languageFromShebang(c);
    if (lang < 0 && eager) {
        /* first line emacs */
        const char *eol = strchr(c, '\n');
        char *first = xstrndup(c, eol ? (size_t)(eol - c) : strlen(c));
        lang = languageFromEmacsModeline(first);
        if (lang < 0 && eol) {
            /* second line also acceptable for emacs modeline when first is shebang */
            const char *eol2 = strchr(eol + 1, '\n');
            char *second = xstrndup(eol + 1, eol2 ? (size_t)(eol2 - eol - 1) : strlen(eol + 1));
            if (c[0] == '#' && c[1] == '!') lang = languageFromEmacsModeline(second);
            free(second);
        }
        free(first);
        if (lang < 0) lang = languageFromEmacsLocalVariables(c, sz);
        if (lang < 0) lang = languageFromVimModeline(c, sz);
    }
    free(buf);
    return lang;
}

int getFileLanguageFull(const char *fileName, const char *content, size_t size, bool isStdinBuffer) {
    if (Option.languageForce >= 0) return Option.languageForce;
    int lang = getLanguageForFilenameAndContents(fileName, content, size);
    if (lang >= 0) return lang;
    bool exec = isStdinBuffer ? false : isExecutableFile(fileName);
    if (exec || Option.guessLanguageEagerly || isStdinBuffer) {
        lang = tasteLanguage(fileName, Option.guessLanguageEagerly, content, size);
    }
    return lang;
}
