void forceInitializeAll(void) {
    for (int i = 0; i < LANG_COUNT; i++) {
        parserObject *p = getParser(i);
        if (!p->initialized) {
            p->initialized = true;
            if (p->impl && p->impl->initialize) p->impl->initialize(i);
        }
    }
}

void notifyLanguageUsed(int lang) {
    parserObject *p = getParser(lang);
    if (!p->initialized) {
        p->initialized = true;
        if (p->impl && p->impl->initialize) p->impl->initialize(lang);
    }
    p->used = true;
}

/* ---- running parsers ---- */
static void runParser(int lang) {
    parserObject *p = getParser(lang);
    CurrentLang = lang;
    setInputLanguage(lang);
    notifyLanguageUsed(lang);
    regexPreparePerFile(lang);
    if (p->impl && p->impl->parser2) {
        unsigned int pass = 0;
        bool again;
        do {
            inputState st; saveInputState(&st);
            again = p->impl->parser2(pass++);
            if (again) restoreInputState(&st);
        } while (again && pass < 3);
    } else if (p->impl && p->impl->parser) {
        p->impl->parser();
    } else {
        findRegexTags();
    }
    /* multi-line & multi-table regexes */
    if (hasMultiLineRegexPatterns(lang) || hasMultiTableRegexPatterns(lang)) {
        size_t size; const char *content = getInputFileContents(&size);
        if (hasMultiLineRegexPatterns(lang)) matchMultiLineRegex(lang, content, size);
        if (hasMultiTableRegexPatterns(lang)) runMultiTableRegex(lang, content, size);
    }
    regexFinishPerFile(lang);
}

void runParserInGuestArea(int lang, size_t start, size_t end) {
    inputState st; saveInputState(&st);
    int savedLang = CurrentLang;
    setInputArea(start, end);
    runParser(lang);
    restoreInputState(&st);
    CurrentLang = savedLang;
    setInputLanguage(savedLang);
}

bool parseRawBuffer(const char *fileName, const char *buf, size_t size, int lang) {
    if (!openInputFile(fileName, lang, buf, size)) return false;
    beginInputFile(fileName, lang);
    corkQueueBegin();
    runParser(lang);
    makeFileTag(fileName, lang, getInputLastLineNumber());
    corkQueueEnd();
    endInputFile();
    closeInputFile();
    return true;
}

bool parseFile(const char *fileName) {
    size_t size;
    char *content = readWholeFile(fileName, &size);
    if (!content) {
        error_warning_perror("cannot open input file \"%s\"", fileName);
        return false;
    }
    int lang = getFileLanguageFull(fileName, content, size, false);
    if (Option.printLanguage) {
        printf("%s: %s\n", fileName, lang >= 0 ? getLanguageName(lang) : "NONE");
        free(content);
        return true;
    }
    if (lang < 0 || !isLanguageEnabled(lang)) {
        verbose("ignoring %s (unknown language/filetype)\n", fileName);
        free(content);
        return false;
    }
    verbose("OPENING %s as %s language file [%s]\n", fileName, getLanguageName(lang), "");
    bool r = parseRawBuffer(fileName, content, size, lang);
    free(content);
    return r;
}

/* ---- --list-languages ---- */
static int cmpLangName(const void *a, const void *b) {
    const parserObject *pa = *(parserObject *const *)a, *pb = *(parserObject *const *)b;
    int r = strcasecmp(pa->def->name, pb->def->name);
    if (r == 0) r = strcmp(pa->def->name, pb->def->name);
    return r;
}
void listLanguages(void) {
    ptrArray *sorted = paNew(NULL);
    for (int i = 0; i < LANG_COUNT; i++) paAdd(sorted, getParser(i));
    paSort(sorted, cmpLangName);
    for (size_t i = 0; i < paCount(sorted); i++) {
        parserObject *p = paItem(sorted, i);
        printf("%s%s\n", p->def->name, p->def->enabled ? "" : " [disabled]");
    }
    paDelete(sorted);
}
