static void buildFullScopeName(tagEntryInfo *e, vString *out, int *outKind) {
    /* walk up the chain */
    int chain[256]; int n = 0;
    int idx = e->ext.scopeIndex;
    while (idx > 0 && n < 256) {
        tagEntryInfo *s = getEntryInCorkQueue(idx);
        if (!s) break;
        chain[n++] = idx;
        idx = s->ext.scopeIndex;
    }
    vsClear(out);
    *outKind = -1;
    for (int i = n - 1; i >= 0; i--) {
        tagEntryInfo *s = getEntryInCorkQueue(chain[i]);
        if (i == n - 1) {
