static bool isTagWritable(tagEntryInfo *e) {
    if (e->placeholder) return false;
    if (e->isPseudoTag) return true;
    int lang = e->langIndex;
    if (e->kindIndex == KIND_FILE_INDEX) return true;
    if (!isLanguageKindEnabled(lang, e->kindIndex)) return false;
    /* role check */
    if (e->roleBits == 0) {
        if (isLanguageRefOnlyKind(lang, e->kindIndex)) return false;
    } else {
        if (!isXtagEnabled(XTAG_REFERENCE_TAGS)) return false;
        bool any = false;
        kindDef *k = getLanguageKind(lang, e->kindIndex);
        for (int r = 0; k && r < k->nroles; r++)
            if ((e->roleBits & (1ULL << r)) && k->roles[r].enabled) any = true;
        if (!any) return false;
    }
    /* file scope */
    if (e->isFileScope && !isXtagEnabled(XTAG_FILE_SCOPE)) return false;
    /* extras */
    for (int x = 0; x < XTAG_COUNT; x++) {
        if (x == XTAG_FILE_SCOPE) continue;
        if ((e->extraBits & (1ULL << x)) && !isXtagEnabled(x)) return false;
    }
    langDef *d = getLangDef(lang);
    for (int x = 0; x < d->nextras; x++)
        if ((e->langExtraBits & (1ULL << x)) && !d->extras[x].enabled) return false;
    if (e->name[0] == '\0' && !isXtagEnabled(XTAG_NULLTAG)) return false;
    return true;
}

