    vString *scope = vsNew();
    size_t n = paCount(CorkQueue);
    for (size_t i = 1; i < n; i++) {
        tagEntryInfo *e = paItem(CorkQueue, i);
        /* resolve scope */
        if (e->ext.scopeIndex > 0 && !e->ext.scopeName) {
            int kind;
            buildFullScopeName(e, scope, &kind);
            if (vsLength(scope) > 0 || kind >= 0) {
                e->ext.scopeName = xstrdup(vsValue(scope));
                e->ext.scopeKindIndex = kind;
            }
        }
    }
    for (size_t i = 1; i < n; i++) {
        tagEntryInfo *e = paItem(CorkQueue, i);
        bool writable = isTagWritable(e);
        if (writable) {
            if (e->isFileScope) markTagExtraBit(e, XTAG_FILE_SCOPE);
            paAdd(AllTags, e);
            /* qualified tag */
            if (isXtagEnabled(XTAG_QUALIFIED_TAGS) && e->ext.scopeName && !e->skipAutoFQEmission
                && e->kindIndex != KIND_FILE_INDEX && e->ext.scopeKindIndex >= 0) {
                tagEntryInfo *q = copyEntry(e);
                const char *sep = getScopeSeparator(e->langIndex, e->ext.scopeKindIndex, e->kindIndex);
                vString *fq = vsNewInit(e->ext.scopeName);
                vsCat(fq, sep);
                vsCat(fq, e->name);
                free(q->name);
                q->name = vsDetach(fq);
                markTagExtraBit(q, XTAG_QUALIFIED_TAGS);
                paAdd(AllTags, q);
            }
        } else {
            /* keep entry alive? free it */
            tagEntryFree(e);
        }
    }
    vsDelete(scope);
    paDelete(CorkQueue);
    CorkQueue = NULL;
}

/* ---- pseudo tags ---- */
typedef struct { char *name; char *value; char *desc; int lang; int fileIndex; } ptagEntry;
static ptrArray *Ptags = NULL;

static void addPtag(const char *name, const char *suffix, const char *value, const char *desc) {
    if (!Ptags) Ptags = paNew(NULL);
    ptagEntry *p = xcalloc(1, sizeof *p);
    vString *n = vsNewInit("!_");
    vsCat(n, name);
    if (suffix) vsCat(n, suffix);
    p->name = vsDetach(n);
    p->value = xstrdup(value ? value : "");
    p->desc = xstrdup(desc ? desc : "");
    paAdd(Ptags, p);
}

static bool ptagsEnabledForOutput(void) {
    if (!isXtagEnabled(XTAG_PSEUDO_TAGS)) return false;
    if (Option.outputFormat == OF_ETAGS || Option.outputFormat == OF_XREF) return false;
    if (isDestinationStdout() && !Option.extrasExplicit[XTAG_PSEUDO_TAGS]) return false;
    return true;
}

void makeLanguagePseudoTags(int lang) {
    parserObject *p = getParser(lang);
    if (p->ptagsEmitted) return;
    p->ptagsEmitted = true;
    if (!ptagsEnabledForOutput()) return;
    langDef *d = p->def;
    char suffix[256];
    snprintf(suffix, sizeof suffix, "!%s", d->name);
    if (Option.ptags[PTAG_TAG_KIND_DESCRIPTION]) {
        for (int i = 0; i < d->nkinds; i++) {
            kindDef *k = &d->kinds[i];
            if (!k->enabled) continue;
            char val[512];
            snprintf(val, sizeof val, "%s,%s", k->letter, k->name);
            addPtag("TAG_KIND_DESCRIPTION", suffix, val, k->desc);
        }
    }
    if (Option.ptags[PTAG_TAG_KIND_SEPARATOR]) {
        for (size_t i = 0; i < paCount(p->scopeSeps); i++) {
            /* struct scopeSep { int parentKind; int childKind; char *sep; } */
            struct { int parentKind; int childKind; char *sep; } *s = paItem(p->scopeSeps, i);
            char val[512];
            const char *pk = s->parentKind == -4 ? "*" : (s->parentKind == -5 ? "" : kindLetter(lang, s->parentKind));
            const char *ck = s->childKind == -4 ? "*" : kindLetter(lang, s->childKind);
            char desc[64];
            if (s->parentKind == -5) { snprintf(val, sizeof val, "%s", s->sep); snprintf(desc, sizeof desc, "%s", ck); }
            else { snprintf(val, sizeof val, "%s", s->sep); snprintf(desc, sizeof desc, "%s%s%s", pk, "", ck); }
            addPtag("TAG_KIND_SEPARATOR", suffix, val, desc);
        }
    }
    if (Option.ptags[PTAG_TAG_ROLE_DESCRIPTION]) {
        for (int i = 0; i < d->nkinds; i++) {
            kindDef *k = &d->kinds[i];
            if (!k->enabled) continue;
            for (int r = 0; r < k->nroles; r++) {
                if (!k->roles[r].enabled) continue;
                char sfx[512];
                snprintf(sfx, sizeof sfx, "!%s!%s", d->name, k->name);
                addPtag("TAG_ROLE_DESCRIPTION", sfx, k->roles[r].name, k->roles[r].desc);
            }
        }
    }
    if (Option.ptags[PTAG_TAG_PARSER_VERSION]) {
        char val[32];
        snprintf(val, sizeof val, "%d.%d", d->verCurrent, d->verAge);
        addPtag("TAG_PARSER_VERSION", suffix, val, "current.age");
    }
}

static int cmpStr(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }

void addPseudoTagEntries(void) {
    if (!ptagsEnabledForOutput()) return;
    if (Option.ptags[PTAG_JSON_OUTPUT_VERSION]) addPtag("JSON_OUTPUT_VERSION", NULL, "1.0", "in development");
    if (Option.ptags[PTAG_TAG_EXTRA_DESCRIPTION]) {
        /* sorted by name, common extras */
        struct { const char *name; const char *desc; int idx; } xs[XTAG_COUNT];
        static const char *xnames[XTAG_COUNT] = { "fileScope", "inputFile", "pseudo", "qualified", "reference", "guest", "subparser", "anonymous", "nulltag" };
        static const char *xdescs[XTAG_COUNT] = {
            "Include tags of file scope", "Include an entry for the base file name of every input file", "Include pseudo tags",
            "Include an extra class-qualified tag entry for each tag", "Include reference tags", "Include tags generated by guest parsers",
            "Include tags generated by subparsers", "Include tags for non-named objects like lambda", "Include tags with empty strings as their names" };
        int n = 0;
        for (int i = 0; i < XTAG_COUNT; i++) if (Option.extras[i]) { xs[n].name = xnames[i]; xs[n].desc = xdescs[i]; xs[n].idx = i; n++; }
        /* sort by name */
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (strcmp(xs[i].name, xs[j].name) > 0) { typeof(xs[0]) t = xs[i]; xs[i] = xs[j]; xs[j] = t; }
        for (int i = 0; i < n; i++) addPtag("TAG_EXTRA_DESCRIPTION", NULL, xs[i].name, xs[i].desc);
    }
    if (Option.ptags[PTAG_TAG_FIELD_DESCRIPTION]) {
        extern const char *FieldNames[FIELD_COUNT];
        extern const char *FieldDescs[FIELD_COUNT];
        struct { const char *name; const char *desc; } fs[FIELD_COUNT];
        int n = 0;
        for (int i = 0; i < FIELD_COUNT; i++) if (Option.fields[i] && FieldNames[i]) { fs[n].name = FieldNames[i]; fs[n].desc = FieldDescs[i]; n++; }
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (strcmp(fs[i].name, fs[j].name) > 0) { typeof(fs[0]) t = fs[i]; fs[i] = fs[j]; fs[j] = t; }
        for (int i = 0; i < n; i++) addPtag("TAG_FIELD_DESCRIPTION", NULL, fs[i].name, fs[i].desc);
    }
    if (Option.ptags[PTAG_TAG_FILE_ENCODING] && Option.outputEncoding) addPtag("TAG_FILE_ENCODING", NULL, Option.outputEncoding, "");
    if (Option.ptags[PTAG_TAG_FILE_FORMAT]) {
        char v[8]; snprintf(v, sizeof v, "%d", Option.format);
        addPtag("TAG_FILE_FORMAT", NULL, v, "extended format; --format=1 will not append ;\" to lines");
    }
    if (Option.ptags[PTAG_TAG_FILE_SORTED]) {
        char v[8]; snprintf(v, sizeof v, "%d", (int)Option.sorted);
        addPtag("TAG_FILE_SORTED", NULL, v, "0=unsorted, 1=sorted, 2=foldcase");
    }
    if (Option.ptags[PTAG_TAG_OUTPUT_EXCMD]) {
        const char *v = Option.locate == EX_MIX ? "mixed" : Option.locate == EX_LINENUM ? "number" : Option.locate == EX_PATTERN ? "pattern" : "combineV2";
        addPtag("TAG_OUTPUT_EXCMD", NULL, v, "number, pattern, mixed, or combineV2");
    }
    if (Option.ptags[PTAG_TAG_OUTPUT_FILESEP]) addPtag("TAG_OUTPUT_FILESEP", NULL, "slash", "slash or backslash");
    if (Option.ptags[PTAG_TAG_OUTPUT_MODE]) addPtag("TAG_OUTPUT_MODE", NULL, Option.outputFormat == OF_ECTAGS ? "e-ctags" : "u-ctags", "u-ctags or e-ctags");
    if (Option.ptags[PTAG_TAG_OUTPUT_VERSION]) addPtag("TAG_OUTPUT_VERSION", NULL, "1.1", "current.age");
    if (Option.ptags[PTAG_TAG_PATTERN_LENGTH_LIMIT]) {
        char v[32]; snprintf(v, sizeof v, "%lu", Option.patternLengthLimit);
        addPtag("TAG_PATTERN_LENGTH_LIMIT", NULL, v, "0 for no limit");
    }
    if (Option.ptags[PTAG_TAG_PROC_CWD]) {
        char *cwd = getCwd();
        size_t n = strlen(cwd);
        cwd = xrealloc(cwd, n + 2);
        if (n == 0 || cwd[n-1] != '/') { cwd[n] = '/'; cwd[n+1] = 0; }
        addPtag("TAG_PROC_CWD", NULL, cwd, "");
        free(cwd);
    }
    if (Option.ptags[PTAG_TAG_PROGRAM_AUTHOR]) addPtag("TAG_PROGRAM_AUTHOR", NULL, "Universal Ctags Team", "");
    if (Option.ptags[PTAG_TAG_PROGRAM_NAME]) addPtag("TAG_PROGRAM_NAME", NULL, "Universal Ctags", "Derived from Exuberant Ctags");
    if (Option.ptags[PTAG_TAG_PROGRAM_URL]) addPtag("TAG_PROGRAM_URL", NULL, "https://ctags.io/", "official site");
    if (Option.ptags[PTAG_TAG_PROGRAM_VERSION]) addPtag("TAG_PROGRAM_VERSION", NULL, "6.2.0", "1cdb801");
}

/* ---- writers ---- */

static const char *PatternDelims(void) { return Option.backward ? "?" : "/"; }

/* build pattern text (without delimiters); returns true if full line was used ($ appended) */
static void appendPatternBody(vString *out, const char *line, bool truncateAfterTag, const char *tagName, bool *omitted) {
    size_t length = strlen(line);
    /* strip trailing newline chars */
    while (length > 0 && (line[length-1] == '\n' || line[length-1] == '\r')) length--;
    size_t limit = Option.patternLengthLimit;
    char delim = PatternDelims()[0];
    *omitted = false;
    size_t useLen = length;
    if (truncateAfterTag && tagName && *tagName) {
        /* cut after the tag name + 1 char */
        const char *p = strstr(line, tagName);
        if (p) {
            size_t cut = (p - line) + strlen(tagName) + 1;
            if (cut < useLen) useLen = cut;
        }
    }
    size_t count = 0;
    size_t i;
    for (i = 0; i < useLen; i++) {
        char c = line[i];
        if (c == '\n' || c == '\r') break;
        size_t add = 1;
        bool esc = false;
        if (c == '\\' || c == delim) { esc = true; add = 2; }
        if (limit > 0 && count + add > limit) { *omitted = true; break; }
        if (esc) vsPut(out, '\\');
        vsPut(out, c);
        count += add;
    }
    if (i < useLen) *omitted = true;
    if (truncateAfterTag && useLen < length) *omitted = true;
}

static void makePatternString(vString *out, tagEntryInfo *e) {
    const char *delim = PatternDelims();
    bool omitted;
    vsCat(out, delim);
    vsPut(out, '^');
    appendPatternBody(out, e->sourceLine ? e->sourceLine : "", e->truncateLineAfterTag, e->name, &omitted);
    if (!omitted) vsPut(out, '$');
    vsCat(out, delim);
}

static void writeExCmd(vString *out, tagEntryInfo *e) {
    bool useLine = (Option.locate == EX_LINENUM) || e->isFileEntry || e->kindIndex == KIND_FILE_INDEX;
    if (Option.locate == EX_COMBINE && !e->isFileEntry) {
        vsPrintf(out, "%lu;", e->lineNumber);
        makePatternString(out, e);
    } else if (useLine) {
        vsPrintf(out, "%lu", e->lineNumber);
    } else {
        makePatternString(out, e);
    }
}

/* escape for u-ctags fields: \ -> \\, tab -> \t, newline -> \n */
static void appendEscaped(vString *out, const char *s, bool uctags) {
    for (; *s; s++) {
        if (uctags) {
            if (*s == '\\') { vsCat(out, "\\\\"); continue; }
            if (*s == '\t') { vsCat(out, "\\t"); continue; }
            if (*s == '\n') { vsCat(out, "\\n"); continue; }
            if (*s == '\r') { vsCat(out, "\\r"); continue; }
        }
        vsPut(out, *s);
    }
}

static const char *roleNames(tagEntryInfo *e, vString *buf) {
    vsClear(buf);
    if (e->roleBits == 0) { vsCat(buf, "def"); return vsValue(buf); }
    kindDef *k = getLanguageKind(e->langIndex, e->kindIndex);
    bool first = true;
    for (int r = 0; k && r < k->nroles; r++) {
        if (e->roleBits & (1ULL << r)) {
            if (!first) vsPut(buf, ',');
            vsCat(buf, k->roles[r].name);
            first = false;
        }
    }
    return vsValue(buf);
}

static const char *extraNames(tagEntryInfo *e, vString *buf) {
    static const char *xnames[XTAG_COUNT] = { "fileScope", "inputFile", "pseudo", "qualified", "reference", "guest", "subparser", "anonymous", "nulltag" };
    vsClear(buf);
    bool first = true;
    for (int x = 0; x < XTAG_COUNT; x++) {
        if (e->extraBits & (1ULL << x)) {
            if (!first) vsPut(buf, ',');
            vsCat(buf, xnames[x]);
            first = false;
        }
    }
    langDef *d = getLangDef(e->langIndex);
    for (int x = 0; x < d->nextras; x++) {
        if (e->langExtraBits & (1ULL << x)) {
            if (!first) vsPut(buf, ',');
            vsCat(buf, d->extras[x].name);
            first = false;
        }
    }
    return vsLength(buf) ? vsValue(buf) : NULL;
}

static bool hasRoleEnabled(tagEntryInfo *e) { (void)e; return true; }

static const char *fieldPrefix(void) { return Option.putFieldPrefix ? "UCTAGS" : ""; }

static void writeCtagsFields(vString *out, tagEntryInfo *e, bool uctags) {
    vString *tmp = vsNew();
    int lang = e->langIndex;
    bool K = Option.fields[FIELD_KIND_LONG], k = Option.fields[FIELD_KIND], z = Option.fields[FIELD_KIND_KEY];
    if (k || K) {
        vsPut(out, '\t');
        if (z) vsCat(out, "kind:");
        if (K) vsCat(out, kindName(lang, e->kindIndex)); else vsCat(out, kindLetter(lang, e->kindIndex));
    }
    if (Option.fields[FIELD_LINE_NUMBER]) vsPrintf(out, "\tline:%lu", e->lineNumber);
    if (Option.fields[FIELD_LANGUAGE]) { vsCat(out, "\tlanguage:"); vsCat(out, getLanguageName(lang)); }
    if ((Option.fields[FIELD_SCOPE] || Option.fields[FIELD_SCOPE_KEY]) && e->ext.scopeName && e->ext.scopeKindIndex >= 0) {
        vsPut(out, '\t');
        if (Option.fields[FIELD_SCOPE_KEY]) vsCat(out, "scope:");
        vsCat(out, kindName(lang, e->ext.scopeKindIndex));
        vsPut(out, ':');
        appendEscaped(out, e->ext.scopeName, uctags);
    }
    if (Option.fields[FIELD_TYPE_REF] && e->ext.typeRefKind && e->ext.typeRefName) {
        vsCat(out, "\ttyperef:");
        appendEscaped(out, e->ext.typeRefKind, uctags);
        vsPut(out, ':');
        appendEscaped(out, e->ext.typeRefName, uctags);
    }
    if (Option.fields[FIELD_FILE_SCOPE] && e->isFileScope) vsCat(out, "\tfile:");
    if (Option.fields[FIELD_INHERITANCE] && e->ext.inherits) { vsCat(out, "\tinherits:"); appendEscaped(out, e->ext.inherits, uctags); }
    if (Option.fields[FIELD_ACCESS] && e->ext.access) { vsCat(out, "\taccess:"); appendEscaped(out, e->ext.access, uctags); }
    if (Option.fields[FIELD_IMPLEMENTATION] && e->ext.implementation) { vsCat(out, "\timplementation:"); appendEscaped(out, e->ext.implementation, uctags); }
    if (Option.fields[FIELD_SIGNATURE] && e->ext.signature) { vsCat(out, "\tsignature:"); appendEscaped(out, e->ext.signature, uctags); }
    if (Option.fields[FIELD_ROLES]) { vsCat(out, "\troles:"); vsCat(out, roleNames(e, tmp)); }
    if (Option.fields[FIELD_EXTRAS]) { const char *x = extraNames(e, tmp); if (x) { vsCat(out, "\textras:"); vsCat(out, x); } }
    if (Option.fields[FIELD_END_LINE] && e->ext.endLine) vsPrintf(out, "\tend:%lu", e->ext.endLine);
    if (Option.fields[FIELD_NTH] && e->ext.nth >= 0) vsPrintf(out, "\tnth:%d", e->ext.nth);
    if (Option.fields[FIELD_XPATH] && e->ext.xpath) { vsCat(out, "\txpath:"); appendEscaped(out, e->ext.xpath, uctags); }
    if (Option.fields[FIELD_EPOCH] && e->kindIndex == KIND_FILE_INDEX) vsPrintf(out, "\tepoch:%ld", (long)CurrentFileMtime);
    /* language specific */
    langDef *d = getLangDef(lang);
    for (int fi = 0; fi < d->nfields; fi++) {
        if (!d->fields[fi].enabled) continue;
        for (int i = 0; i < e->nfields; i++) {
            if (e->fields[i].ftype == fi && e->fields[i].value) {
                vsPut(out, '\t');
                vsCat(out, fieldPrefix());
                vsCat(out, d->fields[fi].name);
                vsPut(out, ':');
                appendEscaped(out, e->fields[i].value, uctags);
            }
        }
    }
    vsDelete(tmp);
}

static char *buildCtagsLine(tagEntryInfo *e, bool uctags) {
    vString *out = vsNew();
    if (!uctags) {
        /* e-ctags: drop tags with tab/newline in name */
        if (strchr(e->name, '\t') || strchr(e->name, '\n')) { vsDelete(out); return NULL; }
    }
    appendEscaped(out, e->name, uctags);
    vsPut(out, '\t');
    vsCat(out, e->inputFileName);
    vsPut(out, '\t');
    writeExCmd(out, e);
    if (Option.format > 1) {
        vsCat(out, ";\"");
        writeCtagsFields(out, e, uctags);
    }
    return vsDetach(out);
}

static void jsonString(vString *out, const char *s) {
    vsPut(out, '"');
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        switch (*p) {
        case '"': vsCat(out, "\\\""); break;
        case '\\': vsCat(out, "\\\\"); break;
        case '\n': vsCat(out, "\\n"); break;
        case '\t': vsCat(out, "\\t"); break;
        case '\r': vsCat(out, "\\r"); break;
        case '\b': vsCat(out, "\\b"); break;
        case '\f': vsCat(out, "\\f"); break;
        default:
            if (*p < 0x20) vsPrintf(out, "\\u%04x", *p);
            else vsPut(out, *p);
        }
    }
    vsPut(out, '"');
}
static void jsonField(vString *out, const char *key, const char *value) {
    vsCat(out, ", "); jsonString(out, key); vsCat(out, ": "); jsonString(out, value);
}
static void jsonFieldInt(vString *out, const char *key, long value) {
    vsCat(out, ", "); jsonString(out, key); vsPrintf(out, ": %ld", value);
}
static void jsonFieldBool(vString *out, const char *key, bool value) {
    vsCat(out, ", "); jsonString(out, key); vsCat(out, value ? ": true" : ": false");
}

static char *buildJsonLine(tagEntryInfo *e) {
    vString *out = vsNew();
    vString *tmp = vsNew();
    int lang = e->langIndex;
    vsCat(out, "{\"_type\": \"tag\"");
    jsonField(out, "name", e->name);
    jsonField(out, "path", e->inputFileName);
    /* pattern */
    if (Option.fields[FIELD_PATTERN]) {
        if (e->isFileEntry || e->kindIndex == KIND_FILE_INDEX) {
            /* no pattern for file entry? ctags prints "pattern": null? use line */
            vsCat(out, ", \"pattern\": null");
        } else {
            vsClear(tmp);
            makePatternString(tmp, e);
            jsonField(out, "pattern", vsValue(tmp));
        }
    }
    if (Option.fields[FIELD_LINE_NUMBER]) jsonFieldInt(out, "line", (long)e->lineNumber);
    if (Option.fields[FIELD_LANGUAGE]) jsonField(out, "language", getLanguageName(lang));
    if (Option.fields[FIELD_FILE_SCOPE] && e->isFileScope) jsonFieldBool(out, "file", true);
    if (Option.fields[FIELD_TYPE_REF] && e->ext.typeRefKind && e->ext.typeRefName) {
        vsClear(tmp); vsCat(tmp, e->ext.typeRefKind); vsPut(tmp, ':'); vsCat(tmp, e->ext.typeRefName);
        jsonField(out, "typeref", vsValue(tmp));
    }
    bool K = Option.fields[FIELD_KIND_LONG], k = Option.fields[FIELD_KIND], z = Option.fields[FIELD_KIND_KEY];
    if (k || K || z) {
        if (K || z) jsonField(out, "kind", kindName(lang, e->kindIndex));
        else jsonField(out, "kind", kindLetter(lang, e->kindIndex));
    }
    if (Option.fields[FIELD_INHERITANCE] && e->ext.inherits) jsonField(out, "inherits", e->ext.inherits);
    if (Option.fields[FIELD_ACCESS] && e->ext.access) jsonField(out, "access", e->ext.access);
    if (Option.fields[FIELD_IMPLEMENTATION] && e->ext.implementation) jsonField(out, "implementation", e->ext.implementation);
    if (Option.fields[FIELD_SIGNATURE] && e->ext.signature) jsonField(out, "signature", e->ext.signature);
    if ((Option.fields[FIELD_SCOPE] || Option.fields[FIELD_SCOPE_KEY]) && e->ext.scopeName && e->ext.scopeKindIndex >= 0) {
        jsonField(out, "scope", e->ext.scopeName);
        if (Option.fields[FIELD_SCOPE_KIND_LONG] || true) jsonField(out, "scopeKind", kindName(lang, e->ext.scopeKindIndex));
    }
    if (Option.fields[FIELD_ROLES]) jsonField(out, "roles", roleNames(e, tmp));
    if (Option.fields[FIELD_EXTRAS]) { const char *x = extraNames(e, tmp); if (x) jsonField(out, "extras", x); }
    if (Option.fields[FIELD_END_LINE] && e->ext.endLine) jsonFieldInt(out, "end", (long)e->ext.endLine);
    if (Option.fields[FIELD_NTH] && e->ext.nth >= 0) jsonFieldInt(out, "nth", e->ext.nth);
    if (Option.fields[FIELD_XPATH] && e->ext.xpath) jsonField(out, "xpath", e->ext.xpath);
    if (Option.fields[FIELD_EPOCH] && e->kindIndex == KIND_FILE_INDEX) jsonFieldInt(out, "epoch", (long)CurrentFileMtime);
    langDef *d = getLangDef(lang);
    for (int fi = 0; fi < d->nfields; fi++) {
        if (!d->fields[fi].enabled) continue;
        for (int i = 0; i < e->nfields; i++) {
            if (e->fields[i].ftype == fi && e->fields[i].value) {
                const char *jt = d->fields[fi].jstype;
                if (jt[1] == 'i') jsonFieldInt(out, d->fields[fi].name, atol(e->fields[i].value));
                else if (jt[0] != 's' && jt[2] == 'b') jsonFieldBool(out, d->fields[fi].name, true);
                else jsonField(out, d->fields[fi].name, e->fields[i].value);
            }
        }
    }
    vsPut(out, '}');
    vsDelete(tmp);
    return vsDetach(out);
}

/* xref: default format "%-16N %-10K %4n %-16F %C" */
static void xrefAppendField(vString *out, tagEntryInfo *e, char spec, int width, bool leftAlign, bool truncate) {
    vString *val = vsNew();
    int lang = e->langIndex;
    switch (spec) {
    case 'N': appendEscaped(val, e->name, true); break;
    case 'K': vsCat(val, kindName(lang, e->kindIndex)); break;
    case 'k': vsCat(val, kindLetter(lang, e->kindIndex)); break;
    case 'n': vsPrintf(val, "%lu", e->lineNumber); break;
    case 'F': vsCat(val, e->inputFileName); break;
    case 'C': { char *c = compactLine(e->sourceLine ? e->sourceLine : ""); vsCat(val, c); free(c); break; }
    case 'P': makePatternString(val, e); break;
    case 'S': if (e->ext.signature) vsCat(val, e->ext.signature); else vsCat(val, "-"); break;
    case 's': if (e->ext.scopeName) vsCat(val, e->ext.scopeName); break;
    case 'Z': if (e->ext.scopeName) vsCat(val, e->ext.scopeName); break;
    case 'z': vsCat(val, kindName(lang, e->kindIndex)); break;
    case 'p': if (e->ext.scopeKindIndex >= 0 && e->ext.scopeName) vsCat(val, kindName(lang, e->ext.scopeKindIndex)); break;
    case 'l': vsCat(val, getLanguageName(lang)); break;
    case 'a': if (e->ext.access) vsCat(val, e->ext.access); break;
    case 'i': if (e->ext.inherits) vsCat(val, e->ext.inherits); break;
    case 'm': if (e->ext.implementation) vsCat(val, e->ext.implementation); break;
    case 't': if (e->ext.typeRefKind) { vsCat(val, e->ext.typeRefKind); vsPut(val, ':'); vsCat(val, e->ext.typeRefName); } break;
    case 'e': if (e->ext.endLine) vsPrintf(val, "%lu", e->ext.endLine); break;
    case 'f': if (e->isFileScope) vsCat(val, "file"); break;
    case 'r': { vString *t = vsNew(); vsCat(val, roleNames(e, t)); vsDelete(t); break; }
    case 'E': { vString *t = vsNew(); const char *x = extraNames(e, t); if (x) vsCat(val, x); vsDelete(t); break; }
    case 'R': vsCat(val, e->roleBits ? "R" : "D"); break;
    case 'x': if (e->ext.xpath) vsCat(val, e->ext.xpath); break;
    case 'o': if (e->ext.nth >= 0) vsPrintf(val, "%d", e->ext.nth); break;
    case 'T': if (e->kindIndex == KIND_FILE_INDEX) vsPrintf(val, "%ld", (long)CurrentFileMtime); break;
    default: break;
    }
    int len = (int)vsLength(val);
    if (truncate && width > 0 && len > width) vsTruncate(val, width);
    if (width > 0 && len < width) {
        if (leftAlign) { vsCatV(out, val); for (int i = len; i < width; i++) vsPut(out, ' '); }
        else { for (int i = len; i < width; i++) vsPut(out, ' '); vsCatV(out, val); }
    } else vsCatV(out, val);
    vsDelete(val);
}

static char *buildXrefLine(tagEntryInfo *e) {
    const char *fmt = Option.xformat ? Option.xformat : "%-16N %-10K %4n %-16F %C";
    vString *out = vsNew();
    for (const char *p = fmt; *p; p++) {
        if (*p != '%') { vsPut(out, *p); continue; }
        p++;
        if (*p == '%') { vsPut(out, '%'); continue; }
        bool left = false, trunc = false;
        if (*p == '-') { left = true; p++; }
        if (*p == '.') { trunc = true; p++; }
        int width = 0;
        while (isdigit((unsigned char)*p)) { width = width * 10 + (*p - '0'); p++; }
        if (*p == '{') {
            /* language specific field {name} or {lang.name} */
            const char *end = strchr(p, '}');
            if (!end) break;
            char *spec = xstrndup(p + 1, end - p - 1);
            char *dot = strchr(spec, '.');
            const char *fname = dot ? dot + 1 : spec;
            int lang = e->langIndex;
            int fi = getLangFieldIndexByName(lang, fname);
            vString *val = vsNew();
            for (int i = 0; fi >= 0 && i < e->nfields; i++) if (e->fields[i].ftype == fi) vsCat(val, e->fields[i].value);
            int len = (int)vsLength(val);
            if (trunc && width > 0 && len > width) vsTruncate(val, width);
            if (left) { vsCatV(out, val); for (int i = len; i < width; i++) vsPut(out, ' '); }
            else { for (int i = len; i < width; i++) vsPut(out, ' '); vsCatV(out, val); }
            vsDelete(val); free(spec);
            p = end;
            continue;
        }
        xrefAppendField(out, e, *p, width, left, trunc);
    }
    return vsDetach(out);
}

static int struppercmp(const char *a, const char *b) {
    for (;; a++, b++) {
        int ca = toupper((unsigned char)*a), cb = toupper((unsigned char)*b);
        if (ca != cb) return ca - cb;
        if (!*a) return 0;
    }
}
static int cmpLines(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }
static int cmpLinesFold(const void *a, const void *b) {
    int r = struppercmp(*(char *const *)a, *(char *const *)b);
    if (r == 0) r = strcmp(*(char *const *)a, *(char *const *)b);
    return r;
}

static FILE *openTagFile(void) {
    if (isDestinationStdout()) return stdout;
    FILE *fp = fopen(Option.tagFileName, Option.append ? "a" : "w");
    if (!fp) error_fatal_perror("cannot open tag file \"%s\"", Option.tagFileName);
    return fp;
}

static void writeEtags(FILE *fp) {
    /* group by file index in order */
    int maxFile = FileCounter;
    for (int f = 1; f <= maxFile; f++) {
        vString *body = vsNew();
        const char *fname = NULL;
        for (size_t i = 0; i < paCount(AllTags); i++) {
            tagEntryInfo *e = paItem(AllTags, i);
            if (e->fileIndex != f) continue;
            if (!fname) fname = e->inputFileName;
            if (e->kindIndex == KIND_FILE_INDEX || e->isFileEntry) {
                vsPrintf(body, "\177%s\001%lu,%ld\n", e->name, e->lineNumber, e->filePosition);
                continue;
            }
            /* line text: the pattern source (truncated as pattern would be) */
            vString *pat = vsNew();
            bool omitted;
            appendPatternBody(pat, e->sourceLine ? e->sourceLine : "", e->truncateLineAfterTag, e->name, &omitted);
            /* unescape: pattern escaping is not applied in etags */
            vString *txt = vsNew();
            for (const char *p = vsValue(pat); *p; p++) { if (*p == '\\' && p[1]) { p++; vsPut(txt, *p); } else vsPut(txt, *p); }
            vsPrintf(body, "%s\177%s\001%lu,%ld\n", vsValue(txt), e->name, e->lineNumber, e->filePosition);
            vsDelete(pat); vsDelete(txt);
        }
        if (fname) {
            fprintf(fp, "\f\n%s,%zu\n", fname, vsLength(body));
            fputs(vsValue(body), fp);
        } else if (f <= maxFile) {
            /* file with no tags: ctags still emits header */
        }
        vsDelete(body);
    }
    /* etags include */
    if (Option.etagsInclude) for (size_t i = 0; i < saCount(Option.etagsInclude); i++) fprintf(fp, "\f\n%s,include\n", saItem(Option.etagsInclude, i));
}

extern strArray *EtagsFileNames;   /* names of files processed in order, for etags headers of tagless files */

void writeAllTags(void) {
    FILE *fp = openTagFile();
    if (Option.outputFormat == OF_ETAGS) {
        /* etags: per file sections even if no tags */
        int maxFile = FileCounter;
        for (int f = 1; f <= maxFile; f++) {
            vString *body = vsNew();
            const char *fname = EtagsFileNames && (size_t)(f-1) < saCount(EtagsFileNames) ? saItem(EtagsFileNames, f-1) : NULL;
            for (size_t i = 0; i < paCount(AllTags); i++) {
                tagEntryInfo *e = paItem(AllTags, i);
                if (e->fileIndex != f) continue;
                if (e->kindIndex == KIND_FILE_INDEX || e->isFileEntry) {
                    vsPrintf(body, "\177%s\001%lu,%ld\n", e->name, e->lineNumber, e->filePosition);
                    continue;
                }
                vString *pat = vsNew();
                bool omitted;
                appendPatternBody(pat, e->sourceLine ? e->sourceLine : "", e->truncateLineAfterTag, e->name, &omitted);
                vString *txt = vsNew();
                for (const char *p = vsValue(pat); *p; p++) { if (*p == '\\' && p[1]) { p++; vsPut(txt, *p); } else vsPut(txt, *p); }
                vsPrintf(body, "%s\177%s\001%lu,%ld\n", vsValue(txt), e->name, e->lineNumber, e->filePosition);
                vsDelete(pat); vsDelete(txt);
            }
            if (fname) {
                fprintf(fp, "\f\n%s,%zu\n", fname, vsLength(body));
                fputs(vsValue(body), fp);
            }
            vsDelete(body);
        }
        if (Option.etagsInclude) for (size_t i = 0; i < saCount(Option.etagsInclude); i++) fprintf(fp, "\f\n%s,include\n", saItem(Option.etagsInclude, i));
        if (fp != stdout) fclose(fp);
        return;
    }
    (void)writeEtags;
    /* pseudo tags first */
    if (Ptags && Option.outputFormat != OF_XREF) {
        ptrArray *plines = paNew(free);
        for (size_t i = 0; i < paCount(Ptags); i++) {
            ptagEntry *p = paItem(Ptags, i);
            vString *l = vsNew();
            if (Option.outputFormat == OF_JSON) {
                vsCat(l, "{\"_type\": \"ptag\"");
                jsonField(l, "name", p->name + 2);
                jsonField(l, "path", p->value);
                jsonField(l, "pattern", p->desc);
                vsPut(l, '}');
            } else {
                vsCat(l, p->name); vsPut(l, '\t'); vsCat(l, p->value); vsCat(l, "\t/");
                for (const char *c = p->desc; *c; c++) { if (*c == '/') vsPut(l, '\\'); vsPut(l, *c); }
                vsPut(l, '/');
            }
            paAdd(plines, vsDetach(l));
        }
        if (Option.sorted == SO_SORTED) paSort(plines, cmpLines);
        else if (Option.sorted == SO_FOLDSORTED) paSort(plines, cmpLinesFold);
        for (size_t i = 0; i < paCount(plines); i++) { fputs(paItem(plines, i), fp); fputc('\n', fp); }
        paDelete(plines);
    }
    ptrArray *lines = paNew(free);
    for (size_t i = 0; i < paCount(AllTags); i++) {
        tagEntryInfo *e = paItem(AllTags, i);
        char *l = NULL;
        switch (Option.outputFormat) {
        case OF_UCTAGS: l = buildCtagsLine(e, true); break;
        case OF_ECTAGS: l = buildCtagsLine(e, false); break;
        case OF_JSON: l = buildJsonLine(e); break;
        case OF_XREF: l = buildXrefLine(e); break;
        default: break;
        }
        if (l) paAdd(lines, l);
    }
    if (Option.sorted == SO_SORTED) paSort(lines, cmpLines);
    else if (Option.sorted == SO_FOLDSORTED) paSort(lines, cmpLinesFold);
    for (size_t i = 0; i < paCount(lines); i++) {
        if (Option.sorted != SO_UNSORTED && i > 0 && strcmp(paItem(lines, i-1), paItem(lines, i)) == 0) continue;
        fputs(paItem(lines, i), fp); fputc('\n', fp);
    }
    paDelete(lines);
    if (fp != stdout) fclose(fp);
}
EOF
echo ok"}

