#include "parse.h"
#include "read.h"
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include <time.h>
#include <sys/stat.h>

ptrArray *AllTags = NULL;
static ptrArray *CorkQueue = NULL;     /* tagEntryInfo* , index 0 is a dummy */
static int FileCounter = 0;
static char *CurrentOutputFileName = NULL;
static int CurrentFileLang = -1;
static time_t CurrentFileMtime = 0;
static unsigned int AnonCounter = 0;

ptagDesc PtagTable[PTAG_COUNT] = {
    { "JSON_OUTPUT_VERSION", false, true, 0, "the version of json output stream format" },
    { "TAG_EXTRA_DESCRIPTION", true, true, 0, "the names and descriptions of enabled extras" },
