    if (Option.etagsInclude) for (size_t i = 0; i < saCount(Option.etagsInclude); i++) fprintf(fp, "\f\n%s,include\n", saItem(Option.etagsInclude, i));
}

extern strArray *EtagsFileNames;   /* names of files processed in order, for etags headers of tagless files */

void writeAllTags(void) {
