                vString *txt = vsNew();
                for (const char *p = vsValue(pat); *p; p++) { if (*p == '\\' && p[1]) { p++; vsPut(txt, *p); } else vsPut(txt, *p); }
                vsPrintf(body, "%s\177%s\001%lu,%ld\n", vsValue(txt), e->name, e->lineNumber, e->filePosition);
