        else if (Option.sorted == SO_FOLDSORTED) paSort(plines, cmpLinesFold);
        for (size_t i = 0; i < paCount(plines); i++) { fputs(paItem(plines, i), fp); fputc('\n', fp); }
        paDelete(plines);
    }
    ptrArray *lines = paNew(free);
    for (size_t i = 0; i < paCount(AllTags); i++) {
        tagEntryInfo *e = paItem(AllTags, i);
        char *l = NULL;
        switch (Option.outputFormat) {
        case OF_UCTAGS: l = buildCtagsLine(e, true); break;
        case OF_ECTAGS: l = buildCtagsLine(e, false); break;
        case OF_JSON: l = buildJsonLine(e); break;
        case OF_XREF: l = buildXrefLine(e); break;
        default: break;
        }
        if (l) paAdd(lines, l);
    }
    if (Option.sorted == SO_SORTED) paSort(lines, cmpLines);
    else if (Option.sorted == SO_FOLDSORTED) paSort(lines, cmpLinesFold);
    for (size_t i = 0; i < paCount(lines); i++) {
        if (Option.sorted != SO_UNSORTED && i > 0 && strcmp(paItem(lines, i-1), paItem(lines, i)) == 0) continue;
        fputs(paItem(lines, i), fp); fputc('\n', fp);
    }
    paDelete(lines);
    if (fp != stdout) fclose(fp);
}
