                    int fi = getLangFieldIndexByName(lang, name);
                    if (fi < 0) error_fatal("no such field: '%s'", name);
                    getLangDef(lang)->fields[fi].enabled = mode;
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLong = true;
        else if (c == '*') {
            if (all) { for (int l = 0; l < LANG_COUNT; l++) { langDef *d = getLangDef(l); for (int i = 0; i < d->nfields; i++) d->fields[i].enabled = mode; } }
            else { langDef *d = getLangDef(lang); for (int i = 0; i < d->nfields; i++) d->fields[i].enabled = mode; }
        } else {
            error_warning("Unsupported parameter '%c' for \"%s\" option", c, option);
        }
    }
    vsDelete(longName);
}

void processLangExtrasOption(const char *langName, const char *param, const char *option) {
    int lang = -1;
    bool all = strcmp(langName, "all") == 0;
    if (!all) {
        lang = getNamedLanguage(langName, 0);
        if (lang < 0) { error_warning("Unknown language: %s (ignoring \"--%s\")", langName, option); return; }
    }
    const char *p = param;
    bool mode = true;
    vString *longName = vsNew();
    bool inLong = false;
    for (; *p; p++) {
        char c = *p;
        if (inLong) {
            if (c == '}') {
                inLong = false;
                const char *name = vsValue(longName);
                if (all) {
                    for (int l = 0; l < LANG_COUNT; l++) { int xi = getLangExtraIndexByName(l, name); if (xi >= 0) getLangDef(l)->extras[xi].enabled = mode; }
                } else {
                    int xi = getLangExtraIndexByName(lang, name);
                    if (xi < 0) error_fatal("no such extra: '%s'", name);
                    getLangDef(lang)->extras[xi].enabled = mode;
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLong = true;
        else if (c == '*') {
            if (all) { for (int l = 0; l < LANG_COUNT; l++) { langDef *d = getLangDef(l); for (int i = 0; i < d->nextras; i++) d->extras[i].enabled = mode; } }
            else { langDef *d = getLangDef(lang); for (int i = 0; i < d->nextras; i++) d->extras[i].enabled = mode; }
        } else {
            error_warning("Unsupported parameter '%c' for \"%s\" option", c, option);
        }
    }
    vsDelete(longName);
}

/* --kinds-<LANG>=[+|-](<kinds>|*) */
void processLangKindsOption(const char *langName, const char *param, const char *optname) {
    bool all = strcmp(langName, "all") == 0;
    int lang = -1;
    if (!all) {
        lang = getNamedLanguage(langName, 0);
        if (lang < 0) { error_warning("Unknown language \"%s\" in \"%s\" option", langName, optname); return; }
    }
    const char *p = param;
    bool mode = true;
    bool inLong = false;
    vString *longName = vsNew();
    if (*p != '+' && *p != '-' && *p != '*' && *p != '{') {
        /* set mode: disable all kinds first */
        if (all) { for (int l = 0; l < LANG_COUNT; l++) for (int k = 0; k < getLanguageKindCount(l); k++) enableKind(l, k, false); }
        else for (int k = 0; k < getLanguageKindCount(lang); k++) enableKind(lang, k, false);
    }
    for (; *p; p++) {
        char c = *p;
        if (inLong) {
            if (c == '}') {
                inLong = false;
                const char *name = vsValue(longName);
                if (all) { for (int l = 0; l < LANG_COUNT; l++) { int k = getKindIndexByName(l, name); if (k >= 0) enableKind(l, k, mode); } }
                else {
                    int k = getKindIndexByName(lang, name);
                    if (k < 0) error_warning("Unsupported kind: '%s' for --%s option", name, optname);
                    else enableKind(lang, k, mode);
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLong = true;
        else if (c == '*') {
            if (all) { for (int l = 0; l < LANG_COUNT; l++) for (int k = 0; k < getLanguageKindCount(l); k++) enableKind(l, k, mode); }
            else for (int k = 0; k < getLanguageKindCount(lang); k++) enableKind(lang, k, mode);
        } else {
            if (all) { for (int l = 0; l < LANG_COUNT; l++) { int k = getKindIndexByLetter(l, c); if (k >= 0) enableKind(l, k, mode); } }
            else {
                int k = getKindIndexByLetter(lang, c);
                if (k < 0) error_warning("Unsupported kind: '%c' for --%s option", c, optname);
                else enableKind(lang, k, mode);
            }
        }
    }
    vsDelete(longName);
}

/* --roles-<LANG>.<kind>=[+|-][<roles>|*] */
void processLangRolesOption(const char *option, const char *param) {
    const char *rest;
    int lang = langFromOptionSuffix(option, "roles-", &rest, true, true);
    if (lang == -1) { error_warning("Unknown language \"%s\" in \"%s\" option", option + 6, option); return; }
    if (!rest) { error_fatal("no kind specified in \"--%s\" option", option); return; }
    bool allLang = (lang == -2);
    /* kind spec: letter or {name} or * */
    for (int l = 0; l < LANG_COUNT; l++) {
        if (!allLang && l != lang) continue;
        int kinds[256]; int nk = 0;
        if (rest[0] == '*') { for (int k = 0; k < getLanguageKindCount(l); k++) kinds[nk++] = k; }
        else if (rest[0] == '{') { const char *e = strchr(rest, '}'); char *n = xstrndup(rest + 1, e ? (size_t)(e - rest - 1) : strlen(rest + 1)); int k = getKindIndexByName(l, n); if (k >= 0) kinds[nk++] = k; else if (!allLang) error_fatal("no such kind: '%s'", n); free(n); }
        else { int k = getKindIndexByLetter(l, rest[0]); if (k >= 0) kinds[nk++] = k; else if (!allLang) error_fatal("no such kind: '%c'", rest[0]); }
        bool mode = true;
        const char *p = param;
        if (*p != '+' && *p != '-') { for (int i = 0; i < nk; i++) { kindDef *kd = getLanguageKind(l, kinds[i]); for (int r = 0; r < kd->nroles; r++) kd->roles[r].enabled = false; } }
        vString *longName = vsNew(); bool inLong = false;
        for (; *p; p++) {
            char c = *p;
            if (inLong) {
                if (c == '}') {
                    inLong = false;
                    for (int i = 0; i < nk; i++) { int r = getRoleIndexByName(l, kinds[i], vsValue(longName)); if (r >= 0) enableRole(l, kinds[i], r, mode); else if (!allLang) error_fatal("no such role: '%s'", vsValue(longName)); }
                    vsClear(longName);
                } else vsPut(longName, c);
                continue;
            }
            if (c == '+') mode = true;
            else if (c == '-') mode = false;
            else if (c == '{') inLong = true;
            else if (c == '*') { for (int i = 0; i < nk; i++) { kindDef *kd = getLanguageKind(l, kinds[i]); for (int r = 0; r < kd->nroles; r++) kd->roles[r].enabled = mode; } }
            else error_fatal("unexpected char in role specification: '%c'", c);
        }
        vsDelete(longName);
    }
}

/* --pseudo-tags */
static void processPseudoTagsOption(const char *option, const char *param) {
    const char *p = param;
    bool mode = true;
    if (*p == '\0') { for (int i = 0; i < PTAG_COUNT; i++) Option.ptags[i] = true; return; }
    if (*p != '+' && *p != '-' && *p != '*') for (int i = 0; i < PTAG_COUNT; i++) Option.ptags[i] = false;
    (void)option;
    vString *name = vsNew();
    while (*p) {
        if (*p == '+') { mode = true; p++; continue; }
        if (*p == '-') { mode = false; p++; continue; }
        if (*p == '*') { for (int i = 0; i < PTAG_COUNT; i++) Option.ptags[i] = mode; p++; continue; }
        if (*p == '{') { p++; vsClear(name); while (*p && *p != '}') vsPut(name, *p++); if (*p) p++; }
        else { vsClear(name); while (*p && *p != ',' && *p != '+' && *p != '-') vsPut(name, *p++); }
        if (*p == ',') p++;
        bool found = false;
        for (int i = 0; i < PTAG_COUNT; i++) if (strcmp(PtagTable[i].name, vsValue(name)) == 0) { Option.ptags[i] = mode; found = true; }
        if (!found) error_fatal("Unknown pseudo tag name: %s", vsValue(name));
    }
    vsDelete(name);
}

/* --languages */
static void processLanguagesOption(const char *option, const char *param) {
    char *copy = xstrdup(param);
    bool mode = true;
    const char *p = copy;
    if (*p != '+' && *p != '-') {
        enableLanguages(false);
    }
    char *tok = copy;
    while (tok && *tok) {
        char *comma = strchr(tok, ',');
        if (comma) *comma = 0;
        char *name = tok;
        if (*name == '+') { mode = true; name++; }
        else if (*name == '-') { mode = false; name++; }
        if (*name) {
            if (strcmp(name, "all") == 0) enableLanguages(mode);
            else {
                int lang = getNamedLanguageFull(name, 0, true);
                if (lang < 0) error_warning("Unknown language \"%s\" in \"%s\" option", name, option);
                else enableLanguage(lang, mode);
            }
        }
        tok = comma ? comma + 1 : NULL;
    }
    free(copy);
}

/* --exclude */
static void processExcludeOption(const char *param, strArray *list) {
    if (*param == '\0') { saClear(list); return; }
    if (param[0] == '@') {
        FILE *fp = fopen(param + 1, "r");
        if (!fp) error_fatal_perror("cannot open \"%s\"", param + 1);
        char buf[4096];
        while (fgets(buf, sizeof buf, fp)) { char *t = strTrim(buf); if (*t) saAdd(list, t); }
        fclose(fp);
    } else saAdd(list, param);
}

bool isExcludedFile(const char *name, bool isDir) {
    (void)isDir;
    const char *base = baseFilename(name);
    bool excluded = false;
    for (size_t i = 0; i < saCount(Option.excludes); i++) {
        const char *pat = saItem(Option.excludes, i);
        if (stringMatch(base, pat, false)) { excluded = true; break; }
        if (base != name && stringMatch(name, pat, false)) { excluded = true; break; }
    }
    if (excluded) {
        for (size_t i = 0; i < saCount(Option.excludeExceptions); i++) {
            const char *pat = saItem(Option.excludeExceptions, i);
            if (stringMatch(base, pat, false) || (base != name && stringMatch(name, pat, false))) { excluded = false; break; }
        }
    }
    return excluded;
}

bool isIncludeFile(const char *fileName) {
    const char *ext = fileExtension(fileName);
    return saContains(Option.headerExt, ext);
}

/* -h */
static void processHeaderListOption(const char *param) {
    if (strcmp(param, "default") == 0) {
        saClear(Option.headerExt);
        for (int i = 0; HeaderExtensions[i]; i++) saAdd(Option.headerExt, HeaderExtensions[i]);
        return;
    }
    bool add = false;
    if (*param == '+') { add = true; param++; }
    if (!add) saClear(Option.headerExt);
    const char *p = param;
    while (*p) {
        if (*p == '.') p++;
        const char *s = p;
        while (*p && *p != '.') p++;
        if (p > s) { char *e = xstrndup(s, p - s); saAdd(Option.headerExt, e); free(e); }
    }
}

/* ---- option files ---- */
static strArray *parseOptionLine(const char *line) {
    /* split by whitespace, respecting quotes (simple) */
    strArray *a = saNew();
    const char *p = line;
    vString *cur = vsNew();
    while (*p) {
        while (isspace((unsigned char)*p)) p++;
        if (!*p) break;
        vsClear(cur);
        bool any = false;
        while (*p && !isspace((unsigned char)*p)) {
            if (*p == '"') { p++; while (*p && *p != '"') vsPut(cur, *p++); if (*p) p++; any = true; }
            else if (*p == '\'') { p++; while (*p && *p != '\'') vsPut(cur, *p++); if (*p) p++; any = true; }
            else { vsPut(cur, *p++); any = true; }
        }
        if (any) saAdd(a, vsValue(cur));
    }
    vsDelete(cur);
    return a;
}

static void processOptionsFile(const char *path, bool maybe);
static void processArgs(strArray *args, const char *source, bool isCmdLine);

static int cmpStrPtr(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }

static void processOptionsDirectory(const char *dir) {
    DIR *d = opendir(dir);
    if (!d) return;
    strArray *files = saNew();
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strEndsWith(ent->d_name, ".ctags")) saAdd(files, ent->d_name);
    }
    closedir(d);
    qsort(files->items, files->count, sizeof(char*), cmpStrPtr);
    for (size_t i = 0; i < saCount(files); i++) {
        char *path = xmalloc(strlen(dir) + strlen(saItem(files, i)) + 2);
        sprintf(path, "%s/%s", dir, saItem(files, i));
        if (isRegularFile(path)) processOptionsFile(path, true);
        free(path);
    }
    saDelete(files);
}

static void processOptionsFile(const char *path, bool maybe) {
    if (isDirectory(path)) { processOptionsDirectory(path); return; }
    FILE *fp = fopen(path, "r");
    if (!fp) {
        if (maybe) return;
        error_fatal_perror("cannot open option file \"%s\"", path);
        return;
    }
    char buf[8192];
    vString *acc = vsNew();
    while (fgets(buf, sizeof buf, fp)) {
        size_t n = strlen(buf);
        while (n && (buf[n-1] == '\n' || buf[n-1] == '\r')) buf[--n] = 0;
        /* line continuation with trailing backslash */
        if (n && buf[n-1] == '\\') { buf[n-1] = 0; vsCat(acc, buf); continue; }
        vsCat(acc, buf);
        char *line = strTrim(vsValue(acc));
        if (*line && *line != '#') {
            if (strncmp(line, "--", 2) == 0 || line[0] == '-') {
                strArray *a = saNew();
                saAdd(a, line);
                processArgs(a, path, false);
                saDelete(a);
            } else {
                /* lines not beginning with - are treated as file names? ctags: options only */
                strArray *a = parseOptionLine(line);
                processArgs(a, path, false);
                saDelete(a);
            }
        }
        vsClear(acc);
    }
    vsDelete(acc);
    fclose(fp);
}

void readOptionConfiguration(void) {
    if (processedOptionFiles) return;
    processedOptionFiles = true;
    const char *xdg = getenv("XDG_CONFIG_HOME");
    const char *home = getenv("HOME");
    char path[4096];
    if (xdg && *xdg) { snprintf(path, sizeof path, "%s/ctags", xdg); processOptionsDirectory(path); }
    else if (home && *home) { snprintf(path, sizeof path, "%s/.config/ctags", home); processOptionsDirectory(path); }
    if (home && *home) { snprintf(path, sizeof path, "%s/.ctags.d", home); processOptionsDirectory(path); }
    processOptionsDirectory(".ctags.d");
    processOptionsDirectory("ctags.d");
}

