static void processShortOption(char c, const char *param) {
    switch (c) {
    case 'a': Option.append = true; break;
    case 'B': Option.backward = true; break;
    case 'D': {
        /* -D macro=def : CPreProcessor define */
        char *opt = xmalloc(strlen(param) + 64);
        sprintf(opt, "param-CPreProcessor.define");
        processParamOption(opt, param);
        free(opt);
        break;
    }
    case 'e': Option.outputFormat = OF_ETAGS; Option.etags = true; break;
    case 'f': case 'o':
        free(Option.tagFileName); Option.tagFileName = xstrdup(param); Option.tagFileNameSpecified = true; break;
    case 'F': Option.backward = false; break;
    case 'G': Option.guessLanguageEagerly = true; break;
    case 'h': processHeaderListOption(param); break;
    case 'I': {
        char *opt = xstrdup("param-CPreProcessor.ignore");
        /* -I may be a comma separated list or @file */
        if (param[0] == '@') {
            FILE *fp = fopen(param + 1, "r");
            if (!fp) error_fatal_perror("cannot open \"%s\"", param + 1);
            char buf[4096];
            while (fgets(buf, sizeof buf, fp)) { char *t = strTrim(buf); if (*t) processParamOption(opt, t); }
            fclose(fp);
        } else {
            char *copy = xstrdup(param);
            for (char *tok = strtok(copy, ","); tok; tok = strtok(NULL, ",")) processParamOption(opt, tok);
            free(copy);
        }
        free(opt);
        break;
    }
    case 'L': free(Option.fileList); Option.fileList = xstrdup(param); break;
    case 'n': Option.locate = EX_LINENUM; break;
    case 'N': Option.locate = EX_PATTERN; break;
    case 'R': Option.recurse = true; break;
    case 'u': Option.sorted = SO_UNSORTED; break;
    case 'V': VerboseEnabled = true; break;
    case 'x': Option.outputFormat = OF_XREF; Option.xref = true; break;
    case '?': printHelp(false); exit(0);
    default: error_fatal("Unknown option: -%c", c);
    }
}

static bool shortOptionTakesParam(char c) { return strchr("DfohILl", c) != NULL; }

static void processArgs(strArray *args, const char *source, bool isCmdLine) {
    (void)source;
    for (size_t i = 0; i < saCount(args); i++) {
        const char *arg = saItem(args, i);
        if (strcmp(arg, "--") == 0 && isCmdLine) {
            /* rest are files */
            for (size_t j = i + 1; j < saCount(args); j++) saAdd(FileArgs, saItem(args, j));
            return;
        }
        if (arg[0] == '-' && arg[1] == '-') {
            const char *eq = strchr(arg + 2, '=');
            char *option = eq ? xstrndup(arg + 2, eq - arg - 2) : xstrdup(arg + 2);
            const char *param = eq ? eq + 1 : NULL;
            processLongOption(option, param, isCmdLine);
            free(option);
        } else if (arg[0] == '-' && arg[1] != '\0') {
            for (const char *p = arg + 1; *p; p++) {
                if (shortOptionTakesParam(*p)) {
                    const char *param;
                    if (p[1]) param = p + 1;
                    else if (i + 1 < saCount(args)) param = saItem(args, ++i);
                    else { error_fatal("Missing parameter for \"-%c\" option", *p); return; }
                    processShortOption(*p, param);
                    break;
                } else processShortOption(*p, NULL);
            }
        } else {
            if (saCount(FileArgs) > 0 || filesSpecifiedByOption) { }
            saAdd(FileArgs, arg);
            filesSpecifiedByOption = true;
        }
        if (isCmdLine && FileArgs->count > 0) {
            /* ctags: options after file names are errors for -o etc. (not strictly) */
        }
    }
}

void processOptionLine(const char *line, const char *source) {
    strArray *a = parseOptionLine(line);
    processArgs(a, source, false);
    saDelete(a);
}

void parseCommandLineOptions(int argc, char **argv) {
    strArray *args = saNew();
    bool sawFile = false;
    for (int i = 1; i < argc; i++) {
        saAdd(args, argv[i]);
    }
    /* ctags: once a file name appears, options -o/-f following are rejected: "-o option may not follow a file name" */
    for (size_t i = 0; i < saCount(args); i++) {
        const char *arg = saItem(args, i);
        if (arg[0] != '-' || arg[1] == '\0') sawFile = true;
        else if (sawFile && arg[0] == '-' && arg[1] != '-') {
            for (const char *p = arg + 1; *p; p++) {
                if (*p == 'o' || *p == 'f') error_fatal("-%c option may not follow a file name", *p);
                if (shortOptionTakesParam(*p)) break;
            }
        }
    }
    processArgs(args, "command line", true);
    saDelete(args);
}

void checkOptions(void) {
    if (Option.outputFormat == OF_ETAGS) {
        if (Option.tagRelative == TREL_NO && !Option.tagFileNameSpecified) Option.tagRelative = TREL_YES;
        else if (Option.tagRelative == TREL_NO) Option.tagRelative = TREL_YES;
    }
    if (Option.xref) {
        Option.sorted = Option.sorted;
    }
    setDefaultTagFileName();
}
