static bool paramEqual(const char *a, const char *b) { return strcmp(a, b) == 0; }

static bool getBooleanOption(const char *option, const char *param) {
    if (param == NULL || param[0] == '\0' || paramEqual(param, "yes") || paramEqual(param, "1") || paramEqual(param, "true") || paramEqual(param, "on")) return true;
    if (paramEqual(param, "no") || paramEqual(param, "0") || paramEqual(param, "false") || paramEqual(param, "off")) return false;
    error_fatal("Invalid value for \"%s\" option", option);
    return false;
}

/* ---- field / extra processing ---- */
int getFieldIndexByLetter(char c) {
    for (int i = 0; i < FIELD_COUNT; i++) if (FieldLetters[i] == c) return i;
    return -1;
}
static int getFieldIndexByName(const char *name) {
    for (int i = 0; i < FIELD_COUNT; i++) if (FieldNames[i] && strcmp(FieldNames[i], name) == 0) return i;
    return -1;
}
static int getXtagIndexByLetter(char c) {
    for (int i = 0; i < XTAG_COUNT; i++) if (XtagLetters[i] == c && c != '-') return i;
    return -1;
}
static int getXtagIndexByName(const char *name) {
    for (int i = 0; i < XTAG_COUNT; i++) if (strcmp(XtagNames[i], name) == 0) return i;
    return -1;
}

static void enableField(int f, bool mode) { Option.fields[f] = mode; Option.fieldsExplicit[f] = true; }
static void enableXtag(int x, bool mode) { Option.extras[x] = mode; Option.extrasExplicit[x] = true; }

/* parse "[+|-][flags|*]" with {longname} support */
static void processFieldsOption(const char *option, const char *param) {
    const char *p = param;
    bool mode = true;
    bool inLongName = false;
    if (*p == '*') {
        for (int i = 0; i < FIELD_COUNT; i++) if (!FieldFixed[i]) enableField(i, true);
        /* also language specific fields of all languages */
        for (int l = 0; l < LANG_COUNT; l++) { langDef *d = getLangDef(l); for (int i = 0; i < d->nfields; i++) d->fields[i].enabled = true; }
        p++;
        if (*p == '\0') return;
    } else if (*p != '+' && *p != '-') {
        /* set mode: disable all non-fixed, then enable listed */
        for (int i = 0; i < FIELD_COUNT; i++) if (!FieldFixed[i]) Option.fields[i] = false;
    }
    vString *longName = vsNew();
    for (; *p; p++) {
        char c = *p;
        if (inLongName) {
            if (c == '}') {
                inLongName = false;
                const char *name = vsValue(longName);
                char *dot = strchr(vsValue(longName), '.');
                if (dot) {
                    *dot = 0;
                    int lang = getNamedLanguage(name, 0);
                    if (lang < 0) error_fatal("no such language: '%s'", name);
                    int fi = getLangFieldIndexByName(lang, dot + 1);
                    if (fi < 0) error_fatal("no such field: '%s'", dot + 1);
                    getLangDef(lang)->fields[fi].enabled = mode;
                } else {
                    int fi = getFieldIndexByName(name);
                    if (fi < 0) {
                        error_fatal("no such field: '%s'", name);
                    }
                    if (!FieldFixed[fi]) enableField(fi, mode);
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLongName = true;
        else if (c == '*') {
            for (int i = 0; i < FIELD_COUNT; i++) if (!FieldFixed[i]) enableField(i, mode);
        } else {
            int fi = getFieldIndexByLetter(c);
            if (fi < 0) error_warning("Unsupported parameter '%c' for \"%s\" option", c, option);
            else if (!FieldFixed[fi]) enableField(fi, mode);
        }
    }
    vsDelete(longName);
}

static void processExtrasOption(const char *option, const char *param) {
    const char *p = param;
    bool mode = true;
    bool inLongName = false;
    if (*p == '*') {
        for (int i = 0; i < XTAG_COUNT; i++) enableXtag(i, true);
        for (int l = 0; l < LANG_COUNT; l++) { langDef *d = getLangDef(l); for (int i = 0; i < d->nextras; i++) d->extras[i].enabled = true; }
        p++;
        if (*p == '\0') return;
    } else if (*p != '+' && *p != '-') {
        for (int i = 0; i < XTAG_COUNT; i++) Option.extras[i] = false;
    }
    vString *longName = vsNew();
    for (; *p; p++) {
        char c = *p;
        if (inLongName) {
            if (c == '}') {
                inLongName = false;
                const char *name = vsValue(longName);
                char *dot = strchr(vsValue(longName), '.');
                if (dot) {
                    *dot = 0;
                    int lang = getNamedLanguage(name, 0);
                    if (lang < 0) error_fatal("no such language: '%s'", name);
                    int xi = getLangExtraIndexByName(lang, dot + 1);
                    if (xi < 0) error_fatal("no such extra: '%s'", dot + 1);
                    getLangDef(lang)->extras[xi].enabled = mode;
                } else {
                    int xi = getXtagIndexByName(name);
                    if (xi < 0) error_fatal("no such extra: '%s'", name);
                    enableXtag(xi, mode);
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLongName = true;
        else if (c == '*') { for (int i = 0; i < XTAG_COUNT; i++) enableXtag(i, mode); }
        else {
            int xi = getXtagIndexByLetter(c);
            if (xi < 0) error_warning("Unsupported parameter '%c' for \"%s\" option", c, option);
            else enableXtag(xi, mode);
        }
    }
    vsDelete(longName);
}

void processLangFieldsOption(const char *langName, const char *param, const char *option) {
    int lang = -1;
    bool all = strcmp(langName, "all") == 0;
    if (!all) {
        lang = getNamedLanguage(langName, 0);
        if (lang < 0) { error_warning("Unknown language: %s (ignoring \"--%s\")", langName, option); return; }
    }
    const char *p = param;
    bool mode = true;
    if (*p != '+' && *p != '-' && *p != '*' && *p != '{') {
        /* set mode: unsupported for fields? ctags requires + or - or { */
    }
    vString *longName = vsNew();
    bool inLong = false;
    for (; *p; p++) {
        char c = *p;
        if (inLong) {
            if (c == '}') {
                inLong = false;
                const char *name = vsValue(longName);
                if (all) {
                    for (int l = 0; l < LANG_COUNT; l++) { int fi = getLangFieldIndexByName(l, name); if (fi >= 0) getLangDef(l)->fields[fi].enabled = mode; }
                } else {
                    int fi = getLangFieldIndexByName(lang, name);
                    if (fi < 0) error_fatal("no such field: '%s'", name);
                    getLangDef(lang)->fields[fi].enabled = mode;
                }
                vsClear(longName);
            } else vsPut(longName, c);
            continue;
        }
        if (c == '+') mode = true;
        else if (c == '-') mode = false;
        else if (c == '{') inLong = true;
        else if (c == '*') {
            if (all) { for (int l = 0; l < LANG_COUNT; l++) { langDef *d = getLangDef(l); for (int i = 0; i < d->nfields; i++) d->fields[i].enabled = mode; } }
            else { langDef *d = getLangDef(lang); for (int i = 0; i < d->nfields; i++) d->fields[i].enabled = mode; }
        } else {
            error_warning("Unsupported parameter '%c' for \"%s\" option", c, option);
        }
    }
    vsDelete(longName);
}

