static bool processLangSpecificOption(const char *option, const char *param) {
    /* --kinds-<LANG>, --<LANG>-kinds, --fields-<LANG>, --extras-<LANG>, --regex-<LANG>, --mline-regex-<LANG>, --kinddef-<LANG>, --map-<LANG>, --alias-<LANG>, --param-<LANG>.<name>, --roles-<LANG>.<kind>, --input-encoding-<LANG>, --_fielddef-<LANG>, --_extradef-<LANG>, --_roledef-<LANG>.<kind>, --_scopesep-<LANG>, --_pretend-<NEW>, --_tabledef-<LANG>, --_mtable-regex-<LANG>, --_mtable-extend-<LANG>, --_prelude-<LANG>, --_sequel-<LANG>, --_paramdef-<LANG> */
    struct { const char *prefix; int kind; } prefixes[] = {
        { "kinds-", 1 }, { "fields-", 2 }, { "extras-", 3 }, { "regex-", 4 }, { "mline-regex-", 5 }, { "kinddef-", 6 }, { "map-", 7 }, { "alias-", 8 },
        { "param-", 9 }, { "roles-", 10 }, { "input-encoding-", 11 }, { "_fielddef-", 12 }, { "_extradef-", 13 }, { "_roledef-", 14 }, { "_scopesep-", 15 },
        { "_pretend-", 16 }, { "_tabledef-", 17 }, { "_mtable-regex-", 18 }, { "_mtable-extend-", 19 }, { "_prelude-", 20 }, { "_sequel-", 21 }, { "_paramdef-", 22 },
        { "extra-", 23 }, { "_roles-", 10 },
        { NULL, 0 } };
    for (int i = 0; prefixes[i].prefix; i++) {
        if (strStartsWith(option, prefixes[i].prefix)) {
            const char *langName = option + strlen(prefixes[i].prefix);
            if (!param && prefixes[i].kind != 0) { error_fatal("Missing parameter for \"--%s\" option", option); }
            switch (prefixes[i].kind) {
            case 1: processLangKindsOption(langName, param, option); return true;
            case 2: processLangFieldsOption(langName, param, option); return true;
            case 3: case 23: processLangExtrasOption(langName, param, option); return true;
            case 4: processRegexOption(option, param, REG_PARSER_SINGLE_LINE); return true;
            case 5: processRegexOption(option, param, REG_PARSER_MULTI_LINE); return true;
            case 6: processKinddefOption(option, param); return true;
            case 7: processMapOption(option, param); return true;
            case 8: processAliasOption(option, param); return true;
            case 9: processParamOption(option, param); return true;
            case 10: processLangRolesOption(option, param); return true;
            case 11: return true;
            case 12: processFielddefOption(option, param); return true;
            case 13: processExtradefOption(option, param); return true;
            case 14: processRoledefOption(option, param); return true;
            case 15: processScopesepOption(option, param); return true;
            case 16: processPretendOption(option, param); return true;
            case 17: processTabledefOption(option, param); return true;
            case 18: processRegexOption(option, param, REG_PARSER_MULTI_TABLE); return true;
            case 19: processMtableExtendOption(option, param); return true;
            case 20: case 21: return true;
            case 22: {
                const char *comma = strchr(param, ',');
                int lang = getNamedLanguage(langName, 0);
                if (lang < 0) error_fatal("Unknown language \"%s\" in \"%s\" option", langName, option);
                langDef *d = getLangDef(lang);
                d->params = xrealloc((void*)d->params, (d->nparams + 1) * sizeof(paramDef));
                d->params[d->nparams].name = comma ? xstrndup(param, comma - param) : xstrdup(param);
                d->params[d->nparams].desc = comma ? xstrdup(comma + 1) : xstrdup("");
                d->nparams++;
                return true;
            }
            }
        }
    }
    /* --<LANG>-kinds (old style) */
    const char *k = strstr(option, "-kinds");
    if (k && k[6] == '\0') {
        char *langName = xstrndup(option, k - option);
        processLangKindsOption(langName, param, option);
        free(langName);
        return true;
    }
    return false;
}

static void processLongOption(const char *option, const char *param, bool fromCmdLine) {
    (void)fromCmdLine;
    /* boolean options */
    for (int i = 0; BooleanLongOptions[i]; i++) {
        if (strcmp(option, BooleanLongOptions[i]) == 0) {
            bool v = getBooleanOption(option, param);
            if (strcmp(option, "append") == 0) Option.append = v;
            else if (strcmp(option, "file-scope") == 0) enableXtag(XTAG_FILE_SCOPE, v);
            else if (strcmp(option, "file-tags") == 0) enableXtag(XTAG_FILE_NAMES, v);
            else if (strcmp(option, "filter") == 0) Option.filter = v;
            else if (strcmp(option, "guess-language-eagerly") == 0) Option.guessLanguageEagerly = v;
            else if (strcmp(option, "line-directives") == 0) Option.lineDirectives = v;
            else if (strcmp(option, "links") == 0) Option.followLinks = v;
