void colAddRow(colTable *t, ...) {
    va_list ap; va_start(ap, t);
    char **row = xmalloc(t->ncols * sizeof(char*));
    for (int i = 0; i < t->ncols; i++) { const char *s = va_arg(ap, const char *); row[i] = xstrdup(s ? s : ""); }
