    paAdd(t->rows, row);
}
void colPrint(colTable *t, FILE *fp) {
    size_t *w = xcalloc(t->ncols, sizeof(size_t));
    if (Option.withListHeader) {
        for (int c = 0; c < t->ncols; c++) w[c] = strlen(t->headers[c]) + (c == 0 ? 1 : 0);
    }
    for (size_t r = 0; r < paCount(t->rows); r++) {
        char **row = paItem(t->rows, r);
        for (int c = 0; c < t->ncols; c++) { size_t l = strlen(row[c]); if (l > w[c]) w[c] = l; }
    }
    if (Option.withListHeader) {
        if (Option.machinable) {
            for (int c = 0; c < t->ncols; c++) fprintf(fp, "%s%s%s", c == 0 ? "#" : "", t->headers[c], c + 1 < t->ncols ? "\t" : "\n");
        } else {
            for (int c = 0; c < t->ncols; c++) {
                char *h = xmalloc(strlen(t->headers[c]) + 2);
                sprintf(h, "%s%s", c == 0 ? "#" : "", t->headers[c]);
                if (c + 1 < t->ncols) fprintf(fp, "%-*s ", (int)w[c], h);
                else fprintf(fp, "%s\n", h);
                free(h);
            }
        }
    }
    for (size_t r = 0; r < paCount(t->rows); r++) {
        char **row = paItem(t->rows, r);
        for (int c = 0; c < t->ncols; c++) {
            if (Option.machinable) fprintf(fp, "%s%s", row[c], c + 1 < t->ncols ? "\t" : "\n");
            else if (c + 1 < t->ncols) {
                if (t->rightAlign && t->rightAlign[c]) fprintf(fp, "%*s ", (int)w[c], row[c]);
                else fprintf(fp, "%-*s ", (int)w[c], row[c]);
            } else fprintf(fp, "%s\n", row[c]);
        }
    }
    free(w);
}
void colDelete(colTable *t) {
