static int cmpLangStrcmp(const void *a, const void *b) { return strcmp(getLanguageName(*(const int*)a), getLanguageName(*(const int*)b)); }
static int *sortedLangs(int *n, bool caseInsensitive) {
    int *arr = xmalloc(LANG_COUNT * sizeof(int));
    int k = 0;
    for (int i = 0; i < LANG_COUNT; i++) arr[k++] = i;
    *n = k;
    if (caseInsensitive) {
        for (int i = 0; i < k; i++) for (int j = i + 1; j < k; j++) if (strcasecmp(getLanguageName(arr[i]), getLanguageName(arr[j])) > 0) { int t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
    } else qsort(arr, k, sizeof(int), cmpLangStrcmp);
    return arr;
}

