    langDef *d = getLangDef(lang);
    kindDef **ks = xmalloc((d->nkinds + 1) * sizeof(kindDef*));
    for (int i = 0; i < d->nkinds; i++) ks[i] = &d->kinds[i];
    qsort(ks, d->nkinds, sizeof(kindDef*), cmpKindLetter);
    for (int i = 0; i < d->nkinds; i++) {
        kindDef *k = ks[i];
        char nroles[16], ver[16];
        snprintf(nroles, sizeof nroles, "%d", k->nroles);
        snprintf(ver, sizeof ver, "%d", k->version);
        if (withLang) colAddRow(t, d->name, k->letter, k->name, k->enabled ? "yes" : "no", k->refonly ? "yes" : "no", nroles, k->master ? k->master : "NONE", ver, k->desc);
        else colAddRow(t, k->letter, k->name, k->enabled ? "yes" : "no", k->refonly ? "yes" : "no", nroles, k->master ? k->master : "NONE", ver, k->desc);
    }
    free(ks);
}
static void printKindsSimple(int lang, bool indent) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nkinds; i++) {
        kindDef *k = &d->kinds[i];
        printf("%s%s  %s%s\n", indent ? "    " : "", k->letter, k->desc, k->enabled ? "" : " [off]");
    }
}
void listKinds(const char *arg, bool full) {
    bool all;
    int lang = resolveLangArg(arg, full ? "list-kinds-full" : "list-kinds", &all);
    if (full) {
        static const char *const hAll[] = { "LANGUAGE", "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
        static const bool rAll[] = { false, false, false, false, false, false, false, true, false };
        static const char *const hOne[] = { "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
        static const bool rOne[] = { false, false, false, false, false, false, true, false };
        colTable *t = all ? colNew(9, hAll, rAll) : colNew(8, hOne, rOne);
        if (all) { int n; int *ls = sortedLangs(&n, false); for (int i = 0; i < n; i++) addKindRows(t, ls[i], true); free(ls); }
