    static const bool r[] = { false, false, false, false, false, true, false };
    colTable *t = colNew(7, h, r);
    if (all) {
        /* order: anonymous(-), F f g p q r s z : sorted by letter with '-' first */
        static const int order[] = { XTAG_ANONYMOUS, XTAG_FILE_SCOPE, XTAG_FILE_NAMES, XTAG_GUEST, XTAG_PSEUDO_TAGS, XTAG_QUALIFIED_TAGS, XTAG_REFERENCE_TAGS, XTAG_SUBPARSER, XTAG_NULLTAG };
        for (int i = 0; i < XTAG_COUNT; i++) {
