    if (all) {
        int n; int *ls = sortedLangs(&n, false);
        for (int i = 0; i < n; i++) { langDef *d = getLangDef(ls[i]); for (int p = 0; p < d->nparams; p++) colAddRow(t, d->name, d->params[p].name, d->params[p].desc); }
        free(ls);
    } else { langDef *d = getLangDef(lang); for (int p = 0; p < d->nparams; p++) colAddRow(t, d->params[p].name, d->params[p].desc); }
    colPrint(t, stdout); colDelete(t);
}

/* ---- aliases ---- */
void listAliases(const char *arg) {
