void listOutputFormats(void) {
    printf("#OFORMAT DEFAULT AVAILABLE NULLTAG \n");
    printf("e-ctags       no       yes      no \n");
    printf("etags         no       yes      no \n");
    printf("json          no       yes     yes \n");
    printf("u-ctags      yes       yes      no \n");
    printf("xref          no       yes     yes \n");
}
void listPseudoTags(void) {
    static const char *const h[] = { "NAME", "ENABLED", "VER", "DESCRIPTION" };
    static const bool r[] = { false, false, true, false };
    colTable *t = colNew(4, h, r);
    for (int i = 0; i < PTAG_COUNT; i++) {
        char ver[16]; snprintf(ver, sizeof ver, "%d", PtagTable[i].version);
        colAddRow(t, PtagTable[i].name, Option.ptags[i] ? "on" : "off", ver, PtagTable[i].desc);
    }
    colPrint(t, stdout); colDelete(t);
}

void describeLanguage(const char *name) {
    int lang = getNamedLanguageFull(name, 0, true);
    if (lang < 0) error_fatal("Unknown language \"%s\" in \"describe-language\" option", name);
    parserObject *p = getParser(lang);
    langDef *d = p->def;
    const char *rule = "-------------------------------------------------------";
    printf("About %s language\n=======================================================\n", d->name);
    printf("enabled: %s\nversion: %d.%d\n\n", d->enabled ? "yes" : "no", d->verCurrent, d->verAge);
    printf("Mappings/rexprs\n%s\n", rule);
    for (int i = 0; i < d->nrexprs; i++) printf(" %s\n", d->rexprs[i].pattern);
    printf("\n\nMappings/patterns\n%s\n", rule);
    for (size_t i = 0; i < saCount(p->pats); i++) printf(" %s\n", saItem(p->pats, i));
    printf("\n\nMappings/extensions\n%s\n", rule);
    for (size_t i = 0; i < saCount(p->exts); i++) printf(" *.%s\n", saItem(p->exts, i));
    printf("\n\nAliases\n%s\n", rule);
    {
        static const char *const h[] = { "ALIAS" };
        colTable *t = colNew(1, h, NULL);
        for (size_t i = 0; i < saCount(p->aliases); i++) colAddRow(t, saItem(p->aliases, i));
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nKinds\n%s\n", rule);
    {
        static const char *const hOne[] = { "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
        static const bool rOne[] = { false, false, false, false, false, false, true, false };
        colTable *t = colNew(8, hOne, rOne);
        addKindRows(t, lang, false);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nRoles\n%s\n", rule);
    {
        static const char *const hOne[] = { "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
        static const bool rOne[] = { false, false, false, true, false };
        colTable *t = colNew(5, hOne, rOne);
        addRoleRows(t, lang, NULL, false);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nFields\n%s\n", rule);
    {
        static const char *const h[] = { "LETTER", "NAME", "ENABLED", "LANGUAGE", "JSTYPE", "FIXED", "OP", "VER", "DESCRIPTION" };
        static const bool r[] = { false, false, false, false, false, false, false, true, false };
        colTable *t = colNew(9, h, r);
        addLangFieldRows(t, lang);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nExtras\n%s\n", rule);
    {
        static const char *const h[] = { "LETTER", "NAME", "ENABLED", "LANGUAGE", "FIXED", "VER", "DESCRIPTION" };
        static const bool r[] = { false, false, false, false, false, true, false };
        colTable *t = colNew(7, h, r);
        addLangExtraRows(t, lang);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nParameters\n%s\n", rule);
    {
        static const char *const hOne[] = { "NAME", "DESCRIPTION" };
        colTable *t = colNew(2, hOne, NULL);
        for (int i = 0; i < d->nparams; i++) colAddRow(t, d->params[i].name, d->params[i].desc);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nSub parsers stacked on this parser\n%s\n", rule);
    {
        static const char *const h[] = { "NAME", "BASEPARSER", "DIRECTIONS" };
        colTable *t = colNew(3, h, NULL);
        int n; int *ls = sortedLangs(&n, false);
        for (int i = 0; i < n; i++) {
            langDef *sd = getLangDef(ls[i]);
            for (int j = 0; j < sd->nsubparsers; j++) if (getNamedLanguageFull(sd->subparsers[j].base, 0, true) == lang) colAddRow(t, sd->name, sd->subparsers[j].base, dirString(sd->subparsers[j].direction));
        }
        free(ls);
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nImplementation specific status\n%s\n", rule);
    printf("allow null tags: %s\n", d->allowNullTag ? "yes" : "no");
}
EOF
echo ok"}

