#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include "util.h"
#include "options.h"
#include "parse.h"
#include "list.h"
#include "entry.h"
#include "lregex.h"

extern const char *HelpText[];
extern const char *HelpFullText[];
extern const char *LicenseText[];
extern const char *FieldNames[FIELD_COUNT];
extern const char *FieldDescs[FIELD_COUNT];
extern const char *FieldJstypes[FIELD_COUNT];
extern const bool FieldFixed[FIELD_COUNT];
extern const char *FieldOps[FIELD_COUNT];
extern const char *XtagNames[XTAG_COUNT];
extern const char *XtagDescs[XTAG_COUNT];
extern const int XtagVersions[XTAG_COUNT];

struct colTable {
    int ncols;
    const char *const *headers;
    const bool *rightAlign;
    ptrArray *rows;   /* char** */
};

colTable *colNew(int ncols, const char *const *headers, const bool *rightAlign) {
    colTable *t = xmalloc(sizeof *t);
    t->ncols = ncols; t->headers = headers; t->rightAlign = rightAlign;
    t->rows = paNew(NULL);
    return t;
}
void colAddRow(colTable *t, ...) {
    va_list ap; va_start(ap, t);
    char **row = xmalloc(t->ncols * sizeof(char*));
    for (int i = 0; i < t->ncols; i++) { const char *s = va_arg(ap, const char *); row[i] = xstrdup(s ? s : ""); }
    va_end(ap);
    paAdd(t->rows, row);
}
void colPrint(colTable *t, FILE *fp) {
    size_t *w = xcalloc(t->ncols, sizeof(size_t));
    if (Option.withListHeader) {
        for (int c = 0; c < t->ncols; c++) w[c] = strlen(t->headers[c]) + (c == 0 ? 1 : 0);
    }
    for (size_t r = 0; r < paCount(t->rows); r++) {
        char **row = paItem(t->rows, r);
        for (int c = 0; c < t->ncols; c++) { size_t l = strlen(row[c]); if (l > w[c]) w[c] = l; }
    }
    if (Option.withListHeader) {
        if (Option.machinable) {
            for (int c = 0; c < t->ncols; c++) fprintf(fp, "%s%s%s", c == 0 ? "#" : "", t->headers[c], c + 1 < t->ncols ? "\t" : "\n");
        } else {
            for (int c = 0; c < t->ncols; c++) {
                char *h = xmalloc(strlen(t->headers[c]) + 2);
                sprintf(h, "%s%s", c == 0 ? "#" : "", t->headers[c]);
                if (c + 1 < t->ncols) fprintf(fp, "%-*s ", (int)w[c], h);
                else fprintf(fp, "%s\n", h);
                free(h);
            }
        }
    }
    for (size_t r = 0; r < paCount(t->rows); r++) {
        char **row = paItem(t->rows, r);
        for (int c = 0; c < t->ncols; c++) {
            if (Option.machinable) fprintf(fp, "%s%s", row[c], c + 1 < t->ncols ? "\t" : "\n");
            else if (c + 1 < t->ncols) {
                if (t->rightAlign && t->rightAlign[c]) fprintf(fp, "%*s ", (int)w[c], row[c]);
                else fprintf(fp, "%-*s ", (int)w[c], row[c]);
            } else fprintf(fp, "%s\n", row[c]);
        }
    }
    free(w);
}
void colDelete(colTable *t) {
    for (size_t r = 0; r < paCount(t->rows); r++) { char **row = paItem(t->rows, r); for (int c = 0; c < t->ncols; c++) free(row[c]); free(row); }
    paDelete(t->rows); free(t);
}

