static int cmpLangStrcmp(const void *a, const void *b) { return strcmp(getLanguageName(*(const int*)a), getLanguageName(*(const int*)b)); }
static int *sortedLangs(int *n, bool caseInsensitive) {
    int *arr = xmalloc(LANG_COUNT * sizeof(int));
    int k = 0;
    for (int i = 0; i < LANG_COUNT; i++) arr[k++] = i;
    *n = k;
    if (caseInsensitive) {
        for (int i = 0; i < k; i++) for (int j = i + 1; j < k; j++) if (strcasecmp(getLanguageName(arr[i]), getLanguageName(arr[j])) > 0) { int t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
    } else qsort(arr, k, sizeof(int), cmpLangStrcmp);
    return arr;
}

static int resolveLangArg(const char *arg, const char *optname, bool *all) {
    *all = false;
    if (arg == NULL || *arg == '\0' || strcmp(arg, "all") == 0) { *all = true; return -1; }
    int lang = getNamedLanguageFull(arg, 0, true);
    if (lang < 0) error_fatal("Unknown language \"%s\" in \"%s\" option", arg, optname);
    return lang;
}

/* ---- kinds ---- */
static int cmpKindLetter(const void *a, const void *b) {
    const kindDef *ka = *(kindDef *const *)a, *kb = *(kindDef *const *)b;
    int r = strcmp(ka->letter, kb->letter);
    if (r == 0) r = strcmp(ka->name, kb->name);
    return r;
}
static void addKindRows(colTable *t, int lang, bool withLang) {
    langDef *d = getLangDef(lang);
    kindDef **ks = xmalloc((d->nkinds + 1) * sizeof(kindDef*));
    for (int i = 0; i < d->nkinds; i++) ks[i] = &d->kinds[i];
    qsort(ks, d->nkinds, sizeof(kindDef*), cmpKindLetter);
    for (int i = 0; i < d->nkinds; i++) {
        kindDef *k = ks[i];
        char nroles[16], ver[16];
        snprintf(nroles, sizeof nroles, "%d", k->nroles);
        snprintf(ver, sizeof ver, "%d", k->version);
        if (withLang) colAddRow(t, d->name, k->letter, k->name, k->enabled ? "yes" : "no", k->refonly ? "yes" : "no", nroles, k->master ? k->master : "NONE", ver, k->desc);
        else colAddRow(t, k->letter, k->name, k->enabled ? "yes" : "no", k->refonly ? "yes" : "no", nroles, k->master ? k->master : "NONE", ver, k->desc);
    }
    free(ks);
}
static void printKindsSimple(int lang, bool indent) {
    langDef *d = getLangDef(lang);
    for (int i = 0; i < d->nkinds; i++) {
        kindDef *k = &d->kinds[i];
        printf("%s%s  %s%s\n", indent ? "    " : "", k->letter, k->desc, k->enabled ? "" : " [off]");
    }
}
void listKinds(const char *arg, bool full) {
    bool all;
    int lang = resolveLangArg(arg, full ? "list-kinds-full" : "list-kinds", &all);
    if (full) {
        static const char *const hAll[] = { "LANGUAGE", "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
        static const bool rAll[] = { false, false, false, false, false, false, false, true, false };
        static const char *const hOne[] = { "LETTER", "NAME", "ENABLED", "REFONLY", "NROLES", "MASTER", "VER", "DESCRIPTION" };
        static const bool rOne[] = { false, false, false, false, false, false, true, false };
        colTable *t = all ? colNew(9, hAll, rAll) : colNew(8, hOne, rOne);
        if (all) { int n; int *ls = sortedLangs(&n, false); for (int i = 0; i < n; i++) addKindRows(t, ls[i], true); free(ls); }
        else addKindRows(t, lang, false);
        colPrint(t, stdout); colDelete(t);
    } else {
        if (all) {
            for (int i = 0; i < LANG_COUNT; i++) {
                printf("%s%s\n", getLanguageName(i), isLanguageEnabled(i) ? "" : " [disabled]");
                printKindsSimple(i, true);
            }
        } else printKindsSimple(lang, false);
    }
}

