/* ---- roles ---- */
static int cmpRoleName(const void *a, const void *b) { return strcmp((*(roleDef *const *)a)->name, (*(roleDef *const *)b)->name); }
static void addRoleRows(colTable *t, int lang, const char *kindspec, bool withLang) {
    langDef *d = getLangDef(lang);
    kindDef **ks = xmalloc((d->nkinds + 1) * sizeof(kindDef*));
    int nk = 0;
    for (int i = 0; i < d->nkinds; i++) {
        kindDef *k = &d->kinds[i];
        bool match = false;
        if (!kindspec || kindspec[0] == '*' || kindspec[0] == '\0') match = true;
        else {
            for (const char *p = kindspec; *p; ) {
                if (*p == '{') { const char *e = strchr(p, '}'); if (!e) break; if ((int)strlen(k->name) == e - p - 1 && strncmp(k->name, p + 1, e - p - 1) == 0) match = true; p = e + 1; }
                else { if (k->letter[0] == *p) match = true; p++; }
            }
        }
        if (match) ks[nk++] = k;
    }
    qsort(ks, nk, sizeof(kindDef*), cmpKindLetter);
    for (int i = 0; i < nk; i++) {
        kindDef *k = ks[i];
        roleDef **rs = xmalloc((k->nroles + 1) * sizeof(roleDef*));
        for (int r = 0; r < k->nroles; r++) rs[r] = &k->roles[r];
        qsort(rs, k->nroles, sizeof(roleDef*), cmpRoleName);
        for (int r = 0; r < k->nroles; r++) {
            char kn[256], ver[16];
            snprintf(kn, sizeof kn, "%s/%s", k->letter, k->name);
            snprintf(ver, sizeof ver, "%d", rs[r]->version);
            if (withLang) colAddRow(t, d->name, kn, rs[r]->name, rs[r]->enabled ? "on" : "off", ver, rs[r]->desc);
            else colAddRow(t, kn, rs[r]->name, rs[r]->enabled ? "on" : "off", ver, rs[r]->desc);
        }
        free(rs);
    }
    free(ks);
}
void listRoles(const char *spec) {
    char *copy = xstrdup(spec ? spec : "");
    char *dot = strchr(copy, '.');
    const char *kindspec = NULL;
    if (dot) { *dot = 0; kindspec = dot + 1; }
    bool all;
    int lang = resolveLangArg(copy, "list-roles", &all);
    static const char *const hAll[] = { "LANGUAGE", "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
    static const bool rAll[] = { false, false, false, false, true, false };
    static const char *const hOne[] = { "KIND(L/N)", "NAME", "ENABLED", "VER", "DESCRIPTION" };
    static const bool rOne[] = { false, false, false, true, false };
    colTable *t = all ? colNew(6, hAll, rAll) : colNew(5, hOne, rOne);
    if (all) { int n; int *ls = sortedLangs(&n, false); for (int i = 0; i < n; i++) addRoleRows(t, ls[i], kindspec, true); free(ls); }
    else addRoleRows(t, lang, kindspec, false);
    colPrint(t, stdout); colDelete(t);
    free(copy);
}

