/* ---- maps ---- */
void listMaps(const char *arg, int which) {
    bool all;
    const char *optname = which == 0 ? "list-maps" : which == 1 ? "list-map-extensions" : which == 2 ? "list-map-patterns" : "list-map-rexprs";
    int lang = resolveLangArg(arg, optname, &all);
    if (which == 0) {
        for (int i = 0; i < LANG_COUNT; i++) {
            if (!all && i != lang) continue;
            parserObject *p = getParser(i);
            printf("%-8s", p->def->name);
            for (size_t j = 0; j < saCount(p->pats); j++) printf(" %s", saItem(p->pats, j));
            for (size_t j = 0; j < saCount(p->exts); j++) printf(" *.%s", saItem(p->exts, j));
            printf("\n");
        }
        return;
    }
    if (which == 3) {
        static const char *const hAll[] = { "LANGUAGE", "EXPRESSION", "CASE" };
        static const char *const hOne[] = { "EXPRESSION", "CASE" };
        /* emulate observed width quirks */
        colTable *t = all ? colNew(3, hAll, NULL) : colNew(2, hOne, NULL);
        for (int i = 0; i < LANG_COUNT; i++) {
            if (!all && i != lang) continue;
            langDef *d = getLangDef(i);
            for (int j = 0; j < d->nrexprs; j++) {
                if (all) colAddRow(t, d->name, d->rexprs[j].pattern, d->rexprs[j].icase ? "insensitive" : "sensitive");
                else colAddRow(t, d->rexprs[j].pattern, d->rexprs[j].icase ? "insensitive" : "sensitive");
            }
        }
        if (!Option.machinable && paCount(t->rows) > 0) {
            /* ctags pads these columns one extra char */
            if (all) {
                size_t wl = strlen("#LANGUAGE"), we = strlen("EXPRESSION");
                for (size_t r = 0; r < paCount(t->rows); r++) { char **row = paItem(t->rows, r); if (strlen(row[0]) > wl) wl = strlen(row[0]); if (strlen(row[1]) > we) we = strlen(row[1]); }
                wl++;
                if (Option.withListHeader) printf("%-*s %-*s %s\n", (int)wl, "#LANGUAGE", (int)we, "EXPRESSION", "CASE");
                for (size_t r = 0; r < paCount(t->rows); r++) { char **row = paItem(t->rows, r); printf("%-*s %-*s %s\n", (int)wl, row[0], (int)we, row[1], row[2]); }
            } else {
                size_t we = strlen("#EXPRESSION");
                for (size_t r = 0; r < paCount(t->rows); r++) { char **row = paItem(t->rows, r); if (strlen(row[0]) + 1 > we) we = strlen(row[0]) + 1; }
                if (Option.withListHeader) printf("%-*s %s\n", (int)we, "#EXPRESSION", "CASE");
                for (size_t r = 0; r < paCount(t->rows); r++) { char **row = paItem(t->rows, r); printf("%-*s %s\n", (int)we, row[0], row[1]); }
            }
            colDelete(t);
            return;
        }
        colPrint(t, stdout); colDelete(t);
        return;
    }
    static const char *const hAllE[] = { "LANGUAGE", "EXTENSION" };
    static const char *const hOneE[] = { "EXTENSION" };
    static const char *const hAllP[] = { "LANGUAGE", "PATTERN" };
    static const char *const hOneP[] = { "PATTERN" };
    colTable *t = all ? colNew(2, which == 1 ? hAllE : hAllP, NULL) : colNew(1, which == 1 ? hOneE : hOneP, NULL);
    for (int i = 0; i < LANG_COUNT; i++) {
        if (!all && i != lang) continue;
        parserObject *p = getParser(i);
        strArray *a = which == 1 ? p->exts : p->pats;
        for (size_t j = 0; j < saCount(a); j++) { if (all) colAddRow(t, p->def->name, saItem(a, j)); else colAddRow(t, saItem(a, j)); }
    }
    colPrint(t, stdout); colDelete(t);
}

