static const char *dirString(subparserDirection d) {
    switch (d) { case SUBPARSER_BI: return "base <> sub {bidirectional}"; case SUBPARSER_BASE_RUNS_SUB: return "base <= sub {dedicated}"; default: return "base => sub {shared}"; }
}
