void describeLanguage(const char *name) {
    int lang = getNamedLanguageFull(name, 0, true);
    if (lang < 0) error_fatal("Unknown language \"%s\" in \"describe-language\" option", name);
    parserObject *p = getParser(lang);
    langDef *d = p->def;
    const char *rule = "-------------------------------------------------------";
    printf("About %s language\n=======================================================\n", d->name);
    printf("enabled: %s\nversion: %d.%d\n\n", d->enabled ? "yes" : "no", d->verCurrent, d->verAge);
    printf("Mappings/rexprs\n%s\n", rule);
    for (int i = 0; i < d->nrexprs; i++) printf(" %s\n", d->rexprs[i].pattern);
    printf("\n\nMappings/patterns\n%s\n", rule);
    for (size_t i = 0; i < saCount(p->pats); i++) printf(" %s\n", saItem(p->pats, i));
    printf("\n\nMappings/extensions\n%s\n", rule);
    for (size_t i = 0; i < saCount(p->exts); i++) printf(" *.%s\n", saItem(p->exts, i));
    printf("\n\nAliases\n%s\n", rule);
    {
        static const char *const h[] = { "ALIAS" };
        colTable *t = colNew(1, h, NULL);
        for (size_t i = 0; i < saCount(p->aliases); i++) colAddRow(t, saItem(p->aliases, i));
        colPrint(t, stdout); colDelete(t);
    }
    printf("\nKinds\n%s\n", rule);
