#include "lregex.h"
#include "parse.h"
#include "options.h"
#include "entry.h"
#include "read.h"
#include "list.h"
#include <regex.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

typedef enum { SCOPE_REF = 1, SCOPE_PUSH = 2, SCOPE_POP = 4, SCOPE_CLEAR = 8, SCOPE_SET = 16, SCOPE_REPLACE = 32, SCOPE_INTERVALTAB = 64 } scopeAction;
typedef enum { TACT_NONE, TACT_ENTER, TACT_LEAVE, TACT_JUMP, TACT_RESET, TACT_QUIT } tableAction;

typedef struct {
    regex_t re;
    bool compiled;
    char *pattern;
    char *nameTmpl;      /* may be NULL for placeholder-only */
    int kindIndex;
    int lang;            /* owner language */
    int foreignLang;     /* -1 */
    bool exclusive;
    bool placeholder;
    bool postrun;
    int scopeActions;
    char *anonPrefix;
    int extraIndex;      /* common extra (-1) */
    int langExtraIndex;  /* -1 */
    int roleIndex;
    char *fatalMsg, *warnMsg;
    struct { int ftype; char *tmpl; } fields[8];
    int nfields;
    /* mline */
    int mgroup;
    int advanceTo; bool advanceToEnd;
    /* mtable */
    tableAction taction;
    char *tableName;      /* for enter/jump/reset */
    char *contTableName;  /* for tenter continuation */
    regexParserType type;
    char *guestSpec;
} regexPattern;

typedef struct { char *name; ptrArray *patterns; } regexTable;

static regexTable *findTable(parserObject *p, const char *name) {
    for (size_t i = 0; i < paCount(p->mtables); i++) { regexTable *t = paItem(p->mtables, i); if (strcmp(t->name, name) == 0) return t; }
    return NULL;
}
void addLanguageTableDef(int lang, const char *name) {
    parserObject *p = getParser(lang);
    if (findTable(p, name)) { error_fatal("regex table \"%s\" is already defined for \"%s\" language", name, getLanguageName(lang)); }
    regexTable *t = xcalloc(1, sizeof *t);
    t->name = xstrdup(name);
    t->patterns = paNew(NULL);
    paAdd(p->mtables, t);
}
void processTabledefOption(const char *option, const char *param) {
    int lang = langFromOptionSuffix(option, "_tabledef-", NULL, false, false);
    if (lang < 0) error_fatal("Unknown language \"%s\" in \"%s\" option", option + 10, option);
    addLanguageTableDef(lang, param);
}

/* split "/a/b/c/flags" by delimiter respecting backslash escapes */
static char **splitRegexSpec(const char *spec, int *nparts, char *delimOut) {
    char delim = spec[0];
    *delimOut = delim;
    if (delim == '\0' || isalnum((unsigned char)delim) || delim == '\\' || isspace((unsigned char)delim)) return NULL;
    char **parts = xcalloc(8, sizeof(char*));
    int n = 0;
    const char *p = spec + 1;
    vString *cur = vsNew();
    while (*p && n < 7) {
        if (*p == '\\' && p[1]) {
            if (p[1] == delim) { vsPut(cur, delim); p += 2; continue; }
            vsPut(cur, *p); vsPut(cur, p[1]); p += 2; continue;
        }
        if (*p == delim) { parts[n++] = xstrdup(vsValue(cur)); vsClear(cur); p++; if (n == 3) break; continue; }
        vsPut(cur, *p++);
    }
    if (n < 3 && (vsLength(cur) || n > 0)) { parts[n++] = xstrdup(vsValue(cur)); vsClear(cur); }
    /* remaining (after third delimiter) are flags */
    if (n >= 3) { parts[n++] = xstrdup(p); }
    vsDelete(cur);
    *nparts = n;
    return parts;
}

static int parseKindSpec(int lang, const char *kindspec, bool *isDefault) {
    *isDefault = false;
    if (!kindspec || *kindspec == '\0') {
        *isDefault = true;
        int k = getKindIndexByLetter(lang, 'r');
        if (k < 0) k = defineKind(lang, 'r', "regex", "regex", true, false);
        return k;
    }
    char letter = kindspec[0];
    const char *name = NULL, *desc = NULL;
    char *copy = xstrdup(kindspec);
    char *c1 = strchr(copy, ',');
    char *nameBuf = NULL, *descBuf = NULL;
    if (c1) {
        *c1 = 0;
        char *c2 = strchr(c1 + 1, ',');
        if (c2) { *c2 = 0; descBuf = xstrdup(c2 + 1); }
        nameBuf = xstrdup(c1 + 1);
        name = nameBuf; desc = descBuf;
    }
    if (letter == '\0' || !isalpha((unsigned char)letter)) { error_warning("kind letter must be an alphabetical character: '%c'", letter); }
    int k = getKindIndexByLetter(lang, letter);
    if (k < 0) {
        k = defineKind(lang, letter, name ? name : "regex", desc ? desc : (name ? name : "regex"), true, false);
    } else {
        /* existing kind: if name given & differs? keep */
    }
    free(copy); free(nameBuf); free(descBuf);
    return k;
}

static char *extractBraced(const char *p, const char **endp) {
    /* p points after '{' ; find matching '}' */
    const char *e = p;
    int depth = 1;
    while (*e) { if (*e == '{') depth++; else if (*e == '}') { depth--; if (depth == 0) break; } e++; }
    char *s = xstrndup(p, e - p);
    *endp = *e ? e + 1 : e;
    return s;
}

static void parseFlags(regexPattern *pat, const char *flags, int lang, int *cflags) {
    const char *p = flags;
    while (p && *p) {
        if (*p == '{') {
            const char *end;
            char *f = extractBraced(p + 1, &end);
            char *eq = strchr(f, '=');
            char *val = eq ? eq + 1 : NULL;
            if (eq) *eq = 0;
            if (strcmp(f, "exclusive") == 0) pat->exclusive = true;
            else if (strcmp(f, "icase") == 0) *cflags |= REG_ICASE;
            else if (strcmp(f, "basic") == 0) *cflags &= ~REG_EXTENDED;
            else if (strcmp(f, "extend") == 0) *cflags |= REG_EXTENDED;
            else if (strcmp(f, "pcre2") == 0) { }
            else if (strcmp(f, "placeholder") == 0) pat->placeholder = true;
            else if (strcmp(f, "postrun") == 0) pat->postrun = true;
            else if (strcmp(f, "scope") == 0 && val) {
                if (strcmp(val, "ref") == 0) pat->scopeActions |= SCOPE_REF;
                else if (strcmp(val, "push") == 0) pat->scopeActions |= SCOPE_PUSH;
                else if (strcmp(val, "pop") == 0) pat->scopeActions |= SCOPE_POP;
                else if (strcmp(val, "clear") == 0) pat->scopeActions |= SCOPE_CLEAR;
                else if (strcmp(val, "set") == 0) pat->scopeActions |= SCOPE_SET;
                else if (strcmp(val, "replace") == 0) pat->scopeActions |= SCOPE_REPLACE;
                else if (strcmp(val, "intervaltab") == 0) pat->scopeActions |= SCOPE_INTERVALTAB;
            }
            else if (strcmp(f, "_anonymous") == 0 && val) pat->anonPrefix = xstrdup(val);
            else if (strcmp(f, "_extra") == 0 && val) {
                int li = getLangExtraIndexByName(lang, val);
                if (li >= 0) pat->langExtraIndex = li;
                else error_warning("no such extra \"%s\" in %s", val, getLanguageName(lang));
            }
            else if (strcmp(f, "_role") == 0 && val) {
                int r = getRoleIndexByName(lang, pat->kindIndex, val);
                if (r >= 0) pat->roleIndex = r;
                else error_warning("no such role: %s", val);
            }
            else if (strcmp(f, "_field") == 0 && val) {
                char *colon = strchr(val, ':');
                if (colon) {
                    *colon = 0;
                    int fi = getLangFieldIndexByName(lang, val);
                    if (fi < 0) error_warning("no such field \"%s\" in %s", val, getLanguageName(lang));
                    else if (pat->nfields < 8) { pat->fields[pat->nfields].ftype = fi; pat->fields[pat->nfields].tmpl = xstrdup(colon + 1); pat->nfields++; }
                }
            }
            else if (strcmp(f, "_language") == 0 && val) { int l = getNamedLanguageFull(val, 0, true); if (l >= 0) pat->foreignLang = l; }
            else if (strcmp(f, "fatal") == 0 && val) pat->fatalMsg = xstrdup(val);
            else if (strcmp(f, "warning") == 0 && val) pat->warnMsg = xstrdup(val);
            else if (strcmp(f, "mgroup") == 0 && val) pat->mgroup = atoi(val);
            else if (strcmp(f, "_advanceTo") == 0 && val) {
                pat->advanceTo = atoi(val);
                pat->advanceToEnd = (strstr(val, "start") == NULL);
            }
            else if (strcmp(f, "tenter") == 0 && val) {
                pat->taction = TACT_ENTER;
                char *comma = strchr(val, ',');
                if (comma) { *comma = 0; pat->contTableName = xstrdup(comma + 1); }
                pat->tableName = xstrdup(val);
            }
            else if (strcmp(f, "tleave") == 0) pat->taction = TACT_LEAVE;
            else if (strcmp(f, "tjump") == 0 && val) { pat->taction = TACT_JUMP; pat->tableName = xstrdup(val); }
            else if (strcmp(f, "treset") == 0 && val) { pat->taction = TACT_RESET; pat->tableName = xstrdup(val); }
            else if (strcmp(f, "tquit") == 0) pat->taction = TACT_QUIT;
            else if (strcmp(f, "_guest") == 0 && val) pat->guestSpec = xstrdup(val);
            free(f);
            p = end;
            continue;
        }
        switch (*p) {
        case 'b': *cflags &= ~REG_EXTENDED; break;
        case 'e': *cflags |= REG_EXTENDED; break;
        case 'i': *cflags |= REG_ICASE; break;
        case 'x': pat->exclusive = true; break;
        case 'p': break;
        default: error_warning("unknown regex flag: '%c'", *p); break;
        }
        p++;
    }
}

/* translate \w etc? POSIX regex (glibc) supports \w \b \< \> in ERE already. */
static bool compilePattern(regexPattern *pat, int cflags) {
    int err = regcomp(&pat->re, pat->pattern, cflags | REG_NEWLINE * 0);
    if (err != 0) {
        char buf[256];
        regerror(err, &pat->re, buf, sizeof buf);
        error_warning("regcomp: %s", buf);
        error_warning("pattern: %s", pat->pattern);
        error_warning("language: %s[0]", getLanguageName(pat->lang));
        error_warning("Failed in compiling the regex pattern with \"default\" regex engine");
        return false;
    }
    pat->compiled = true;
    return true;
}

static regexPattern *newPattern(int lang, const char *regex, const char *name, const char *kindspec, const char *flags, regexParserType type, bool *ok) {
    regexPattern *pat = xcalloc(1, sizeof *pat);
    pat->lang = lang;
    pat->foreignLang = -1;
    pat->extraIndex = -1; pat->langExtraIndex = -1; pat->roleIndex = -1;
    pat->mgroup = -1; pat->advanceTo = -1;
    pat->type = type;
    pat->pattern = xstrdup(regex);
    pat->nameTmpl = xstrdup(name ? name : "");
    bool isDefault;
    int cflags = REG_EXTENDED;
    if (type == REG_PARSER_MULTI_TABLE && (!kindspec)) kindspec = "";
    pat->kindIndex = parseKindSpec(lang, kindspec, &isDefault);
    parseFlags(pat, flags, lang, &cflags);
    if (type != REG_PARSER_SINGLE_LINE) cflags |= REG_NEWLINE;
    *ok = compilePattern(pat, cflags);
    if (name == NULL || *name == '\0') {
        if (!(pat->scopeActions & (SCOPE_POP|SCOPE_CLEAR)) && !pat->placeholder && pat->taction == TACT_NONE && type == REG_PARSER_SINGLE_LINE && !pat->anonPrefix)
            error_warning("%s: regexp missing name pattern", regex);
    }
    return pat;
}

void addRegexRule(int lang, const char *rule, regexParserType type) {
    int n; char delim;
    const char *tableName = NULL;
    char *tbl = NULL;
    const char *spec = rule;
    if (type == REG_PARSER_MULTI_TABLE) {
        const char *slash = rule;
        while (*slash && (isalnum((unsigned char)*slash) || *slash == '_')) slash++;
        tbl = xstrndup(rule, slash - rule);
        tableName = tbl;
        spec = slash;
    }
    char **parts = splitRegexSpec(spec, &n, &delim);
    if (!parts || n < 2) {
        error_warning("Wrong regex pattern format: %s", rule);
        free(tbl);
        return;
    }
    const char *regex = parts[0];
    const char *name = parts[1];
    const char *kind = n > 2 ? parts[2] : NULL;
    const char *flags = n > 3 ? parts[3] : "";
    if (type == REG_PARSER_MULTI_TABLE) {
        /* for mtable: <table>/<pattern>/<name>/[<kind>/]<flags> — kind optional: if n==3 then parts[2] is flags */
        if (n == 3) { flags = parts[2]; kind = ""; }
    }
    bool ok;
    regexPattern *pat = newPattern(lang, regex, name, kind, flags, type, &ok);
    if (ok) {
        parserObject *p = getParser(lang);
        if (type == REG_PARSER_SINGLE_LINE) paAdd(p->regexPatterns, pat);
        else if (type == REG_PARSER_MULTI_LINE) paAdd(p->mlinePatterns, pat);
        else {
            regexTable *t = findTable(p, tableName);
            if (!t) error_fatal("unknown table name: %s", tableName);
            else paAdd(t->patterns, pat);
        }
    }
    for (int i = 0; i < n; i++) free(parts[i]);
    free(parts); free(tbl);
}

void processRegexOption(const char *option, const char *param, regexParserType type) {
    const char *prefix = type == REG_PARSER_SINGLE_LINE ? "regex-" : type == REG_PARSER_MULTI_LINE ? "mline-regex-" : "_mtable-regex-";
    const char *langName = option + strlen(prefix);
    int lang = getNamedLanguageFull(langName, 0, true);
    if (lang < 0) { error_warning("Unknown language \"%s\" in \"%s\" option", langName, option); return; }
    addRegexRule(lang, param, type);
}

void processMtableExtendOption(const char *option, const char *param) {
    int lang = langFromOptionSuffix(option, "_mtable-extend-", NULL, false, false);
    if (lang < 0) error_fatal("Unknown language in \"%s\" option", option);
    char *copy = xstrdup(param);
    char *plus = strchr(copy, '+');
    if (!plus) error_fatal("wrong format: %s", param);
    *plus = 0;
    parserObject *p = getParser(lang);
    regexTable *dst = findTable(p, copy), *src = findTable(p, plus + 1);
    if (!dst || !src) error_fatal("unknown table in \"%s\"", param);
    for (size_t i = 0; i < paCount(src->patterns); i++) paAdd(dst->patterns, paItem(src->patterns, i));
    free(copy);
}

bool hasSingleLineRegexPatterns(int lang) { return paCount(getParser(lang)->regexPatterns) > 0; }
bool hasMultiLineRegexPatterns(int lang) { return paCount(getParser(lang)->mlinePatterns) > 0; }
bool hasMultiTableRegexPatterns(int lang) { return paCount(getParser(lang)->mtables) > 0; }
bool hasRegexPatterns(int lang) { return hasSingleLineRegexPatterns(lang) || hasMultiLineRegexPatterns(lang) || hasMultiTableRegexPatterns(lang); }

/* ---- scope stack ---- */
static int ScopeStack[1024];
static int ScopeTop = 0;   /* count */

void regexPreparePerFile(int lang) { (void)lang; ScopeTop = 0; }
void regexFinishPerFile(int lang) { (void)lang; ScopeTop = 0; }
void regexNotifyFileStart(int lang) { (void)lang; ScopeTop = 0; }

static void substitute(vString *out, const char *tmpl, const char *subject, regmatch_t *pm, int nmatch) {
    for (const char *p = tmpl; *p; p++) {
        if (*p == '\\' && p[1]) {
            p++;
            if (isdigit((unsigned char)*p)) {
                int g = *p - '0';
                if (g < nmatch && pm[g].rm_so >= 0) vsCatN(out, subject + pm[g].rm_so, pm[g].rm_eo - pm[g].rm_so);
            } else if (*p == 't') vsPut(out, '\t');
            else if (*p == 'n') vsPut(out, '\n');
            else if (*p == '\\') vsPut(out, '\\');
            else vsPut(out, *p);
        } else vsPut(out, *p);
    }
}

static void doScopeAndTag(regexPattern *pat, const char *subject, regmatch_t *pm, int nmatch, unsigned long lineNumber, long linePos) {
    vString *name = vsNew();
    if (pat->anonPrefix) anonGenerate(name, pat->anonPrefix, pat->kindIndex);
    else substitute(name, pat->nameTmpl, subject, pm, nmatch);
    if (pat->fatalMsg) error_fatal("%s", pat->fatalMsg);
    if (pat->warnMsg) error_warning("%s", pat->warnMsg);

    if (pat->scopeActions & SCOPE_CLEAR) {
        /* set end lines of all */
        for (int i = ScopeTop - 1; i >= 0; i--) { tagEntryInfo *e = getEntryInCorkQueue(ScopeStack[i]); if (e && e->ext.endLine == 0) e->ext.endLine = lineNumber; }
        ScopeTop = 0;
    }
    if (pat->scopeActions & SCOPE_POP) {
        if (ScopeTop > 0) {
            tagEntryInfo *e = getEntryInCorkQueue(ScopeStack[ScopeTop - 1]);
            if (e && e->ext.endLine == 0) e->ext.endLine = lineNumber;
            ScopeTop--;
        }
    }
    int scope = CORK_NIL;
    if ((pat->scopeActions & (SCOPE_REF|SCOPE_PUSH|SCOPE_REPLACE)) && ScopeTop > 0) scope = ScopeStack[ScopeTop - 1];
    if (pat->scopeActions & SCOPE_REPLACE) { if (ScopeTop > 0) { tagEntryInfo *e = getEntryInCorkQueue(ScopeStack[ScopeTop-1]); if (e && e->ext.endLine == 0) e->ext.endLine = lineNumber; ScopeTop--; } }

    int cork = CORK_NIL;
    bool nullName = (vsLength(name) == 0);
    if (nullName && !pat->placeholder && (pat->scopeActions & (SCOPE_PUSH|SCOPE_SET|SCOPE_REPLACE)) == 0 && pat->type == REG_PARSER_SINGLE_LINE && pat->taction == TACT_NONE && !pat->anonPrefix) {
        if (!(pat->scopeActions & (SCOPE_POP|SCOPE_CLEAR)))
            error_warning("%s:%lu: null expansion of name pattern \"%s\"", getInputFileName(), lineNumber, pat->nameTmpl);
    } else if (!nullName || pat->placeholder || (pat->scopeActions & (SCOPE_PUSH|SCOPE_REPLACE|SCOPE_SET))) {
        if (nullName && !pat->placeholder && pat->type == REG_PARSER_SINGLE_LINE)
            error_warning("%s:%lu: null expansion of name pattern \"%s\"", getInputFileName(), lineNumber, pat->nameTmpl);
        tagEntryInfo e;
        initTagEntry(&e, vsValue(name), pat->kindIndex);
        if (pat->foreignLang >= 0) e.langIndex = pat->foreignLang;
        e.lineNumber = lineNumber;
        e.filePosition = linePos;
        if (pat->placeholder) e.placeholder = true;
        if (pat->roleIndex >= 0) assignRole(&e, pat->roleIndex);
        if (pat->langExtraIndex >= 0) markTagLangExtraBit(&e, pat->langExtraIndex);
        if (pat->anonPrefix) markTagExtraBit(&e, XTAG_ANONYMOUS);
        e.ext.scopeIndex = (pat->scopeActions & SCOPE_SET) ? ((pat->scopeActions & SCOPE_REF) ? scope : CORK_NIL) : scope;
        if ((pat->scopeActions & SCOPE_SET) && !(pat->scopeActions & SCOPE_REF)) e.ext.scopeIndex = CORK_NIL;
        /* fields */
        vString *fv[8];
        for (int i = 0; i < pat->nfields; i++) { fv[i] = vsNew(); substitute(fv[i], pat->fields[i].tmpl, subject, pm, nmatch); attachParserField(&e, pat->fields[i].ftype, vsValue(fv[i])); }
        cork = makeTagEntry(&e);
        for (int i = 0; i < pat->nfields; i++) vsDelete(fv[i]);
        if (pat->scopeActions & SCOPE_SET) { ScopeTop = 0; }
        if (pat->scopeActions & (SCOPE_PUSH|SCOPE_SET|SCOPE_REPLACE)) { if (ScopeTop < 1024) ScopeStack[ScopeTop++] = cork; }
    }
    vsDelete(name);
}

/* match single-line patterns against a line */
void matchRegexLine(int lang, const unsigned char *line) {
    parserObject *p = getParser(lang);
    if (paCount(p->regexPatterns) == 0) return;
    regmatch_t pm[10];
    unsigned long ln = getInputLineNumber();
    long pos = getInputFilePosition();
    for (size_t i = 0; i < paCount(p->regexPatterns); i++) {
        regexPattern *pat = paItem(p->regexPatterns, i);
        if (!pat->compiled) continue;
        if (regexec(&pat->re, (const char *)line, 10, pm, 0) == 0) {
            doScopeAndTag(pat, (const char *)line, pm, 10, ln, pos);
            if (pat->exclusive) break;
        }
    }
}

void findRegexTags(void) {
    int lang = getInputLanguage();
    const unsigned char *line;
    while ((line = readLineFromInputFile()) != NULL) matchRegexLine(lang, line);
}

void matchMultiLineRegex(int lang, const char *content, size_t size) {
    parserObject *p = getParser(lang);
    (void)size;
    for (size_t i = 0; i < paCount(p->mlinePatterns); i++) {
        regexPattern *pat = paItem(p->mlinePatterns, i);
        if (!pat->compiled) continue;
        size_t off = 0;
        regmatch_t pm[10];
        while (off <= strlen(content) && regexec(&pat->re, content + off, 10, pm, off ? REG_NOTBOL : 0) == 0) {
            if (pm[0].rm_eo == 0 && pm[0].rm_so == 0) { if (!content[off]) break; off++; continue; }
            int g = pat->mgroup > 0 ? pat->mgroup : 0;
            if (g >= 10 || pm[g].rm_so < 0) g = 0;
            size_t tagOff = off + pm[g].rm_so;
            unsigned long ln = getInputLineNumberForOffset(tagOff);
            long pos = (long)getInputLineStart(ln);
            doScopeAndTag(pat, content + off, pm, 10, ln, pos);
            size_t next;
            if (pat->advanceTo >= 0 && pat->advanceTo < 10 && pm[pat->advanceTo].rm_so >= 0) next = off + (pat->advanceToEnd ? pm[pat->advanceTo].rm_eo : pm[pat->advanceTo].rm_so);
            else next = off + pm[0].rm_eo;
            if (next <= off) next = off + 1;
            off = next;
        }
    }
}

void runMultiTableRegex(int lang, const char *content, size_t size) {
    parserObject *p = getParser(lang);
    if (paCount(p->mtables) == 0) return;
    regexTable *cur = paItem(p->mtables, 0);
    regexTable *stack[256]; int sp = 0;
    size_t off = 0;
    size_t len = strlen(content);
    (void)size;
    int guard = 0;
    while (off <= len && cur) {
        bool matched = false;
        for (size_t i = 0; i < paCount(cur->patterns); i++) {
            regexPattern *pat = paItem(cur->patterns, i);
            if (!pat->compiled) continue;
            regmatch_t pm[10];
            if (regexec(&pat->re, content + off, 10, pm, off ? REG_NOTBOL : 0) == 0 && pm[0].rm_so == 0) {
                matched = true;
                int g = pat->mgroup > 0 ? pat->mgroup : 0;
                if (g >= 10 || pm[g].rm_so < 0) g = 0;
                size_t tagOff = off + pm[g].rm_so;
                unsigned long ln = getInputLineNumberForOffset(tagOff);
                long pos = (long)getInputLineStart(ln);
                if (vsLength((vString*)&(vString){0}) == 0) { }
                if ((pat->nameTmpl && *pat->nameTmpl) || pat->anonPrefix || pat->scopeActions || pat->placeholder)
                    doScopeAndTag(pat, content + off, pm, 10, ln, pos);
                size_t next;
                if (pat->advanceTo >= 0 && pat->advanceTo < 10 && pm[pat->advanceTo].rm_so >= 0) next = off + (pat->advanceToEnd ? pm[pat->advanceTo].rm_eo : pm[pat->advanceTo].rm_so);
                else next = off + pm[0].rm_eo;
                switch (pat->taction) {
                case TACT_ENTER: if (sp < 256) stack[sp++] = pat->contTableName ? findTable(p, pat->contTableName) : cur; cur = findTable(p, pat->tableName); break;
                case TACT_LEAVE: cur = sp > 0 ? stack[--sp] : NULL; break;
                case TACT_JUMP: cur = findTable(p, pat->tableName); break;
                case TACT_RESET: sp = 0; cur = findTable(p, pat->tableName); break;
                case TACT_QUIT: cur = NULL; break;
                default: break;
                }
                if (next == off) { if (++guard > 1000) { off++; guard = 0; } }
                else guard = 0;
                off = next;
                break;
            }
        }
        if (!matched) { if (off >= len) break; off++; }
        if (off >= len && matched) { /* allow patterns matching at EOF once */ if (guard++ > 2) break; }
    }
}

