        if (eq) *eq = 0;
        if (strcmp(flags, "base") == 0 && eq) {
            int base = getNamedLanguageFull(eq + 1, 0, true);
            if (base < 0) error_fatal("Unknown language \"%s\" in \"base\" flag", eq + 1);
            po->baseLang = base;
