            d->subparsers[0].base = xstrdup(getLanguageName(base));
            d->subparsers[0].direction = SUBPARSER_BASE_RUNS_SUB;
            d->nsubparsers = 1;
        } else if (strcmp(flags, "bidirectional") == 0 && po->def->nsubparsers) po->def->subparsers[0].direction = SUBPARSER_BI;
        else if (strcmp(flags, "shared") == 0 && po->def->nsubparsers) po->def->subparsers[0].direction = SUBPARSER_SUB_RUNS_BASE;
        else if (strcmp(flags, "dedicated") == 0 && po->def->nsubparsers) po->def->subparsers[0].direction = SUBPARSER_BASE_RUNS_SUB;
        else if (strcmp(flags, "version") == 0 && eq) { sscanf(eq + 1, "%d.%d", &po->def->verCurrent, &po->def->verAge); }
        else if (strcmp(flags, "_autoFQTag") == 0) po->autoFQ = true;
        flags = end + 1;
        while (*flags == '{') flags++;
    }
