}

static int langForDefOption(const char *option, const char *prefix) {
    const char *rest;
    int lang = langFromOptionSuffix(option, prefix, &rest, false, false);
    if (lang < 0) error_fatal("Unknown language \"%s\" in \"%s\" option", option + strlen(prefix), option);
    return lang;
}

/* --kinddef-<LANG>=<letter>,<name>,<description>[{flags}] */
void processKinddefOption(const char *option, const char *param) {
    int lang = langForDefOption(option, "kinddef-");
    char *copy = xstrdup(param);
    char *brace = strchr(copy, '{');
    char *flags = NULL;
    if (brace) { *brace = 0; flags = brace + 1; }
    char letter = copy[0];
    if (letter == '\0' || copy[1] != ',') error_fatal("wrong kind definition: %s", param);
    char *name = copy + 2;
    char *comma = strchr(name, ',');
    if (!comma) error_fatal("no kind description in \"--%s=%s\"", option, param);
    *comma = 0;
    char *desc = comma + 1;
    if (!isalnum((unsigned char)letter)) error_fatal("the kind letter given in \"--%s\" option is not an alphabet or numeric: %c", option, letter);
    if (letter == 'F') error_fatal("'F' is reserved for the kind for file. choose another letter");
    if (getKindIndexByLetter(lang, letter) >= 0) error_fatal("the kind for letter `%c' is already defined.", letter);
    if (getKindIndexByName(lang, name) >= 0) error_fatal("the kind for name `%s' is already defined.", name);
    for (char *p = name; *p; p++) if (!(isalnum((unsigned char)*p))) error_fatal("unacceptable char as part of kind name in \"--%s\" option: %c", option, *p);
    bool refonly = false;
    int version = 0;
    while (flags && *flags) {
        char *end = strchr(flags, '}'); if (!end) break; *end = 0;
        char *eq = strchr(flags, '='); if (eq) *eq = 0;
        if (strcmp(flags, "_refonly") == 0) refonly = true;
        else if (strcmp(flags, "version") == 0 && eq) version = atoi(eq + 1);
        flags = end + 1; while (*flags == '{') flags++;
    }
    int k = defineKind(lang, letter, name, desc, true, refonly);
    getLanguageKind(lang, k)->version = version;
    free(copy);
}

/* --_fielddef-<LANG>=<name>,<description>[{flags}] */
void processFielddefOption(const char *option, const char *param) {
    int lang = langForDefOption(option, "_fielddef-");
    char *copy = xstrdup(param);
    char *brace = strchr(copy, '{'); char *flags = NULL; if (brace) { *brace = 0; flags = brace + 1; }
    char *comma = strchr(copy, ',');
    if (!comma) error_fatal("no field description in \"--%s=%s\"", option, param);
    *comma = 0;
    if (getLangFieldIndexByName(lang, copy) >= 0) error_fatal("the field name `%s' is already defined.", copy);
    int fi = defineField(lang, copy, comma + 1);
    fieldDef *f = &getLangDef(lang)->fields[fi];
    while (flags && *flags) {
        char *end = strchr(flags, '}'); if (!end) break; *end = 0;
        char *eq = strchr(flags, '='); if (eq) *eq = 0;
        if (strcmp(flags, "datatype") == 0 && eq) {
            if (strcmp(eq + 1, "str") == 0) f->jstype = "s--";
            else if (strcmp(eq + 1, "bool") == 0) f->jstype = "--b";
            else if (strcmp(eq + 1, "int") == 0) f->jstype = "-i-";
            else if (strcmp(eq + 1, "str+bool") == 0) f->jstype = "s-b";
        } else if (strcmp(flags, "version") == 0 && eq) f->version = atoi(eq + 1);
        flags = end + 1; while (*flags == '{') flags++;
    }
    free(copy);
}

