strArray *EtagsFileNames = NULL;
static unsigned long TotalFiles = 0, TotalLines = 0, TotalBytes = 0;

static void recurseIntoDirectory(const char *dirName, int depth);

static char *combinePath(const char *dir, const char *file) {
    size_t n = strlen(dir);
    char *r = xmalloc(n + strlen(file) + 2);
    if (n && dir[n-1] == '/') sprintf(r, "%s%s", dir, file);
    else sprintf(r, "%s/%s", dir, file);
    return r;
}

static void countFileStats(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) TotalBytes += st.st_size;
    FILE *fp = fopen(path, "rb");
    if (fp) { int c; unsigned long lines = 0; int last = '\n'; while ((c = fgetc(fp)) != EOF) { if (c == '\n') lines++; last = c; } if (last != '\n') lines++; TotalLines += lines; fclose(fp); }
}

static void createTagsForEntry(const char *path, int depth) {
    if (isExcludedFile(path, false)) { verbose("excluding \"%s\"\n", path); return; }
    if (!Option.followLinks && isSymlink(path)) return;
    if (isDirectory(path)) {
        if (Option.recurse && (long)depth < Option.maxRecursionDepth) recurseIntoDirectory(path, depth);
        return;
    }
    if (!doesFileExist(path)) {
        error_warning_perror("cannot open input file \"%s\"", path);
        return;
    }
    if (parseFile(path)) {
        TotalFiles++;
        if (Option.totals) countFileStats(path);
        if (Option.outputFormat == OF_ETAGS) {
            /* record output name */
            extern char *currentOutputName(void);
            saAdd(EtagsFileNames, currentOutputName());
        }
    }
}

