/* C preprocessor layer shared by C-family parsers */
#include "cpp.h"
#include "../read.h"
#include "../entry.h"
#include "../options.h"
#include "../parse.h"
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

typedef struct {
    bool ignoreAllBranches;
    bool singleBranch;
    bool branchChosen;
    bool ignoring;
} conditionalInfo;

#define MAX_NEST 64
static struct {
    cppClientInfo client;
    bool accept;             /* '#' accepted at this position */
    conditionalInfo cond[MAX_NEST];
    int nestLevel;
    bool resolveRequired;    /* statement in progress */
    int ungetBuf[8];
    int ungetIdx;
    int braceCount;
} Cpp;

/* ignore tokens (-I) */
typedef struct { char *name; int kind; char *replacement; } ignoreTok;
static ptrArray *IgnoreToks = NULL;

void cppSetIgnoreToken(const char *tok) {
    if (!IgnoreToks) IgnoreToks = paNew(NULL);
    ignoreTok *t = xcalloc(1, sizeof *t);
    const char *eq = strchr(tok, '=');
    if (eq) { t->name = xstrndup(tok, eq - tok); t->kind = IGN_REPLACE; t->replacement = xstrdup(eq + 1); }
    else {
        size_t n = strlen(tok);
        if (n && tok[n-1] == '+') { t->name = xstrndup(tok, n - 1); t->kind = IGN_SKIP | IGN_SKIP_PARENS; }
        else { t->name = xstrdup(tok); t->kind = IGN_SKIP; }
    }
    paAdd(IgnoreToks, t);
}
const char *cppGetIgnoreReplacement(const char *tok, int *kind) {
    *kind = IGN_NONE;
    if (!IgnoreToks) return NULL;
    for (size_t i = 0; i < paCount(IgnoreToks); i++) {
        ignoreTok *t = paItem(IgnoreToks, i);
        if (strcmp(t->name, tok) == 0) { *kind = t->kind; return t->replacement; }
    }
    return NULL;
}

void cppInit(const cppClientInfo *info) {
    memset(&Cpp, 0, sizeof Cpp);
    Cpp.client = *info;
    Cpp.accept = true;
    Cpp.nestLevel = 0;
    Cpp.resolveRequired = false;
}
void cppTerminate(void) { }
void cppBeginStatement(void) { Cpp.resolveRequired = true; }
void cppEndStatement(void) { Cpp.resolveRequired = false; }
unsigned int cppGetDirectiveNestLevel(void) { return Cpp.nestLevel; }
bool cppIsBraceFormat(void) { return false; }
void cppPushExternalParserBlock(void) {}
void cppPopExternalParserBlock(void) {}

static bool isIgnore(void) { return Cpp.nestLevel > 0 && Cpp.cond[Cpp.nestLevel - 1].ignoring; }

static bool setIgnore(bool ignore) {
    if (Cpp.nestLevel > 0) Cpp.cond[Cpp.nestLevel - 1].ignoring = ignore;
    return ignore;
}
static bool isIgnoreBranch(void) {
    if (Cpp.nestLevel == 0) return false;
    conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
    if (Cpp.resolveRequired) c->singleBranch = true;
    return c->ignoreAllBranches || (c->branchChosen && c->singleBranch);
}
static void chooseBranch(void) {
    if (Cpp.nestLevel == 0) return;
    conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
    c->branchChosen = (c->singleBranch || Cpp.resolveRequired);
}
static bool pushConditional(bool firstBranchChosen) {
    bool ignoreAll = isIgnore();
    bool ignoreBranch = false;
    if (Cpp.nestLevel < MAX_NEST - 1) {
        Cpp.nestLevel++;
        conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
        c->ignoreAllBranches = ignoreAll;
        c->singleBranch = Cpp.resolveRequired;
        c->branchChosen = firstBranchChosen;
        c->ignoring = ignoreAll || (!firstBranchChosen && (c->singleBranch || !Option.if0));
        ignoreBranch = c->ignoring;
    }
    return ignoreBranch;
}
static bool popConditional(void) {
    if (Cpp.nestLevel > 0) Cpp.nestLevel--;
    return isIgnore();
}

static int rawGetc(void) { return getcFromInputFile(); }
static void rawUngetc(int c) { ungetcToInputFile(c); }

static void skipToEndOfLine(void) {
    int c;
    do { c = rawGetc(); if (c == '\\') { int n = rawGetc(); if (n == '\n') continue; if (n == '\r') { continue; } rawUngetc(n); } } while (c != EOF && c != '\n');
    if (c == '\n') rawUngetc(c);
}

/* read rest of a directive line into vString handling continuations and comments */
static void readDirectiveLine(vString *out) {
    int c;
    for (;;) {
        c = rawGetc();
        if (c == EOF) break;
        if (c == '\\') {
            int n = rawGetc();
            if (n == '\n') { vsPut(out, '\n'); continue; }
            if (n == '\r') { int m = rawGetc(); if (m == '\n') { vsPut(out, '\n'); continue; } rawUngetc(m); continue; }
            vsPut(out, c); rawUngetc(n); continue;
        }
        if (c == '\n') { rawUngetc(c); break; }
        if (c == '/') {
            int n = rawGetc();
            if (n == '*') {
                /* block comment: may span lines */
                int prev = 0;
                for (;;) { int d = rawGetc(); if (d == EOF) break; if (d == '\n') vsPut(out, '\n'); if (prev == '*' && d == '/') break; prev = d; }
                vsPut(out, ' ');
                continue;
            }
            if (n == '/') { /* line comment: skip to EOL */ for (;;) { int d = rawGetc(); if (d == EOF) break; if (d == '\n') { rawUngetc(d); break; } } break; }
            rawUngetc(n);
        }
        vsPut(out, c);
    }
}

static bool isident1(int c) { return isalpha(c) || c == '_' || c == '$'; }
static bool isident(int c) { return isalnum(c) || c == '_' || c == '$'; }

static void makeIncludeTag(const char *name, bool system, unsigned long line, long pos) {
    if (Cpp.client.headerKind < 0) return;
    tagEntryInfo e;
    initRefTagEntry(&e, name, Cpp.client.headerKind, system ? Cpp.client.sysRole : Cpp.client.localRole);
    e.langIndex = Cpp.client.lang;
    e.lineNumber = line; e.filePosition = pos;
    e.truncateLineAfterTag = true;
    e.isFileScope = false;
    makeTagEntry(&e);
}

static void directiveDefine(const char *text, bool undef, unsigned long line, long pos, unsigned long endLine) {
    const char *p = text;
    while (*p == ' ' || *p == '\t') p++;
    if (!isident1((unsigned char)*p)) return;
    const char *s = p;
    while (isident((unsigned char)*p)) p++;
    char *name = xstrndup(s, p - s);
    if (Cpp.client.macroKind < 0) { free(name); return; }
    tagEntryInfo e;
    if (undef) initRefTagEntry(&e, name, Cpp.client.macroKind, Cpp.client.undefRole);
    else initTagEntry(&e, name, Cpp.client.macroKind);
    e.langIndex = Cpp.client.lang;
    e.lineNumber = line; e.filePosition = pos;
    e.truncateLineAfterTag = true;
    e.isFileScope = !isInputHeaderFile();
    vString *sig = NULL;
    strArray *params = NULL;
    if (!undef && *p == '(') {
        sig = vsNew();
        params = saNew();
        vString *cur = vsNew();
        int depth = 0;
        for (; *p; p++) {
            char c = *p;
            vsPut(sig, c);
            if (c == '(') depth++;
            else if (c == ')') { depth--; if (depth == 0) { if (vsLength(cur)) saAdd(params, vsValue(cur)); p++; break; } }
            else if (c == ',') { if (vsLength(cur)) saAdd(params, vsValue(cur)); vsClear(cur); }
            else if (isident((unsigned char)c) || c == '.') vsPut(cur, c);
        }
        vsDelete(cur);
        e.ext.signature = vsValue(sig);
    }
    if (!undef) e.ext.endLine = endLine;
    int cork = makeTagEntry(&e);
    if (params && Cpp.client.macroParamKind >= 0) {
        for (size_t i = 0; i < saCount(params); i++) {
            const char *pn = saItem(params, i);
            if (strcmp(pn, "...") == 0) continue;
            tagEntryInfo pe;
            initTagEntry(&pe, pn, Cpp.client.macroParamKind);
            pe.langIndex = Cpp.client.lang;
            pe.lineNumber = line; pe.filePosition = pos;
            pe.ext.scopeIndex = cork;
            pe.isFileScope = true;
            makeTagEntry(&pe);
        }
    }
    /* macrodef field */
    int mf = getLangFieldIndexByName(Cpp.client.lang, "macrodef");
    if (mf >= 0 && cork && isLangFieldEnabled(Cpp.client.lang, mf) && !undef) {
        while (*p == ' ' || *p == '\t') p++;
        char *def = xstrdup(p);
        /* collapse newlines */
        for (char *q = def; *q; q++) if (*q == '\n') *q = ' ';
        char *t = strTrim(def);
        if (*t) attachParserFieldToCorkEntry(cork, mf, t);
        free(def);
    }
    if (sig) vsDelete(sig);
    if (params) saDelete(params);
    free(name);
}

static void directiveInclude(const char *text, unsigned long line, long pos) {
    const char *p = text;
    while (*p == ' ' || *p == '\t') p++;
    if (*p == '<' || *p == '"') {
        char close = (*p == '<') ? '>' : '"';
        bool system = (*p == '<');
        p++;
        const char *s = p;
        while (*p && *p != close && *p != '\n') p++;
        if (*p == close && p > s) {
            char *name = xstrndup(s, p - s);
            makeIncludeTag(name, system, line, pos);
            free(name);
        }
    }
}

/* returns true if the following text should be ignored */
static bool handleDirective(void) {
    /* read directive name */
    unsigned long line = getInputLineNumber();
    long pos = getInputFilePosition();
    vString *txt = vsNew();
    readDirectiveLine(txt);
    unsigned long endLine = getInputLineNumber();
    const char *p = vsValue(txt);
    while (*p == ' ' || *p == '\t') p++;
    const char *s = p;
    while (isalpha((unsigned char)*p)) p++;
    char *dir = xstrndup(s, p - s);
    bool ignore = isIgnore();
    if (strcmp(dir, "define") == 0) {
        if (!isIgnore()) directiveDefine(p, false, line, pos, endLine);
    } else if (strcmp(dir, "undef") == 0) {
        if (!isIgnore()) directiveDefine(p, true, line, pos, endLine);
    } else if (strcmp(dir, "include") == 0 || strcmp(dir, "include_next") == 0 || strcmp(dir, "import") == 0) {
        if (!isIgnore()) directiveInclude(p, line, pos);
    } else if (strcmp(dir, "if") == 0) {
        while (*p == ' ' || *p == '\t') p++;
        bool zero = (*p == '0' && !isident((unsigned char)p[1]) && p[1] != '.');
        ignore = pushConditional(!zero);
    } else if (strcmp(dir, "ifdef") == 0 || strcmp(dir, "ifndef") == 0) {
        ignore = pushConditional(true);
    } else if (strcmp(dir, "elif") == 0 || strcmp(dir, "elifdef") == 0 || strcmp(dir, "elifndef") == 0) {
        ignore = setIgnore(isIgnoreBranch());
        if (!ignore) chooseBranch();
    } else if (strcmp(dir, "else") == 0) {
        ignore = setIgnore(isIgnoreBranch());
        if (!ignore) chooseBranch();
    } else if (strcmp(dir, "endif") == 0) {
        ignore = popConditional();
    } else {
        /* pragma, line, error, warning, empty, etc. */
    }
    free(dir);
    vsDelete(txt);
    return ignore;
}

static int skipToEndOfString(int quote) {
    int c;
    while ((c = rawGetc()) != EOF) {
        if (c == '\\') { int n = rawGetc(); if (n == EOF) break; if (n == '\n') continue; continue; }
        if (c == quote) break;
        if (c == '\n') { rawUngetc(c); break; }
    }
    return STRING_SYMBOL;
}
static int skipToEndOfChar(void) {
    int c;
    int count = 0;
    while ((c = rawGetc()) != EOF) {
        count++;
        if (c == '\\') { int n = rawGetc(); if (n == EOF) break; continue; }
        if (c == '\'') break;
        if (c == '\n') { rawUngetc(c); break; }
        if (count > 4) { /* not a char literal (e.g. digit separators); stop */ }
    }
    return CHAR_SYMBOL;
}

int cppSkipOverCComment(void) {
    int c = rawGetc();
    while (c != EOF) {
        if (c != '*') c = rawGetc();
        else {
            int n = rawGetc();
            if (n == '/') break;
            c = n;
        }
    }
    return ' ';
}
static int skipOverCplusComment(void) {
    int c;
    while ((c = rawGetc()) != EOF) {
        if (c == '\\') { int n = rawGetc(); if (n == '\n') continue; rawUngetc(n); }
        else if (c == '\n') break;
    }
    return c;
}

static bool skipRawString(void) {
    /* positioned after R" ; read delimiter up to '(' */
    char delim[32]; int n = 0;
    int c;
    while ((c = rawGetc()) != EOF && c != '(' && n < 31) delim[n++] = (char)c;
    delim[n] = 0;
    if (c != '(') return false;
    /* look for )delim" */
    int m = 0;
    bool afterParen = false;
    while ((c = rawGetc()) != EOF) {
        if (c == ')') { afterParen = true; m = 0; continue; }
        if (afterParen) {
            if (m < n && c == delim[m]) { m++; continue; }
            if (m == n && c == '"') return true;
            afterParen = (c == ')');
            m = 0;
        }
    }
    return true;
}

void cppUngetc(int c) { if (Cpp.ungetIdx < 8) Cpp.ungetBuf[Cpp.ungetIdx++] = c; }

int cppGetc(void) {
    if (Cpp.ungetIdx > 0) return Cpp.ungetBuf[--Cpp.ungetIdx];
    bool ignore = isIgnore();
    int c;
    for (;;) {
        c = rawGetc();
        if (c == EOF) return EOF;
        if (c == '\n') { Cpp.accept = true; if (ignore) continue; return c; }
        if (c == ' ' || c == '\t' || c == '\f' || c == '\v' || c == '\r') { if (ignore) continue; return c; }
        if (c == '#' && Cpp.accept) {
            Cpp.accept = false;
            ignore = handleDirective();
            /* the newline will be returned on next iteration */
            if (ignore) continue;
            continue;
        }
        Cpp.accept = false;
        if (ignore) continue;
        if (c == '"') { return skipToEndOfString('"'); }
        if (c == '\'') {
            return skipToEndOfChar();
        }
        if (c == '/') {
            int n = rawGetc();
            if (n == '*') { return cppSkipOverCComment(); }
            if (n == '/') { c = skipOverCplusComment(); if (c == '\n') { Cpp.accept = true; } return c == EOF ? EOF : '\n'; }
            rawUngetc(n);
            return c;
        }
        if (c == 'R' && Cpp.client.rawStrings) {
            int n = rawGetc();
            if (n == '"') { skipRawString(); return STRING_SYMBOL; }
            rawUngetc(n);
            return c;
        }
        if ((c == 'L' || c == 'u' || c == 'U') ) {
            int n = rawGetc();
            if (n == '"') return skipToEndOfString('"');
            if (n == '\'') return skipToEndOfChar();
            if (n == '8' && Cpp.client.cplusplus) {
                int m = rawGetc();
                if (m == '"') return skipToEndOfString('"');
                if (m == '\'') return skipToEndOfChar();
                rawUngetc(m);
            }
            rawUngetc(n);
            return c;
        }
        if (c == '@' && Cpp.client.hasAtLiterals) {
            int n = rawGetc();
            if (n == '"') return skipToEndOfString('"');
            rawUngetc(n);
            return c;
        }
        if (c == '\\') {
            int n = rawGetc();
            if (n == '\n') { continue; }
            rawUngetc(n);
            return c;
        }
        return c;
    }
}
