}
static bool isIgnoreBranch(void) {
    if (Cpp.nestLevel == 0) return false;
    conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
    if (Cpp.resolveRequired) c->singleBranch = true;
    return c->ignoreAllBranches || (c->branchChosen && c->singleBranch);
}
static void chooseBranch(void) {
    if (Cpp.nestLevel == 0) return;
    conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
    c->branchChosen = (c->singleBranch || Cpp.resolveRequired);
}
static bool pushConditional(bool firstBranchChosen) {
    bool ignoreAll = isIgnore();
    bool ignoreBranch = false;
    if (Cpp.nestLevel < MAX_NEST - 1) {
        Cpp.nestLevel++;
        conditionalInfo *c = &Cpp.cond[Cpp.nestLevel - 1];
