/* read rest of a directive line into vString handling continuations and comments */
static void readDirectiveLine(vString *out) {
    int c;
    for (;;) {
        c = rawGetc();
        if (c == EOF) break;
        if (c == '\\') {
            int n = rawGetc();
            if (n == '\n') { vsPut(out, '\n'); continue; }
            if (n == '\r') { int m = rawGetc(); if (m == '\n') { vsPut(out, '\n'); continue; } rawUngetc(m); continue; }
            vsPut(out, c); rawUngetc(n); continue;
        }
        if (c == '\n') { rawUngetc(c); break; }
        if (c == '/') {
            int n = rawGetc();
