/* kinds (C order): d e f g h l m p s t u v x z L D ; C++ adds c n A N U Z M P */
static int K_d, K_e, K_f, K_g, K_h, K_l, K_m, K_p, K_s, K_t, K_u, K_v, K_x, K_z, K_L, K_D, K_c, K_n, K_A, K_N, K_U, K_Z;
static int F_properties, F_macrodef, F_template, F_captures, F_name, F_specialization, F_alias, F_section;
static int Lang;
static int LangMode;  /* 1=C 2=C++ 4=CUDA */
static bool isCxx;

/* ---------- tokenizer ---------- */
static Tok *Lookahead = NULL;
static bool LastFollowedBySpace = false;

static int kwLookup(const char *s) {
    for (int i = 0; Keywords[i].name; i++) if ((Keywords[i].langs & LangMode) && strcmp(Keywords[i].name, s) == 0) return Keywords[i].id;
    return KW_NONE;
}

static int getcSkipSpace(bool *sawSpace) {
    int c;
    *sawSpace = false;
    for (;;) {
        c = cppGetc();
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v') { *sawSpace = true; continue; }
        return c;
    }
}

static Tok *readRawToken(void) {
    bool sp;
    int c = getcSkipSpace(&sp);
    Tok *t;
    unsigned long line = getInputLineNumber();
    long pos = getInputFilePosition();
    if (c == EOF) { t = tokNew(TK_EOF, NULL); }
    else if (isalpha(c) || c == '_' || c == '$' || (c & 0x80)) {
        vString *v = vsNew();
        while (c != EOF && (isalnum(c) || c == '_' || c == '$' || (c & 0x80))) { vsPut(v, c); c = cppGetc(); }
        cppUngetc(c);
        t = tokNew(TK_IDENT, vsValue(v));
        t->kw = kwLookup(vsValue(v));
        vsDelete(v);
    } else if (isdigit(c) || (c == '.' && (unsigned)(cppGetc()) , false)) {
        t = NULL;
    } else t = NULL;
    if (!t) {
        if (isdigit(c)) {
            vString *v = vsNew();
            int prev = 0;
            while (c != EOF && (isalnum(c) || c == '.' || c == '_' || c == '\'' || ((c == '+' || c == '-') && (prev == 'e' || prev == 'E' || prev == 'p' || prev == 'P')))) { vsPut(v, c); prev = c; c = cppGetc(); }
            cppUngetc(c);
            t = tokNew(TK_NUMBER, vsValue(v));
            vsDelete(v);
        } else if (c == STRING_SYMBOL) t = tokNew(TK_STRING, "\"\"");
        else if (c == CHAR_SYMBOL) t = tokNew(TK_CHAR, "''");
        else if (c == ';') t = tokNew(TK_SEMI, ";");
        else if (c == ',') t = tokNew(TK_COMMA, ",");
        else if (c == '{') t = tokNew(TK_LBRACE, "{");
        else if (c == '}') t = tokNew(TK_RBRACE, "}");
        else if (c == '(') t = tokNew(TK_PAREN, "(");
        else if (c == ')') t = tokNew(TK_RPAREN, ")");
        else if (c == '[') t = tokNew(TK_BRACKET, "[");
        else if (c == ']') t = tokNew(TK_RBRACKET, "]");
        else {
            /* operators: handle multi-char */
            char buf[4] = { (char)c, 0, 0, 0 };
            int n = cppGetc();
            if (c == ':' && n == ':') { buf[1] = ':'; }
            else if (c == '-' && n == '>') { buf[1] = '>'; int m = cppGetc(); if (m == '*') buf[2] = '*'; else cppUngetc(m); }
            else if (c == '.' && n == '.') { int m = cppGetc(); if (m == '.') { buf[1] = '.'; buf[2] = '.'; } else { cppUngetc(m); cppUngetc(n); } }
            else if ((c == '&' && n == '&') || (c == '|' && n == '|') || (c == '+' && n == '+') || (c == '-' && n == '-') || (c == '<' && n == '<' ) || (c == '>' && n == '>' && false)) { buf[1] = (char)n; int m = cppGetc(); if ((c == '<') && m == '=') buf[2] = '='; else cppUngetc(m); }
            else if (n == '=' && strchr("=!<>+-*/%&|^", c)) { buf[1] = '='; if (c == '<') { int m = cppGetc(); if (m == '>') buf[2] = '>'; else cppUngetc(m); } }
            else if (c == '.' && n == '*') { buf[1] = '*'; }
            else cppUngetc(n);
            t = tokNew(TK_OP, buf);
        }
    }
    t->line = line; t->pos = pos;
    t->precededBySpace = sp;
    /* peek for following space */
    {
        int n = cppGetc();
        t->followedBySpace = (n == ' ' || n == '\t' || n == '\n' || n == '\r' || n == '\f' || n == '\v');
        cppUngetc(n);
    }
    return t;
}

/* with -I ignore handling */
static Tok *nextToken(void) {
    Tok *t;
    if (Lookahead) { t = Lookahead; Lookahead = NULL; return t; }
    for (;;) {
        t = readRawToken();
        if (t->type == TK_IDENT) {
            int kind; const char *rep = cppGetIgnoreReplacement(t->text, &kind);
            if (kind & IGN_SKIP) {
                if (kind & IGN_SKIP_PARENS) {
                    Tok *n = readRawToken();
                    if (n->type == TK_PAREN) { int depth = 1; while (depth > 0) { Tok *m = readRawToken(); if (m->type == TK_EOF) { tokDelete(m); break; } if (m->type == TK_PAREN) depth++; else if (m->type == TK_RPAREN) depth--; tokDelete(m); } tokDelete(n); }
                    else { Lookahead = n; }
                }
                tokDelete(t);
                continue;
            } else if (kind & IGN_REPLACE) {
                free(t->text); t->text = xstrdup(rep); t->kw = kwLookup(rep);
            }
        }
        return t;
    }
}
static void pushBack(Tok *t) { Lookahead = t; }

/* ---------- statement collection ---------- */
/* Collect tokens until ';' '{' '}' at depth 0. Parens/brackets are chained. */
static Tok *collectChain(Tok *open);

static bool looksLikeTemplateStart(TokList *l) {
    if (l->count == 0) return false;
    Tok *prev = l->items[l->count - 1];
    if (prev->type == TK_IDENT && prev->kw == KW_TEMPLATE) return true;
    if (prev->type == TK_IDENT && prev->kw == KW_NONE && !prev->followedBySpace) return true;
    if (prev->type == TK_IDENT && (prev->kw == KW_TYPENAME)) return false;
    if (prev->type == TK_IDENT && prev->kw == KW_OPERATOR) return false;
    if (prev->type == TK_IDENT && prev->kw == KW_NONE) return true;
    return false;
}

/* try to collect an angle chain starting after '<'; returns chain tok or NULL (tokens restored) */
static Tok *tryCollectAngle(Tok *lt) {
    TokList *saved = tlNew();
    int depth = 1;
    Tok *chain = tokNew(TK_ANGLE, NULL);
    chain->chain = tlNew();
    chain->line = lt->line; chain->pos = lt->pos; chain->precededBySpace = lt->precededBySpace;
    bool ok = false;
    int guard = 0;
    while (guard++ < 2000) {
        Tok *t = nextToken();
        if (t->type == TK_EOF || t->type == TK_SEMI || t->type == TK_LBRACE || t->type == TK_RBRACE) { tlAdd(saved, t); break; }
        if (t->type == TK_OP && strcmp(t->text, ">") == 0) {
            depth--;
            if (depth == 0) { chain->endLine = t->line; chain->followedBySpace = t->followedBySpace; tokDelete(t); ok = true; break; }
            tlAdd(chain->chain, t); continue;
        }
        if (t->type == TK_OP && strcmp(t->text, ">>") == 0) {
            depth -= 2;
            if (depth <= 0) { chain->endLine = t->line; chain->followedBySpace = t->followedBySpace; tokDelete(t); ok = true; if (depth < 0) { /* one extra '>' belongs to outer */ Lookahead = tokNew(TK_OP, ">"); } break; }
            tlAdd(chain->chain, t); continue;
        }
        if (t->type == TK_OP && strcmp(t->text, ">=") == 0) { tlAdd(saved, t); break; }
        if (t->type == TK_OP && strcmp(t->text, "<") == 0) { depth++; tlAdd(chain->chain, t); continue; }
        if (t->type == TK_OP && (strcmp(t->text, "&&") == 0 || strcmp(t->text, "||") == 0)) { tlAdd(saved, t); break; }
        if (t->type == TK_PAREN || t->type == TK_BRACKET) { Tok *c = collectChain(t); tlAdd(chain->chain, c); continue; }
        if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tlAdd(saved, t); break; }
        tlAdd(chain->chain, t);
    }
    if (ok) { tlDelete(saved); return chain; }
    /* failure: cannot push back many tokens; we stash them into a pending list */
    extern void stashTokens(Tok *lt, TokList *chainToks, TokList *saved);
    stashTokens(lt, chain->chain, saved);
    chain->chain = NULL; tokDelete(chain);
    saved->count = 0; tlDelete(saved);
    return NULL;
}

/* pending tokens queue (for failed angle collection) */
static TokList *Pending = NULL;
void stashTokens(Tok *lt, TokList *chainToks, TokList *saved) {
    if (!Pending) Pending = tlNew();
    /* order: lt as plain '<' op, then chain tokens, then saved, then existing Lookahead */
    TokList *n = tlNew();
    Tok *op = tokNew(TK_OP, "<"); op->line = lt->line; op->pos = lt->pos; op->followedBySpace = lt->followedBySpace; op->precededBySpace = lt->precededBySpace;
    tlAdd(n, op);
    for (int i = 0; i < chainToks->count; i++) tlAdd(n, chainToks->items[i]);
    chainToks->count = 0;
    for (int i = 0; i < saved->count; i++) tlAdd(n, saved->items[i]);
    saved->count = 0;
    if (Lookahead) { tlAdd(n, Lookahead); Lookahead = NULL; }
    for (int i = 0; i < Pending->count; i++) tlAdd(n, Pending->items[i]);
    Pending->count = 0;
    tlDelete(Pending);
    Pending = n;
}
static Tok *nextTokenP(void) {
    if (Pending && Pending->count > 0) {
        Tok *t = Pending->items[0];
        memmove(Pending->items, Pending->items + 1, (Pending->count - 1) * sizeof(Tok*));
        Pending->count--;
        return t;
    }
    return nextToken();
}
static void pushBackP(Tok *t) {
    if (Pending && Pending->count > 0) {
        if (Pending->count == Pending->cap) { Pending->cap *= 2; Pending->items = xrealloc(Pending->items, Pending->cap * sizeof(Tok*)); }
        memmove(Pending->items + 1, Pending->items, Pending->count * sizeof(Tok*));
        Pending->items[0] = t; Pending->count++;
    } else pushBack(t);
}

static Tok *collectChain(Tok *open) {
    tokType closeType = open->type == TK_PAREN ? TK_RPAREN : open->type == TK_BRACKET ? TK_RBRACKET : TK_RBRACE;
    open->chain = tlNew();
    int guard = 0;
    for (;;) {
        Tok *t = nextTokenP();
        if (t->type == TK_EOF) { tokDelete(t); break; }
        if (t->type == closeType) { open->endLine = t->line; open->followedBySpace = t->followedBySpace; tokDelete(t); break; }
        if (t->type == TK_PAREN || t->type == TK_BRACKET || t->type == TK_LBRACE) {
            if (t->type == TK_LBRACE) { t->type = TK_BRACE; }
            tlAdd(open->chain, collectChain(t));
            continue;
        }
        if (t->type == TK_RBRACE && closeType != TK_RBRACE) { pushBackP(t); break; } /* unbalanced: stop */
        if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tokDelete(t); continue; } /* mismatched; drop */
        if (t->type == TK_OP && strcmp(t->text, "<") == 0 && isCxx && looksLikeTemplateStart(open->chain)) {
            Tok *a = tryCollectAngle(t);
            if (a) { tokDelete(t); tlAdd(open->chain, a); continue; }
            /* failure path: '<' op pushed in Pending */
            tokDelete(t);
            continue;
        }
        if (++guard > 2000000) break;
        tlAdd(open->chain, t);
    }
    return open;
}

/* returns terminator type: TK_SEMI, TK_LBRACE, TK_RBRACE, TK_EOF */
static tokType readStatement(TokList *out, Tok **termTok) {
    for (;;) {
        Tok *t = nextTokenP();
        if (t->type == TK_EOF || t->type == TK_SEMI || t->type == TK_LBRACE || t->type == TK_RBRACE) { *termTok = t; return t->type; }
        if (t->type == TK_PAREN || t->type == TK_BRACKET) { tlAdd(out, collectChain(t)); continue; }
        if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tokDelete(t); continue; }
        if (t->type == TK_OP && strcmp(t->text, "<") == 0 && isCxx && looksLikeTemplateStart(out)) {
            /* don't treat as template inside initializers */
            bool afterAssign = false;
            for (int i = 0; i < out->count; i++) if (out->items[i]->type == TK_OP && strcmp(out->items[i]->text, "=") == 0) afterAssign = true;
            if (!afterAssign) {
                Tok *a = tryCollectAngle(t);
                if (a) { tokDelete(t); tlAdd(out, a); continue; }
                tokDelete(t);
                continue;
            }
        }
        tlAdd(out, t);
    }
}

/* ---------- scopes ---------- */
typedef struct {
    int cork;
    int kind;       /* kind index or -1 for root; -2 for function body block */
    int access;     /* 0 none, 1 public, 2 protected, 3 private */
    int memberCount;
    char *name;
    bool isFunction;
} Scope;
static Scope ScopeStack[128];
static int ScopeTop = 0;   /* count */

static Scope *curScope(void) { return ScopeTop ? &ScopeStack[ScopeTop - 1] : NULL; }
static int curScopeCork(void) { for (int i = ScopeTop - 1; i >= 0; i--) if (ScopeStack[i].cork > 0) return ScopeStack[i].cork; return CORK_NIL; }
static int curScopeKind(void) { for (int i = ScopeTop - 1; i >= 0; i--) if (ScopeStack[i].kind != -2) return ScopeStack[i].kind; return -1; }
static bool inFunctionScope(void) { for (int i = ScopeTop - 1; i >= 0; i--) { if (ScopeStack[i].isFunction) return true; if (ScopeStack[i].kind >= 0 && ScopeStack[i].kind != K_f) return false; } return false; }
static bool inClassScope(void) { int k = curScopeKind(); return k >= 0 && (k == K_c || k == K_s || k == K_u); }
static bool inNamespaceOrGlobal(void) { int k = curScopeKind(); return k < 0 || k == K_n; }
static void pushScope(int cork, int kind, int access, const char *name, bool isFunction) {
    if (ScopeTop >= 128) return;
    Scope *s = &ScopeStack[ScopeTop++];
    s->cork = cork; s->kind = kind; s->access = access; s->memberCount = 0; s->name = name ? xstrdup(name) : NULL; s->isFunction = isFunction;
}
static void popScope(unsigned long endLine) {
    if (ScopeTop == 0) return;
    Scope *s = &ScopeStack[--ScopeTop];
    if (s->cork > 0 && endLine) setTagEndLineToCorkEntry(s->cork, endLine);
    free(s->name); s->name = NULL;
}

/* known type names: name -> kind (for scope qualification) */
typedef struct { char *name; int kind; int cork; } knownType;
static ptrArray *KnownTypes = NULL;
static void rememberType(const char *name, int kind, int cork) {
    if (!KnownTypes) KnownTypes = paNew(NULL);
    knownType *k = xmalloc(sizeof *k); k->name = xstrdup(name); k->kind = kind; k->cork = cork;
    paAdd(KnownTypes, k);
}
static knownType *lookupType(const char *name) {
    if (!KnownTypes) return NULL;
    for (int i = (int)paCount(KnownTypes) - 1; i >= 0; i--) { knownType *k = paItem(KnownTypes, i); if (strcmp(k->name, name) == 0) return k; }
    return NULL;
}

static const char *accessName(int a) { return a == 1 ? "public" : a == 2 ? "protected" : a == 3 ? "private" : NULL; }

/* ---------- tag helpers ---------- */
static bool isStorageSpecifier(Tok *t) {
    if (t->type != TK_IDENT) return false;
    switch (t->kw) {
    case KW_STATIC: case KW_EXTERN: case KW_INLINE: case KW_VIRTUAL: case KW_EXPLICIT: case KW_FRIEND: case KW_MUTABLE: case KW_REGISTER:
    case KW_THREAD_LOCAL: case KW_CONSTEXPR: case KW_CONSTEVAL: case KW_CONSTINIT: case KW_TYPEDEF: case KW_EXPORT: case KW_NORETURN:
    case KW_FORCEINLINE: case KW_EXTENSION: case KW_STDCALL: case KW_CDECL: case KW_GLOBAL: case KW_DEVICE: case KW_HOST: case KW_SHARED: case KW_CONSTANT: case KW_MANAGED:
        return true;
    default: return false;
    }
}
static bool isAttributeTok(TokList *l, int i) {
    Tok *t = l->items[i];
    if (t->type == TK_IDENT && (t->kw == KW_ATTRIBUTE || t->kw == KW_DECLSPEC || t->kw == KW_ALIGNAS) && i + 1 < l->count && l->items[i+1]->type == TK_PAREN) return true;
    if (t->type == TK_BRACKET && t->chain && t->chain->count > 0 && t->chain->items[0]->type == TK_BRACKET) return true;  /* [[...]] */
    return false;
}
/* remove attributes & storage specifiers from a token list copy -> returns new list (shallow: tokens shared) */
static TokList *stripSpecifiers(TokList *l, int from, int to, bool *sawStatic, bool *sawExtern, bool *sawTypedef, bool *sawVirtual, bool *sawInline) {
    TokList *r = tlNew();
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (isAttributeTok(l, i)) { if (t->type == TK_IDENT) i++; continue; }
        if (isStorageSpecifier(t)) {
            if (t->kw == KW_STATIC && sawStatic) *sawStatic = true;
            if (t->kw == KW_EXTERN && sawExtern) *sawExtern = true;
            if (t->kw == KW_TYPEDEF && sawTypedef) *sawTypedef = true;
            if (t->kw == KW_VIRTUAL && sawVirtual) *sawVirtual = true;
            if ((t->kw == KW_INLINE || t->kw == KW_FORCEINLINE) && sawInline) *sawInline = true;
            continue;
        }
        tlAdd(r, t);
    }
    return r;
}
static void tlFreeShallow(TokList *l) { if (l) { free(l->items); free(l); } }

/* compute typeref from type tokens [from,to) of list l */
static void setTypeRef(tagEntryInfo *e, TokList *l, int from, int to, vString *kindBuf, vString *nameBuf) {
    if (to <= from) return;
    int i = from;
    Tok *t0 = l->items[i];
    const char *kind = "typename";
    if (t0->type == TK_IDENT && (t0->kw == KW_STRUCT || t0->kw == KW_UNION || t0->kw == KW_ENUM || t0->kw == KW_CLASS) && to - from >= 2) {
        kind = t0->kw == KW_STRUCT ? "struct" : t0->kw == KW_UNION ? "union" : t0->kw == KW_ENUM ? "enum" : "class";
        i++;
    }
    vsClear(nameBuf);
    tokJoinRange(nameBuf, l, i, to);
    if (vsLength(nameBuf) == 0) return;
    vsCopy(kindBuf, kind);
    e->ext.typeRefKind = vsValue(kindBuf);
    e->ext.typeRefName = vsValue(nameBuf);
}

static bool fileScopeForVariable(bool isStatic) {
    if (inFunctionScope()) return true;
    if (inNamespaceOrGlobal()) return isStatic && !isInputHeaderFile();
    return !isInputHeaderFile();
}
static bool fileScopeForFunction(bool isStatic) { return fileScopeForVariable(isStatic); }

static void addProperty(vString *props, const char *p) { if (vsLength(props)) vsPut(props, ','); vsCat(props, p); }

/* ---------- declaration processing ---------- */

/* find index of top-level '=' in [from,to) */
static int findAssign(TokList *l, int from, int to) {
    for (int i = from; i < to; i++) if (l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "=") == 0) return i;
    return -1;
}

static bool isOperatorKeyword(Tok *t) { return t->type == TK_IDENT && t->kw == KW_OPERATOR; }

/* Build operator name from tokens starting at index i (operator keyword). returns end index (exclusive, before paren) */
static int buildOperatorName(TokList *l, int i, int to, vString *name) {
    vsClear(name);
    vsCat(name, "operator");
    int j = i + 1;
    bool first = true;
    while (j < to && l->items[j]->type != TK_PAREN) {
        Tok *t = l->items[j];
        if (first && t->precededBySpace) vsPut(name, ' ');
        else if (!first && t->precededBySpace) vsPut(name, ' ');
        if (t->type == TK_PAREN || t->type == TK_BRACKET || t->type == TK_ANGLE) tokChainToString(name, t);
        else vsCat(name, t->text);
        first = false;
        j++;
    }
    /* operator() or operator[] : the paren is the operator itself when followed by another paren */
    if (j < to && l->items[j]->type == TK_PAREN && j + 1 < to && l->items[j+1]->type == TK_PAREN) {
        if (l->items[j]->chain->count == 0) { if (l->items[j]->precededBySpace) vsPut(name, ' '); vsCat(name, "()"); j++; }
    }
    return j;
}

/* qualified name: tokens like A :: B :: name -> returns name token index, and fills scope string */
static int splitQualifiedName(TokList *l, int nameIdx, vString *qual) {
    vsClear(qual);
    int i = nameIdx;
    /* walk backwards over :: X pairs */
    int start = nameIdx;
    while (start - 2 >= 0 && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "::") == 0 && (l->items[start-2]->type == TK_IDENT || l->items[start-2]->type == TK_ANGLE)) {
        start -= 2;
        if (l->items[start]->type == TK_ANGLE && start - 1 >= 0 && l->items[start-1]->type == TK_IDENT) start--;
    }
    if (start - 1 >= 0 && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "::") == 0) start--; /* leading :: */
    for (int k = start; k < i; k++) {
        Tok *t = l->items[k];
        if (t->type == TK_OP) { if (k != start || true) { if (vsLength(qual)) vsCat(qual, "::"); } }
        else if (t->type == TK_ANGLE) tokChainToString(qual, t);
        else vsCat(qual, t->text);
    }
    /* remove possible trailing "::" */
    return start;
}

/* make a scope chain for a qualified name "A::B" under current scope; returns cork for innermost (creating placeholders) */
static int scopeForQualifier(const char *qual, int *kindOut) {
    *kindOut = -1;
    if (!qual || !*qual) return curScopeCork();
    /* look up the last component only in known types */
    const char *last = strrchr(qual, ':');
    last = last ? last + 1 : qual;
    knownType *k = lookupType(qual);
    if (!k) k = lookupType(last);
    if (k) { *kindOut = k->kind; return k->cork; }
    /* unknown: create a placeholder tag so scope prints */
    tagEntryInfo e;
    initTagEntry(&e, qual, isCxx ? K_c : K_s);
    e.placeholder = true;
    e.ext.scopeIndex = curScopeCork();
    int cork = makeTagEntry(&e);
    *kindOut = isCxx ? K_c : K_s;
    return cork;
}

/* locate the declarator name in [from,to): last identifier not inside chains that is followed by end/,/=/[ /:/( */
static int findDeclaratorName(TokList *l, int from, int to) {
    /* handle (*name)(...) : paren chain whose inner has '*' + ident */
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (t->type == TK_PAREN && t->chain && t->chain->count >= 2) {
            Tok *a = t->chain->items[0];
            if (a->type == TK_OP && (strcmp(a->text, "*") == 0 || strcmp(a->text, "&") == 0 || strcmp(a->text, "^") == 0)) {
                /* find identifier inside */
                for (int j = 1; j < t->chain->count; j++) if (t->chain->items[j]->type == TK_IDENT && t->chain->items[j]->kw == KW_NONE) return -(1000 * i + j) - 1;  /* encoded */
            }
            /* ( ident ) e.g. int (x) = 3 */
        }
    }
    int last = -1;
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (t->type == TK_IDENT && t->kw == KW_NONE) {
            /* skip if followed by :: (qualifier part) */
            if (i + 1 < to && l->items[i+1]->type == TK_OP && strcmp(l->items[i+1]->text, "::") == 0) continue;
            last = i;
            /* name is followed by '=' or '[' or ':' (bitfield) or '(' (ctor init) or end */
            if (i + 1 == to) return i;
            Tok *n = l->items[i+1];
            if (n->type == TK_OP && (strcmp(n->text, "=") == 0 || strcmp(n->text, ":") == 0)) return i;
            if (n->type == TK_BRACKET || n->type == TK_PAREN || n->type == TK_BRACE) return i;
            if (n->type == TK_IDENT && (n->kw == KW_ATTRIBUTE || n->kw == KW_ASM)) return i;
        }
        if (t->type == TK_OP && (strcmp(t->text, "=") == 0 || strcmp(t->text, ":") == 0)) break;
    }
    return last;
}

typedef struct {
    int nameTok;          /* index of the name token (>=0) or encoded for function pointers */
    int typeEnd;          /* exclusive end of type tokens */
    int declEnd;          /* exclusive end of declarator (before =, : bitfield) */
} declaratorInfo;

/* emit a variable-like tag */
static int emitVariable(TokList *l, int typeFrom, int typeTo, int nameIdx, int declFrom, int declTo, int kind, bool isStatic, bool isExtern, unsigned long endLine, vString *props, Tok **nameTokOut) {
    vString *kb = vsNew(), *nb = vsNew();
    Tok *nameTok;
    int fpParen = -1, fpInner = -1;
    if (nameIdx < 0) { int enc = -nameIdx - 1; fpParen = enc / 1000; fpInner = enc % 1000; nameTok = l->items[fpParen]->chain->items[fpInner]; }
    else nameTok = l->items[nameIdx];
    if (nameTokOut) *nameTokOut = nameTok;
    tagEntryInfo e;
    initTagEntry(&e, nameTok->text, kind);
    e.lineNumber = nameTok->line; e.filePosition = nameTok->pos;
    /* type: tokens from typeFrom to typeTo, plus declarator parts other than the name (pointers, arrays, function pointer parens) */
    {
        /* build a temporary list: type tokens + declarator tokens excluding the name */
        TokList *tmp = tlNew();
        for (int i = typeFrom; i < typeTo; i++) tlAdd(tmp, l->items[i]);
        if (fpParen >= 0) {
            /* function pointer: (*name)(args) -> (*)(args) */
            Tok *p = l->items[fpParen];
            Tok *np = tokNew(TK_PAREN, NULL); np->chain = tlNew();
            for (int j = 0; j < p->chain->count; j++) if (j != fpInner) tlAdd(np->chain, p->chain->items[j]);
            tlAdd(tmp, np);
            for (int i = fpParen + 1; i < declTo; i++) tlAdd(tmp, l->items[i]);
            setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
            np->chain->count = 0; tlDelete(np->chain); np->chain = NULL; tokDelete(np);
        } else {
            for (int i = declFrom; i < declTo; i++) if (i != nameIdx) tlAdd(tmp, l->items[i]);
            setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
        }
        tlFreeShallow(tmp);
    }
    e.isFileScope = fileScopeForVariable(isStatic);
    if (kind == K_x) e.isFileScope = false;
    if (kind == K_l) e.isFileScope = true;
    int sc = curScopeCork();
    e.ext.scopeIndex = sc;
    Scope *s = curScope();
    if (kind == K_m && s && s->access) e.ext.access = (char *)accessName(s->access);
    if (kind == K_m && s) { e.ext.nth = s->memberCount++; }
    e.ext.endLine = endLine;
    if (props && vsLength(props) && F_properties >= 0) attachParserField(&e, F_properties, vsValue(props));
    int cork = makeTagEntry(&e);
    vsDelete(kb); vsDelete(nb);
    return cork;
}

/* parameters of a function paren chain: emit z tags and nth */
static void emitParameters(Tok *paren, int funcCork) {
    if (K_z < 0 || !isLanguageKindEnabled(Lang, K_z)) return;
    if (!paren || !paren->chain) return;
    TokList *c = paren->chain;
    int start = 0, nth = 0;
    for (int i = 0; i <= c->count; i++) {
        if (i == c->count || c->items[i]->type == TK_COMMA) {
            if (i > start) {
                /* skip "void" alone and "..." */
                if (!(i - start == 1 && (c->items[start]->kw == KW_VOID || (c->items[start]->type == TK_OP && strcmp(c->items[start]->text, "...") == 0)))) {
                    int eq = findAssign(c, start, i);
                    int declTo = eq >= 0 ? eq : i;
                    int nameIdx = findDeclaratorName(c, start, declTo);
                    if (nameIdx != -1 && !(nameIdx >= 0 && nameIdx == start && declTo - start == 1 && lookupType(c->items[nameIdx]->text) == NULL && false)) {
                        if (nameIdx >= 0 && nameIdx == start && declTo - start == 1) {
                            /* lone identifier: it's a type (e.g. "int" is keyword, "size_t" unknown) -> no name */
                        } else {
                            /* type is from start to nameIdx-ish: compute typeEnd as start of declarator = position of first '*' or name */
                            int typeTo = nameIdx >= 0 ? nameIdx : (-nameIdx - 1) / 1000;
                            while (typeTo > start && c->items[typeTo-1]->type == TK_OP && (strcmp(c->items[typeTo-1]->text, "*") == 0 || strcmp(c->items[typeTo-1]->text, "&") == 0 || strcmp(c->items[typeTo-1]->text, "&&") == 0)) typeTo--;
                            int declFrom = typeTo;
                            vString *kb = vsNew(), *nb = vsNew();
                            Tok *nameTok = nameIdx >= 0 ? c->items[nameIdx] : c->items[(-nameIdx-1)/1000]->chain->items[(-nameIdx-1)%1000];
                            tagEntryInfo e;
                            initTagEntry(&e, nameTok->text, K_z);
                            e.lineNumber = nameTok->line; e.filePosition = nameTok->pos;
                            TokList *tmp = tlNew();
                            for (int k = start; k < typeTo; k++) tlAdd(tmp, c->items[k]);
                            if (nameIdx < 0) {
                                int fpParen = (-nameIdx-1)/1000, fpInner = (-nameIdx-1)%1000;
                                Tok *p = c->items[fpParen];
                                Tok *np = tokNew(TK_PAREN, NULL); np->chain = tlNew();
                                for (int j = 0; j < p->chain->count; j++) if (j != fpInner) tlAdd(np->chain, p->chain->items[j]);
                                tlAdd(tmp, np);
                                for (int k = fpParen + 1; k < declTo; k++) tlAdd(tmp, c->items[k]);
                                setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
                                np->chain->count = 0; tlDelete(np->chain); np->chain = NULL; tokDelete(np);
                            } else {
                                for (int k = declFrom; k < declTo; k++) if (k != nameIdx) tlAdd(tmp, c->items[k]);
                                setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
                            }
                            tlFreeShallow(tmp);
                            e.isFileScope = true;
                            e.ext.scopeIndex = funcCork;
                            e.ext.nth = nth;
                            makeTagEntry(&e);
                            vsDelete(kb); vsDelete(nb);
                        }
                    }
                }
                nth++;
            }
            start = i + 1;
        }
    }
}

/* signature string from paren chain + trailing qualifiers [qfrom,qto) */
static void buildSignature(vString *sig, Tok *paren, TokList *l, int qfrom, int qto) {
    vsClear(sig);
    tokChainToString(sig, paren);
    for (int i = qfrom; i < qto; i++) {
        Tok *t = l->items[i];
        if (t->type == TK_OP && strcmp(t->text, "=") == 0) break;   /* = 0 / = default / = delete */
        if (t->type == TK_OP && strcmp(t->text, ":") == 0) break;   /* ctor initializer */
        if (t->type == TK_IDENT && (t->kw == KW_OVERRIDE || t->kw == KW_FINAL)) { continue; }
        if (isAttributeTok(l, i)) { if (t->type == TK_IDENT) i++; continue; }
        if (t->type == TK_IDENT && t->kw == KW_REQUIRES) break;
        vsPut(sig, ' ');
        if (t->type == TK_PAREN || t->type == TK_BRACKET || t->type == TK_ANGLE || t->type == TK_BRACE) {
            if (vsLast(sig) == ' ' && i > qfrom && (l->items[i-1]->kw == KW_NOEXCEPT || l->items[i-1]->kw == KW_THROW || l->items[i-1]->kw == KW_ALIGNAS)) vsChop(sig);
            tokChainToString(sig, t);
        } else vsCat(sig, t->text);
    }
}

static void collectProps(TokList *l, int from, int to, vString *props, bool *isStatic, bool *isVirtual, bool *isInline, bool *isExtern) {
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (t->type != TK_IDENT) continue;
        switch (t->kw) {
        case KW_STATIC: *isStatic = true; break;
        case KW_VIRTUAL: *isVirtual = true; break;
        case KW_INLINE: case KW_FORCEINLINE: *isInline = true; break;
        case KW_EXTERN: *isExtern = true; break;
        default: break;
        }
    }
}

static int emitFunction(TokList *l, int from, int to, int parenIdx, int nameIdx, int nameStart, bool isDefinition, Tok **nameTokOut, bool isLambda, const char *overrideName) {
    Tok *paren = l->items[parenIdx];
    Tok *nameTok = nameIdx >= 0 ? l->items[nameIdx] : paren;
    vString *name = vsNew();
    if (overrideName) vsCat(name, overrideName);
    else if (nameIdx >= 0 && isOperatorKeyword(l->items[nameIdx])) { buildOperatorName(l, nameIdx, parenIdx, name); }
    else if (nameIdx >= 0) {
        /* destructor ~Name */
        if (nameIdx > 0 && l->items[nameIdx-1]->type == TK_OP && strcmp(l->items[nameIdx-1]->text, "~") == 0) vsPut(name, '~');
        vsCat(name, nameTok->text);
