        bool st = false, ex = false, td = false, vi = false, in = false;
        TokList *typ = stripSpecifiers(l, from, nameStart, &st, &ex, &td, &vi, &in);
        /* remove trailing '~' for destructor */
        while (typ->count && typ->items[typ->count-1]->type == TK_OP && strcmp(typ->items[typ->count-1]->text, "~") == 0) typ->count--;
        isStatic = st; isVirtual = vi; isInline = in; isExtern = ex;
        /* trailing return type -> type */
        int arrow = -1;
        for (int i = parenIdx + 1; i < to; i++) if (l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "->") == 0) { arrow = i; break; }
        if (arrow >= 0 && typ->count == 1 && typ->items[0]->kw == KW_AUTO) {
            int end = to;
            for (int i = arrow + 1; i < to; i++) if (l->items[i]->type == TK_IDENT && (l->items[i]->kw == KW_REQUIRES || l->items[i]->kw == KW_OVERRIDE || l->items[i]->kw == KW_FINAL)) { end = i; break; }
            for (int i = arrow + 1; i < to; i++) if (l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "=") == 0) { end = i; break; }
            setTypeRef(&e, l, arrow + 1, end, kb, nb);
        } else if (typ->count > 0) {
