            setTypeRef(&e, typ, 0, typ->count, kb, nb);
        }
        tlFreeShallow(typ);
    }
    vString *sig = vsNew();
    buildSignature(sig, paren, l, parenIdx + 1, to);
    if (isLambda && paren->followedBySpace) vsPut(sig, ' ');
    e.ext.signature = vsValue(sig);
    e.isFileScope = fileScopeForFunction(isStatic);
    if (isLambda) e.isFileScope = true;
    /* scope */
    int scopeCork = curScopeCork();
    if (nameIdx >= 0 && nameStart < nameIdx) {
        vString *qual = vsNew();
