        if (vsLength(qual)) {
            int kindOut;
            scopeCork = scopeForQualifier(vsValue(qual), &kindOut);
            e.isFileScope = fileScopeForFunction(isStatic) && !inNamespaceOrGlobal();
            if (inNamespaceOrGlobal()) e.isFileScope = isStatic && !isInputHeaderFile();
        }
        vsDelete(qual);
    }
    e.ext.scopeIndex = scopeCork;
    Scope *s = curScope();
    if (inClassScope() && s && s->access && !isLambda) e.ext.access = (char *)accessName(s->access);
    /* properties */
    {
        bool pure = false, isConst = false, isVolatile = false, isDefault = false, isDelete = false, isOverride = false, isFinal = false, isNoexcept = false, isConstexpr = false, isExplicit = false, isFriend = false;
        for (int i = parenIdx + 1; i < to; i++) {
