    }
    if (isLambda) { markTagExtraBit(&e, XTAG_ANONYMOUS); }
    int cork = makeTagEntry(&e);
    if (nameTokOut) *nameTokOut = nameTok;
    emitParameters(paren, cork);
    vsDelete(name); vsDelete(sig); vsDelete(kb); vsDelete(nb); vsDelete(props);
    return cork;
}
