static void pushBack(Tok *t) { Lookahead = t; }

/* ---------- statement collection ---------- */
/* Collect tokens until ';' '{' '}' at depth 0. Parens/brackets are chained. */
static Tok *collectChain(Tok *open);

static bool looksLikeTemplateStart(TokList *l) {
    if (l->count == 0) return false;
    Tok *prev = l->items[l->count - 1];
    if (prev->type == TK_IDENT && prev->kw == KW_TEMPLATE) return true;
    if (prev->type == TK_IDENT && prev->kw == KW_NONE && !prev->followedBySpace) return true;
    if (prev->type == TK_IDENT && (prev->kw == KW_TYPENAME)) return false;
    if (prev->type == TK_IDENT && prev->kw == KW_OPERATOR) return false;
    if (prev->type == TK_IDENT && prev->kw == KW_NONE) return true;
    return false;
}

/* try to collect an angle chain starting after '<'; returns chain tok or NULL (tokens restored) */
static Tok *tryCollectAngle(Tok *lt) {
    TokList *saved = tlNew();
    int depth = 1;
    Tok *chain = tokNew(TK_ANGLE, NULL);
    chain->chain = tlNew();
    chain->line = lt->line; chain->pos = lt->pos; chain->precededBySpace = lt->precededBySpace;
    bool ok = false;
    int guard = 0;
    while (guard++ < 2000) {
        Tok *t = nextToken();
        if (t->type == TK_EOF || t->type == TK_SEMI || t->type == TK_LBRACE || t->type == TK_RBRACE) { tlAdd(saved, t); break; }
        if (t->type == TK_OP && strcmp(t->text, ">") == 0) {
            depth--;
            if (depth == 0) { chain->endLine = t->line; chain->followedBySpace = t->followedBySpace; tokDelete(t); ok = true; break; }
            tlAdd(chain->chain, t); continue;
        }
        if (t->type == TK_OP && strcmp(t->text, ">>") == 0) {
            depth -= 2;
            if (depth <= 0) { chain->endLine = t->line; chain->followedBySpace = t->followedBySpace; tokDelete(t); ok = true; if (depth < 0) { /* one extra '>' belongs to outer */ Lookahead = tokNew(TK_OP, ">"); } break; }
            tlAdd(chain->chain, t); continue;
        }
        if (t->type == TK_OP && strcmp(t->text, ">=") == 0) { tlAdd(saved, t); break; }
        if (t->type == TK_OP && strcmp(t->text, "<") == 0) { depth++; tlAdd(chain->chain, t); continue; }
        if (t->type == TK_OP && (strcmp(t->text, "&&") == 0 || strcmp(t->text, "||") == 0)) { tlAdd(saved, t); break; }
        if (t->type == TK_PAREN || t->type == TK_BRACKET) { Tok *c = collectChain(t); tlAdd(chain->chain, c); continue; }
        if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tlAdd(saved, t); break; }
        tlAdd(chain->chain, t);
