            if (from + 1 < to && l->items[from+1]->kw == KW_NAMESPACE) {
                if (K_U >= 0) { vString *n = vsNew(); for (int i = from + 2; i < to; i++) { if (l->items[i]->type == TK_OP) vsCat(n, l->items[i]->text); else vsCat(n, l->items[i]->text); } tagEntryInfo e; initTagEntry(&e, vsValue(n), K_U); e.lineNumber = l->items[from+2 < to ? from+2 : from]->line; e.filePosition = l->items[from+2 < to ? from+2 : from]->pos; e.isFileScope = !isInputHeaderFile(); e.ext.scopeIndex = curScopeCork(); makeTagEntry(&e); vsDelete(n); }
                return;
            }
            int eq = findAssign(l, from, to);
            if (eq >= 0 && eq == from + 2 && l->items[from+1]->type == TK_IDENT) {
                Tok *nt = l->items[from+1];
                tagEntryInfo e;
                initTagEntry(&e, nt->text, K_t);
                e.lineNumber = nt->line; e.filePosition = nt->pos;
                vString *kb = vsNew(), *nb = vsNew();
                bool st = false, ex = false, td = false, vi = false, in = false;
                TokList *typ = stripSpecifiers(l, eq + 1, to, &st, &ex, &td, &vi, &in);
                /* remove 'typename' */
                setTypeRef(&e, typ, 0, typ->count, kb, nb);
                tlFreeShallow(typ);
                e.isFileScope = !isInputHeaderFile();
                e.ext.scopeIndex = curScopeCork();
                Scope *cs = curScope();
                if (inClassScope() && cs && cs->access) e.ext.access = (char *)accessName(cs->access);
                makeTagEntry(&e);
