    if (inFunctionScope() && first->type == TK_IDENT && first->kw == KW_NONE && from + 1 < to && l->items[from+1]->type == TK_OP && strcmp(l->items[from+1]->text, ":") == 0 && !(from + 2 < to && l->items[from+2]->type == TK_OP && strcmp(l->items[from+2]->text, ":") == 0)) {
        if (K_L >= 0) { tagEntryInfo e; initTagEntry(&e, first->text, K_L); e.lineNumber = first->line; e.filePosition = first->pos; e.isFileScope = true; e.ext.scopeIndex = curScopeCork(); makeTagEntry(&e); }
        /* continue with the rest */
        from += 2;
        if (from >= to) return;
        TokList *rest = tlNew(); for (int i = from; i < to; i++) tlAdd(rest, l->items[i]);
