                if (isProto) {
                    /* multiple declarators e.g. int f(int), g(int); handle first only + rest */
                    Tok *nt;
                    int qto = to;
                    for (int j = paren + 1; j < to; j++) if (l->items[j]->type == TK_COMMA) { qto = j; break; }
