                return;
            }
        }
        /* function pointer variable: TYPE (*name)(args); */
        int nameIdx = findDeclaratorName(l, from, to);
        if (nameIdx < -0) {
            int fpParen = (-nameIdx - 1) / 1000;
            int typeTo = fpParen;
            int kind = inClassScope() ? K_m : (inFunctionScope() ? K_l : (isExtern ? K_x : K_v));
            if (kind == K_l && !isLanguageKindEnabled(Lang, K_l)) return;
            bool st = false, ex = false, td = false, vi = false, in = false;
            TokList *typ = stripSpecifiers(l, from, typeTo, &st, &ex, &td, &vi, &in);
            TokList *full = tlNew();
            for (int i = 0; i < typ->count; i++) tlAdd(full, typ->items[i]);
            int tt = full->count;
            for (int i = typeTo; i < to; i++) tlAdd(full, l->items[i]);
            int eq = findAssign(full, tt, full->count);
            int declTo = eq >= 0 ? eq : full->count;
            int enc = -(1000 * (tt + (fpParen - typeTo)) + ((-nameIdx - 1) % 1000)) - 1;
            emitVariable(full, 0, tt, enc, tt, declTo, kind, isStatic, isExtern, term->line, NULL, NULL);
            tlFreeShallow(typ); tlFreeShallow(full);
