    }
    /* variables: type declarator-list */
    {
        int nameIdx0 = -1;
        /* first segment */
        int segEnd = to;
        for (int i = from; i < to; i++) {
            Tok *t = l->items[i];
            if (t->type == TK_COMMA) { segEnd = i; break; }
            if (t->type == TK_OP && strcmp(t->text, "=") == 0) { /* find comma after initializer: top-level commas in initializer are declarator separators */ for (int j = i; j < to; j++) if (l->items[j]->type == TK_COMMA) { segEnd = j; break; } break; }
        }
        int eq = findAssign(l, from, segEnd);
        int declTo = eq >= 0 ? eq : segEnd;
        for (int k = from; k < declTo; k++) if (l->items[k]->type == TK_OP && strcmp(l->items[k]->text, ":") == 0 && !(k + 1 < declTo && l->items[k+1]->type == TK_OP && strcmp(l->items[k+1]->text, ":") == 0)) { declTo = k; break; }
        nameIdx0 = findDeclaratorName(l, from, declTo);
        if (nameIdx0 == -1) return;
        if (nameIdx0 >= 0) {
            /* must have a type before the name (at least one token that is type-ish) */
            bool hasType = false;
            for (int i = from; i < nameIdx0; i++) { Tok *t = l->items[i]; if (isAttributeTok(l, i)) { if (t->type == TK_IDENT) i++; continue; } if (isStorageSpecifier(t)) continue; if (t->type == TK_IDENT || t->type == TK_ANGLE) { hasType = true; break; } if (t->type == TK_OP && strcmp(t->text, "::") == 0) { hasType = true; break; } }
            if (!hasType) {
                /* "x = 3;" assignment or expression -> ignore (unless 'auto'?) */
                return;
            }
            /* reject expression statements like "a * b;" or "foo::bar();" : name followed by operator other than = [ : */
            Tok *n = nameIdx0 + 1 < declTo ? l->items[nameIdx0+1] : NULL;
            if (n && !(n->type == TK_BRACKET || n->type == TK_IDENT || n->type == TK_PAREN)) return;
        }
        int typeTo = nameIdx0 >= 0 ? nameIdx0 : (-nameIdx0 - 1) / 1000;
        while (typeTo > from && l->items[typeTo-1]->type == TK_OP && (strcmp(l->items[typeTo-1]->text, "*") == 0 || strcmp(l->items[typeTo-1]->text, "&") == 0 || strcmp(l->items[typeTo-1]->text, "&&") == 0 || strcmp(l->items[typeTo-1]->text, "^") == 0)) typeTo--;
        /* also exclude 'const'/'volatile' after '*' belonging to declarator?  keep in type */
        int kind = inClassScope() ? K_m : (inFunctionScope() ? K_l : (isExtern ? K_x : K_v));
        if (kind == K_l && !isLanguageKindEnabled(Lang, K_l)) return;
        if (kind == K_x && !isLanguageKindEnabled(Lang, K_x)) return;
        /* reject if type is only keywords like "return" etc. (already handled) or if in function and looks like expression "a.b = c" */
        bool st = false, ex = false, td = false, vi = false, in = false;
        TokList *typ = stripSpecifiers(l, from, typeTo, &st, &ex, &td, &vi, &in);
        if (typ->count == 0) { tlFreeShallow(typ); return; }
        /* type must not contain operators other than :: * & < > */
        for (int i = 0; i < typ->count; i++) { Tok *t = typ->items[i]; if (t->type == TK_OP && !(strcmp(t->text, "::") == 0 || strcmp(t->text, "*") == 0 || strcmp(t->text, "&") == 0 || strcmp(t->text, "&&") == 0 || strcmp(t->text, "...") == 0)) { tlFreeShallow(typ); return; } if (t->type == TK_NUMBER || t->type == TK_STRING) { tlFreeShallow(typ); return; } if (t->type == TK_IDENT && (t->kw == KW_RETURN || t->kw == KW_GOTO || t->kw == KW_NEW || t->kw == KW_DELETE || t->kw == KW_THROW || t->kw == KW_SIZEOF)) { tlFreeShallow(typ); return; } }
        vString *props = vsNew();
        if (st) addProperty(props, "static");
        if (ex) addProperty(props, "extern");
        /* iterate declarators */
        TokList *full = tlNew();
        for (int i = 0; i < typ->count; i++) tlAdd(full, typ->items[i]);
        int tt = full->count;
        for (int i = typeTo; i < to; i++) tlAdd(full, l->items[i]);
        int segStart = tt;
        for (int i = tt; i <= full->count; i++) {
            bool atEnd = (i == full->count);
            if (atEnd || full->items[i]->type == TK_COMMA) {
                int eq2 = findAssign(full, segStart, i);
                int dTo = eq2 >= 0 ? eq2 : i;
                for (int k = segStart; k < dTo; k++) if (full->items[k]->type == TK_OP && strcmp(full->items[k]->text, ":") == 0) { dTo = k; break; }
                int ni = findDeclaratorName(full, segStart, dTo);
                if (ni != -1 && !(ni >= 0 && segStart > tt && ni == segStart && dTo - segStart == 1 && false)) {
                    /* skip segments without a name (e.g., initializer list commas) */
                    bool ok = true;
                    if (segStart > tt) {
                        /* the segment must look like a declarator: only * & ident [ ] */
                        for (int k = segStart; k < dTo; k++) { Tok *t = full->items[k]; if (!(t->type == TK_IDENT || t->type == TK_BRACKET || t->type == TK_PAREN || (t->type == TK_OP && (strcmp(t->text, "*") == 0 || strcmp(t->text, "&") == 0 || strcmp(t->text, "&&") == 0 || strcmp(t->text, "::") == 0)))) { ok = false; break; } }
                    }
                    if (ok) {
                        unsigned long endLine = atEnd ? term->line : full->items[i]->line;
                        emitVariable(full, 0, tt, ni, segStart, dTo, kind, st, ex, endLine, props, NULL);
                    }
                }
                segStart = i + 1;
            }
        }
        tlFreeShallow(typ); tlFreeShallow(full); vsDelete(props);
    }
}

/* statement terminated by '{' */
static void handleBlock(TokList *l, Tok *lbrace) {
    int from = 0, to = l->count;
    if (to == 0) {
        /* bare block */
        if (inFunctionScope()) { pushScope(CORK_NIL, -2, 0, NULL, false); parseScope(true); }
        else skipBlockSimple();
        return;
    }
    from = skipTemplatePrefix(l, from, to);
    while (from < to && isAttributeTok(l, from)) { if (l->items[from]->type == TK_IDENT) from++; from++; }
    if (from >= to) { skipBlockSimple(); return; }
    Tok *first = l->items[from];
    /* extern "C" { */
    if (first->kw == KW_EXTERN && from + 1 < to && l->items[from+1]->type == TK_STRING && from + 2 == to) {
        pushScope(CORK_NIL, -2, 0, NULL, false);
        parseScope(false);
        return;
    }
    /* namespace */
    if (first->kw == KW_NAMESPACE) { handleNamespace(l, from, lbrace); return; }
    /* export module / export { */
    if (first->kw == KW_EXPORT && from + 1 == to) { pushScope(CORK_NIL, -2, 0, NULL, false); parseScope(false); return; }
    /* initializer: contains '=' at top level before '{' -> variable with brace init */
    int eq = findAssign(l, from, to);
    if (eq >= 0) {
        if (inFunctionScope() && !isLanguageKindEnabled(Lang, K_l)) {
            /* still need to scan the braces for lambdas */
            Tok *b = tokNew(TK_BRACE, NULL); b->line = lbrace ? lbrace->line : 0;
            collectChain(b);
            tlAdd(l, b);
            TokList *more = tlNew(); Tok *t2; readStatement(more, &t2);
            for (int i = 0; i < more->count; i++) tlAdd(l, more->items[i]);
            more->count = 0; tlFreeShallow(more);
            scanForLambdas(l);
            if (t2 && t2->type == TK_RBRACE) pushBackP(t2); else if (t2) tokDelete(t2);
            return;
        }
        /* collect the brace chain and rest until ';' then process as declaration */
        Tok *b = tokNew(TK_BRACE, NULL); b->line = lbrace ? lbrace->line : 0;
        collectChain(b);
        tlAdd(l, b);
        TokList *more = tlNew(); Tok *t2;
        tokType tt = readStatement(more, &t2);
        for (int i = 0; i < more->count; i++) tlAdd(l, more->items[i]);
        more->count = 0; tlFreeShallow(more);
        if (tt == TK_SEMI) { handleDeclaration(l, t2); tokDelete(t2); }
        else if (tt == TK_LBRACE) { handleBlock(l, t2); tokDelete(t2); }
        else if (tt == TK_RBRACE) { Tok *fake = tokNew(TK_SEMI, ";"); fake->line = t2->line; handleDeclaration(l, fake); tokDelete(fake); pushBackP(t2); }
        else if (t2) tokDelete(t2);
        return;
    }
    /* class/struct/union/enum definition? find keyword not inside, with the token sequence ending in name/bases */
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (t->type == TK_IDENT && (t->kw == KW_STRUCT || t->kw == KW_CLASS || t->kw == KW_UNION || t->kw == KW_ENUM)) {
            /* make sure it's not a function returning struct: no PAREN after the keyword's name */
            bool hasParen = false;
            for (int j = i + 1; j < to; j++) if (l->items[j]->type == TK_PAREN) { hasParen = true; break; }
            /* "struct X : Base {" has no paren; "struct X f() {" has */
            if (!hasParen) {
                bool st = false, ex = false, td = false, vi = false, in = false;
                for (int j = from; j < i; j++) { Tok *q = l->items[j]; if (q->kw == KW_STATIC) st = true; if (q->kw == KW_EXTERN) ex = true; if (q->kw == KW_TYPEDEF) td = true; }
                (void)vi; (void)in;
                handleCompound(l, i, lbrace, td, st, ex);
                return;
            }
            break;
        }
        if (t->type == TK_PAREN) break;
    }
    /* function definition */
    int nameIdx = -1, nameStart = -1;
    int paren = findFunctionParen(l, from, to, &nameIdx, &nameStart);
    if (paren >= 0 && nameIdx >= 0) {
        /* control statements inside function bodies */
        if (inFunctionScope()) {
            Tok *nt = l->items[nameIdx];
            if (nt->kw != KW_NONE || nameIdx != paren - 1 || (nameStart < nameIdx)) {
                /* qualified name defined inside a function? unlikely; treat as block */
            }
            /* inside a function, "name(...) {" is likely a macro or control construct -> scan for lambdas and parse block */
            scanForLambdas(l);
            pushScope(CORK_NIL, -2, 0, NULL, false);
            parseScope(true);
            return;
        }
        /* reject if name token is keyword-ish */
        Tok *nt = l->items[nameIdx];
        if (nt->type == TK_IDENT && nt->kw == KW_NONE) {
            /* "if"/"while" are keywords so excluded. Also require: no '=' before (handled) */
            Tok *nameTok;
            int cork = emitFunction(l, from, to, paren, nameIdx, nameStart, true, &nameTok, false, NULL);
            /* function body */
            pushScope(cork, K_f, 0, nt->text, true);
            parseScope(true);
            return;
        }
        if (nt->type == TK_IDENT && nt->kw == KW_OPERATOR) {
            Tok *nameTok;
            int cork = emitFunction(l, from, to, paren, nameIdx, nameStart, true, &nameTok, false, NULL);
            pushScope(cork, K_f, 0, "operator", true);
            parseScope(true);
            return;
        }
    }
    /* lambda assigned? e.g. "auto f = [](){" handled by '=' path. Here: other blocks (if/for/while/switch/try/do/else/catch) */
    if (inFunctionScope()) {
        scanForLambdas(l);
        pushScope(CORK_NIL, -2, 0, NULL, false);
        parseScope(true);
        return;
    }
    /* brace-init variable without '=': "T v{...};" */
    if (to - from >= 2 && l->items[to-1]->type == TK_IDENT && l->items[to-1]->kw == KW_NONE && paren < 0) {
        Tok *b = tokNew(TK_BRACE, NULL); b->line = lbrace ? lbrace->line : 0;
        collectChain(b);
        TokList *more = tlNew(); Tok *t2;
        tokType tt = readStatement(more, &t2);
        if (tt == TK_SEMI && more->count == 0) {
            handleDeclaration(l, t2);
        } else if (tt == TK_RBRACE) pushBackP(t2), t2 = NULL;
        tlDelete(more); if (t2) tokDelete(t2); tokDelete(b);
        return;
    }
    /* K&R function definition or unknown: skip block */
    {
        /* K&R: tokens: TYPE NAME(params) decls... ; -- our readStatement would have split at ';'. Not handled. */
        pushScope(CORK_NIL, -2, 0, NULL, false);
        parseScope(inFunctionScope());
    }
}

/* parse statements until matching '}' (pops scope) or EOF */
static void parseScope(bool isFunctionBody) {
    for (;;) {
        TokList *l = tlNew();
        Tok *term;
        /* access specifiers: "public:" etc. -- detect early */
        tokType tt;
        /* custom loop to catch "access:" */
        for (;;) {
            Tok *t = nextTokenP();
            if (t->type == TK_EOF || t->type == TK_SEMI || t->type == TK_LBRACE || t->type == TK_RBRACE) { term = t; tt = t->type; break; }
            if (t->type == TK_PAREN || t->type == TK_BRACKET) { tlAdd(l, collectChain(t)); continue; }
            if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tokDelete(t); continue; }
            if (isCxx && l->count == 1 && t->type == TK_OP && strcmp(t->text, ":") == 0 && l->items[0]->type == TK_IDENT && (l->items[0]->kw == KW_PUBLIC || l->items[0]->kw == KW_PRIVATE || l->items[0]->kw == KW_PROTECTED)) {
                Scope *s = curScope();
                if (s) s->access = l->items[0]->kw == KW_PUBLIC ? 1 : l->items[0]->kw == KW_PROTECTED ? 2 : 3;
                tokDelete(t); tlDelete(l); l = tlNew();
                continue;
            }
            /* Q_OBJECT style "signals:" / "slots:" / "case X:" / labels handled elsewhere */
            if (isCxx && l->count >= 1 && t->type == TK_OP && strcmp(t->text, ":") == 0 && inClassScope() && l->items[l->count-1]->type == TK_IDENT && l->items[l->count-1]->kw == KW_NONE && (strcmp(l->items[l->count-1]->text, "slots") == 0 || strcmp(l->items[l->count-1]->text, "signals") == 0 || strcmp(l->items[l->count-1]->text, "Q_SIGNALS") == 0 || strcmp(l->items[l->count-1]->text, "Q_SLOTS") == 0)) {
                Scope *s = curScope();
                for (int i = 0; i < l->count; i++) { int kw = l->items[i]->kw; if (kw == KW_PUBLIC) s->access = 1; else if (kw == KW_PROTECTED) s->access = 2; else if (kw == KW_PRIVATE) s->access = 3; }
                tokDelete(t); tlDelete(l); l = tlNew();
                continue;
            }
            if (t->type == TK_OP && strcmp(t->text, "<") == 0 && isCxx && looksLikeTemplateStart(l)) {
                bool afterAssign = false;
                for (int i = 0; i < l->count; i++) if (l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "=") == 0) afterAssign = true;
                if (!afterAssign) {
                    Tok *a = tryCollectAngle(t);
                    if (a) { tokDelete(t); tlAdd(l, a); continue; }
                    tokDelete(t);
                    continue;
                }
            }
            tlAdd(l, t);
        }
        if (tt == TK_EOF) {
            if (l->count) { handleDeclaration(l, term); }
            tlDelete(l);
            /* pop remaining scope? leave to caller */
            popScope(term->line);
            tokDelete(term);
            return;
        }
        if (tt == TK_RBRACE) {
            if (l->count) { Tok *fake = tokNew(TK_SEMI, ";"); fake->line = term->line; handleDeclaration(l, fake); tokDelete(fake); }
            tlDelete(l);
            popScope(term->line);
            tokDelete(term);
            return;
        }
        if (tt == TK_SEMI) {
            if (isFunctionBody) {
                scanForLambdas(l);
                if (isLanguageKindEnabled(Lang, K_l) || isLanguageKindEnabled(Lang, K_L)) handleDeclaration(l, term);
            } else handleDeclaration(l, term);
            tlDelete(l); tokDelete(term);
            continue;
        }
        /* '{' */
        handleBlock(l, term);
        tlDelete(l); tokDelete(term);
    }
}

/* ---------- entry points ---------- */
static void initKinds(int lang) {
    Lang = lang;
    K_d = getKindIndexByLetter(lang, 'd'); K_e = getKindIndexByLetter(lang, 'e'); K_f = getKindIndexByLetter(lang, 'f'); K_g = getKindIndexByLetter(lang, 'g');
    K_h = getKindIndexByLetter(lang, 'h'); K_l = getKindIndexByLetter(lang, 'l'); K_m = getKindIndexByLetter(lang, 'm'); K_p = getKindIndexByLetter(lang, 'p');
    K_s = getKindIndexByLetter(lang, 's'); K_t = getKindIndexByLetter(lang, 't'); K_u = getKindIndexByLetter(lang, 'u'); K_v = getKindIndexByLetter(lang, 'v');
    K_x = getKindIndexByLetter(lang, 'x'); K_z = getKindIndexByLetter(lang, 'z'); K_L = getKindIndexByLetter(lang, 'L'); K_D = getKindIndexByLetter(lang, 'D');
    K_c = getKindIndexByLetter(lang, 'c'); K_n = getKindIndexByLetter(lang, 'n'); K_A = getKindIndexByLetter(lang, 'A'); K_N = getKindIndexByLetter(lang, 'N');
    K_U = getKindIndexByLetter(lang, 'U'); K_Z = getKindIndexByLetter(lang, 'Z');
    F_properties = getLangFieldIndexByName(lang, "properties"); if (F_properties >= 0 && !isLangFieldEnabled(lang, F_properties)) F_properties = -1;
    F_macrodef = getLangFieldIndexByName(lang, "macrodef");
    F_template = getLangFieldIndexByName(lang, "template"); if (F_template >= 0 && !isLangFieldEnabled(lang, F_template)) F_template = -1;
    F_captures = getLangFieldIndexByName(lang, "captures"); if (F_captures >= 0 && !isLangFieldEnabled(lang, F_captures)) F_captures = -1;
    F_name = getLangFieldIndexByName(lang, "name");
    F_specialization = getLangFieldIndexByName(lang, "specialization"); if (F_specialization >= 0 && !isLangFieldEnabled(lang, F_specialization)) F_specialization = -1;
    F_alias = getLangFieldIndexByName(lang, "alias");
    F_section = getLangFieldIndexByName(lang, "section");
}

static void runCxx(int mode) {
    int lang = getInputLanguage();
    LangMode = mode;
    isCxx = (mode == 2);
    initKinds(lang);
    cppClientInfo ci;
    memset(&ci, 0, sizeof ci);
    ci.lang = lang;
    ci.macroKind = K_d; ci.headerKind = K_h; ci.macroParamKind = (K_D >= 0 && isLanguageKindEnabled(lang, K_D)) ? K_D : -1;
    ci.undefRole = getRoleIndexByName(lang, K_d, "undef");
    ci.sysRole = getRoleIndexByName(lang, K_h, "system"); ci.localRole = getRoleIndexByName(lang, K_h, "local");
    ci.cplusplus = isCxx; ci.rawStrings = isCxx;
    cppInit(&ci);
    Lookahead = NULL;
    if (Pending) { tlDelete(Pending); Pending = NULL; }
    ScopeTop = 0;
    if (KnownTypes) { for (size_t i = 0; i < paCount(KnownTypes); i++) { knownType *k = paItem(KnownTypes, i); free(k->name); free(k); } paDelete(KnownTypes); KnownTypes = NULL; }
    pushScope(CORK_NIL, -1, 0, NULL, false);
    /* top level: loop until EOF, handling stray '}' */
    for (;;) {
        parseScope(false);
        /* parseScope returns at '}' or EOF; check EOF */
        Tok *t = nextTokenP();
        if (t->type == TK_EOF) { tokDelete(t); break; }
        pushBackP(t);
        pushScope(CORK_NIL, -1, 0, NULL, false);
    }
    if (Lookahead) { tokDelete(Lookahead); Lookahead = NULL; }
    cppTerminate();
}

static void parseC(void) { runCxx(1); }
static void parseCpp(void) { runCxx(2); }
static void parseCuda(void) { runCxx(4); }

static void cxxParamHandler(int lang, const char *name, const char *arg) { (void)lang; (void)name; (void)arg; }

parserDefinition CParser = { "C", parseC, NULL, NULL, NULL, true, false, NULL, NULL };
