/* CPreProcessor language: only macros/headers */
static void parseCPreProcessor(void) {
    int lang = getInputLanguage();
    cppClientInfo ci; memset(&ci, 0, sizeof ci);
    ci.lang = lang;
    ci.macroKind = getKindIndexByLetter(lang, 'd'); ci.headerKind = getKindIndexByLetter(lang, 'h');
    int D = getKindIndexByLetter(lang, 'D');
    ci.macroParamKind = (D >= 0 && isLanguageKindEnabled(lang, D)) ? D : -1;
    ci.undefRole = getRoleIndexByName(lang, ci.macroKind, "undef");
    ci.sysRole = getRoleIndexByName(lang, ci.headerKind, "system"); ci.localRole = getRoleIndexByName(lang, ci.headerKind, "local");
    cppInit(&ci);
