    cppTerminate();
}
static void cppParamHandler(int lang, const char *name, const char *arg) {
    (void)lang;
    if (strcmp(name, "ignore") == 0) cppSetIgnoreToken(arg);
    else if (strcmp(name, "if0") == 0) Option.if0 = (strcmp(arg, "true") == 0 || strcmp(arg, "yes") == 0 || strcmp(arg, "1") == 0);
    else if (strcmp(name, "define") == 0) { /* -D: define replacement */ char *copy = xstrdup(arg); char *eq = strchr(copy, '='); if (eq) { *eq = 0; char *s = xmalloc(strlen(copy) + strlen(eq+1) + 2); sprintf(s, "%s=%s", copy, eq + 1); cppSetIgnoreToken(s); free(s); } else { cppSetIgnoreToken(copy); } free(copy); }
}
parserDefinition CPreProcessorParser = { "CPreProcessor", parseCPreProcessor, NULL, NULL, NULL, true, false, NULL, cppParamHandler };
