/* ---------- forward decls ---------- */
static void parseScope(bool isFunctionBody);
static void handleBlock(TokList *l, Tok *lbrace);
static void handleDeclaration(TokList *l, Tok *term);

/* skip a brace block (after '{' consumed), scanning for lambdas/nested definitions when inside function */
static unsigned long skipBlockSimple(void) {
    int depth = 1;
    unsigned long endLine = getInputLineNumber();
    for (;;) {
        Tok *t = nextTokenP();
        if (t->type == TK_EOF) { endLine = t->line; tokDelete(t); break; }
        if (t->type == TK_LBRACE) depth++;
        else if (t->type == TK_RBRACE) { depth--; if (depth == 0) { endLine = t->line; tokDelete(t); break; } }
        tokDelete(t);
    }
    return endLine;
}

/* find lambda(s) in token list (recursive into chains) and emit them */
static void scanForLambdas(TokList *l) {
    for (int i = 0; i < l->count; i++) {
        Tok *t = l->items[i];
        if (t->type == TK_BRACKET && isCxx) {
            /* [captures] (params) [specs] -> type { body } */
            int j = i + 1;
            if (j < l->count && l->items[j]->type == TK_PAREN) {
                int parenIdx = j; j++;
                int k = j;
                while (k < l->count && l->items[k]->type != TK_BRACE && l->items[k]->type != TK_SEMI && l->items[k]->type != TK_COMMA) k++;
                if (k < l->count && l->items[k]->type == TK_BRACE) {
                    /* it's a lambda */
                    vString *an = vsNew();
                    anonGenerate(an, "__anon", K_f);
                    /* fake list: paren + specs */
                    Tok *paren = l->items[parenIdx];
                    tagEntryInfo e;
                    initTagEntry(&e, vsValue(an), K_f);
                    e.lineNumber = paren->line; e.filePosition = paren->pos;
                    vString *sig = vsNew();
                    buildSignature(sig, paren, l, parenIdx + 1, k);
                    if (paren->followedBySpace && k == parenIdx + 1) vsPut(sig, ' ');
                    e.ext.signature = vsValue(sig);
                    e.isFileScope = true;
                    e.ext.scopeIndex = curScopeCork();
                    e.ext.endLine = l->items[k]->endLine;
                    /* trailing return type */
                    vString *kb = vsNew(), *nb = vsNew();
                    for (int m = parenIdx + 1; m < k; m++) if (l->items[m]->type == TK_OP && strcmp(l->items[m]->text, "->") == 0) { setTypeRef(&e, l, m + 1, k, kb, nb); break; }
                    markTagExtraBit(&e, XTAG_ANONYMOUS);
                    if (F_captures >= 0 && t->chain) { vString *cap = vsNew(); tokChainToString(cap, t); attachParserField(&e, F_captures, vsValue(cap)); vsDelete(cap); }
                    int cork = makeTagEntry(&e);
                    emitParameters(paren, cork);
                    /* scan body with lambda as scope */
                    pushScope(cork, K_f, 0, vsValue(an), true);
                    if (l->items[k]->chain) scanForLambdas(l->items[k]->chain);
                    popScope(0);
                    vsDelete(an); vsDelete(sig); vsDelete(kb); vsDelete(nb);
                    i = k;
                    continue;
                }
            }
        }
        if ((t->type == TK_PAREN || t->type == TK_BRACKET || t->type == TK_BRACE) && t->chain) scanForLambdas(t->chain);
    }
}

/* ---------- enum ---------- */
static void parseEnumBody(int enumCork) {
    int nth = 0;
    for (;;) {
        TokList *l = tlNew();
        Tok *term;
        /* collect until ',' or '}' at depth 0 */
        tokType tt = TK_EOF;
        for (;;) {
            Tok *t = nextTokenP();
            if (t->type == TK_EOF || t->type == TK_RBRACE || t->type == TK_COMMA || t->type == TK_SEMI) { term = t; tt = t->type; break; }
            if (t->type == TK_PAREN || t->type == TK_BRACKET || t->type == TK_LBRACE) { if (t->type == TK_LBRACE) t->type = TK_BRACE; tlAdd(l, collectChain(t)); continue; }
            if (t->type == TK_RPAREN || t->type == TK_RBRACKET) { tokDelete(t); continue; }
            tlAdd(l, t);
        }
        /* first identifier is the enumerator */
        int idx = -1;
        for (int i = 0; i < l->count; i++) { if (isAttributeTok(l, i)) { if (l->items[i]->type == TK_IDENT) i++; continue; } if (l->items[i]->type == TK_IDENT) { idx = i; break; } else break; }
        if (idx >= 0) {
            Tok *nt = l->items[idx];
            tagEntryInfo e;
            initTagEntry(&e, nt->text, K_e);
            e.lineNumber = nt->line; e.filePosition = nt->pos;
            e.isFileScope = !isInputHeaderFile();
            e.ext.scopeIndex = enumCork;
            e.ext.access = "public";
            e.ext.nth = nth++;
            makeTagEntry(&e);
        }
        tlDelete(l);
        if (tt == TK_RBRACE) { popScope(term->line); tokDelete(term); return; }
        if (tt == TK_EOF) { popScope(term->line); tokDelete(term); return; }
        tokDelete(term);
    }
}

/* ---------- class / struct / union / enum / namespace definitions ---------- */

/* Parse declarators following a '}' of struct/enum definition: e.g. "} x, *y;" or typedef names */
static void handleTrailingDeclarators(TokList *l, Tok *term, const char *typeKw, const char *typeName, bool wasTypedef, bool isStatic, bool isExtern, Tok *kwTok, bool anonymous, int typeCork) {
    (void)kwTok;
    /* l contains tokens after '}' up to term (';') */
    if (l->count == 0) return;
    /* build a synthetic type token list: typeKw typeName */
    Tok *tkw = tokNew(TK_IDENT, typeKw); tkw->kw = strcmp(typeKw, "struct") == 0 ? KW_STRUCT : strcmp(typeKw, "union") == 0 ? KW_UNION : strcmp(typeKw, "enum") == 0 ? KW_ENUM : KW_CLASS;
    Tok *tnm = tokNew(TK_IDENT, typeName);
    TokList *full = tlNew();
    tlAdd(full, tkw); tlAdd(full, tnm);
    for (int i = 0; i < l->count; i++) tlAdd(full, l->items[i]);
    int typeTo = 2;
    int start = 2;
    for (int i = 2; i <= full->count; i++) {
        if (i == full->count || full->items[i]->type == TK_COMMA) {
            int eq = findAssign(full, start, i);
            int declTo = eq >= 0 ? eq : i;
            /* bitfield */
            for (int k = start; k < declTo; k++) if (full->items[k]->type == TK_OP && strcmp(full->items[k]->text, ":") == 0) { declTo = k; break; }
            int nameIdx = findDeclaratorName(full, start, declTo);
            if (nameIdx != -1) {
                if (wasTypedef) {
                    Tok *nameTok = nameIdx >= 0 ? full->items[nameIdx] : full->items[(-nameIdx-1)/1000]->chain->items[(-nameIdx-1)%1000];
                    tagEntryInfo e;
                    initTagEntry(&e, nameTok->text, K_t);
                    e.lineNumber = nameTok->line; e.filePosition = nameTok->pos;
                    vString *kb = vsNew(), *nb = vsNew();
                    TokList *tmp = tlNew();
                    for (int k = 0; k < typeTo; k++) tlAdd(tmp, full->items[k]);
                    if (nameIdx >= 0) { for (int k = start; k < declTo; k++) if (k != nameIdx) tlAdd(tmp, full->items[k]); }
                    setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
                    tlFreeShallow(tmp);
                    e.isFileScope = !isInputHeaderFile();
                    e.ext.scopeIndex = curScopeCork();
                    makeTagEntry(&e);
                    rememberType(nameTok->text, K_t, 0);
                    if (anonymous && F_name >= 0 && typeCork > 0) { /* aliased name */ }
                    vsDelete(kb); vsDelete(nb);
                } else {
                    int kind = inClassScope() ? K_m : (inFunctionScope() ? K_l : (isExtern ? K_x : K_v));
                    Tok *nt = NULL;
                    unsigned long endLine = (i < full->count) ? full->items[i]->line : term->line;
                    emitVariable(full, 0, typeTo, nameIdx, start, declTo, kind, isStatic, isExtern, endLine, NULL, &nt);
                }
            }
            start = i + 1;
        }
    }
    full->count = 0; tlFreeShallow(full);
    tokDelete(tkw); tokDelete(tnm);
}

/* process "struct/class/union/enum ... {" ; returns after the whole definition incl. trailing declarators */
static void handleCompound(TokList *l, int kwIdx, Tok *lbrace, bool wasTypedef, bool isStatic, bool isExtern) {
    Tok *kw = l->items[kwIdx];
    bool isEnum = kw->kw == KW_ENUM;
    int kind = kw->kw == KW_STRUCT ? K_s : kw->kw == KW_UNION ? K_u : kw->kw == KW_ENUM ? K_g : K_c;
    const char *kwName = kw->kw == KW_STRUCT ? "struct" : kw->kw == KW_UNION ? "union" : kw->kw == KW_ENUM ? "enum" : "class";
    int i = kwIdx + 1;
    /* enum class / enum struct */
    if (isEnum && i < l->count && (l->items[i]->kw == KW_CLASS || l->items[i]->kw == KW_STRUCT)) i++;
    /* skip attributes */
    while (i < l->count && isAttributeTok(l, i)) { if (l->items[i]->type == TK_IDENT) i += 2; else i++; }
    /* name (possibly qualified) */
    int nameIdx = -1;
    int nameEnd = i;
    if (i < l->count && l->items[i]->type == TK_IDENT && l->items[i]->kw == KW_NONE) {
        nameIdx = i; i++;
        while (i + 1 < l->count && l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "::") == 0 && l->items[i+1]->type == TK_IDENT) { nameIdx = i + 1; i += 2; }
        if (i < l->count && l->items[i]->type == TK_ANGLE) i++;   /* specialization */
        nameEnd = i;
    }
    vString *name = vsNew();
    bool anonymous = false;
    Tok *nameTok = nameIdx >= 0 ? l->items[nameIdx] : kw;
    if (nameIdx >= 0) vsCat(name, l->items[nameIdx]->text);
    else { anonGenerate(name, "__anon", kind); anonymous = true; }
    /* inheritance / underlying type */
    vString *inherits = vsNew();
    vString *kb = vsNew(), *nb = vsNew();
    tagEntryInfo e;
    initTagEntry(&e, vsValue(name), kind);
    e.lineNumber = nameTok->line; e.filePosition = nameTok->pos;
    if (anonymous) e.lineNumber = kw->line, e.filePosition = kw->pos;
    while (i < l->count && l->items[i]->kw == KW_FINAL) i++;
    if (i < l->count && l->items[i]->type == TK_OP && strcmp(l->items[i]->text, ":") == 0) {
        i++;
        if (isEnum) {
            setTypeRef(&e, l, i, l->count, kb, nb);
        } else {
            /* base list */
            int start = i;
            for (int k = i; k <= l->count; k++) {
                if (k == l->count || l->items[k]->type == TK_COMMA) {
                    /* skip access/virtual keywords */
                    int s = start;
                    while (s < k && l->items[s]->type == TK_IDENT && (l->items[s]->kw == KW_PUBLIC || l->items[s]->kw == KW_PRIVATE || l->items[s]->kw == KW_PROTECTED || l->items[s]->kw == KW_VIRTUAL)) s++;
                    if (s < k) {
                        if (vsLength(inherits)) vsPut(inherits, ',');
                        vString *tmp = vsNew();
                        for (int m = s; m < k; m++) { Tok *t = l->items[m]; if (t->type == TK_ANGLE || t->type == TK_PAREN) tokChainToString(tmp, t); else if (t->type == TK_OP && strcmp(t->text, "...") == 0) vsCat(tmp, "..."); else vsCat(tmp, t->text); }
                        vsCatV(inherits, tmp); vsDelete(tmp);
                    }
                    start = k + 1;
                }
            }
            if (vsLength(inherits)) e.ext.inherits = vsValue(inherits);
        }
    }
    e.isFileScope = !isInputHeaderFile();
    /* scope: qualified name? */
    int scopeCork = curScopeCork();
    if (nameIdx >= 0 && nameIdx > kwIdx + 1 && l->items[nameIdx-1]->type == TK_OP && strcmp(l->items[nameIdx-1]->text, "::") == 0) {
        vString *qual = vsNew();
        splitQualifiedName(l, nameIdx, qual);
        if (vsLength(qual)) { int ko; scopeCork = scopeForQualifier(vsValue(qual), &ko); }
        vsDelete(qual);
    }
    e.ext.scopeIndex = scopeCork;
    Scope *cs = curScope();
    if (inClassScope() && cs && cs->access) e.ext.access = (char *)accessName(cs->access);
    if (anonymous) markTagExtraBit(&e, XTAG_ANONYMOUS);
    /* template field */
    if (F_template >= 0 && kwIdx > 0 && l->items[0]->kw == KW_TEMPLATE && l->count > 1 && l->items[1]->type == TK_ANGLE) { vString *tp = vsNew(); tokChainToString(tp, l->items[1]); attachParserField(&e, F_template, vsValue(tp)); vsDelete(tp); }
    if (F_specialization >= 0 && nameIdx >= 0 && nameIdx + 1 < nameEnd && l->items[nameIdx+1]->type == TK_ANGLE) { vString *tp = vsNew(); tokChainToString(tp, l->items[nameIdx+1]); attachParserField(&e, F_specialization, vsValue(tp)); vsDelete(tp); }
    int cork = makeTagEntry(&e);
    if (!anonymous) rememberType(vsValue(name), kind, cork);
    /* body */
    int defaultAccess = (kind == K_c) ? 3 : 1;
    if (isEnum) {
        pushScope(cork, K_g, 0, vsValue(name), false);
        parseEnumBody(cork);
    } else {
        pushScope(cork, kind, isCxx ? defaultAccess : 1, vsValue(name), false);
        parseScope(false);
    }
    /* after '}' : trailing declarators until ';' */
    TokList *rest = tlNew();
    Tok *term;
    tokType tt = readStatement(rest, &term);
    if (tt == TK_SEMI) {
        handleTrailingDeclarators(rest, term, kwName, vsValue(name), wasTypedef, isStatic, isExtern, kw, anonymous, cork);
        tokDelete(term);
    } else if (tt == TK_LBRACE) {
        /* e.g. "} var = {" initializer */
        int eq = findAssign(rest, 0, rest->count);
        if (eq >= 0) {
            unsigned long endLine = skipBlockSimple();
            /* read until ; */
            TokList *more = tlNew(); Tok *t2; tokType tt2 = readStatement(more, &t2);
            (void)tt2;
            TokList *decl = tlNew();
            for (int k = 0; k < eq; k++) tlAdd(decl, rest->items[k]);
            Tok *fake = tokNew(TK_SEMI, ";"); fake->line = t2 ? t2->line : endLine;
            handleTrailingDeclarators(decl, fake, kwName, vsValue(name), wasTypedef, isStatic, isExtern, kw, anonymous, cork);
            tokDelete(fake);
            decl->count = 0; tlFreeShallow(decl);
            tlDelete(more); if (t2) tokDelete(t2);
        } else {
            pushBackP(term);
            term = NULL;
            /* unexpected: treat as new block statement */
            handleBlock(rest, NULL);
            rest = NULL;
        }
        if (term) tokDelete(term);
    } else if (tt == TK_RBRACE) {
        pushBackP(term);
    } else {
        tokDelete(term);
    }
    if (rest) tlDelete(rest);
    vsDelete(name); vsDelete(inherits); vsDelete(kb); vsDelete(nb);
}

/* namespace NAME { */
static void handleNamespace(TokList *l, int kwIdx, Tok *lbrace) {
    int i = kwIdx + 1;
    while (i < l->count && (l->items[i]->kw == KW_INLINE || isAttributeTok(l, i))) { if (l->items[i]->type == TK_IDENT && l->items[i]->kw != KW_INLINE) i++; i++; }
    /* nested names A::B::C */
    int depth = 0;
    if (i >= l->count) {
        vString *an = vsNew();
        anonGenerate(an, "__anon", K_n);
        tagEntryInfo e;
        initTagEntry(&e, vsValue(an), K_n);
        e.lineNumber = l->items[kwIdx]->line; e.filePosition = l->items[kwIdx]->pos;
        e.isFileScope = !isInputHeaderFile();
        e.ext.scopeIndex = curScopeCork();
        markTagExtraBit(&e, XTAG_ANONYMOUS);
        int cork = makeTagEntry(&e);
        pushScope(cork, K_n, 0, vsValue(an), false);
        depth = 1;
        vsDelete(an);
    } else {
        while (i < l->count && l->items[i]->type == TK_IDENT) {
            tagEntryInfo e;
            initTagEntry(&e, l->items[i]->text, K_n);
            e.lineNumber = l->items[i]->line; e.filePosition = l->items[i]->pos;
            e.isFileScope = !isInputHeaderFile();
            e.ext.scopeIndex = curScopeCork();
            int cork = makeTagEntry(&e);
            rememberType(l->items[i]->text, K_n, cork);
            pushScope(cork, K_n, 0, l->items[i]->text, false);
            depth++;
            i++;
            if (i < l->count && l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "::") == 0) i++; else break;
        }
    }
    parseScope(false);   /* pops one scope at '}' */
    /* pop extra nested */
    for (int k = 1; k < depth; k++) popScope(getInputLineNumber());
}

/* decide whether token list (before '{') is a function definition; returns paren index or -1 */
static int findFunctionParen(TokList *l, int from, int to, int *nameIdx, int *nameStart) {
    /* find the last PAREN chain such that tokens after it are qualifiers only */
    for (int i = to - 1; i >= from; i--) {
        Tok *t = l->items[i];
        if (t->type != TK_PAREN) continue;
        /* tokens after: must be qualifiers */
        bool ok = true;
        bool sawArrow = false, sawColon = false;
        for (int j = i + 1; j < to && ok; j++) {
            Tok *q = l->items[j];
            if (sawColon) break;  /* ctor initializer: anything goes */
            if (q->type == TK_IDENT) {
                if (q->kw == KW_CONST || q->kw == KW_VOLATILE || q->kw == KW_NOEXCEPT || q->kw == KW_THROW || q->kw == KW_OVERRIDE || q->kw == KW_FINAL || q->kw == KW_ATTRIBUTE || q->kw == KW_REQUIRES || q->kw == KW_TRY || q->kw == KW_DECLSPEC || q->kw == KW_RESTRICT || q->kw == KW_MUTABLE || q->kw == KW_ASM) continue;
                if (sawArrow) continue;
                ok = false;
            } else if (q->type == TK_OP) {
                if (strcmp(q->text, "&") == 0 || strcmp(q->text, "&&") == 0) continue;
                if (strcmp(q->text, "->") == 0) { sawArrow = true; continue; }
                if (strcmp(q->text, ":") == 0) { sawColon = true; continue; }
                if (strcmp(q->text, "::") == 0 || strcmp(q->text, "*") == 0 || strcmp(q->text, "<") == 0 || strcmp(q->text, ">") == 0) { if (sawArrow) continue; }
                if (strcmp(q->text, "=") == 0) { continue; }
                ok = false;
            } else if (q->type == TK_PAREN || q->type == TK_ANGLE || q->type == TK_BRACKET) continue;
            else if (q->type == TK_NUMBER && j > i + 1 && l->items[j-1]->type == TK_OP && strcmp(l->items[j-1]->text, "=") == 0) continue;
            else if (q->type == TK_IDENT) continue;
            else ok = false;
        }
        if (!ok) continue;
        /* name: token before paren */
        int n = i - 1;
        if (n < from) return -1;
        Tok *nt = l->items[n];
        if (nt->type == TK_ANGLE && n - 1 >= from) { n--; nt = l->items[n]; }  /* name<T>(...) template specialization */
        if (nt->type == TK_IDENT && nt->kw == KW_NONE) {
            *nameIdx = n;
            *nameStart = splitQualifiedName(l, n, &(vString){0}) , n;
            /* compute nameStart via qualified walk */
            int start = n;
            while (start - 2 >= from && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "::") == 0 && (l->items[start-2]->type == TK_IDENT || l->items[start-2]->type == TK_ANGLE)) { start -= 2; if (l->items[start]->type == TK_ANGLE && start - 1 >= from && l->items[start-1]->type == TK_IDENT) start--; }
            if (start - 1 >= from && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "~") == 0) start--;
            if (start - 1 >= from && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "::") == 0) start--;
            *nameStart = start;
            return i;
        }
        /* operator */
        for (int k = n; k >= from; k--) {
            if (l->items[k]->type == TK_IDENT && l->items[k]->kw == KW_OPERATOR) {
                *nameIdx = k;
                int start = k;
                while (start - 2 >= from && l->items[start-1]->type == TK_OP && strcmp(l->items[start-1]->text, "::") == 0 && l->items[start-2]->type == TK_IDENT) start -= 2;
                *nameStart = start;
                return i;
            }
            if (l->items[k]->type == TK_PAREN || l->items[k]->type == TK_SEMI) break;
        }
        /* (*name)(args) function returning pointer to function: int (*f(int))(int) -- rare */
        if (nt->type == TK_PAREN) {
            /* e.g. int (*signal(int, void(*)(int)))(int) */
            return -1;
        }
        return -1;
    }
    return -1;
}

/* is paren content a parameter-declaration list (prototype) rather than an expression (variable ctor init)? */
static bool parenLooksLikeParams(Tok *paren) {
    TokList *c = paren->chain;
    if (!c || c->count == 0) return true;
    /* (void) */
    bool allIdent = true;
    for (int i = 0; i < c->count; i++) {
        Tok *t = c->items[i];
        if (t->type == TK_NUMBER || t->type == TK_STRING || t->type == TK_CHAR) return false;
        if (t->type == TK_IDENT) {
            if (t->kw == KW_THIS || t->kw == KW_NEW || t->kw == KW_SIZEOF || t->kw == KW_TRUE || t->kw == KW_FALSE || t->kw == KW_NULLPTR) return false;
            if (t->kw != KW_NONE) allIdent = false;
            continue;
        }
        if (t->type == TK_OP) {
            if (strcmp(t->text, "*") == 0 || strcmp(t->text, "&") == 0 || strcmp(t->text, "&&") == 0 || strcmp(t->text, "::") == 0 || strcmp(t->text, "...") == 0 || strcmp(t->text, "=") == 0) { allIdent = false; continue; }
            if (strcmp(t->text, "<") == 0 || strcmp(t->text, ">") == 0) { allIdent = false; continue; }
            return false;
        }
        if (t->type == TK_COMMA) continue;
        if (t->type == TK_BRACKET || t->type == TK_ANGLE) { allIdent = false; continue; }
        if (t->type == TK_PAREN) { allIdent = false; continue; }
    }
    if (allIdent) {
        /* all plain identifiers separated by commas: "f(a, b)" -> each segment length 1 => expression? e.g. Foo f(x); ctags treats as prototype. */
        /* segments with 2+ identifiers are declarations */
        return true;
    }
    return true;
}

static int findTopLevelParen(TokList *l, int from, int to) {
    for (int i = from; i < to; i++) if (l->items[i]->type == TK_PAREN) return i;
    return -1;
}

static bool hasKw(TokList *l, int from, int to, int kw) { for (int i = from; i < to; i++) if (l->items[i]->type == TK_IDENT && l->items[i]->kw == kw) return true; return false; }
static int findKw(TokList *l, int from, int to, int kw) { for (int i = from; i < to; i++) if (l->items[i]->type == TK_IDENT && l->items[i]->kw == kw) return i; return -1; }

/* skip template<...> prefix(es); returns new from */
static int skipTemplatePrefix(TokList *l, int from, int to) {
    while (from < to && l->items[from]->kw == KW_TEMPLATE) {
        from++;
        if (from < to && l->items[from]->type == TK_ANGLE) from++;
        /* requires clause */
        if (from < to && l->items[from]->kw == KW_REQUIRES) { from++; while (from < to && !(l->items[from]->type == TK_IDENT && l->items[from]->kw != KW_NONE && l->items[from]->kw != KW_REQUIRES) ) { if (l->items[from]->type == TK_IDENT && l->items[from]->kw == KW_NONE && from + 1 < to && l->items[from+1]->type != TK_OP) break; from++; } }
    }
    return from;
}

/* typedef declaration: tokens from 'typedef' (index from) to end */
static void handleTypedef(TokList *l, int from, int to) {
    /* l[from] == typedef */
    int i = from + 1;
    /* typedef struct X {...} handled elsewhere (block). Here: typedef <type> declarators; */
    if (i >= to) return;
    /* struct keyword followed by name */
    int kwi = i;
    (void)kwi;
    int start = i;
    /* determine type end: find declarator names; multiple declarators separated by commas */
    /* type tokens: up to the first declarator start. Heuristic: the declarator name is the last identifier of each comma segment. type = tokens before the first '*'/'('/name in segment 1 */
    int segStart = start;
    int typeTo = -1;
    for (int k = start; k <= to; k++) {
        if (k == to || l->items[k]->type == TK_COMMA) {
            int nameIdx = findDeclaratorName(l, segStart, k);
            if (nameIdx == -1) { segStart = k + 1; continue; }
            if (typeTo < 0) {
                int t = nameIdx >= 0 ? nameIdx : (-nameIdx - 1) / 1000;
                while (t > segStart && l->items[t-1]->type == TK_OP && (strcmp(l->items[t-1]->text, "*") == 0 || strcmp(l->items[t-1]->text, "&") == 0 || strcmp(l->items[t-1]->text, "&&") == 0)) t--;
                typeTo = t;
            }
            int fpParen = nameIdx < 0 ? (-nameIdx-1)/1000 : -1, fpInner = nameIdx < 0 ? (-nameIdx-1)%1000 : -1;
            Tok *nameTok = nameIdx >= 0 ? l->items[nameIdx] : l->items[fpParen]->chain->items[fpInner];
            tagEntryInfo e;
            initTagEntry(&e, nameTok->text, K_t);
            e.lineNumber = nameTok->line; e.filePosition = nameTok->pos;
            vString *kb = vsNew(), *nb = vsNew();
            TokList *tmp = tlNew();
            for (int m = start; m < typeTo; m++) tlAdd(tmp, l->items[m]);
            int declFrom = (k == to || segStart == start) ? typeTo : segStart;
            if (segStart != start) declFrom = segStart;
            if (fpParen >= 0) {
                Tok *p = l->items[fpParen];
                Tok *np = tokNew(TK_PAREN, NULL); np->chain = tlNew();
                for (int j = 0; j < p->chain->count; j++) if (j != fpInner) tlAdd(np->chain, p->chain->items[j]);
                for (int m = declFrom; m < fpParen; m++) tlAdd(tmp, l->items[m]);
                tlAdd(tmp, np);
                for (int m = fpParen + 1; m < k; m++) tlAdd(tmp, l->items[m]);
                setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
                np->chain->count = 0; tlDelete(np->chain); np->chain = NULL; tokDelete(np);
            } else {
                for (int m = declFrom; m < k; m++) if (m != nameIdx) tlAdd(tmp, l->items[m]);
                setTypeRef(&e, tmp, 0, tmp->count, kb, nb);
            }
            tlFreeShallow(tmp);
            e.isFileScope = !isInputHeaderFile();
            e.ext.scopeIndex = curScopeCork();
            Scope *cs = curScope();
            if (inClassScope() && cs && cs->access) e.ext.access = (char *)accessName(cs->access);
            makeTagEntry(&e);
            rememberType(nameTok->text, K_t, 0);
            vsDelete(kb); vsDelete(nb);
            segStart = k + 1;
        }
    }
}

/* generic declaration terminated by ';' */
static void handleDeclaration(TokList *l, Tok *term) {
    if (l->count == 0) return;
    int from = 0, to = l->count;
    /* access specifiers "public:" etc. are handled in parseScope (they end with ':' not ';') */
    from = skipTemplatePrefix(l, from, to);
    if (from >= to) return;
    Tok *first = l->items[from];
    /* skip leading attributes */
    while (from < to && isAttributeTok(l, from)) { if (l->items[from]->type == TK_IDENT) from++; from++; }
    if (from >= to) return;
    first = l->items[from];
    if (first->type == TK_IDENT) {
        switch (first->kw) {
        case KW_USING: {
            /* using namespace X; | using X = type; | using A::b; */
            if (from + 1 < to && l->items[from+1]->kw == KW_NAMESPACE) {
                if (K_U >= 0) { vString *n = vsNew(); for (int i = from + 2; i < to; i++) { if (l->items[i]->type == TK_OP) vsCat(n, l->items[i]->text); else vsCat(n, l->items[i]->text); } tagEntryInfo e; initTagEntry(&e, vsValue(n), K_U); e.lineNumber = l->items[from+2 < to ? from+2 : from]->line; e.filePosition = l->items[from+2 < to ? from+2 : from]->pos; e.isFileScope = !isInputHeaderFile(); e.ext.scopeIndex = curScopeCork(); makeTagEntry(&e); vsDelete(n); }
                return;
            }
            int eq = findAssign(l, from, to);
            if (eq >= 0 && eq == from + 2 && l->items[from+1]->type == TK_IDENT) {
                Tok *nt = l->items[from+1];
                tagEntryInfo e;
                initTagEntry(&e, nt->text, K_t);
                e.lineNumber = nt->line; e.filePosition = nt->pos;
                vString *kb = vsNew(), *nb = vsNew();
                bool st = false, ex = false, td = false, vi = false, in = false;
                TokList *typ = stripSpecifiers(l, eq + 1, to, &st, &ex, &td, &vi, &in);
                /* remove 'typename' */
                setTypeRef(&e, typ, 0, typ->count, kb, nb);
                tlFreeShallow(typ);
                e.isFileScope = !isInputHeaderFile();
                e.ext.scopeIndex = curScopeCork();
                Scope *cs = curScope();
                if (inClassScope() && cs && cs->access) e.ext.access = (char *)accessName(cs->access);
                makeTagEntry(&e);
                rememberType(nt->text, K_t, 0);
                vsDelete(kb); vsDelete(nb);
                return;
            }
            if (eq >= 0 && eq > from + 1 && l->items[eq-1]->type == TK_ANGLE && l->items[eq-2]->type == TK_IDENT) { /* using X<T> = ... rare */ }
            if (K_N >= 0) {
                /* using A::b; -> N tag "b"? ctags uses full name */
                vString *n = vsNew();
                int st = from + 1;
                if (st < to && (l->items[st]->kw == KW_TYPENAME || l->items[st]->kw == KW_ENUM)) st++;
                for (int i = st; i < to; i++) { Tok *t = l->items[i]; if (t->type == TK_ANGLE) tokChainToString(n, t); else vsCat(n, t->text); }
                if (vsLength(n)) { tagEntryInfo e; initTagEntry(&e, vsValue(n), K_N); Tok *nt = l->items[to-1]; e.lineNumber = nt->line; e.filePosition = nt->pos; e.isFileScope = !isInputHeaderFile(); e.ext.scopeIndex = curScopeCork(); makeTagEntry(&e); }
                vsDelete(n);
            }
            return;
        }
        case KW_NAMESPACE: {
            /* namespace A = B; */
            int eq = findAssign(l, from, to);
            if (eq == from + 2 && K_A >= 0) {
                Tok *nt = l->items[from+1];
                tagEntryInfo e; initTagEntry(&e, nt->text, K_A); e.lineNumber = nt->line; e.filePosition = nt->pos; e.isFileScope = !isInputHeaderFile(); e.ext.scopeIndex = curScopeCork();
                vString *kb = vsNew(), *nb = vsNew(); setTypeRef(&e, l, eq + 1, to, kb, nb); e.ext.typeRefKind = NULL; e.ext.typeRefName = NULL;
                makeTagEntry(&e); vsDelete(kb); vsDelete(nb);
            }
            return;
        }
        case KW_FRIEND: case KW_STATIC_ASSERT: case KW_GOTO: case KW_RETURN: case KW_BREAK: case KW_CONTINUE: case KW_CASE: case KW_DEFAULT:
        case KW_DELETE: case KW_THROW: case KW_CO_RETURN: case KW_CO_YIELD: case KW_IMPORT: case KW_MODULE: case KW_ASM: case KW_CONCEPT:
            return;
        case KW_TEMPLATE: return;
        case KW_TYPEDEF: {
            handleTypedef(l, from, to);
            return;
        }
        default: break;
        }
    }
    /* labels: IDENT ':' at start inside function */
    if (inFunctionScope() && first->type == TK_IDENT && first->kw == KW_NONE && from + 1 < to && l->items[from+1]->type == TK_OP && strcmp(l->items[from+1]->text, ":") == 0 && !(from + 2 < to && l->items[from+2]->type == TK_OP && strcmp(l->items[from+2]->text, ":") == 0)) {
        if (K_L >= 0) { tagEntryInfo e; initTagEntry(&e, first->text, K_L); e.lineNumber = first->line; e.filePosition = first->pos; e.isFileScope = true; e.ext.scopeIndex = curScopeCork(); makeTagEntry(&e); }
        /* continue with the rest */
        from += 2;
        if (from >= to) return;
        TokList *rest = tlNew(); for (int i = from; i < to; i++) tlAdd(rest, l->items[i]);
        handleDeclaration(rest, term);
        rest->count = 0; tlFreeShallow(rest);
        return;
    }
    /* collect specifiers */
    bool isStatic = false, isExtern = false, isTypedef = false, isVirtual = false, isInline = false;
    for (int i = from; i < to; i++) {
        Tok *t = l->items[i];
        if (t->type != TK_IDENT) continue;
        if (t->kw == KW_STATIC) isStatic = true;
        else if (t->kw == KW_EXTERN) isExtern = true;
        else if (t->kw == KW_TYPEDEF) isTypedef = true;
        else if (t->kw == KW_VIRTUAL) isVirtual = true;
        else if (t->kw == KW_INLINE) isInline = true;
    }
    if (isTypedef) { int ti = findKw(l, from, to, KW_TYPEDEF); if (ti >= 0) { /* typedef not first: e.g. "static typedef"? */ handleTypedef(l, ti, to); return; } }
    /* extern "C" int foo(); */
    if (first->kw == KW_EXTERN && from + 1 < to && l->items[from+1]->type == TK_STRING) { from += 2; if (from >= to) return; }
    /* forward declarations: struct X; class Y; enum E; */
    {
        int f2 = from;
        while (f2 < to && isStorageSpecifier(l->items[f2])) f2++;
        if (f2 < to && (l->items[f2]->kw == KW_STRUCT || l->items[f2]->kw == KW_CLASS || l->items[f2]->kw == KW_UNION || l->items[f2]->kw == KW_ENUM)) {
            int k = f2 + 1;
            if (l->items[f2]->kw == KW_ENUM && k < to && (l->items[k]->kw == KW_CLASS || l->items[k]->kw == KW_STRUCT)) k++;
            while (k < to && isAttributeTok(l, k)) { if (l->items[k]->type == TK_IDENT) k++; k++; }
            /* name with qualifiers */
            int kk = k;
            while (kk < to && (l->items[kk]->type == TK_IDENT || (l->items[kk]->type == TK_OP && strcmp(l->items[kk]->text, "::") == 0) || l->items[kk]->type == TK_ANGLE)) kk++;
            if (kk == to && k < to && !isTypedef) return;  /* forward declaration -> no tag */
            /* enum E : int ; forward */
            if (kk < to && l->items[kk]->type == TK_OP && strcmp(l->items[kk]->text, ":") == 0 && l->items[f2]->kw == KW_ENUM) return;
        }
    }
    /* find top-level paren */
    int paren = -1;
    for (int i = from; i < to; i++) {
        if (l->items[i]->type == TK_OP && strcmp(l->items[i]->text, "=") == 0) break;
        if (l->items[i]->type == TK_PAREN) { paren = i; break; }
    }
    if (paren >= 0) {
        /* prototype or function-pointer variable or variable with ctor args */
        Tok *before = paren > from ? l->items[paren-1] : NULL;
        if (before && before->type == TK_IDENT && (before->kw == KW_NONE || before->kw == KW_OPERATOR) ) {
            /* could be prototype  TYPE NAME(params) [quals];  or variable  TYPE NAME(args); */
            int nameIdx = paren - 1;
            if (before->kw == KW_OPERATOR) { for (int k = paren - 1; k >= from; k--) if (l->items[k]->kw == KW_OPERATOR) { nameIdx = k; break; } }
            else {
                /* operator with symbol tokens before paren: find 'operator' keyword */
                for (int k = paren - 1; k >= from && k >= paren - 4; k--) if (l->items[k]->type == TK_IDENT && l->items[k]->kw == KW_OPERATOR) { nameIdx = k; break; }
            }
            int nameStart = nameIdx;
            while (nameStart - 2 >= from && l->items[nameStart-1]->type == TK_OP && strcmp(l->items[nameStart-1]->text, "::") == 0 && (l->items[nameStart-2]->type == TK_IDENT || l->items[nameStart-2]->type == TK_ANGLE)) { nameStart -= 2; if (l->items[nameStart]->type == TK_ANGLE && nameStart - 1 >= from && l->items[nameStart-1]->type == TK_IDENT) nameStart--; }
            if (nameStart - 1 >= from && l->items[nameStart-1]->type == TK_OP && strcmp(l->items[nameStart-1]->text, "~") == 0) nameStart--;
            if (nameStart - 1 >= from && l->items[nameStart-1]->type == TK_OP && strcmp(l->items[nameStart-1]->text, "::") == 0) nameStart--;
            /* type tokens exist? */
            bool hasType = false;
            for (int i = from; i < nameStart; i++) { Tok *t = l->items[i]; if (isAttributeTok(l, i)) { if (t->type == TK_IDENT) i++; continue; } if (isStorageSpecifier(t)) continue; if (t->type == TK_IDENT || t->type == TK_OP) { hasType = true; break; } if (t->type == TK_ANGLE) { hasType = true; break; } }
            bool isCtorLike = false;
            if (!hasType) {
                /* constructor/destructor if in class scope or qualified X::X */
                Scope *cs = curScope();
                if (inClassScope() && cs && cs->name && (strcmp(cs->name, before->text) == 0 || (nameStart < nameIdx) || (nameIdx > from && l->items[nameIdx-1]->type == TK_OP && strcmp(l->items[nameIdx-1]->text, "~") == 0))) isCtorLike = true;
                else if (nameStart < nameIdx) {
                    /* X::X or X::~X */
                    Tok *q = l->items[nameIdx-2];
                    if (q->type == TK_IDENT && strcmp(q->text, before->text) == 0) isCtorLike = true;
                    if (nameIdx - 1 >= from && l->items[nameIdx-1]->type == TK_OP && strcmp(l->items[nameIdx-1]->text, "~") == 0) isCtorLike = true;
                }
                if (inClassScope() && before->kw == KW_OPERATOR) isCtorLike = true;
                if (inClassScope() && isCxx && before->kw == KW_NONE) {
                    /* e.g. explicit Foo(int); handled above; or macro like Q_OBJECT(...)? treat as ctor if name==class */
                }
            }
            if (hasType || isCtorLike) {
                /* distinguish prototype vs variable: check tokens after paren */
                bool afterOk = true;
                for (int j = paren + 1; j < to; j++) {
                    Tok *q = l->items[j];
                    if (q->type == TK_IDENT && (q->kw == KW_CONST || q->kw == KW_VOLATILE || q->kw == KW_NOEXCEPT || q->kw == KW_THROW || q->kw == KW_OVERRIDE || q->kw == KW_FINAL || q->kw == KW_ATTRIBUTE || q->kw == KW_REQUIRES || q->kw == KW_DEFAULT || q->kw == KW_DELETE || q->kw == KW_ASM || q->kw == KW_DECLSPEC)) continue;
                    if (q->type == TK_OP && (strcmp(q->text, "&") == 0 || strcmp(q->text, "&&") == 0 || strcmp(q->text, "=") == 0 || strcmp(q->text, "->") == 0 || strcmp(q->text, "::") == 0 || strcmp(q->text, "*") == 0)) continue;
                    if (q->type == TK_PAREN || q->type == TK_ANGLE || q->type == TK_BRACKET || q->type == TK_NUMBER || q->type == TK_IDENT || q->type == TK_STRING) continue;
