static bool isIdentStart(int c) { return isalpha(c) || c == '_' || (c & 0x80); }
static bool isIdentChar(int c) { return isalnum(c) || c == '_' || (c & 0x80); }

static const char *accessFor(const char *name, int kind, int parentKind) {
    size_t len = strlen(name);
    if (parentKind != -1 && parentKind != K_c) return "private";
    if (len < 1 || name[0] != '_') return "public";
    if (kind == K_m && parentKind == K_c && len > 3 && name[1] == '_' && name[len-2] == '_' && name[len-1] == '_') return "public";
    if (parentKind == K_c && len > 1 && name[1] == '_') return "private";
    return "protected";
}

/* logical line buffer with per-char line numbers */
typedef struct { vString *text; unsigned long *lines; size_t cap; unsigned long startLine; long startPos; } logLine;

static void llPut(logLine *ll, int c, unsigned long line) {
    if (vsLength(ll->text) + 1 >= ll->cap) { ll->cap = ll->cap ? ll->cap * 2 : 256; ll->lines = xrealloc(ll->lines, ll->cap * sizeof(unsigned long)); }
    ll->lines[vsLength(ll->text)] = line;
    vsPut(ll->text, c);
}

/* read a logical line: handles brackets, backslash continuation, strings (incl. triple), comments (stripped).
   returns false at EOF with empty line. indent returned via *indent. blank/comment-only lines are skipped. */
static bool readLogicalLine(logLine *ll, int *indent, unsigned long *lastCodeLine) {
    vsClear(ll->text);
    for (;;) {
        int c = getcFromInputFile();
        if (c == EOF) return false;
        /* measure indentation */
        int ind = 0;
        while (c == ' ' || c == '\t' || c == '\f') { if (c == '\t') ind = (ind / 8 + 1) * 8; else if (c == ' ') ind++; c = getcFromInputFile(); }
        if (c == '\n') continue;      /* blank line */
        if (c == '#') { while (c != EOF && c != '\n') c = getcFromInputFile(); if (c == EOF) return false; continue; }
        if (c == EOF) return false;
        *indent = ind;
        ll->startLine = getInputLineNumber();
        ll->startPos = getInputFilePosition();
        int depth = 0;
        for (;;) {
            unsigned long line = getInputLineNumber();
            if (c == EOF) break;
            if (c == '\n') { if (depth > 0) { llPut(ll, ' ', line); c = getcFromInputFile(); continue; } break; }
            if (c == '#') { while (c != EOF && c != '\n') c = getcFromInputFile(); continue; }
            if (c == '\\') { int n = getcFromInputFile(); if (n == '\n') { c = getcFromInputFile(); continue; } llPut(ll, c, line); c = n; continue; }
            if (c == '"' || c == '\'') {
                int q = c;
                int n1 = getcFromInputFile();
                if (n1 == q) {
                    int n2 = getcFromInputFile();
                    if (n2 == q) {
                        /* triple quoted */
                        llPut(ll, q, line); llPut(ll, q, line); llPut(ll, q, line);
                        int match = 0;
                        for (;;) {
                            c = getcFromInputFile();
                            if (c == EOF) break;
                            unsigned long l2 = getInputLineNumber();
                            if (c == '\\') { llPut(ll, c, l2); c = getcFromInputFile(); if (c == EOF) break; llPut(ll, c == '\n' ? ' ' : c, l2); match = 0; continue; }
                            llPut(ll, c == '\n' ? ' ' : c, l2);
                            if (c == q) { match++; if (match == 3) break; } else match = 0;
                        }
                        c = getcFromInputFile();
                        continue;
                    }
                    /* empty string */
                    llPut(ll, q, line); llPut(ll, q, line);
                    c = n2; continue;
                }
                llPut(ll, q, line);
                c = n1;
                while (c != EOF && c != q && c != '\n') { if (c == '\\') { llPut(ll, c, line); c = getcFromInputFile(); if (c == EOF || c == '\n') break; } llPut(ll, c, line); c = getcFromInputFile(); }
                if (c == q) { llPut(ll, q, line); c = getcFromInputFile(); }
                continue;
            }
            if (c == '(' || c == '[' || c == '{') depth++;
            else if (c == ')' || c == ']' || c == '}') { if (depth > 0) depth--; }
            llPut(ll, c, line);
            *lastCodeLine = line;
            c = getcFromInputFile();
        }
        /* strip trailing spaces */
        while (vsLength(ll->text) && isspace((unsigned char)vsLast(ll->text))) vsChop(ll->text);
        if (vsLength(ll->text) == 0) continue;
        return true;
    }
}

/* simple tokenizer over the logical line */
typedef struct { const char *s; size_t i; const unsigned long *lines; } cursor;
static void skipWs(cursor *c) { while (c->s[c->i] == ' ' || c->s[c->i] == '\t') c->i++; }
static bool readIdent(cursor *c, vString *out) {
    skipWs(c);
    if (!isIdentStart((unsigned char)c->s[c->i])) return false;
    vsClear(out);
    while (isIdentChar((unsigned char)c->s[c->i])) vsPut(out, c->s[c->i++]);
    return true;
}
static bool readDottedName(cursor *c, vString *out) {
    if (!readIdent(c, out)) return false;
    for (;;) {
        skipWs(c);
        if (c->s[c->i] == '.' && isIdentStart((unsigned char)c->s[c->i+1])) { c->i++; vsPut(out, '.'); while (isIdentChar((unsigned char)c->s[c->i])) vsPut(out, c->s[c->i++]); }
        else break;
    }
    return true;
}
static bool startsWithKw(const char *s, const char *kw) {
    size_t n = strlen(kw);
    return strncmp(s, kw, n) == 0 && !isIdentChar((unsigned char)s[n]);
}

static vString *Decorators = NULL;

static int makePyTag(const char *name, int kind, unsigned long line, long pos, int scopeCork, int parentKind, const char *sig, const char *inherits, const char *typeref, int role) {
    tagEntryInfo e;
    if (role >= 0) initRefTagEntry(&e, name, kind, role); else initTagEntry(&e, name, kind);
    e.lineNumber = line; e.filePosition = pos;
    e.ext.scopeIndex = scopeCork;
    if (kind == K_c || kind == K_f || kind == K_m || kind == K_v || kind == K_l) e.ext.access = (char *)accessFor(name, kind, parentKind);
    if (sig) e.ext.signature = (char *)sig;
    if (inherits && *inherits) e.ext.inherits = (char *)inherits;
    if (typeref) { e.ext.typeRefKind = "typename"; e.ext.typeRefName = (char *)typeref; }
    if (Decorators && vsLength(Decorators) && (kind == K_c || kind == K_f || kind == K_m) && F_decorators >= 0) attachParserField(&e, F_decorators, vsValue(Decorators));
    return makeTagEntry(&e);
}

/* extract balanced paren content starting at s[i]=='(' ; returns end index after ')' ; fills out with normalized text */
static size_t readParenText(const char *s, size_t i, vString *out) {
    int depth = 0;
    vsClear(out);
    bool lastSpace = false;
    for (; s[i]; i++) {
        char ch = s[i];
        if (ch == '"' || ch == '\'') {
            char q = ch; vsPut(out, ch); i++;
            while (s[i] && s[i] != q) { if (s[i] == '\\' && s[i+1]) { vsPut(out, s[i]); i++; } vsPut(out, s[i]); i++; }
            if (s[i]) vsPut(out, s[i]);
            lastSpace = false;
            continue;
        }
        if (ch == '(' || ch == '[' || ch == '{') depth++;
        if (ch == ')' || ch == ']' || ch == '}') { depth--; if (depth == 0) { vsPut(out, ch); return i + 1; } }
        if (ch == ' ' || ch == '\t') { if (lastSpace || vsLength(out) == 0 || vsLast(out) == '(') continue; lastSpace = true; vsPut(out, ' '); continue; }
        lastSpace = false;
        vsPut(out, ch);
    }
    return i;
}

static void processDef(cursor *c, logLine *ll, int indent, bool isAsync) {
    vString *name = vsNew();
    if (!readIdent(c, name)) { vsDelete(name); return; }
    unsigned long line = ll->lines[c->i - 1];
    skipWs(c);
    vString *sig = vsNew();
    vString *ret = vsNew();
    if (c->s[c->i] == '(') {
        size_t e = readParenText(c->s, c->i, sig);
        c->i = e;
    }
    /* normalize signature spacing: "(a, b=1)" keep as source but collapse spaces */
    skipWs(c);
    if (c->s[c->i] == '-' && c->s[c->i+1] == '>') {
        c->i += 2; skipWs(c);
        while (c->s[c->i] && c->s[c->i] != ':') vsPut(ret, c->s[c->i++]);
        vsStripTrailing(ret);
    }
    int pk = curKind();
    int kind = (pk == K_c) ? K_m : K_f;
    int cork = makePyTag(vsValue(name), kind, line, ll->startPos + 0, curCork(), pk, vsLength(sig) ? vsValue(sig) : NULL, NULL, vsLength(ret) ? vsValue(ret) : NULL, -1);
    /* parameters */
    if (K_z >= 0 && isLanguageKindEnabled(Lang, K_z) && vsLength(sig) > 2) {
        const char *p = vsValue(sig) + 1;
        int depth = 0;
        vString *pn = vsNew();
        bool atStart = true;
        while (*p) {
            if (*p == '(' || *p == '[' || *p == '{') { depth++; p++; atStart = false; continue; }
            if (*p == ')' || *p == ']' || *p == '}') { if (depth == 0) break; depth--; p++; continue; }
            if (depth == 0 && *p == ',') { atStart = true; p++; continue; }
            if (depth == 0 && atStart) {
                while (*p == ' ' || *p == '*') p++;
                if (isIdentStart((unsigned char)*p)) { vsClear(pn); while (isIdentChar((unsigned char)*p)) vsPut(pn, *p++); makePyTag(vsValue(pn), K_z, line, ll->startPos, cork, kind, NULL, NULL, NULL, -1); }
                atStart = false;
                continue;
            }
            p++;
        }
        vsDelete(pn);
    }
    if (Top < 256) { Stack[Top].indent = indent; Stack[Top].cork = cork; Stack[Top].kind = kind; Top++; }
    (void)isAsync;
    vsDelete(name); vsDelete(sig); vsDelete(ret);
}

static void processClass(cursor *c, logLine *ll, int indent) {
    vString *name = vsNew();
    if (!readIdent(c, name)) { vsDelete(name); return; }
    unsigned long line = ll->lines[c->i - 1];
    skipWs(c);
    vString *inh = vsNew();
    if (c->s[c->i] == '(') {
        vString *tmp = vsNew();
        c->i = readParenText(c->s, c->i, tmp);
        /* inherits: comma separated, strip spaces, skip keyword args */
        const char *p = vsValue(tmp) + 1;
        vString *cur = vsNew();
        int depth = 0;
        for (; *p; p++) {
            if (*p == '(' || *p == '[') depth++;
            else if (*p == ')' || *p == ']') { if (depth == 0) break; depth--; }
            if (depth == 0 && *p == ',') { if (vsLength(cur)) { if (vsLength(inh)) vsPut(inh, ','); vsCatV(inh, cur); } vsClear(cur); continue; }
            if (*p == ' ') continue;
            vsPut(cur, *p);
        }
        if (vsLength(cur)) { if (vsLength(inh)) vsPut(inh, ','); vsCatV(inh, cur); }
        vsDelete(cur); vsDelete(tmp);
    }
    int cork = makePyTag(vsValue(name), K_c, line, ll->startPos, curCork(), curKind(), NULL, vsValue(inh), NULL, -1);
    if (Top < 256) { Stack[Top].indent = indent; Stack[Top].cork = cork; Stack[Top].kind = K_c; Top++; }
    vsDelete(name); vsDelete(inh);
}

static void processImport(cursor *c, logLine *ll, bool isFrom) {
    vString *mod = vsNew(), *name = vsNew(), *alias = vsNew();
    unsigned long line = ll->startLine;
    if (isFrom) {
        /* from MOD import a as b, c */
        skipWs(c);
        vsClear(mod);
        while (c->s[c->i] == '.') { vsPut(mod, '.'); c->i++; }
        vString *tmp = vsNew();
        if (readDottedName(c, tmp)) vsCatV(mod, tmp);
        vsDelete(tmp);
        skipWs(c);
        if (!startsWithKw(c->s + c->i, "import")) { vsDelete(mod); vsDelete(name); vsDelete(alias); return; }
        c->i += 6;
        if (vsLength(mod)) makePyTag(vsValue(mod), K_i, line, ll->startPos, CORK_NIL, -1, NULL, NULL, NULL, R_i_namespace);
        for (;;) {
            skipWs(c);
            if (c->s[c->i] == '(') { c->i++; continue; }
            if (c->s[c->i] == ')') { c->i++; continue; }
            if (c->s[c->i] == '*') { c->i++; break; }
            if (!readIdent(c, name)) break;
            skipWs(c);
            if (startsWithKw(c->s + c->i, "as")) {
                c->i += 2;
                if (readIdent(c, alias)) {
                    makePyTag(vsValue(name), K_Y, line, ll->startPos, CORK_NIL, -1, NULL, NULL, NULL, R_Y_indirect);
                    tagEntryInfo e; initTagEntry(&e, vsValue(alias), K_Y); e.lineNumber = line; e.filePosition = ll->startPos; e.ext.scopeIndex = curCork();
                    if (F_nameref >= 0) { vString *nr = vsNewInit("unknown:"); vsCatV(nr, name); attachParserField(&e, F_nameref, vsValue(nr)); makeTagEntry(&e); vsDelete(nr); } else makeTagEntry(&e);
                }
            } else {
                makePyTag(vsValue(name), K_Y, line, ll->startPos, CORK_NIL, -1, NULL, NULL, NULL, R_Y_imported);
            }
            skipWs(c);
            if (c->s[c->i] == ',') { c->i++; continue; }
            if (c->s[c->i] == ')') { c->i++; skipWs(c); }
            if (c->s[c->i] != ',') break;
            c->i++;
        }
    } else {
        for (;;) {
            if (!readDottedName(c, mod)) break;
            skipWs(c);
            if (startsWithKw(c->s + c->i, "as")) {
                c->i += 2;
                if (readIdent(c, alias)) {
                    makePyTag(vsValue(mod), K_i, line, ll->startPos, CORK_NIL, -1, NULL, NULL, NULL, R_i_indirect);
                    tagEntryInfo e; initTagEntry(&e, vsValue(alias), K_I); e.lineNumber = line; e.filePosition = ll->startPos; e.ext.scopeIndex = curCork();
                    if (F_nameref >= 0) { vString *nr = vsNewInit("module:"); vsCatV(nr, mod); attachParserField(&e, F_nameref, vsValue(nr)); makeTagEntry(&e); vsDelete(nr); } else makeTagEntry(&e);
                }
            } else makePyTag(vsValue(mod), K_i, line, ll->startPos, CORK_NIL, -1, NULL, NULL, NULL, R_i_imported);
            skipWs(c);
            if (c->s[c->i] != ',') break;
            c->i++;
        }
    }
    vsDelete(mod); vsDelete(name); vsDelete(alias);
}

/* assignment statement: find top-level '=' (not ==, !=, <=, >=, and not inside brackets) */
static void processAssignment(cursor *c, logLine *ll) {
    const char *s = c->s;
    size_t i = c->i;
    /* find lhs end */
    int depth = 0;
    size_t eq = (size_t)-1;
    size_t colon = (size_t)-1;
    for (size_t k = i; s[k]; k++) {
        char ch = s[k];
        if (ch == '"' || ch == '\'') { char q = ch; k++; while (s[k] && s[k] != q) { if (s[k] == '\\') k++; if (s[k]) k++; } if (!s[k]) break; continue; }
        if (ch == '(' || ch == '[' || ch == '{') depth++;
        else if (ch == ')' || ch == ']' || ch == '}') depth--;
        else if (depth == 0 && ch == ':' && colon == (size_t)-1 && s[k+1] != '=') colon = k;
        else if (depth == 0 && ch == '=') {
            if (s[k+1] == '=') { k++; continue; }
            if (k > 0 && strchr("!<>+-*/%&|^@:", s[k-1])) { if (s[k-1] == ':' ) {} return; }  /* augmented or walrus: no tag */
            eq = k; break;
        }
        if (depth == 0 && ch == ' ' && strncmp(s + k, " lambda", 7) == 0 && false) break;
    }
    if (eq == (size_t)-1 && colon == (size_t)-1) return;
    size_t lhsEnd = (eq != (size_t)-1) ? eq : strlen(s);
    if (colon != (size_t)-1 && colon < lhsEnd) lhsEnd = colon;
    /* annotation type */
    vString *typ = NULL;
    if (colon != (size_t)-1 && (eq == (size_t)-1 || colon < eq)) {
        typ = vsNew();
        size_t te = (eq != (size_t)-1) ? eq : strlen(s);
        for (size_t k = colon + 1; k < te; k++) vsPut(typ, s[k]);
        vsStripTrailing(typ); vsStripLeading(typ);
        if (vsLength(typ) == 0) { vsDelete(typ); typ = NULL; }
    }
    /* lhs targets: split by top-level commas; each must be a plain identifier (optionally in parens); skip attribute/subscript targets */
    int kind = (curKind() == K_f || curKind() == K_m) ? K_l : K_v;
    if (kind == K_l && !isLanguageKindEnabled(Lang, K_l)) { if (typ) vsDelete(typ); return; }
    vString *name = vsNew();
    size_t k = i;
    /* handle chained assignment a = b = 1 : only process first target list here, then recurse */
    while (k < lhsEnd) {
        while (k < lhsEnd && (s[k] == ' ' || s[k] == '(' || s[k] == ')' || s[k] == '\t')) k++;
        if (k >= lhsEnd) break;
        if (s[k] == '*') { k++; continue; }
        if (!isIdentStart((unsigned char)s[k])) { break; }
        vsClear(name);
        size_t nstart = k;
        while (k < lhsEnd && isIdentChar((unsigned char)s[k])) vsPut(name, s[k++]);
        size_t tmp = k; while (tmp < lhsEnd && s[tmp] == ' ') tmp++;
        if (tmp < lhsEnd && (s[tmp] == '.' || s[tmp] == '[')) {
            /* attribute/subscript target: skip to next comma */
            int d = 0;
            while (k < lhsEnd && !(d == 0 && s[k] == ',')) { if (s[k] == '[' || s[k] == '(') d++; else if (s[k] == ']' || s[k] == ')') d--; k++; }
            if (k < lhsEnd) k++;
            continue;
        }
        if (strcmp(vsValue(name), "lambda") == 0 || strcmp(vsValue(name), "yield") == 0 || strcmp(vsValue(name), "return") == 0 || strcmp(vsValue(name), "print") == 0 || strcmp(vsValue(name), "assert") == 0 || strcmp(vsValue(name), "del") == 0) break;
        makePyTag(vsValue(name), kind, ll->lines[nstart], ll->startPos, curCork(), curKind(), NULL, NULL, typ ? vsValue(typ) : NULL, -1);
        k = tmp;
        if (k < lhsEnd && s[k] == ',') k++;
        else if (k < lhsEnd && s[k] == ')') { k++; }
        else break;
    }
    /* chained: a = b = 1 -> process rhs as another assignment if it has '=' */
    if (eq != (size_t)-1) {
        cursor c2 = { s, eq + 1, c->lines };
        skipWs(&c2);
        /* only if rhs starts with identifier followed by '=' */
        size_t j = c2.i;
        if (isIdentStart((unsigned char)s[j])) {
            while (isIdentChar((unsigned char)s[j]) || s[j] == ',' || s[j] == ' ') j++;
            if (s[j] == '=' && s[j+1] != '=') processAssignment(&c2, ll);
        }
    }
    vsDelete(name); if (typ) vsDelete(typ);
}

static void parsePython(void) {
    Lang = getInputLanguage();
    K_c = getKindIndexByLetter(Lang, 'c'); K_f = getKindIndexByLetter(Lang, 'f'); K_m = getKindIndexByLetter(Lang, 'm'); K_v = getKindIndexByLetter(Lang, 'v');
    K_I = getKindIndexByLetter(Lang, 'I'); K_i = getKindIndexByLetter(Lang, 'i'); K_Y = getKindIndexByLetter(Lang, 'Y'); K_l = getKindIndexByLetter(Lang, 'l'); K_z = getKindIndexByLetter(Lang, 'z');
