    vsClear(Decorators);
    logLine ll; memset(&ll, 0, sizeof ll); ll.text = vsNew();
    int indent;
    unsigned long lastCodeLine = 0, prevLastCode = 0;
    while (readLogicalLine(&ll, &indent, &lastCodeLine)) {
        popTo(indent, prevLastCode);
        prevLastCode = lastCodeLine;
        cursor c = { vsValue(ll.text), 0, ll.lines };
        const char *s = c.s;
        if (s[0] == '@') {
            /* decorator */
            if (vsLength(Decorators)) vsPut(Decorators, ',');
            const char *p = s + 1; while (*p && *p != '(' && *p != ' ') vsPut(Decorators, *p++);
            continue;
        }
        bool isAsync = false;
        if (startsWithKw(s, "async")) { c.i = 5; skipWs(&c); isAsync = true; }
        const char *q = s + c.i;
        if (startsWithKw(q, "def") || startsWithKw(q, "cdef") || startsWithKw(q, "cpdef")) {
            size_t kwlen = startsWithKw(q, "def") ? 3 : startsWithKw(q, "cdef") ? 4 : 5;
            c.i += kwlen;
            /* cdef class */
            skipWs(&c);
            if (startsWithKw(s + c.i, "class")) { c.i += 5; processClass(&c, &ll, indent); vsClear(Decorators); continue; }
            if (kwlen > 3) {
                /* cdef may declare variables: cdef int x = 1 ; or functions cdef int f(...): */
                if (!strchr(s + c.i, '(')) { processAssignment(&c, &ll); vsClear(Decorators); continue; }
                /* skip return type tokens until identifier followed by '(' */
                size_t save = c.i;
                vString *tmp = vsNew();
                size_t lastIdent = c.i;
                while (readIdent(&c, tmp)) { skipWs(&c); if (s[c.i] == '(') { c.i = lastIdent; break; } if (s[c.i] == '*') { while (s[c.i] == '*') c.i++; } lastIdent = c.i; }
                if (s[c.i] != '(' && !isIdentStart((unsigned char)s[c.i])) c.i = save;
                vsDelete(tmp);
                /* position c.i at the identifier start */
                { size_t j = lastIdent; while (s[j] == ' ') j++; c.i = j; }
            }
            processDef(&c, &ll, indent, isAsync);
            vsClear(Decorators);
            continue;
        }
        if (startsWithKw(q, "class")) { c.i += 5; processClass(&c, &ll, indent); vsClear(Decorators); continue; }
        vsClear(Decorators);
        if (startsWithKw(q, "import")) { c.i += 6; processImport(&c, &ll, false); continue; }
        if (startsWithKw(q, "from")) { c.i += 4; processImport(&c, &ll, true); continue; }
        if (startsWithKw(q, "cimport")) { c.i += 7; processImport(&c, &ll, false); continue; }
        /* skip keywords that cannot start assignments */
        static const char *const skipKws[] = { "if", "elif", "else", "for", "while", "try", "except", "finally", "with", "return", "yield", "raise", "pass", "break", "continue", "global", "nonlocal", "assert", "del", "print", "exec", "lambda", "match", "case", NULL };
        bool skip = false;
        for (int k = 0; skipKws[k]; k++) if (startsWithKw(q, skipKws[k])) { skip = true; break; }
        if (skip) continue;
        processAssignment(&c, &ll);
    }
    popTo(-1, lastCodeLine);
    vsDelete(ll.text); free(ll.lines);
}

