static bool isMakeIdent(int c) { return c != '\0' && !isspace(c) && strchr(":=#(){}", c) == NULL; }

static void parseMake(void) {
    int lang = getInputLanguage();
    int K_I = KIND(lang, 'I'), K_m = KIND(lang, 'm'), K_t = KIND(lang, 't');
