    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        /* continuation lines */
        vsClear(acc); vsCat(acc, p);
        accLine = getInputLineNumber();
        while (vsLength(acc) && vsLast(acc) == '\\') {
            vsChop(acc);
            const unsigned char *nl = readLineFromInputFile();
            if (!nl) break;
            vsPut(acc, ' ');
            vsCat(acc, (const char *)nl);
        }
        p = vsValue(acc);
        if (inDefine) { if (strncmp(skipSpaces(p), "endef", 5) == 0) inDefine = false; continue; }
        if (*p == '\t') { inRecipe = true; continue; }   /* recipe line */
