        if (*q == '\0' || *q == '#') continue;
        inRecipe = false;
        /* directives */
        if (wordAt(q, "include") || wordAt(q, "-include") || wordAt(q, "sinclude")) {
            bool opt = (*q == '-' || *q == 's');
            q += (*q == '-') ? 8 : (*q == 's' ? 8 : 7);
            while (*q) { q = skipSpaces(q); if (!*q) break; vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w) && K_I >= 0) simpleRefTag(vsValue(w), K_I, opt ? R_optional : R_included, accLine, CORK_NIL); }
            continue;
        }
        if (wordAt(q, "define")) {
            q = skipSpaces(q + 6);
            vsClear(w); while (isMakeIdent((unsigned char)*q)) vsPut(w, *q++);
            if (vsLength(w) && K_m >= 0) simpleTag(vsValue(w), K_m, accLine, CORK_NIL);
            inDefine = true;
            continue;
        }
        if (wordAt(q, "ifeq") || wordAt(q, "ifneq") || wordAt(q, "ifdef") || wordAt(q, "ifndef") || wordAt(q, "else") || wordAt(q, "endif") || wordAt(q, "vpath") || wordAt(q, "unexport")) continue;
        if (wordAt(q, "export") || wordAt(q, "override") || wordAt(q, "private")) {
            const char *r = q;
            while (wordAt(r, "export") || wordAt(r, "override") || wordAt(r, "private")) { while (pIsIdent((unsigned char)*r)) r++; r = skipSpaces(r); }
