            int depth = 0;
            const char *eq = NULL, *colon = NULL;
            for (; *r; r++) {
                if (*r == '$' && (r[1] == '(' || r[1] == '{')) { depth++; r++; continue; }
                if (depth && (*r == ')' || *r == '}')) { depth--; continue; }
                if (depth) continue;
                if (*r == '#') break;
                if (*r == '=' ) { eq = r; break; }
                if (*r == ':' ) { if (r[1] == '=' ) { eq = r; break; } if (r[1] == ':' && r[2] == '=') { eq = r; break; } colon = r; break; }
