    int k = (c == 't' || c == 'f') ? K_b : (c == 'n') ? K_z : K_n;
    for (;;) { int n = jsGetc(); if (n == EOF) break; if (n == ',' || n == '}' || n == ']' || isspace(n)) { ungetcToInputFile(n); break; } }
    *endLine = getInputLineNumber();
    return k;
}

static void parseJSON(void) {
    int lang = getInputLanguage();
    K_o = KIND(lang, 'o'); K_a = KIND(lang, 'a'); K_n = KIND(lang, 'n'); K_s = KIND(lang, 's'); K_b = KIND(lang, 'b'); K_z = KIND(lang, 'z');
    int c = skipWsJ();
    while (c != EOF) { unsigned long el; parseValue(c, CORK_NIL, &el, true); c = skipWsJ(); }
}
