/* Markdown parser */
#include "common.h"

static int K_c, K_s, K_S, K_t, K_T, K_u, K_n, K_h;
static int F_sectionMarker;

typedef struct { int level; int cork; } mdScope;
static mdScope MdStack[16];
static int MdTop = 0;

static void mdPop(int level, unsigned long endLine) {
    while (MdTop > 0 && MdStack[MdTop-1].level >= level) { MdTop--; if (MdStack[MdTop].cork) setTagEndLineToCorkEntry(MdStack[MdTop].cork, endLine); }
}
static int kindForLevel(int level) {
    switch (level) { case 1: return K_c; case 2: return K_s; case 3: return K_S; case 4: return K_t; case 5: return K_T; default: return K_u; }
}
static void mdHeading(const char *text, int level, unsigned long line, const char *marker, unsigned long prevLine) {
    mdPop(level, prevLine);
    tagEntryInfo e;
    initTagEntry(&e, text, kindForLevel(level));
    e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
    e.ext.scopeIndex = MdTop ? MdStack[MdTop-1].cork : CORK_NIL;
    if (F_sectionMarker >= 0) attachParserField(&e, F_sectionMarker, marker);
    int cork = makeTagEntry(&e);
    if (MdTop < 16) { MdStack[MdTop].level = level; MdStack[MdTop].cork = cork; MdTop++; }
}

static void parseMarkdown(void) {
    int lang = getInputLanguage();
    K_c = KIND(lang, 'c'); K_s = KIND(lang, 's'); K_S = KIND(lang, 'S'); K_t = KIND(lang, 't'); K_T = KIND(lang, 'T'); K_u = KIND(lang, 'u'); K_n = KIND(lang, 'n'); K_h = KIND(lang, 'h');
    F_sectionMarker = getLangFieldIndexByName(lang, "sectionMarker"); if (F_sectionMarker >= 0 && !isLangFieldEnabled(lang, F_sectionMarker)) F_sectionMarker = -1;
    MdTop = 0;
    const unsigned char *line;
    vString *prev = vsNew();       /* previous line text (for setext) */
    unsigned long prevLine = 0;
    bool prevIsText = false;
    bool inFence = false; char fenceChar = 0; int fenceLen = 0;
    unsigned long lastNonBlank = 0;
    vString *name = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        const char *q = p;
        int sp = 0; while (*q == ' ' && sp < 3) { q++; sp++; }
        /* fences */
        if ((q[0] == '`' && q[1] == '`' && q[2] == '`') || (q[0] == '~' && q[1] == '~' && q[2] == '~')) {
            int n = 0; char ch = q[0]; while (q[n] == ch) n++;
            if (!inFence) { inFence = true; fenceChar = ch; fenceLen = n; prevIsText = false; continue; }
            else if (ch == fenceChar && n >= fenceLen) { const char *r = q + n; while (*r == ' ') r++; if (*r == '\0') { inFence = false; continue; } }
        }
        if (inFence) { prevIsText = false; continue; }
        /* ATX heading */
        if (*q == '#') {
