        }
        bool blank = (*skipSpaces(p) == '\0');
        if (!blank) lastNonBlank = ln;
        prevIsText = !blank && !(*q == '-' && (q[1] == ' ' || q[1] == '-')) && !(*q == '>') && !(*q == '*' && q[1] == ' ') && !(*q == '+' && q[1] == ' ') && !(isdigit((unsigned char)*q) && (q[1] == '.' || q[1] == ')') && q[2] == ' ');
        if (sp >= 4 || *p == '\t') prevIsText = false;
        vsClear(prev); vsCat(prev, q);
        prevLine = ln;
    }
    mdPop(0, lastNonBlank);
    vsDelete(prev); vsDelete(name);
}
