/* JSON parser */
#include "common.h"

static int K_o, K_a, K_n, K_s, K_b, K_z;

static int jsGetc(void) { return getcFromInputFile(); }
static int skipWsJ(void) { int c; do { c = jsGetc(); } while (c == ' ' || c == '\t' || c == '\n' || c == '\r'); return c; }
static void readString(vString *out) {
    int c;
    vsClear(out);
    while ((c = jsGetc()) != EOF) {
        if (c == '\\') { int n = jsGetc(); if (n == EOF) break; vsPut(out, '\\'); vsPut(out, n); continue; }
        if (c == '"') break;
        vsPut(out, c);
    }
}
/* parse a value; c is its first char. 'scope' is cork of enclosing named key; returns kind of the value */
static int parseValue(int c, int scope, unsigned long *endLine, bool makeTags);

static void parseObject(int scope) {
    vString *key = vsNew();
    int c = skipWsJ();
    while (c != EOF && c != '}') {
        if (c == '"') {
            unsigned long line = getInputLineNumber();
            readString(key);
            c = skipWsJ();
            if (c != ':') { break; }
            c = skipWsJ();
            /* determine kind from value first char */
            int kind = -1;
            if (c == '{') kind = K_o; else if (c == '[') kind = K_a; else if (c == '"') kind = K_s; else if (c == 't' || c == 'f') kind = K_b; else if (c == 'n') kind = K_z; else kind = K_n;
            tagEntryInfo e;
            initTagEntry(&e, vsValue(key), kind);
            e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
            e.ext.scopeIndex = scope;
            int cork = makeTagEntry(&e);
            unsigned long endLine = line;
            parseValue(c, cork, &endLine, true);
            if (kind == K_o || kind == K_a) setTagEndLineToCorkEntry(cork, endLine);
            c = skipWsJ();
            if (c == ',') c = skipWsJ();
        } else {
            c = skipWsJ();
        }
    }
    vsDelete(key);
}
static void parseArray(int scope) {
    int c = skipWsJ();
    while (c != EOF && c != ']') {
        unsigned long el;
        parseValue(c, scope, &el, true);
        c = skipWsJ();
        if (c == ',') c = skipWsJ();
    }
}
static int parseValue(int c, int scope, unsigned long *endLine, bool makeTags) {
    (void)makeTags;
    if (c == '{') { parseObject(scope); *endLine = getInputLineNumber(); return K_o; }
    if (c == '[') { parseArray(scope); *endLine = getInputLineNumber(); return K_a; }
    if (c == '"') { vString *tmp = vsNew(); readString(tmp); vsDelete(tmp); *endLine = getInputLineNumber(); return K_s; }
    /* literal: read until delimiter */
    int k = (c == 't' || c == 'f') ? K_b : (c == 'n') ? K_z : K_n;
    for (;;) { int n = jsGetc(); if (n == EOF) break; if (n == ',' || n == '}' || n == ']' || isspace(n)) { ungetcToInputFile(n); break; } }
    *endLine = getInputLineNumber();
    return k;
}

static void parseJSON(void) {
    int lang = getInputLanguage();
    K_o = KIND(lang, 'o'); K_a = KIND(lang, 'a'); K_n = KIND(lang, 'n'); K_s = KIND(lang, 's'); K_b = KIND(lang, 'b'); K_z = KIND(lang, 'z');
    int c = skipWsJ();
    while (c != EOF) { unsigned long el; parseValue(c, CORK_NIL, &el, true); c = skipWsJ(); }
}
