/* CSS parser */
#include "common.h"

static void parseCSS(void) {
    int lang = getInputLanguage();
    int K_c = KIND(lang, 'c'), K_i = KIND(lang, 'i'), K_s = KIND(lang, 's');
    vString *sel = vsNew();
    unsigned long selLine = 0;
    int c;
    int braceDepth = 0;
    bool inAt = false;
    bool lastSpace = false;
    while ((c = getcFromInputFile()) != EOF) {
        if (c == '/' ) { int n = getcFromInputFile(); if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (prev == '*' && c == '/') break; prev = c; } continue; } ungetcToInputFile(n); }
        if (c == '"' || c == '\'') { int q = c; vsPut(sel, c); while ((c = getcFromInputFile()) != EOF && c != q) { if (c == '\\') { vsPut(sel, c); c = getcFromInputFile(); } vsPut(sel, c); } if (c != EOF) vsPut(sel, c); lastSpace = false; continue; }
        if (c == '{') {
            /* emit selectors */
            vsStripTrailing(sel); vsStripLeading(sel);
            if (vsLength(sel) && vsValue(sel)[0] != '@') {
                /* split by ',' */
                char *copy = xstrdup(vsValue(sel));
                char *save = copy;
                char *tok;
                while ((tok = strsep(&save, ",")) != NULL) {
                    char *t = strTrim(tok);
                    if (!*t) continue;
                    int kind = t[0] == '.' ? K_c : t[0] == '#' ? K_i : K_s;
                    tagEntryInfo e; initTagEntry(&e, t, kind); e.lineNumber = selLine; e.filePosition = (long)getInputLineStart(selLine);
                    makeTagEntry(&e);
                }
                free(copy);
                /* rule body: skip to matching '}' unless it is a nested block like @media */
                int depth = 1;
                while (depth > 0 && (c = getcFromInputFile()) != EOF) {
                    if (c == '"' || c == '\'') { int q = c; while ((c = getcFromInputFile()) != EOF && c != q) if (c == '\\') getcFromInputFile(); continue; }
                    if (c == '/') { int n = getcFromInputFile(); if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (prev == '*' && c == '/') break; prev = c; } continue; } ungetcToInputFile(n); }
                    if (c == '{') depth++; else if (c == '}') depth--;
                }
            } else {
                braceDepth++;
            }
            vsClear(sel); lastSpace = false; inAt = false;
            continue;
        }
        if (c == '}') { if (braceDepth > 0) braceDepth--; vsClear(sel); continue; }
        if (c == ';') { vsClear(sel); inAt = false; continue; }
        if (isspace(c)) { if (vsLength(sel) && !lastSpace) { vsPut(sel, ' '); lastSpace = true; } continue; }
