    if (Cur.type == GT_OP && strcmp(Cur.text, "=") == 0) {
        int depth = 0;
        for (;;) {
            if (Cur.type == GT_EOF) break;
            if (depth == 0 && (Cur.type == GT_SEMI || Cur.type == GT_RPAREN)) break;
            if (depth == 0 && Cur.nlBefore && Cur.type != GT_LBRACE && !(Cur.type == GT_OP)) {
