        if (scope == CORK_NIL) scope = findCork(rtn, K_i, K_a);
        if (scope == CORK_NIL) {
            tagEntryInfo e; initRefTagEntry(&e, rtn, K_Y, R_receiverType);
            e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
            scope = makeTagEntry(&e);
        }
        free(rtn);
    }
    if (Cur.type != GT_IDENT) { vsDelete(recvType); free(receiverName); return; }
    char *name = xstrdup(Cur.text);
    unsigned long nline = Cur.line;
    next();
