    if (Cur.type == GT_LPAREN) readType(sig);
    if (Cur.type != GT_LBRACE && Cur.type != GT_SEMI && Cur.type != GT_EOF && !Cur.nlBefore) readType(ret);
    tagEntryInfo e; initTagEntry(&e, name, K_f);
    e.lineNumber = nline; e.filePosition = (long)getInputLineStart(nline);
    e.ext.scopeIndex = scope;
    e.ext.signature = vsValue(sig);
    if (vsLength(ret)) { e.ext.typeRefKind = "typename"; e.ext.typeRefName = vsValue(ret); }
    if (receiverName && F_receiver >= 0) attachParserField(&e, F_receiver, receiverName);
    int cork = makeTagEntry(&e);
    if (receiverName && K_R >= 0 && isLanguageKindEnabled(Lang, K_R)) makeGoTag(receiverName, K_R, line, cork, NULL, vsValue(recvType));
    if (Cur.type == GT_LBRACE) { unsigned long end = skipBlock(); setTagEndLineToCorkEntry(cork, end); }
    free(name); free(receiverName); vsDelete(recvType); vsDelete(sig); vsDelete(ret);
}

static void parseGo(void) {
    Lang = getInputLanguage();
    K_p = KIND(Lang, 'p'); K_f = KIND(Lang, 'f'); K_c = KIND(Lang, 'c'); K_t = KIND(Lang, 't'); K_v = KIND(Lang, 'v'); K_s = KIND(Lang, 's'); K_i = KIND(Lang, 'i');
    K_m = KIND(Lang, 'm'); K_M = KIND(Lang, 'M'); K_n = KIND(Lang, 'n'); K_a = KIND(Lang, 'a'); K_P = KIND(Lang, 'P'); K_R = KIND(Lang, 'R'); K_Y = KIND(Lang, 'Y');
    F_package = getLangFieldIndexByName(Lang, "package"); F_packageName = getLangFieldIndexByName(Lang, "packageName");
    F_howImported = getLangFieldIndexByName(Lang, "howImported"); if (F_howImported >= 0 && !isLangFieldEnabled(Lang, F_howImported)) F_howImported = -1;
    F_receiver = getLangFieldIndexByName(Lang, "receiver"); if (F_receiver >= 0 && !isLangFieldEnabled(Lang, F_receiver)) F_receiver = -1;
    R_imported = ROLE(Lang, K_p, "imported"); R_receiverType = ROLE(Lang, K_Y, "receiverType");
