/* Go parser */
#include "common.h"

static int K_p, K_f, K_c, K_t, K_v, K_s, K_i, K_m, K_M, K_n, K_a, K_P, K_R, K_Y;
static int F_package, F_packageName, F_howImported, F_receiver;
static int R_imported, R_receiverType;
static int Lang;

typedef struct { int type; char *text; unsigned long line; bool nlBefore; } gtok;
enum { GT_EOF, GT_IDENT, GT_KW, GT_STRING, GT_NUM, GT_OP, GT_LPAREN, GT_RPAREN, GT_LBRACE, GT_RBRACE, GT_LBRACK, GT_RBRACK, GT_SEMI, GT_COMMA, GT_DOT, GT_STAR };

static const char *GoKws[] = { "break","case","chan","const","continue","default","defer","else","fallthrough","for","func","go","goto","if","import","interface","map","package","range","return","select","struct","switch","type","var", NULL };
static bool isGoKw(const char *s) { for (int i = 0; GoKws[i]; i++) if (strcmp(s, GoKws[i]) == 0) return true; return false; }

static gtok Cur;
static bool HaveLook = false; static gtok Look;
static bool LastWasValueEnd = false;   /* for automatic semicolon insertion */

static void readRaw(gtok *t) {
    free(t->text); t->text = NULL;
    int c;
    bool nl = false;
    for (;;) {
        c = getcFromInputFile();
        if (c == '\n') { nl = true; continue; }
        if (c == ' ' || c == '\t' || c == '\r') continue;
        if (c == '/') {
            int n = getcFromInputFile();
            if (n == '/') { while ((c = getcFromInputFile()) != EOF && c != '\n') ; nl = true; continue; }
            if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (c == '\n') nl = true; if (prev == '*' && c == '/') break; prev = c; } continue; }
            ungetcToInputFile(n);
        }
        break;
    }
    t->nlBefore = nl;
    t->line = getInputLineNumber();
    vString *v = vsNew();
    if (c == EOF) t->type = GT_EOF;
    else if (pIsIdentStart(c)) { while (pIsIdent(c)) { vsPut(v, c); c = getcFromInputFile(); } ungetcToInputFile(c); t->type = isGoKw(vsValue(v)) ? GT_KW : GT_IDENT; }
    else if (isdigit(c) || (c == '.' && isdigit(peekcFromInputFile()))) { while (isalnum(c) || c == '.' || c == '_') { vsPut(v, c); c = getcFromInputFile(); } ungetcToInputFile(c); t->type = GT_NUM; }
    else if (c == '"' || c == '`' || c == '\'') {
        int q = c; vsPut(v, c);
        while ((c = getcFromInputFile()) != EOF) { if (q != '`' && c == '\\') { vsPut(v, c); c = getcFromInputFile(); if (c == EOF) break; vsPut(v, c); continue; } vsPut(v, c); if (c == q) break; }
        t->type = GT_STRING;
    }
    else {
        vsPut(v, c);
        switch (c) {
        case '(': t->type = GT_LPAREN; break; case ')': t->type = GT_RPAREN; break;
        case '{': t->type = GT_LBRACE; break; case '}': t->type = GT_RBRACE; break;
        case '[': t->type = GT_LBRACK; break; case ']': t->type = GT_RBRACK; break;
        case ';': t->type = GT_SEMI; break; case ',': t->type = GT_COMMA; break;
        case '.': t->type = GT_DOT; break; case '*': t->type = GT_STAR; break;
        default: {
            int n = getcFromInputFile();
            if ((c == ':' && n == '=') || (c == '<' && n == '-') || (c == '=' && n == '=') || (c == '!' && n == '=') || (c == '<' && n == '=') || (c == '>' && n == '=') || (c == '&' && n == '&') || (c == '|' && n == '|') || (c == '+' && n == '+') || (c == '-' && n == '-') || (c == '.' && n == '.') || (n == '=' && strchr("+-*/%&|^<>", c)) || (c == '<' && n == '<') || (c == '>' && n == '>')) vsPut(v, n);
            else ungetcToInputFile(n);
            t->type = GT_OP;
        }
        }
    }
    t->text = vsDetach(v);
}
static void next(void) {
    if (HaveLook) { free(Cur.text); Cur = Look; Look.text = NULL; HaveLook = false; }
    else readRaw(&Cur);
}
static gtok *peek(void) { if (!HaveLook) { readRaw(&Look); HaveLook = true; } return &Look; }
static bool curIs(const char *s) { return Cur.text && strcmp(Cur.text, s) == 0; }

/* skip balanced block starting at current '{' ; returns line of closing */
static unsigned long skipBlock(void) {
    int depth = 0;
    unsigned long end = Cur.line;
    do {
        if (Cur.type == GT_LBRACE) depth++;
        else if (Cur.type == GT_RBRACE) { depth--; end = Cur.line; }
        else if (Cur.type == GT_EOF) break;
        next();
    } while (depth > 0);
    return end;
}
static void skipParens(void) { int depth = 0; do { if (Cur.type == GT_LPAREN) depth++; else if (Cur.type == GT_RPAREN) depth--; else if (Cur.type == GT_EOF) return; next(); } while (depth > 0); }

/* collect raw text until a token type at depth 0 ; appends tokens with single spaces where needed */
static void appendTok(vString *out, const gtok *t, const gtok *prev) {
    if (prev && prev->text && t->text) {
        bool needSpace = false;
        int pt = prev->type, ct = t->type;
        if ((pt == GT_IDENT || pt == GT_KW || pt == GT_NUM || pt == GT_RBRACK || pt == GT_RPAREN || pt == GT_RBRACE) && (ct == GT_IDENT || ct == GT_KW || ct == GT_NUM || ct == GT_STRING || ct == GT_STAR || ct == GT_LBRACK && false)) needSpace = true;
        if (pt == GT_COMMA) needSpace = true;
        if (pt == GT_KW && (ct == GT_LBRACK || ct == GT_LBRACE || ct == GT_LPAREN) && (strcmp(prev->text, "chan") == 0 || strcmp(prev->text, "func") == 0 || strcmp(prev->text, "map") == 0 || strcmp(prev->text, "interface") == 0 || strcmp(prev->text, "struct") == 0)) needSpace = (strcmp(prev->text, "chan") == 0);
        if (pt == GT_OP && strcmp(prev->text, "<-") == 0) needSpace = false;
        if (ct == GT_OP && strcmp(t->text, "<-") == 0 && pt == GT_KW) needSpace = true;
        if (needSpace) vsPut(out, ' ');
    }
    vsCat(out, t->text);
}

/* read a type expression starting at Cur; appends to out; stops before ',' ')' '{' ';' '=' '}' at depth 0 */
static void readType(vString *out) {
    int depth = 0;
    gtok prev = { GT_EOF, NULL, 0, false };
    bool first = true;
    for (;;) {
        if (Cur.type == GT_EOF) break;
        if (depth == 0 && (Cur.type == GT_COMMA || Cur.type == GT_RPAREN || Cur.type == GT_SEMI || Cur.type == GT_RBRACE || (Cur.type == GT_OP && strcmp(Cur.text, "=") == 0))) break;
        if (depth == 0 && Cur.type == GT_LBRACE && !(prev.type == GT_KW && (strcmp(prev.text, "struct") == 0 || strcmp(prev.text, "interface") == 0))) break;
        if (!first && Cur.nlBefore && depth == 0) break;
        if (Cur.type == GT_LPAREN || Cur.type == GT_LBRACK || Cur.type == GT_LBRACE) depth++;
        if (Cur.type == GT_RPAREN || Cur.type == GT_RBRACK || Cur.type == GT_RBRACE) depth--;
        appendTok(out, &Cur, first ? NULL : &prev);
        free(prev.text); prev = Cur; prev.text = xstrdup(Cur.text);
        first = false;
        next();
    }
    free(prev.text);
}

static int makeGoTag(const char *name, int kind, unsigned long line, int scope, const char *sig, const char *typeref) {
    tagEntryInfo e; initTagEntry(&e, name, kind);
    e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
    e.ext.scopeIndex = scope;
    if (sig) e.ext.signature = (char *)sig;
    if (typeref && *typeref) { e.ext.typeRefKind = "typename"; e.ext.typeRefName = (char *)typeref; }
    return makeTagEntry(&e);
}

/* find a tag by name in the cork queue with given kinds */
static int findCork(const char *name, int kind1, int kind2) {
    int n = countEntryInCorkQueue();
    for (int i = n - 1; i >= 1; i--) { tagEntryInfo *e = getEntryInCorkQueue(i); if (e && e->name && strcmp(e->name, name) == 0 && (e->kindIndex == kind1 || e->kindIndex == kind2) && !e->placeholder && e->roleBits == 0) return i; }
    return CORK_NIL;
}

static void parseStructBody(int scope);
static void parseInterfaceBody(int scope);

static void parseTypeSpec(unsigned long line) {
    if (Cur.type != GT_IDENT) return;
    char *name = xstrdup(Cur.text);
    next();
    /* type params [T any] */
    if (Cur.type == GT_LBRACK) { int d = 0; do { if (Cur.type == GT_LBRACK) d++; else if (Cur.type == GT_RBRACK) d--; next(); } while (d > 0 && Cur.type != GT_EOF); }
    bool alias = false;
    if (Cur.type == GT_OP && strcmp(Cur.text, "=") == 0) { alias = true; next(); }
    if (Cur.type == GT_KW && strcmp(Cur.text, "struct") == 0 && peek()->type == GT_LBRACE) {
        int cork = makeGoTag(name, K_s, line, CORK_NIL, NULL, NULL);
        next(); /* { */
        parseStructBody(cork);
        setTagEndLineToCorkEntry(cork, Cur.line);
        next();
    } else if (Cur.type == GT_KW && strcmp(Cur.text, "interface") == 0 && peek()->type == GT_LBRACE) {
        int cork = makeGoTag(name, K_i, line, CORK_NIL, NULL, NULL);
        next();
        parseInterfaceBody(cork);
        setTagEndLineToCorkEntry(cork, Cur.line);
        next();
    } else {
        vString *typ = vsNew();
        readType(typ);
        makeGoTag(name, alias ? K_a : K_t, line, CORK_NIL, NULL, vsValue(typ));
        vsDelete(typ);
    }
    free(name);
}

static void parseStructBody(int scope) {
    /* Cur is '{' */
    next();
    vString *typ = vsNew();
    while (Cur.type != GT_RBRACE && Cur.type != GT_EOF) {
        if (Cur.type == GT_SEMI) { next(); continue; }
        unsigned long line = Cur.line;
        /* field names list or embedded type */
        if (Cur.type == GT_IDENT) {
            gtok *pk = peek();
            if (pk->type == GT_COMMA || pk->type == GT_IDENT || pk->type == GT_STAR || pk->type == GT_LBRACK || (pk->type == GT_KW && (strcmp(pk->text, "map") == 0 || strcmp(pk->text, "chan") == 0 || strcmp(pk->text, "func") == 0 || strcmp(pk->text, "struct") == 0 || strcmp(pk->text, "interface") == 0)) || pk->type == GT_LPAREN || (pk->type == GT_OP && strcmp(pk->text, "<-") == 0)) {
                strArray *names = saNew();
                saAdd(names, Cur.text); next();
                while (Cur.type == GT_COMMA) { next(); if (Cur.type == GT_IDENT) { saAdd(names, Cur.text); next(); } }
                vsClear(typ);
                if (Cur.type == GT_KW && strcmp(Cur.text, "struct") == 0 && peek()->type == GT_LBRACE) {
                    /* anonymous struct field */
                    int c0 = CORK_NIL;
                    for (size_t i = 0; i < saCount(names); i++) c0 = makeGoTag(saItem(names, i), K_m, line, scope, NULL, "struct");
                    next(); parseStructBody(c0); next();
                } else {
                    readType(typ);
                    for (size_t i = 0; i < saCount(names); i++) makeGoTag(saItem(names, i), K_m, line, scope, NULL, vsValue(typ));
                }
                saDelete(names);
            } else {
                /* embedded: pkg.Type or Type */
                vsClear(typ);
                readType(typ);
                const char *nm = vsValue(typ); const char *dot = strrchr(nm, '.');
                makeGoTag(dot ? dot + 1 : nm, K_M, line, scope, NULL, nm);
            }
        } else if (Cur.type == GT_STAR) {
            vsClear(typ); readType(typ);
            const char *nm = vsValue(typ); const char *dot = strrchr(nm, '.');
            if (*nm == '*') nm++;
            makeGoTag(dot ? dot + 1 : nm, K_M, line, scope, NULL, vsValue(typ));
        } else next();
        /* tag string */
        if (Cur.type == GT_STRING) next();
    }
    vsDelete(typ);
}

static void parseInterfaceBody(int scope) {
    next();
    vString *sig = vsNew(), *ret = vsNew();
    while (Cur.type != GT_RBRACE && Cur.type != GT_EOF) {
        if (Cur.type == GT_SEMI) { next(); continue; }
        unsigned long line = Cur.line;
        if (Cur.type == GT_IDENT && peek()->type == GT_LPAREN) {
            char *name = xstrdup(Cur.text); next();
            vsClear(sig); readType(sig);  /* reads (params) and stops? readType stops at ')' depth0: handles the paren group */
            /* readType appended "(...)" ; now return type */
            vsClear(ret);
            if (Cur.type != GT_SEMI && Cur.type != GT_RBRACE && !Cur.nlBefore) readType(ret);
            makeGoTag(name, K_n, line, scope, vsValue(sig), vsValue(ret));
            free(name);
        } else { vsClear(sig); readType(sig); if (Cur.type != GT_SEMI && Cur.type != GT_RBRACE) next(); }
    }
    vsDelete(sig); vsDelete(ret);
}

static void parseImportSpec(void) {
    unsigned long line = Cur.line;
    char *alias = NULL;
    bool dot = false, blank = false;
    if (Cur.type == GT_IDENT) { alias = xstrdup(Cur.text); if (strcmp(alias, "_") == 0) blank = true; next(); }
    else if (Cur.type == GT_DOT) { dot = true; next(); }
    if (Cur.type != GT_STRING) return;
    vString *path = vsNew();
    const char *t = Cur.text;
    size_t n = strlen(t);
    if (n >= 2) vsCatN(path, t + 1, n - 2);
    const char *base = strrchr(vsValue(path), '/'); base = base ? base + 1 : vsValue(path);
    const char *pname = alias ? alias : base;
    /* ref tag for package */
    {
