            if (vsLength(inh) && vsLast(inh) != '.' && vsLast(inh) != ',') vsPut(inh, ',');
            vsCat(inh, Cur.text); next();
            while (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0) { vsPut(inh, '.'); next(); if (Cur.type == JT_IDENT) { vsCat(inh, Cur.text); next(); } }
            if (Cur.type == JT_LT) { int d = 0; do { if (Cur.type == JT_LT) d++; else if (Cur.type == JT_GT) d--; vsCat(inh, Cur.text); next(); } while (d > 0 && Cur.type != JT_EOF && Cur.type != JT_LBRACE); }
            continue;
        }
        if (Cur.type == JT_COMMA) { next(); continue; }
        next();
    }
    int cork = makeJTag(vsValue(name), kind, line, access, impl, vsValue(inh), NULL);
    if (Cur.type == JT_LBRACE) {
        if (Top < 128) { Stack[Top].cork = cork; Stack[Top].kind = kind; Stack[Top].name = xstrdup(vsValue(name)); Top++; }
        parseBody(cork, kind);
        if (Top > 0) { Top--; free(Stack[Top].name); }
        setTagEndLineToCorkEntry(cork, Cur.line);
        next();
    } else if (Cur.type == JT_SEMI) next();
    vsDelete(name); vsDelete(inh); free(kw);
}

static void parseEnumBody(int cork) {
    /* Cur at '{' */
    next();
    while (Cur.type != JT_RBRACE && Cur.type != JT_EOF && Cur.type != JT_SEMI) {
        while (Cur.type == JT_AT) skipAnnotation();
        if (Cur.type == JT_IDENT) {
            makeJTag(Cur.text, K_e, Cur.line, NULL, NULL, NULL, NULL);
            next();
            if (Cur.type == JT_LPAREN) readParenGroup();
            if (Cur.type == JT_LBRACE) { skipBlock(); }
        }
        if (Cur.type == JT_COMMA) next();
        else if (Cur.type != JT_SEMI && Cur.type != JT_RBRACE) next();
    }
    if (Cur.type == JT_SEMI) { next(); parseBody(cork, K_g); }
}

/* parse class/interface body until matching '}' (Cur ends at '}') */
static void parseBody(int cork, int kind) {
    if (kind == K_g && Cur.type == JT_LBRACE) { parseEnumBody(cork); return; }
    if (Cur.type == JT_LBRACE) next();
    (void)cork;
    while (Cur.type != JT_RBRACE && Cur.type != JT_EOF) {
        /* declaration: modifiers, annotations, type, name */
        const char *access = NULL; const char *impl = NULL;
        bool sawStatic = false;
        strArray *toks = saNew();  /* collected identifier tokens of type/name */
        unsigned long nameLine = Cur.line;
        bool done = false;
        while (!done) {
            switch (Cur.type) {
            case JT_AT:
                if (peek()->type == JT_IDENT && strcmp(peek()->text, "interface") == 0) { next(); parseTypeDecl(access, impl, true); done = true; break; }
                skipAnnotation(); break;
            case JT_IDENT:
                if (isModifier(Cur.text)) {
                    if (curIs("public") || curIs("private") || curIs("protected")) access = curIs("public") ? "public" : curIs("private") ? "private" : "protected";
                    else if (curIs("abstract")) impl = "abstract";
                    else if (curIs("static")) sawStatic = true;
                    else if (IsCSharp && curIs("internal")) access = "internal";
                    next(); break;
                }
                if (isTypeKw(Cur.text) && !(curIs("record") && peek()->type != JT_IDENT)) { parseTypeDecl(access, impl, false); done = true; break; }
                saAdd(toks, Cur.text); nameLine = Cur.line; next();
                /* generic type args or array */
                if (Cur.type == JT_LT) skipAngle();
                while (Cur.type == JT_LBRACK) { next(); if (Cur.type == JT_RBRACK) next(); }
                while (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0) { next(); if (Cur.type == JT_IDENT) { char *last = toks->items[saCount(toks)-1]; char *nn = xmalloc(strlen(last) + strlen(Cur.text) + 2); sprintf(nn, "%s.%s", last, Cur.text); free(last); toks->items[saCount(toks)-1] = nn; nameLine = Cur.line; next(); } if (Cur.type == JT_LT) skipAngle(); }
                if (Cur.type == JT_OP && strcmp(Cur.text, "?") == 0) next();
                break;
            case JT_LT: skipAngle(); break;
            case JT_LPAREN: {
                /* method: last token is name */
                if (saCount(toks) == 0) { int d = 0; do { if (Cur.type == JT_LPAREN) d++; else if (Cur.type == JT_RPAREN) d--; next(); } while (d > 0 && Cur.type != JT_EOF); break; }
                const char *name = toks->items[saCount(toks)-1];
                readParenGroup();
                /* throws clause / C# where / => expression body */
                while (Cur.type != JT_LBRACE && Cur.type != JT_SEMI && Cur.type != JT_EOF && !(Cur.type == JT_OP && strcmp(Cur.text, "=>") == 0)) next();
                const char *acc = access;
                if (!acc && !IsCSharp) acc = "default";
                if (!acc && IsCSharp) acc = "private";
                int mc = makeJTag(name, K_m, nameLine, acc, impl, NULL, vsValue(Paren));
                if (Cur.type == JT_LBRACE) {
                    /* scan body for anonymous classes */
                    if (Top < 128) { Stack[Top].cork = mc; Stack[Top].kind = K_m; Stack[Top].name = xstrdup(name); Top++; }
                    extern void javaScanBlock(void);
                    javaScanBlock();
                    if (Top > 0) { Top--; free(Stack[Top].name); }
                    setTagEndLineToCorkEntry(mc, Cur.line);
                    next();
                } else if (Cur.type == JT_SEMI) { setTagEndLineToCorkEntry(mc, Cur.line); next(); }
                else { /* => expr ; */ while (Cur.type != JT_SEMI && Cur.type != JT_EOF) next(); setTagEndLineToCorkEntry(mc, Cur.line); next(); }
                done = true; break;
            }
            case JT_OP:
                if (strcmp(Cur.text, "=") == 0 || strcmp(Cur.text, ":") == 0) {
                    /* field with initializer */
                    if (saCount(toks) >= 2) { const char *acc = access ? access : (IsCSharp ? "private" : "default"); makeJTag(toks->items[saCount(toks)-1], K_f, nameLine, acc, NULL, NULL, NULL); }
                    /* skip initializer to ; or , */
                    int d = 0;
                    for (;;) { next(); if (Cur.type == JT_EOF) break; if (Cur.type == JT_LPAREN || Cur.type == JT_LBRACE || Cur.type == JT_LBRACK) d++; if (Cur.type == JT_RPAREN || Cur.type == JT_RBRACE || Cur.type == JT_RBRACK) d--; if (d == 0 && (Cur.type == JT_SEMI || Cur.type == JT_COMMA)) break; if (d < 0) break; }
                    if (Cur.type == JT_COMMA) { /* more declarators: keep type */ char *typ = xstrdup(toks->items[0]); saClear(toks); saAddOwn(toks, typ); next(); break; }
                    if (Cur.type == JT_SEMI) next();
                    done = true; break;
                }
                next(); break;
            case JT_COMMA:
                if (saCount(toks) >= 2) { const char *acc = access ? access : (IsCSharp ? "private" : "default"); makeJTag(toks->items[saCount(toks)-1], K_f, nameLine, acc, NULL, NULL, NULL); char *typ = xstrdup(toks->items[0]); saClear(toks); saAddOwn(toks, typ); }
                next(); break;
            case JT_SEMI:
                if (saCount(toks) >= 2) { const char *acc = access ? access : (IsCSharp ? "private" : "default"); makeJTag(toks->items[saCount(toks)-1], K_f, nameLine, acc, NULL, NULL, NULL); }
                next(); done = true; break;
            case JT_LBRACE:
                /* static/instance initializer or C# property */
                if (IsCSharp && saCount(toks) >= 2 && K_pr_prop >= 0) { const char *acc = access ? access : "private"; int pc = makeJTag(toks->items[saCount(toks)-1], K_pr_prop, nameLine, acc, NULL, NULL, NULL); unsigned long e = skipBlock(); setTagEndLineToCorkEntry(pc, e); if (Cur.type == JT_OP && strcmp(Cur.text, "=") == 0) { while (Cur.type != JT_SEMI && Cur.type != JT_EOF) next(); next(); } }
                else skipBlock();
                done = true; break;
            case JT_RBRACE: case JT_EOF: done = true; break;
            default: next(); break;
            }
        }
        saDelete(toks);
        (void)sawStatic;
    }
}

/* scan a method body: handle anonymous classes "new X(...) {" and local classes; Cur at '{', ends at matching '}' */
void javaScanBlock(void) {
    int depth = 0;
    for (;;) {
        if (Cur.type == JT_EOF) return;
        if (Cur.type == JT_LBRACE) { depth++; next(); continue; }
        if (Cur.type == JT_RBRACE) { depth--; if (depth == 0) return; next(); continue; }
        if (Cur.type == JT_IDENT && curIs("new")) {
            next();
            /* type name */
            vString *tn = vsNew();
            unsigned long line = Cur.line;
            while (Cur.type == JT_IDENT || (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0)) { vsCat(tn, Cur.text); next(); }
            if (Cur.type == JT_LT) skipAngle();
            if (Cur.type == JT_LPAREN) {
                readParenGroup();
                if (Cur.type == JT_LBRACE) {
                    vString *an = vsNew(); anonGenerate(an, "__anon", K_c);
                    tagEntryInfo e; initTagEntry(&e, vsValue(an), K_c); e.lineNumber = line; e.filePosition = (long)getInputLineStart(line); e.ext.scopeIndex = scopeCork(); e.ext.inherits = vsValue(tn); markTagExtraBit(&e, XTAG_ANONYMOUS);
                    int c = makeTagEntry(&e);
                    if (Top < 128) { Stack[Top].cork = c; Stack[Top].kind = K_c; Stack[Top].name = xstrdup(vsValue(an)); Top++; }
                    parseBody(c, K_c);
                    if (Top > 0) { Top--; free(Stack[Top].name); }
                    setTagEndLineToCorkEntry(c, Cur.line);
                    next();
                    vsDelete(an);
                }
            }
            vsDelete(tn);
            continue;
        }
        if (Cur.type == JT_IDENT && (curIs("class") || curIs("interface") || curIs("enum")) && !IsCSharp) { parseTypeDecl(NULL, NULL, false); continue; }
        next();
    }
}

static void parseJavaLike(bool csharp) {
    IsCSharp = csharp;
    Lang = getInputLanguage();
    K_c = KIND(Lang, 'c'); K_i = KIND(Lang, 'i'); K_g = KIND(Lang, 'g'); K_e = KIND(Lang, 'e'); K_f = KIND(Lang, 'f'); K_m = KIND(Lang, 'm'); K_p = KIND(Lang, 'p'); K_a = KIND(Lang, 'a'); K_l = KIND(Lang, 'l');
    K_s_ns = KIND(Lang, 'n'); K_d_struct = KIND(Lang, 's'); K_E_event = KIND(Lang, 'E'); K_pr_prop = KIND(Lang, 'p'); K_t_typedef = KIND(Lang, 't');
    if (csharp) { K_p = KIND(Lang, 'n'); K_a = -1; } else { K_pr_prop = -1; K_d_struct = K_c; K_s_ns = K_p; }
    R_imported = csharp ? -1 : ROLE(Lang, K_p, "imported");
    if (!Paren) Paren = vsNew();
    memset(&Cur, 0, sizeof Cur); memset(&Look, 0, sizeof Look); HaveLook = false; Top = 0;
    next();
    while (Cur.type != JT_EOF) {
        if (Cur.type == JT_IDENT && (curIs("package") || (csharp && curIs("namespace")))) {
            bool isNs = curIs("namespace");
            next();
            vString *n = vsNew(); unsigned long line = Cur.line;
            while (Cur.type == JT_IDENT || (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0)) { vsCat(n, Cur.text); next(); }
            if (vsLength(n)) {
                int kind = isNs ? K_s_ns : K_p;
                int cork = makeJTag(vsValue(n), kind, line, NULL, NULL, NULL, NULL);
                if (isNs && Cur.type == JT_LBRACE) { if (Top < 128) { Stack[Top].cork = cork; Stack[Top].kind = kind; Stack[Top].name = xstrdup(vsValue(n)); Top++; } parseBody(cork, kind); if (Top > 0) { Top--; free(Stack[Top].name); } setTagEndLineToCorkEntry(cork, Cur.line); next(); }
            }
            vsDelete(n);
            while (Cur.type == JT_SEMI) next();
            continue;
        }
        if (Cur.type == JT_IDENT && (curIs("import") || (csharp && curIs("using")))) {
            bool isImport = curIs("import");
            next();
            if (Cur.type == JT_IDENT && curIs("static")) next();
            vString *n = vsNew(); unsigned long line = Cur.line;
            while (Cur.type == JT_IDENT || (Cur.type == JT_OP && (strcmp(Cur.text, ".") == 0 || strcmp(Cur.text, "*") == 0))) { vsCat(n, Cur.text); next(); }
            if (isImport && vsLength(n) && R_imported >= 0) {
                /* strip .* */
                char *s = xstrdup(vsValue(n)); size_t l = strlen(s); if (l > 2 && s[l-1] == '*' && s[l-2] == '.') s[l-2] = 0;
                tagEntryInfo e; initRefTagEntry(&e, s, K_p, R_imported); e.lineNumber = line; e.filePosition = (long)getInputLineStart(line); makeTagEntry(&e); free(s);
            }
            while (Cur.type != JT_SEMI && Cur.type != JT_EOF) next();
            next(); vsDelete(n);
            continue;
        }
        /* top-level type declarations */
        parseBody(CORK_NIL, -1);
        if (Cur.type == JT_RBRACE) next();
    }
    free(Cur.text); Cur.text = NULL; if (HaveLook) { free(Look.text); Look.text = NULL; HaveLook = false; }
}
static void parseJava(void) { parseJavaLike(false); }
static void parseCSharp(void) { parseJavaLike(true); }
