/* Java / C# parser (simplified, modeled after legacy c.c behaviour) */
#include "common.h"

typedef struct { int type; char *text; unsigned long line; } jtok;
enum { JT_EOF, JT_IDENT, JT_STRING, JT_NUM, JT_OP, JT_LPAREN, JT_RPAREN, JT_LBRACE, JT_RBRACE, JT_LBRACK, JT_RBRACK, JT_SEMI, JT_COMMA, JT_LT, JT_GT, JT_AT };

static jtok Cur, Look; static bool HaveLook = false;
static vString *Paren = NULL;   /* text of last paren group read */
static bool IsCSharp = false;

static void readRaw(jtok *t) {
    free(t->text); t->text = NULL;
    int c;
    for (;;) {
        c = getcFromInputFile();
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f') continue;
        if (c == '/') {
            int n = getcFromInputFile();
            if (n == '/') { while ((c = getcFromInputFile()) != EOF && c != '\n') ; continue; }
            if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (prev == '*' && c == '/') break; prev = c; } continue; }
            ungetcToInputFile(n);
        }
        if (c == '#' && IsCSharp) { while ((c = getcFromInputFile()) != EOF && c != '\n') ; continue; }
        break;
    }
    t->line = getInputLineNumber();
    vString *v = vsNew();
    if (c == EOF) t->type = JT_EOF;
    else if (pIsIdentStart(c) || c == '$') { while (pIsIdent(c) || c == '$') { vsPut(v, c); c = getcFromInputFile(); } ungetcToInputFile(c); t->type = JT_IDENT; }
    else if (isdigit(c)) { while (isalnum(c) || c == '.' || c == '_') { vsPut(v, c); c = getcFromInputFile(); } ungetcToInputFile(c); t->type = JT_NUM; }
    else if (c == '"' || c == '\'') {
        int q = c; vsPut(v, c);
        /* text block """ */
        int n = getcFromInputFile();
        if (q == '"' && n == '"') { int m = getcFromInputFile(); if (m == '"') { int cnt = 0; while ((c = getcFromInputFile()) != EOF) { if (c == '"') { if (++cnt == 3) break; } else cnt = 0; } vsCat(v, "\"\""); t->type = JT_STRING; t->text = vsDetach(v); return; } ungetcToInputFile(m); vsPut(v, '"'); t->type = JT_STRING; t->text = vsDetach(v); return; }
        c = n;
        while (c != EOF) { if (c == '\\') { vsPut(v, c); c = getcFromInputFile(); if (c == EOF) break; vsPut(v, c); c = getcFromInputFile(); continue; } vsPut(v, c); if (c == q || c == '\n') break; c = getcFromInputFile(); }
        t->type = JT_STRING;
    } else {
        vsPut(v, c);
        switch (c) {
        case '(': t->type = JT_LPAREN; break; case ')': t->type = JT_RPAREN; break;
        case '{': t->type = JT_LBRACE; break; case '}': t->type = JT_RBRACE; break;
        case '[': t->type = JT_LBRACK; break; case ']': t->type = JT_RBRACK; break;
        case ';': t->type = JT_SEMI; break; case ',': t->type = JT_COMMA; break;
        case '<': t->type = JT_LT; break; case '>': t->type = JT_GT; break;
        case '@': t->type = JT_AT; break;
        default: t->type = JT_OP; break;
        }
    }
    t->text = vsDetach(v);
}
static void next(void) { if (HaveLook) { free(Cur.text); Cur = Look; Look.text = NULL; HaveLook = false; } else readRaw(&Cur); }
static jtok *peek(void) { if (!HaveLook) { readRaw(&Look); HaveLook = true; } return &Look; }
static bool curIs(const char *s) { return Cur.text && strcmp(Cur.text, s) == 0; }

static int K_c, K_i, K_g, K_e, K_f, K_m, K_p, K_a, K_l, K_s_ns, K_E, K_d_struct, K_E_event, K_pr_prop, K_t_typedef;
static int R_imported;
static int Lang;

/* read balanced paren group into Paren (source-like text with single spaces) */
static void readParenGroup(void) {
    vsClear(Paren);
    int depth = 0;
    int prevType = -1;
    for (;;) {
        if (Cur.type == JT_EOF) break;
        if (Cur.type == JT_LPAREN) depth++;
        if (Cur.type == JT_RPAREN) depth--;
        bool space = false;
        if (prevType != -1) {
            if ((prevType == JT_IDENT || prevType == JT_GT || prevType == JT_RBRACK || prevType == JT_NUM || prevType == JT_STRING) && (Cur.type == JT_IDENT || Cur.type == JT_NUM || Cur.type == JT_STRING || Cur.type == JT_AT)) space = true;
            if (prevType == JT_COMMA) space = true;
            if (prevType == JT_OP && (Cur.type == JT_IDENT || Cur.type == JT_NUM)) space = true;
            if (Cur.type == JT_OP && (prevType == JT_IDENT || prevType == JT_NUM || prevType == JT_RBRACK || prevType == JT_GT)) space = true;
            if (Cur.type == JT_OP && strcmp(Cur.text, "...") == 0) space = false;
        }
        if (space) vsPut(Paren, ' ');
        if (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0) { /* varargs ... */
            vsCat(Paren, ".");
            prevType = JT_OP;
            next();
            continue;
        }
        vsCat(Paren, Cur.text);
        prevType = Cur.type;
        next();
        if (depth == 0) break;
    }
    /* collapse "..." spacing */
}

static unsigned long skipBlock(void) {
    int depth = 0; unsigned long end = Cur.line;
    do { if (Cur.type == JT_LBRACE) depth++; else if (Cur.type == JT_RBRACE) { depth--; end = Cur.line; } else if (Cur.type == JT_EOF) break; next(); } while (depth > 0);
    return end;
}
static void skipAngle(void) { int depth = 0; do { if (Cur.type == JT_LT) depth++; else if (Cur.type == JT_GT) depth--; else if (Cur.type == JT_OP && strcmp(Cur.text, ">>") == 0) depth -= 2; else if (Cur.type == JT_EOF || Cur.type == JT_SEMI || Cur.type == JT_LBRACE) return; next(); } while (depth > 0); }

static bool isTypeKw(const char *w) {
    static const char *kws[] = { "class", "interface", "enum", "record", "struct", "delegate", "namespace", NULL };
    for (int i = 0; kws[i]; i++) if (strcmp(w, kws[i]) == 0) return true; return false;
}
static bool isModifier(const char *w) {
    static const char *kws[] = { "public", "private", "protected", "static", "final", "abstract", "native", "synchronized", "transient", "volatile", "strictfp", "default", "sealed", "non-sealed",
        "internal", "readonly", "virtual", "override", "unsafe", "extern", "partial", "new", "const", "async", "event", "ref", "out", "in", "params", NULL };
    for (int i = 0; kws[i]; i++) if (strcmp(w, kws[i]) == 0) return true; return false;
}

typedef struct { int cork; int kind; char *name; } jscope;
static jscope Stack[128]; static int Top = 0;
static int scopeCork(void) { return Top ? Stack[Top-1].cork : CORK_NIL; }
static int scopeKind(void) { return Top ? Stack[Top-1].kind : -1; }

static int makeJTag(const char *name, int kind, unsigned long line, const char *access, const char *impl, const char *inherits, const char *sig) {
    tagEntryInfo e; initTagEntry(&e, name, kind);
    e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
    e.ext.scopeIndex = scopeCork();
    if (access) e.ext.access = (char *)access;
    if (impl) e.ext.implementation = (char *)impl;
    if (inherits && *inherits) e.ext.inherits = (char *)inherits;
    if (sig) e.ext.signature = (char *)sig;
    return makeTagEntry(&e);
}

static void parseBody(int cork, int kind);

static void skipAnnotation(void) {
    /* @Name or @Name(...) ; but "@interface" is a type */
    next();
    if (Cur.type == JT_IDENT && !curIs("interface")) {
        next();
        while (Cur.type == JT_OP && strcmp(Cur.text, ".") == 0) { next(); if (Cur.type == JT_IDENT) next(); }
        if (Cur.type == JT_LPAREN) { int d = 0; do { if (Cur.type == JT_LPAREN) d++; else if (Cur.type == JT_RPAREN) d--; else if (Cur.type == JT_EOF) return; next(); } while (d > 0); }
    }
}

/* parse a type declaration: Cur at class/interface/enum/record/struct keyword */
static void parseTypeDecl(const char *access, const char *impl, bool isAnnotation) {
    char *kw = xstrdup(Cur.text);
    int kind = isAnnotation ? K_a : strcmp(kw, "interface") == 0 ? K_i : strcmp(kw, "enum") == 0 ? K_g : (IsCSharp && strcmp(kw, "struct") == 0) ? K_d_struct : (IsCSharp && strcmp(kw, "namespace") == 0) ? K_s_ns : K_c;
    next();
    if (Cur.type != JT_IDENT) { free(kw); return; }
    vString *name = vsNewInit(Cur.text);
