        case '=': { int n = getcFromInputFile(); if (n == '>') { vsPut(v, n); t->type = T_ARROW; } else if (n == '=') { vsPut(v, n); int m = getcFromInputFile(); if (m == '=') vsPut(v, m); else ungetcToInputFile(m); t->type = T_OP; } else { ungetcToInputFile(n); t->type = T_EQ; } break; }
        default: {
            int n = getcFromInputFile();
            if (n != EOF && strchr("=&|+-<>*", n) && strchr("=!<>+-*/%&|^", c)) { vsPut(v, n); int m = getcFromInputFile(); if (m == '=' || (m == '>' && c == '>' && n == '>')) vsPut(v, m); else ungetcToInputFile(m); }
            else ungetcToInputFile(n);
            t->type = T_OP;
        }
        }
    }
    t->text = vsDetach(v);
}
static void next(void) { PrevType = Cur.type; if (HaveLook) { free(Cur.text); Cur = Look; Look.text = NULL; HaveLook = false; } else readRaw(&Cur); }
static jst *peek(void) { if (!HaveLook) { int saved = PrevType; PrevType = Cur.type; readRaw(&Look); PrevType = saved; HaveLook = true; } return &Look; }
static bool curIs(const char *s) { return Cur.text && strcmp(Cur.text, s) == 0; }

typedef struct { int cork; int kind; } jscope;
static jscope Stack[128]; static int Top = 0;
static int scopeCork(void) { return Top ? Stack[Top-1].cork : CORK_NIL; }
static int scopeKind(void) { return Top ? Stack[Top-1].kind : -1; }
static void push(int cork, int kind) { if (Top < 128) { Stack[Top].cork = cork; Stack[Top].kind = kind; Top++; } }
static void pop(void) { if (Top) Top--; }

static vString *Sig = NULL;
static void readParenGroup(vString *out) {
    vsClear(out);
    int depth = 0; int prev = -1;
    for (;;) {
        if (Cur.type == T_EOF) break;
        if (Cur.type == T_LPAREN) depth++;
        if (Cur.type == T_RPAREN) depth--;
        if (prev != -1) {
            bool space = false;
            if (prev == T_COMMA) space = true;
            if ((prev == T_IDENT || prev == T_KW || prev == T_NUM || prev == T_STRING || prev == T_RBRACK || prev == T_RBRACE || prev == T_RPAREN) && (Cur.type == T_IDENT || Cur.type == T_KW || Cur.type == T_NUM || Cur.type == T_STRING)) space = true;
            if (Cur.type == T_EQ || Cur.type == T_ARROW || Cur.type == T_OP) space = true;
            if (prev == T_EQ || prev == T_ARROW || prev == T_OP) space = true;
            if (prev == T_COLON) space = true;
            if (IsTS && prev == T_IDENT && Cur.type == T_COLON) space = false;
            if (Cur.type == T_LPAREN && prev == T_COLON) space = true;
            if (space) vsPut(out, ' ');
        }
        vsCat(out, Cur.text);
        prev = Cur.type;
        next();
        if (depth == 0) break;
    }
}

static int makeTag(const char *name, int kind, unsigned long line, const char *sig, const char *inherits, int scope, const char *props) {
    tagEntryInfo e; initTagEntry(&e, name, kind);
    e.lineNumber = line; e.filePosition = (long)getInputLineStart(line);
    e.ext.scopeIndex = scope;
    if (sig) e.ext.signature = (char *)sig;
    if (inherits && *inherits) e.ext.inherits = (char *)inherits;
    if (props && *props && F_properties >= 0) attachParserField(&e, F_properties, props);
    return makeTagEntry(&e);
}

static void parseBlock(void);            /* Cur at '{', ends after '}' */
static void parseStatement(void);
static void parseClassBody(int cork);
static bool parseObjectLiteral(int parentCork, const char *parentName, unsigned long parentLine, int *corkOut, bool parentIsVar);
static void skipExpression(bool stopAtComma);

/* function expression at 'function' keyword: makes tag with given name (or anonymous skip) */
static void parseFunctionBody(int cork) {
    if (Cur.type == T_LBRACE) {
        push(cork, K_f);
        parseBlock();
        pop();
        /* Cur is after '}' */
    }
}

static unsigned long LastRBraceLine = 0;

static void parseBlock(void) {
    if (Cur.type != T_LBRACE) return;
    next();
    while (Cur.type != T_RBRACE && Cur.type != T_EOF) parseStatement();
    LastRBraceLine = Cur.line;
    if (Cur.type == T_RBRACE) next();
}

/* skip TS type annotation after ':' (simplified): reads until , ) = { ; => at depth 0 */
static void skipTypeAnnotation(void) {
    int depth = 0;
    for (;;) {
        if (Cur.type == T_EOF) return;
        if (depth == 0 && (Cur.type == T_COMMA || Cur.type == T_RPAREN || Cur.type == T_EQ || Cur.type == T_SEMI || Cur.type == T_ARROW)) return;
        if (depth == 0 && Cur.type == T_LBRACE && PrevType != T_COLON && PrevType != T_OP) return;
        if (depth == 0 && Cur.type == T_RBRACE) return;
        if (Cur.type == T_LPAREN || Cur.type == T_LBRACK || Cur.type == T_LBRACE) depth++;
        if (Cur.type == T_RPAREN || Cur.type == T_RBRACK || Cur.type == T_RBRACE) depth--;
        if (Cur.type == T_OP && strcmp(Cur.text, "<") == 0) depth++;
        if (Cur.type == T_OP && strcmp(Cur.text, ">") == 0) depth--;
        next();
    }
}

/* parse "function [*] [name] (params) { body }" with Cur at 'function'. nameOverride used for assignments. */
static int parseFunction(const char *nameOverride, unsigned long line, int scope, bool isAsync, const char *props) {
    bool gen = false;
    next();
    if (Cur.type == T_OP && strcmp(Cur.text, "*") == 0) { gen = true; next(); }
    char *name = NULL;
    if (Cur.type == T_IDENT || (Cur.type == T_KW && Cur.type != T_LPAREN && !curIs("function"))) { if (Cur.type == T_IDENT) { name = xstrdup(Cur.text); line = Cur.line; next(); } }
    if (IsTS && Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
    vsClear(Sig);
    if (Cur.type == T_LPAREN) readParenGroup(Sig);
    if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
    const char *tagName = nameOverride ? nameOverride : name;
    int cork = CORK_NIL;
    if (tagName) {
        int kind = gen ? K_g : K_f;
        if (scopeKind() == K_c && !nameOverride) kind = K_m;
        cork = makeTag(tagName, kind, line, vsValue(Sig), NULL, scope, props);
    } else if (K_f >= 0 && Cur.type == T_LBRACE) {
        /* anonymous function: ctags makes anonymous tag? JavaScript does make __anon tags for anonymous functions */
        vString *an = vsNew(); anonGenerate(an, "__anon", K_f);
        tagEntryInfo e; initTagEntry(&e, vsValue(an), K_f); e.lineNumber = line; e.filePosition = (long)getInputLineStart(line); e.ext.scopeIndex = scope; e.ext.signature = vsValue(Sig); markTagExtraBit(&e, XTAG_ANONYMOUS);
        cork = makeTagEntry(&e); vsDelete(an);
    }
    if (Cur.type == T_LBRACE) { push(cork, K_f); parseBlock(); pop(); if (cork) setTagEndLineToCorkEntry(cork, LastRBraceLine); }
    (void)isAsync;
    free(name);
    return cork;
}

/* arrow function: Cur at '(' or ident ; returns true if it was an arrow function (consumed) */
static bool tryArrowFunction(const char *name, unsigned long line, int scope, const char *props) {
    /* lookahead limited: if Cur is IDENT and peek is ARROW */
    if ((Cur.type == T_IDENT || Cur.type == T_KW) && peek()->type == T_ARROW) {
        vsClear(Sig); vsPut(Sig, '('); vsCat(Sig, Cur.text); vsPut(Sig, ')');
        next(); next();
        int cork = CORK_NIL;
        if (name) cork = makeTag(name, K_f, line, vsValue(Sig), NULL, scope, props);
        if (Cur.type == T_LBRACE) { push(cork, K_f); parseBlock(); pop(); if (cork) setTagEndLineToCorkEntry(cork, LastRBraceLine); }
        else skipExpression(true);
        return true;
    }
    if (Cur.type == T_LPAREN) {
        /* need to find matching ')' and check for '=>' : collect paren group then check */
        vString *tmp = vsNew();
        readParenGroup(tmp);
        if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
        if (Cur.type == T_ARROW) {
            next();
            int cork = CORK_NIL;
            if (name) cork = makeTag(name, K_f, line, vsValue(tmp), NULL, scope, props);
            if (Cur.type == T_LBRACE) { push(cork, K_f); parseBlock(); pop(); if (cork) setTagEndLineToCorkEntry(cork, LastRBraceLine); }
            else skipExpression(true);
            vsDelete(tmp);
            return true;
        }
        /* not arrow: it was a parenthesized expression; continue skipping */
        vsDelete(tmp);
        skipExpression(true);
        return true;
    }
    return false;
}

/* skip an expression until ';' or ',' (if stopAtComma) or '}' at depth 0 or newline-terminated statement */
static void skipExpression(bool stopAtComma) {
    int depth = 0;
    for (;;) {
        if (Cur.type == T_EOF) return;
        if (depth == 0 && (Cur.type == T_SEMI || Cur.type == T_RBRACE || Cur.type == T_RPAREN || Cur.type == T_RBRACK)) return;
        if (depth == 0 && stopAtComma && Cur.type == T_COMMA) return;
        if (Cur.type == T_KW && curIs("function")) { parseFunction(NULL, Cur.line, scopeCork(), false, NULL); continue; }
        if (Cur.type == T_KW && curIs("class")) { parseStatement(); continue; }
        if (Cur.type == T_LBRACE) {
            /* object literal or block */
            int d = 0;
            do { if (Cur.type == T_LBRACE) d++; else if (Cur.type == T_RBRACE) d--; else if (Cur.type == T_EOF) return; else if (Cur.type == T_KW && curIs("function")) { parseFunction(NULL, Cur.line, scopeCork(), false, NULL); continue; } next(); } while (d > 0);
            continue;
        }
        if (Cur.type == T_LPAREN || Cur.type == T_LBRACK) depth++;
        if (Cur.type == T_RPAREN || Cur.type == T_RBRACK) depth--;
        if (depth == 0 && (Cur.type == T_IDENT || Cur.type == T_KW) && peek()->type == T_ARROW) { tryArrowFunction(NULL, Cur.line, scopeCork(), NULL); continue; }
        if (depth == 0 && Cur.type == T_LPAREN) { if (tryArrowFunction(NULL, Cur.line, scopeCork(), NULL)) continue; }
        next();
    }
}

/* object literal: Cur at '{'. Creates property/method tags under parent. Returns true if methods found */
static bool parseObjectLiteral(int parentCork, const char *parentName, unsigned long parentLine, int *corkOut, bool parentIsVar) {
    (void)parentName; (void)parentLine; (void)parentIsVar;
    bool hasMethods = false;
    next(); /* { */
    while (Cur.type != T_RBRACE && Cur.type != T_EOF) {
        if (Cur.type == T_COMMA) { next(); continue; }
        if (Cur.type == T_OP && strcmp(Cur.text, "...") == 0) { next(); skipExpression(true); continue; }
        /* key */
        char *key = NULL; unsigned long line = Cur.line;
        bool isGet = false, isSet = false, isAsync = false, isGen = false;
        if ((Cur.type == T_KW) && (curIs("get") || curIs("set") || curIs("async")) && peek()->type != T_COLON && peek()->type != T_LPAREN && peek()->type != T_COMMA && peek()->type != T_RBRACE) { if (curIs("get")) isGet = true; else if (curIs("set")) isSet = true; else isAsync = true; next(); }
        if (Cur.type == T_OP && strcmp(Cur.text, "*") == 0) { isGen = true; next(); }
        if (Cur.type == T_IDENT || Cur.type == T_KW || Cur.type == T_NUM) { key = xstrdup(Cur.text); line = Cur.line; next(); }
        else if (Cur.type == T_STRING) { size_t n = strlen(Cur.text); key = xstrndup(Cur.text + 1, n >= 2 ? n - 2 : 0); line = Cur.line; next(); }
        else if (Cur.type == T_LBRACK) { int d = 0; do { if (Cur.type == T_LBRACK) d++; else if (Cur.type == T_RBRACK) d--; next(); } while (d > 0 && Cur.type != T_EOF); }
        else { next(); continue; }
        if (Cur.type == T_LPAREN) {
            /* method shorthand */
            vsClear(Sig); readParenGroup(Sig);
            if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
            int kind = isGet ? K_G : isSet ? K_S : isGen ? K_g : K_m;
            int c = key ? makeTag(key, kind, line, vsValue(Sig), NULL, parentCork, NULL) : CORK_NIL;
            hasMethods = true;
            if (Cur.type == T_LBRACE) { push(c, K_c); parseBlock(); pop(); if (c) setTagEndLineToCorkEntry(c, LastRBraceLine); }
        } else if (Cur.type == T_COLON) {
            next();
            if (Cur.type == T_KW && curIs("function")) {
                /* method */
                unsigned long l = line;
                next();
                if (Cur.type == T_OP && strcmp(Cur.text, "*") == 0) next();
                if (Cur.type == T_IDENT) next();
                vsClear(Sig); if (Cur.type == T_LPAREN) readParenGroup(Sig);
                int c = key ? makeTag(key, K_m, l, vsValue(Sig), NULL, parentCork, NULL) : CORK_NIL;
                hasMethods = true;
                if (Cur.type == T_LBRACE) { push(c, K_c); parseBlock(); pop(); if (c) setTagEndLineToCorkEntry(c, LastRBraceLine); }
            } else if (Cur.type == T_KW && curIs("async") && (peek()->type == T_LPAREN || peek()->type == T_IDENT)) {
                next();
                if (key) { if (tryArrowFunction(key, line, parentCork, NULL)) hasMethods = true; }
            } else if (Cur.type == T_LBRACE) {
                /* nested object */
                int c = key ? makeTag(key, K_p, line, NULL, NULL, parentCork, NULL) : CORK_NIL;
                int dummy;
                parseObjectLiteral(c, key, line, &dummy, false);
                if (c) setTagEndLineToCorkEntry(c, LastRBraceLine);
            } else if ((Cur.type == T_LPAREN || ((Cur.type == T_IDENT || Cur.type == T_KW) && peek()->type == T_ARROW))) {
                /* maybe arrow function */
                if (Cur.type == T_LPAREN) {
                    vString *tmp = vsNew(); readParenGroup(tmp);
                    if (Cur.type == T_ARROW) {
                        next();
                        int c = key ? makeTag(key, K_m, line, vsValue(tmp), NULL, parentCork, NULL) : CORK_NIL;
                        hasMethods = true;
                        if (Cur.type == T_LBRACE) { push(c, K_c); parseBlock(); pop(); if (c) setTagEndLineToCorkEntry(c, LastRBraceLine); } else skipExpression(true);
                    } else { if (key) makeTag(key, K_p, line, NULL, NULL, parentCork, NULL); skipExpression(true); }
                    vsDelete(tmp);
                } else {
                    vsClear(Sig); vsPut(Sig, '('); vsCat(Sig, Cur.text); vsPut(Sig, ')'); next(); next();
                    int c = key ? makeTag(key, K_m, line, vsValue(Sig), NULL, parentCork, NULL) : CORK_NIL;
                    hasMethods = true;
                    if (Cur.type == T_LBRACE) { push(c, K_c); parseBlock(); pop(); if (c) setTagEndLineToCorkEntry(c, LastRBraceLine); } else skipExpression(true);
                }
            } else {
                if (key) makeTag(key, K_p, line, NULL, NULL, parentCork, NULL);
                skipExpression(true);
            }
        } else {
            /* shorthand property { a, b } */
            if (key && (Cur.type == T_COMMA || Cur.type == T_RBRACE)) makeTag(key, K_p, line, NULL, NULL, parentCork, NULL);
            else skipExpression(true);
        }
        free(key);
    }
    LastRBraceLine = Cur.line;
    if (Cur.type == T_RBRACE) next();
    if (corkOut) *corkOut = parentCork;
    return hasMethods;
}

static void parseClassBody(int cork) {
    /* Cur at '{' */
    next();
    while (Cur.type != T_RBRACE && Cur.type != T_EOF) {
        if (Cur.type == T_SEMI) { next(); continue; }
        bool isStatic = false, isGet = false, isSet = false, isGen = false, isAsync = false;
        /* decorators */
        while (Cur.type == T_IDENT && Cur.text[0] == '@') { next(); if (Cur.type == T_LPAREN) { vString *t = vsNew(); readParenGroup(t); vsDelete(t); } }
        for (;;) {
            if (Cur.type == T_KW && curIs("static") && peek()->type != T_LPAREN && peek()->type != T_EQ) { isStatic = true; next(); continue; }
            if (IsTS && Cur.type == T_IDENT && (curIs("public") || curIs("private") || curIs("protected") || curIs("readonly") || curIs("declare") || curIs("abstract") || curIs("override")) && peek()->type != T_LPAREN && peek()->type != T_EQ && peek()->type != T_COLON) { next(); continue; }
            if (Cur.type == T_KW && curIs("async") && peek()->type != T_LPAREN && peek()->type != T_EQ) { isAsync = true; next(); continue; }
            if (Cur.type == T_KW && (curIs("get") || curIs("set")) && peek()->type != T_LPAREN && peek()->type != T_EQ && peek()->type != T_SEMI) { if (curIs("get")) isGet = true; else isSet = true; next(); continue; }
            if (Cur.type == T_OP && strcmp(Cur.text, "*") == 0) { isGen = true; next(); continue; }
            break;
        }
        if (isStatic && Cur.type == T_LBRACE) { parseBlock(); continue; }   /* static init block */
        char *name = NULL; unsigned long line = Cur.line;
        if (Cur.type == T_IDENT || Cur.type == T_KW || Cur.type == T_NUM) { name = xstrdup(Cur.text); next(); }
        else if (Cur.type == T_STRING) { size_t n = strlen(Cur.text); name = xstrndup(Cur.text + 1, n >= 2 ? n - 2 : 0); next(); }
        else if (Cur.type == T_LBRACK) { int d = 0; do { if (Cur.type == T_LBRACK) d++; else if (Cur.type == T_RBRACK) d--; next(); } while (d > 0 && Cur.type != T_EOF); }
        else { next(); continue; }
        if (IsTS && (Cur.type == T_QUESTION || (Cur.type == T_OP && strcmp(Cur.text, "!") == 0))) next();
        if (IsTS && Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
        const char *props = isStatic ? "static" : NULL;
        if (Cur.type == T_LPAREN) {
            vsClear(Sig); readParenGroup(Sig);
            if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
            int kind = isGet ? K_G : isSet ? K_S : isGen ? K_g : K_m;
            int c = name ? makeTag(name, kind, line, vsValue(Sig), NULL, cork, props) : CORK_NIL;
            if (Cur.type == T_LBRACE) { push(c, K_c); parseBlock(); pop(); if (c) setTagEndLineToCorkEntry(c, LastRBraceLine); }
            else if (Cur.type == T_SEMI) next();
        } else {
            /* field */
            if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
            if (Cur.type == T_EQ) {
                next();
                if (Cur.type == T_KW && curIs("function")) { int c = parseFunction(name, line, cork, false, props); (void)c; }
                else if (Cur.type == T_KW && curIs("async")) { next(); if (!tryArrowFunction(name, line, cork, props)) skipExpression(false); }
                else if (!tryArrowFunction(name, line, cork, props)) { if (name) makeTag(name, K_M, line, NULL, NULL, cork, props); skipExpression(false); }
            } else if (name) makeTag(name, K_M, line, NULL, NULL, cork, props);
            if (Cur.type == T_SEMI) next();
        }
        free(name);
        (void)isAsync;
    }
    LastRBraceLine = Cur.line;
    if (Cur.type == T_RBRACE) next();
}

/* class declaration at 'class' */
static void parseClass(const char *nameOverride, unsigned long line0, int scope) {
    next();
    char *name = NULL; unsigned long line = line0;
    if (Cur.type == T_IDENT) { name = xstrdup(Cur.text); line = Cur.line; next(); }
    if (IsTS && Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
    vString *inh = vsNew();
    if (Cur.type == T_KW && curIs("extends")) {
        next();
        while (Cur.type != T_LBRACE && Cur.type != T_EOF && !(Cur.type == T_IDENT && curIs("implements"))) { if (Cur.type == T_IDENT || Cur.type == T_KW || Cur.type == T_DOT) vsCat(inh, Cur.text); next(); if (Cur.type == T_LPAREN) { vString *t = vsNew(); readParenGroup(t); vsDelete(t); } }
    }
    if (IsTS && Cur.type == T_IDENT && curIs("implements")) { while (Cur.type != T_LBRACE && Cur.type != T_EOF) next(); }
    const char *tn = nameOverride ? nameOverride : name;
    int cork = CORK_NIL;
    if (tn) cork = makeTag(tn, K_c, line, NULL, vsValue(inh), scope, NULL);
    else if (K_c >= 0) { vString *an = vsNew(); anonGenerate(an, "__anon", K_c); tagEntryInfo e; initTagEntry(&e, vsValue(an), K_c); e.lineNumber = line; e.filePosition = (long)getInputLineStart(line); e.ext.scopeIndex = scope; if (vsLength(inh)) e.ext.inherits = vsValue(inh); markTagExtraBit(&e, XTAG_ANONYMOUS); cork = makeTagEntry(&e); vsDelete(an); }
    if (Cur.type == T_LBRACE) { push(cork, K_c); parseClassBody(cork); pop(); if (cork) setTagEndLineToCorkEntry(cork, LastRBraceLine); }
    free(name); vsDelete(inh);
}

/* assignment: NAME [.prop ...] = value ; Cur at first ident. Returns true if handled */
static void parseAssignmentOrExpression(void) {
    /* collect dotted chain */
    strArray *chain = saNew();
    unsigned long line = Cur.line;
    saAdd(chain, Cur.text); next();
    while (Cur.type == T_DOT && (peek()->type == T_IDENT || peek()->type == T_KW)) { next(); saAdd(chain, Cur.text); next(); }
    if (Cur.type == T_EQ) {
        next();
        /* determine target */
        size_t n = saCount(chain);
        const char *last = saItem(chain, n - 1);
        int scope = scopeCork();
        int targetScope = scope;
        bool isProto = false;
        if (n >= 2) {
            /* X.prototype.m or X.m or a.b.c */
            const char *base = saItem(chain, 0);
            size_t baseLen = n - 1;
            if (n >= 3 && strcmp(saItem(chain, n - 2), "prototype") == 0) { isProto = true; baseLen = n - 2; }
            /* find or create class tag for base chain */
            vString *bn = vsNew();
            for (size_t i = 0; i < baseLen; i++) { if (i) vsPut(bn, '.'); vsCat(bn, saItem(chain, i)); }
            (void)base;
            /* look up existing */
            int found = CORK_NIL;
            int cnt = countEntryInCorkQueue();
            for (int i = cnt - 1; i >= 1; i--) { tagEntryInfo *e = getEntryInCorkQueue(i); if (e && e->name && strcmp(e->name, saItem(chain, baseLen - 1)) == 0 && (e->kindIndex == K_c || e->kindIndex == K_f || e->kindIndex == K_v || e->kindIndex == K_C || e->kindIndex == K_p)) { found = i; break; } }
            if (found == CORK_NIL) {
                tagEntryInfo e; initTagEntry(&e, vsValue(bn), K_c); e.placeholder = true; e.ext.scopeIndex = CORK_NIL; found = makeTagEntry(&e);
            }
            targetScope = found;
            vsDelete(bn);
            if (strcmp(last, "prototype") == 0 && Cur.type == T_LBRACE) { int d; parseObjectLiteral(found, last, line, &d, false); saDelete(chain); if (Cur.type == T_SEMI) next(); return; }
        }
        if (Cur.type == T_KW && curIs("function")) { const char *props = NULL; int c = parseFunction(last, line, targetScope, false, props); if (n >= 2 && c) { tagEntryInfo *e = getEntryInCorkQueue(c); if (e) e->kindIndex = K_m; } }
        else if (Cur.type == T_KW && curIs("async") && (peek()->type == T_LPAREN || peek()->type == T_IDENT || (peek()->type == T_KW && strcmp(peek()->text, "function") == 0))) { next(); if (Cur.type == T_KW && curIs("function")) parseFunction(last, line, targetScope, true, NULL); else if (!tryArrowFunction(last, line, targetScope, NULL)) skipExpression(false); }
        else if (Cur.type == T_KW && curIs("class")) parseClass(last, line, targetScope);
        else if (Cur.type == T_LBRACE) {
            int c = (n >= 2) ? makeTag(last, K_p, line, NULL, NULL, targetScope, NULL) : CORK_NIL;
            if (n == 1 && scopeKind() == -1) {
                /* top-level object assigned to undeclared name: treat as variable/class */
                c = makeTag(last, K_v, line, NULL, NULL, scope, NULL);
            }
            int d; bool hm = parseObjectLiteral(c, last, line, &d, true);
            if (c) { tagEntryInfo *e = getEntryInCorkQueue(c); if (e && hm && e->kindIndex == K_v) e->kindIndex = K_c; setTagEndLineToCorkEntry(c, LastRBraceLine); }
        }
        else if (tryArrowFunction(n >= 2 ? last : (scopeKind() == -1 ? last : NULL), line, targetScope, NULL)) { if (n >= 2) { int cnt = countEntryInCorkQueue(); tagEntryInfo *e = getEntryInCorkQueue(cnt - 1); if (e && e->kindIndex == K_f && strcmp(e->name, last) == 0) e->kindIndex = K_m; } }
        else {
            if (n >= 2 && !isProto) makeTag(last, K_p, line, NULL, NULL, targetScope, NULL);
            else if (n == 1 && scopeKind() == -1 && Top == 0) { /* implicit global */ }
            skipExpression(false);
        }
    } else skipExpression(false);
