}

static void parseVarDecl(int kind) {
    /* Cur after var/let/const */
    for (;;) {
        if (Cur.type == T_LBRACE || Cur.type == T_LBRACK) { skipExpression(true); }
        if (Cur.type != T_IDENT && Cur.type != T_KW) break;
        char *name = xstrdup(Cur.text); unsigned long line = Cur.line;
        next();
        int scope = scopeCork();
        bool inFunc = (scopeKind() == K_f || scopeKind() == K_m || scopeKind() == K_g || scopeKind() == K_G || scopeKind() == K_S);
        if (IsTS && (Cur.type == T_OP && strcmp(Cur.text, "!") == 0)) next();
        if (IsTS && Cur.type == T_COLON) { next(); skipTypeAnnotation(); }
        if (Cur.type == T_EQ) {
            next();
            if (Cur.type == T_KW && curIs("function")) { if (inFunc) parseFunction(NULL, line, scope, false, NULL), (void)0; else parseFunction(name, line, scope, false, NULL); }
            else if (Cur.type == T_KW && curIs("async") && (peek()->type == T_LPAREN || peek()->type == T_IDENT || (peek()->type == T_KW && strcmp(peek()->text, "function") == 0))) { next(); if (Cur.type == T_KW && curIs("function")) parseFunction(inFunc ? NULL : name, line, scope, true, NULL); else if (!tryArrowFunction(inFunc ? NULL : name, line, scope, NULL)) skipExpression(true); }
            else if (Cur.type == T_KW && curIs("class")) parseClass(inFunc ? NULL : name, line, scope);
            else if (Cur.type == T_LBRACE) {
                int c = inFunc ? CORK_NIL : makeTag(name, kind, line, NULL, NULL, scope, NULL);
                int d; bool hm = parseObjectLiteral(c, name, line, &d, true);
                if (c) { tagEntryInfo *e = getEntryInCorkQueue(c); if (e && hm) e->kindIndex = K_c; setTagEndLineToCorkEntry(c, LastRBraceLine); }
            }
            else if (tryArrowFunction(inFunc ? NULL : name, line, scope, NULL)) { }
            else { if (!inFunc) makeTag(name, kind, line, NULL, NULL, scope, NULL); skipExpression(true); }
        } else {
            if (!inFunc) makeTag(name, kind, line, NULL, NULL, scope, NULL);
        }
        free(name);
        if (Cur.type == T_COMMA) { next(); continue; }
        break;
    }
    if (Cur.type == T_SEMI) next();
}

static void parseStatement(void) {
    if (Cur.type == T_EOF) return;
    if (Cur.type == T_SEMI) { next(); return; }
    if (Cur.type == T_LBRACE) { parseBlock(); return; }
    if (Cur.type == T_KW) {
        if (curIs("function")) { parseFunction(NULL, Cur.line, scopeCork(), false, NULL); return; }
        if (curIs("async") && peek()->type == T_KW && strcmp(peek()->text, "function") == 0) { next(); parseFunction(NULL, Cur.line, scopeCork(), true, NULL); return; }
        if (curIs("class")) { parseClass(NULL, Cur.line, scopeCork()); return; }
        if (curIs("var") || curIs("let") || curIs("const")) { int kind = curIs("const") ? K_C : K_v; next(); parseVarDecl(kind); return; }
        if (curIs("export")) { next(); if (Cur.type == T_KW && curIs("default")) next(); return; }
        if (curIs("import")) { while (Cur.type != T_SEMI && Cur.type != T_EOF && !(Cur.nlBefore && Cur.type != T_KW && Cur.type != T_LBRACE)) { next(); if (Cur.type == T_STRING) { next(); break; } } if (Cur.type == T_SEMI) next(); return; }
        if (curIs("return") || curIs("throw") || curIs("yield") || curIs("await") || curIs("delete") || curIs("typeof") || curIs("void") || curIs("new")) { next(); skipExpression(false); if (Cur.type == T_SEMI) next(); return; }
        if (curIs("if") || curIs("while") || curIs("for") || curIs("switch") || curIs("with") || curIs("catch")) { next(); if (Cur.type == T_LPAREN) { int d = 0; do { if (Cur.type == T_LPAREN) d++; else if (Cur.type == T_RPAREN) d--; else if (Cur.type == T_KW && curIs("function")) { parseFunction(NULL, Cur.line, scopeCork(), false, NULL); continue; } next(); } while (d > 0 && Cur.type != T_EOF); } return; }
        if (curIs("else") || curIs("do") || curIs("try") || curIs("finally") || curIs("default")) { next(); if (Cur.type == T_COLON) next(); return; }
        if (curIs("case")) { next(); skipExpression(false); if (Cur.type == T_COLON) next(); return; }
        if (curIs("break") || curIs("continue") || curIs("debugger")) { next(); if (Cur.type == T_IDENT) next(); if (Cur.type == T_SEMI) next(); return; }
        next(); skipExpression(false); if (Cur.type == T_SEMI) next(); return;
    }
    if (IsTS && Cur.type == T_IDENT && (curIs("interface") || curIs("type") || curIs("enum") || curIs("namespace") || curIs("module") || curIs("declare") || curIs("abstract"))) {
        extern void tsParseDeclaration(void);
        tsParseDeclaration();
        return;
    }
    if (Cur.type == T_IDENT) {
        /* label? */
        if (peek()->type == T_COLON) { next(); next(); return; }
        parseAssignmentOrExpression();
        return;
    }
    skipExpression(false);
    if (Cur.type == T_SEMI) next(); else if (Cur.type == T_RBRACE) { } else next();
}

/* TypeScript declarations */
static int K_i_ts, K_e_ts, K_a_ts, K_n_ts, K_l_ts, K_z_ts, K_t_ts, K_p_ts_prop, K_m_ts, K_G_ts, K_S_ts, K_M_ts;
void tsParseDeclaration(void) {
    if (curIs("declare") || curIs("abstract")) { next(); if (Cur.type == T_KW) { parseStatement(); return; } if (!(Cur.type == T_IDENT)) return; }
    if (curIs("interface")) {
        next();
        if (Cur.type != T_IDENT) return;
        char *name = xstrdup(Cur.text); unsigned long line = Cur.line; next();
        if (Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
        vString *inh = vsNew();
        if (Cur.type == T_KW && curIs("extends")) { next(); while (Cur.type != T_LBRACE && Cur.type != T_EOF) { if (Cur.type == T_IDENT || Cur.type == T_DOT || Cur.type == T_COMMA) vsCat(inh, Cur.text); next(); } }
        int cork = makeTag(name, K_i_ts, line, NULL, vsValue(inh), scopeCork(), NULL);
        if (Cur.type == T_LBRACE) {
            next();
            while (Cur.type != T_RBRACE && Cur.type != T_EOF) {
                if (Cur.type == T_SEMI || Cur.type == T_COMMA) { next(); continue; }
                bool ro = false;
                if (Cur.type == T_IDENT && curIs("readonly") && peek()->type != T_COLON && peek()->type != T_QUESTION && peek()->type != T_LPAREN) { ro = true; next(); }
                (void)ro;
