                if (Cur.type == T_IDENT || Cur.type == T_KW) { mn = xstrdup(Cur.text); next(); }
                else if (Cur.type == T_STRING) { size_t n = strlen(Cur.text); mn = xstrndup(Cur.text + 1, n >= 2 ? n - 2 : 0); next(); }
                else if (Cur.type == T_LBRACK) { int d = 0; do { if (Cur.type == T_LBRACK) d++; else if (Cur.type == T_RBRACK) d--; next(); } while (d > 0 && Cur.type != T_EOF); if (Cur.type == T_COLON) { next(); skipTypeAnnotation(); } continue; }
                else if (Cur.type == T_LPAREN) { vString *t = vsNew(); readParenGroup(t); vsDelete(t); if (Cur.type == T_COLON) { next(); skipTypeAnnotation(); } continue; }
                else { next(); continue; }
                if (Cur.type == T_QUESTION) next();
                if (Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
                if (Cur.type == T_LPAREN) { vsClear(Sig); readParenGroup(Sig); if (Cur.type == T_COLON) { next(); skipTypeAnnotation(); } if (mn) makeTag(mn, K_m_ts, ml, vsValue(Sig), NULL, cork, NULL); }
                else { if (Cur.type == T_COLON) { next(); skipTypeAnnotation(); } if (mn) makeTag(mn, K_p_ts_prop, ml, NULL, NULL, cork, NULL); }
                free(mn);
            }
            setTagEndLineToCorkEntry(cork, Cur.line);
            next();
        }
        free(name); vsDelete(inh);
        return;
    }
    if (curIs("type")) {
        next();
        if (Cur.type != T_IDENT) return;
        makeTag(Cur.text, K_a_ts, Cur.line, NULL, NULL, scopeCork(), NULL);
        next();
        if (Cur.type == T_OP && strcmp(Cur.text, "<") == 0) skipTypeAnnotation();
        if (Cur.type == T_EQ) { next(); skipTypeAnnotation(); }
        while (Cur.type != T_SEMI && Cur.type != T_EOF && !Cur.nlBefore) next();
        if (Cur.type == T_SEMI) next();
        return;
    }
    if (curIs("enum") || (curIs("const") && peek()->type == T_IDENT && strcmp(peek()->text, "enum") == 0)) {
        if (curIs("const")) next();
        next();
        if (Cur.type != T_IDENT) return;
        int cork = makeTag(Cur.text, K_e_ts, Cur.line, NULL, NULL, scopeCork(), NULL);
        next();
        if (Cur.type == T_LBRACE) {
            next();
            while (Cur.type != T_RBRACE && Cur.type != T_EOF) {
                if (Cur.type == T_IDENT || Cur.type == T_KW) { makeTag(Cur.text, K_t_ts, Cur.line, NULL, NULL, cork, NULL); next(); }
                else if (Cur.type == T_STRING) { size_t n = strlen(Cur.text); char *mn = xstrndup(Cur.text + 1, n >= 2 ? n - 2 : 0); makeTag(mn, K_t_ts, Cur.line, NULL, NULL, cork, NULL); free(mn); next(); }
