                if (Cur.type == T_COMMA) next(); else if (Cur.type != T_RBRACE) next();
            }
            setTagEndLineToCorkEntry(cork, Cur.line);
            next();
        }
        return;
    }
    if (curIs("namespace") || curIs("module")) {
        next();
        if (Cur.type != T_IDENT && Cur.type != T_STRING) return;
        char *name = xstrdup(Cur.text); unsigned long line = Cur.line; next();
        while (Cur.type == T_DOT) { next(); if (Cur.type == T_IDENT) { char *nn = xmalloc(strlen(name) + strlen(Cur.text) + 2); sprintf(nn, "%s.%s", name, Cur.text); free(name); name = nn; next(); } }
        int cork = makeTag(name, K_n_ts, line, NULL, NULL, scopeCork(), NULL);
        if (Cur.type == T_LBRACE) { push(cork, K_n_ts); parseBlock(); pop(); setTagEndLineToCorkEntry(cork, LastRBraceLine); }
        free(name);
        return;
    }
    parseAssignmentOrExpression();
}

