/* JavaScript / TypeScript (simplified) parser */
#include "common.h"

typedef struct { int type; char *text; unsigned long line; bool nlBefore; } jst;
enum { T_EOF, T_IDENT, T_KW, T_STRING, T_NUM, T_TEMPLATE, T_REGEX, T_OP, T_LPAREN, T_RPAREN, T_LBRACE, T_RBRACE, T_LBRACK, T_RBRACK, T_SEMI, T_COMMA, T_DOT, T_COLON, T_ARROW, T_EQ, T_QUESTION };

static jst Cur, Look; static bool HaveLook = false;
