static const char *JsKws[] = { "function","var","let","const","class","extends","return","if","else","for","while","do","switch","case","break","continue","new","delete","typeof","instanceof","in","of","this","null","true","false","throw","try","catch","finally","void","yield","async","await","static","get","set","import","export","default","from","as","super","with","debugger","prototype", NULL };
