    }
}

static void readRaw(jst *t) {
    free(t->text); t->text = NULL;
    int c; bool nl = false;
    for (;;) {
        c = getcFromInputFile();
        if (c == '\n') { nl = true; continue; }
        if (c == ' ' || c == '\t' || c == '\r' || c == '\f') continue;
        if (c == '/') {
            int n = getcFromInputFile();
            if (n == '/') { while ((c = getcFromInputFile()) != EOF && c != '\n') ; nl = true; continue; }
            if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (c == '\n') nl = true; if (prev == '*' && c == '/') break; prev = c; } continue; }
            ungetcToInputFile(n);
        }
