    vString *v = vsNew();
    if (c == EOF) t->type = T_EOF;
    else if (pIsIdentStart(c) || c == '$' || c == '#' || c == '@') { while (pIsIdent(c) || c == '$' || c == '#' || c == '@') { vsPut(v, c); c = getcFromInputFile(); } ungetcToInputFile(c); t->type = isKw(vsValue(v)) ? T_KW : T_IDENT; }
