    else if (c == '"' || c == '\'') { int q = c; vsPut(v, c); while ((c = getcFromInputFile()) != EOF) { if (c == '\\') { vsPut(v, c); c = getcFromInputFile(); if (c == EOF) break; vsPut(v, c); continue; } vsPut(v, c); if (c == q || c == '\n') break; } t->type = T_STRING; }
