cd /workspace; cat > src/parsers/simple1.c <<'EOF'
/* A collection of simple line-oriented parsers */
#include "common.h"

/* ---------- Iniconf (+ SystemdUnit, YumRepo, DBusService, PythonLoggingConfig, PythonEntryPoints share it) ---------- */
static void parseIniconfLike(void) {
    int lang = getInputLanguage();
    int iniLang = getNamedLanguageFull("Iniconf", 0, true);
    int K_s = KIND(iniLang, 's'), K_k = KIND(iniLang, 'k');
    bool sub = (lang != iniLang);
    if (sub) setInputLanguage(iniLang);
    const unsigned char *line;
    vString *w = vsNew();
    int section = CORK_NIL;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        if (*p == '#' || *p == ';' || *p == '\0') continue;
        if (*p == '[') {
            const char *e = strchr(p, ']');
            if (e) { vsClear(w); vsCatN(w, p + 1, e - p - 1); if (vsLength(w)) section = simpleTag(vsValue(w), K_s, 0, CORK_NIL); }
            continue;
        }
        const char *q = p;
        while (*q && *q != '=' && *q != ':' && !isspace((unsigned char)*q)) q++;
        const char *r = skipSpaces(q);
        if ((*r == '=' || (*r == ':' && *q != ':')) && q > p) { vsClear(w); vsCatN(w, p, q - p); simpleTag(vsValue(w), K_k, 0, section); }
    }
    vsDelete(w);
    if (sub) setInputLanguage(lang);
}
parserDefinition IniconfParser = { "Iniconf", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };
parserDefinition SystemdUnitParser = { "SystemdUnit", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };
parserDefinition YumRepoParser = { "YumRepo", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };
parserDefinition DBusServiceParser = { "DBusService", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };
parserDefinition PythonLoggingConfigParser = { "PythonLoggingConfig", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };
parserDefinition PythonEntryPointsParser = { "PythonEntryPoints", parseIniconfLike, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Diff ---------- */
static void parseDiff(void) {
    int lang = getInputLanguage();
    int K_d = KIND(lang, 'd'), K_h = KIND(lang, 'h'), K_m = KIND(lang, 'm'), K_n = KIND(lang, 'n');
    const unsigned char *line;
    vString *old = vsNew(), *w = vsNew();
    int fileCork = CORK_NIL;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        if (strncmp(p, "--- ", 4) == 0) { vsClear(old); const char *q = p + 4; while (*q && *q != '\t') vsPut(old, *q++); continue; }
        if (strncmp(p, "+++ ", 4) == 0) {
            vsClear(w); const char *q = p + 4; while (*q && *q != '\t') vsPut(w, *q++);
            const char *name = vsValue(w);
            int kind = K_m;
            if (strcmp(name, "/dev/null") == 0) { kind = K_d; name = vsValue(old); }
            else if (strcmp(vsValue(old), "/dev/null") == 0) kind = K_n;
            if ((name[0] == 'a' || name[0] == 'b') && name[1] == '/') name += 2;
            if (*name) fileCork = simpleTag(name, kind, 0, CORK_NIL);
            continue;
        }
        if (strncmp(p, "@@", 2) == 0 && K_h >= 0) {
            const char *q = strstr(p + 2, "@@");
            if (q) { q += 2; while (*q == ' ') q++; if (*q) simpleTag(q, K_h, 0, fileCork); else simpleTag(p, K_h, 0, fileCork); }
            continue;
        }
    }
    vsDelete(old); vsDelete(w);
}
parserDefinition DiffParser = { "Diff", parseDiff, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- DosBatch ---------- */
static void parseDosBatch(void) {
    int lang = getInputLanguage();
    int K_l = KIND(lang, 'l'), K_v = KIND(lang, 'v'), K_b = KIND(lang, 'b');
    int R_call = ROLE(lang, K_b, "called");
    const unsigned char *line;
    vString *w = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        if (*p == ':' && p[1] != ':') { p++; vsClear(w); while (*p && !isspace((unsigned char)*p)) vsPut(w, *p++); if (vsLength(w)) simpleTag(vsValue(w), K_l, 0, CORK_NIL); continue; }
        if (strncasecmp(p, "rem", 3) == 0 && (isspace((unsigned char)p[3]) || p[3] == 0)) continue;
        if (*p == '@') p = skipSpaces(p + 1);
        if (strncasecmp(p, "set", 3) == 0 && isspace((unsigned char)p[3])) {
            p = skipSpaces(p + 3);
            if (*p == '/') { p++; while (*p && !isspace((unsigned char)*p)) p++; p = skipSpaces(p); }
            if (*p == '"') p++;
            vsClear(w); while (*p && *p != '=' && !isspace((unsigned char)*p)) vsPut(w, *p++);
            if (*p == '=' && vsLength(w)) simpleTag(vsValue(w), K_v, 0, CORK_NIL);
            continue;
        }
        if (strncasecmp(p, "call", 4) == 0 && isspace((unsigned char)p[4]) && K_b >= 0) {
            p = skipSpaces(p + 4);
            if (*p != ':' && *p != '%') { vsClear(w); while (*p && !isspace((unsigned char)*p)) vsPut(w, *p++); if (vsLength(w) && R_call >= 0) simpleRefTag(vsValue(w), K_b, R_call, 0, CORK_NIL); }
        }
    }
    vsDelete(w);
}
parserDefinition DosBatchParser = { "DosBatch", parseDosBatch, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Txt2tags ---------- */
static void parseTxt2tags(void) {
    int lang = getInputLanguage();
    int K_s = KIND(lang, 's');
    const unsigned char *line;
    vString *w = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        if (*p == '=' || *p == '+') {
            char ch = *p; int n = 0; while (p[n] == ch) n++;
            const char *e = p + strlen(p);
            while (e > p && isspace((unsigned char)e[-1])) e--;
            /* optional [label] */
            const char *lab = e;
            if (e > p && e[-1] == ']') { const char *b = e - 1; while (b > p && *b != '[') b--; if (*b == '[') { lab = b; e = b; while (e > p && isspace((unsigned char)e[-1])) e--; } }
            (void)lab;
            int m = 0; while (e > p && e[-1] == ch) { e--; m++; }
            if (m == n && n >= 1 && n <= 5 && e > p + n) { vsClear(w); vsCatN(w, p + n, e - p - n); vsStripLeading(w); vsStripTrailing(w); if (vsLength(w)) simpleTag(vsValue(w), K_s, 0, CORK_NIL); }
        }
    }
    vsDelete(w);
}
parserDefinition Txt2tagsParser = { "Txt2tags", parseTxt2tags, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Asciidoc ---------- */
static void parseAsciidoc(void) {
    int lang = getInputLanguage();
    int kinds[6] = { KIND(lang, 'c'), KIND(lang, 's'), KIND(lang, 'S'), KIND(lang, 't'), KIND(lang, 'T'), KIND(lang, 'u') };
    int K_a = KIND(lang, 'a');
    const unsigned char *line;
    vString *w = vsNew(), *prev = vsNew();
    unsigned long prevLine = 0;
    int corks[6] = { 0, 0, 0, 0, 0, 0 };
    bool inBlock = false; char blockCh = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        /* delimited blocks (----, ====, ...., ****, ++++, ____ of length >= 4) */
        if ((p[0] == '-' || p[0] == '=' || p[0] == '.' || p[0] == '*' || p[0] == '+' || p[0] == '_' || p[0] == '/') && p[1] == p[0] && p[2] == p[0] && p[3] == p[0]) {
            const char *q = p; while (*q == p[0]) q++;
            if (*q == '\0') { if (inBlock && p[0] == blockCh) inBlock = false; else if (!inBlock) { inBlock = true; blockCh = p[0]; } vsClear(prev); continue; }
        }
        if (inBlock) continue;
        if (*p == '=' ) {
            int n = 0; while (p[n] == '=') n++;
            if (n <= 6 && p[n] == ' ') {
                vsClear(w); vsCat(w, skipSpaces(p + n)); vsStripTrailing(w);
                while (vsLength(w) && vsLast(w) == '=') vsChop(w); vsStripTrailing(w);
                int level = n - 1;
                for (int i = level; i < 6; i++) { if (corks[i]) setTagEndLineToCorkEntry(corks[i], ln - 1); corks[i] = 0; }
                int scope = CORK_NIL; for (int i = level - 1; i >= 0; i--) if (corks[i]) { scope = corks[i]; break; }
                corks[level] = simpleTag(vsValue(w), kinds[level], ln, scope);
                vsClear(prev); continue;
            }
        }
        /* setext */
        if (vsLength(prev) && (*p == '=' || *p == '-' || *p == '~' || *p == '^' || *p == '+')) {
            char ch = *p; const char *q = p; while (*q == ch) q++;
            size_t ul = q - p, tl = vsLength(prev);
            if (*q == '\0' && ul >= 2 && (ul + 2 >= tl && tl + 2 >= ul)) {
                int level = ch == '=' ? 0 : ch == '-' ? 1 : ch == '~' ? 2 : ch == '^' ? 3 : 4;
                for (int i = level; i < 6; i++) { if (corks[i]) setTagEndLineToCorkEntry(corks[i], prevLine - 1); corks[i] = 0; }
                int scope = CORK_NIL; for (int i = level - 1; i >= 0; i--) if (corks[i]) { scope = corks[i]; break; }
                vsStripTrailing(prev);
                corks[level] = simpleTag(vsValue(prev), kinds[level], prevLine, scope);
                vsClear(prev); continue;
            }
        }
        /* anchors [[id]] */
        if (p[0] == '[' && p[1] == '[' && K_a >= 0) { const char *e = strstr(p + 2, "]]"); if (e) { vsClear(w); vsCatN(w, p + 2, e - p - 2); char *c = strchr(vsValue(w), ','); if (c) vsTruncate(w, c - vsValue(w)); if (vsLength(w)) simpleTag(vsValue(w), K_a, ln, CORK_NIL); } }
        vsClear(prev); if (*p && *p != '.' && *p != '/' && *p != '[' && !isspace((unsigned char)*p)) vsCat(prev, p);
        prevLine = ln;
    }
    for (int i = 0; i < 6; i++) if (corks[i]) setTagEndLineToCorkEntry(corks[i], getInputLastLineNumber());
    vsDelete(w); vsDelete(prev);
}
parserDefinition AsciidocParser = { "Asciidoc", parseAsciidoc, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- ReStructuredText ---------- */
static void parseRst(void) {
    int lang = getInputLanguage();
    int kinds[7] = { KIND(lang, 'H'), KIND(lang, 'h'), KIND(lang, 'c'), KIND(lang, 's'), KIND(lang, 'S'), KIND(lang, 't'), KIND(lang, 'T') };
    int K_T = KIND(lang, 'T'), K_d = KIND(lang, 'd'), K_C = KIND(lang, 'C');
    int F_marker = getLangFieldIndexByName(lang, "sectionMarker"); if (F_marker >= 0 && !isLangFieldEnabled(lang, F_marker)) F_marker = -1;
    int F_overline = getLangFieldIndexByName(lang, "overline"); if (F_overline >= 0 && !isLangFieldEnabled(lang, F_overline)) F_overline = -1;
    const unsigned char *line;
    vString *prev = vsNew(), *w = vsNew();
    unsigned long prevLine = 0;
    char adorn[16]; bool adornOver[16]; int nAdorn = 0;
    int corks[7] = {0};
    bool prevIsAdorn = false; char prevAdornCh = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        bool isAdorn = false; char ch = p[0];
        if (ch && strchr("=-`:'\"~^_*+#<>", ch)) { const char *q = p; while (*q == ch) q++; const char *r = q; while (*r == ' ') r++; if (*r == '\0' && q - p >= 2) isAdorn = true; }
        if (isAdorn && vsLength(prev) && (size_t)(strlen(p)) >= vsLength(prev) - 0 && !(prevIsAdorn && vsLength(prev) == 0)) {
            bool overline = prevIsAdorn && prevAdornCh == ch;
            /* find level */
            int level = -1;
            for (int i = 0; i < nAdorn; i++) if (adorn[i] == ch && adornOver[i] == overline) { level = i; break; }
            if (level < 0 && nAdorn < 16) { adorn[nAdorn] = ch; adornOver[nAdorn] = overline; level = nAdorn++; }
            if (level >= 0 && level < 7) {
                for (int i = level; i < 7; i++) { if (corks[i]) setTagEndLineToCorkEntry(corks[i], (overline ? prevLine - 1 : prevLine) - 1); corks[i] = 0; }
                int scope = CORK_NIL; for (int i = level - 1; i >= 0; i--) if (corks[i]) { scope = corks[i]; break; }
                vsStripTrailing(prev); vsStripLeading(prev);
                tagEntryInfo e; initTagEntry(&e, vsValue(prev), kinds[level]); e.lineNumber = prevLine; e.filePosition = (long)getInputLineStart(prevLine); e.ext.scopeIndex = scope;
                char m[2] = { ch, 0 };
                if (F_marker >= 0) attachParserField(&e, F_marker, m);
                if (F_overline >= 0 && overline) attachParserField(&e, F_overline, "");
                corks[level] = makeTagEntry(&e);
            }
            vsClear(prev); prevIsAdorn = false; continue;
        }
        if (strncmp(p, ".. _", 4) == 0 && K_T >= 0) { const char *e = strchr(p + 4, ':'); if (e) { vsClear(w); vsCatN(w, p + 4, e - p - 4); if (vsLength(w)) simpleTag(vsValue(w), K_T, ln, CORK_NIL); } }
        else if (strncmp(p, ".. |", 4) == 0 && K_d >= 0) { const char *e = strchr(p + 4, '|'); if (e) { vsClear(w); vsCatN(w, p + 4, e - p - 4); if (vsLength(w)) simpleTag(vsValue(w), K_d, ln, CORK_NIL); } }
        else if (strncmp(p, ".. [", 4) == 0 && K_C >= 0) { const char *e = strchr(p + 4, ']'); if (e && p[4] != '#' && !isdigit((unsigned char)p[4])) { vsClear(w); vsCatN(w, p + 4, e - p - 4); if (vsLength(w)) simpleTag(vsValue(w), K_C, ln, CORK_NIL); } }
        prevIsAdorn = isAdorn; prevAdornCh = ch;
        vsClear(prev); if (!isAdorn && *p && !isspace((unsigned char)*p)) vsCat(prev, p); else if (!isAdorn && *p) { vsCat(prev, p); }
        if (isAdorn) vsClear(prev);
        prevLine = ln;
    }
    for (int i = 0; i < 7; i++) if (corks[i]) setTagEndLineToCorkEntry(corks[i], getInputLastLineNumber());
    vsDelete(prev); vsDelete(w);
}
parserDefinition RstParser = { "ReStructuredText", parseRst, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Awk ---------- */
static void parseAwk(void) {
    int lang = getInputLanguage(); int K_f = KIND(lang, 'f');
    const unsigned char *line; vString *w = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        if (wordAt(p, "function") || wordAt(p, "func")) { p = skipSpaces(p + (p[1] == 'u' && p[4] == 't' ? 8 : 4)); vsClear(w); while (pIsIdent((unsigned char)*p)) vsPut(w, *p++); if (vsLength(w)) simpleTag(vsValue(w), K_f, 0, CORK_NIL); }
    }
    vsDelete(w);
}
parserDefinition AwkParser = { "Awk", parseAwk, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Tcl / ITcl / TclOO (simplified) ---------- */
static void parseTcl(void) {
    int lang = getInputLanguage();
    int K_n = KIND(lang, 'n'), K_p = KIND(lang, 'p');
    const unsigned char *line; vString *w = vsNew();
    typedef struct { int cork; int depth; } ts; ts stack[64]; int top = 0; int depth = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        unsigned long ln = getInputLineNumber();
        if (*p == '#') continue;
        int scope = top ? stack[top-1].cork : CORK_NIL;
        if (wordAt(p, "proc")) {
            const char *q = skipSpaces(p + 4);
            vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++);
            if (vsLength(w)) {
                const char *n = vsValue(w); if (n[0] == ':' && n[1] == ':') n += 2;
                /* qualified name a::b -> scope a */
                const char *last = strrchr(n, ':');
                if (last && last > n && last[-1] == ':') { char *q2 = xstrndup(n, last - 1 - n); tagEntryInfo e; initTagEntry(&e, q2, K_n); e.placeholder = true; e.ext.scopeIndex = scope; int sc = makeTagEntry(&e); free(q2); simpleTag(last + 1, K_p, ln, sc); }
                else simpleTag(n, K_p, ln, scope);
            }
        } else if (wordAt(p, "namespace")) {
            const char *q = skipSpaces(p + 9);
            if (wordAt(q, "eval")) {
                q = skipSpaces(q + 4); vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++);
                if (vsLength(w)) { const char *n = vsValue(w); if (n[0] == ':' && n[1] == ':') n += 2; int c = simpleTag(n, K_n, ln, scope); if (strchr(q, '{') && top < 64) { stack[top].cork = c; stack[top].depth = depth; top++; } }
            }
        }
        for (const char *h = p; *h; h++) { if (*h == '\\' && h[1]) { h++; continue; } if (*h == '{') depth++; else if (*h == '}') { depth--; if (top && depth == stack[top-1].depth) { setTagEndLineToCorkEntry(stack[top-1].cork, ln); top--; } } }
    }
    vsDelete(w);
}
parserDefinition TclParser = { "Tcl", parseTcl, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Vim ---------- */
static void parseVim(void) {
    int lang = getInputLanguage();
    int K_f = KIND(lang, 'f'), K_v = KIND(lang, 'v'), K_c = KIND(lang, 'c'), K_a = KIND(lang, 'a'), K_m = KIND(lang, 'm'), K_C = KIND(lang, 'C'), K_k = KIND(lang, 'k');
    const unsigned char *line; vString *w = vsNew(), *acc = vsNew();
    int funcCork = CORK_NIL; int funcDepth = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        vsClear(acc); vsCat(acc, (const char *)line);
        unsigned long ln = getInputLineNumber();
        /* continuation lines start with \ */
        for (;;) { int c = getcFromInputFile(); if (c == EOF) break; if (c == ' ' || c == '\t') { int d = c; vString *t = vsNew(); while (d == ' ' || d == '\t') { vsPut(t, d); d = getcFromInputFile(); } if (d == '\\') { const unsigned char *l2 = readLineFromInputFile(); vsCat(acc, (const char *)l2); vsDelete(t); continue; } ungetcToInputFile(d); for (int i = (int)vsLength(t) - 1; i >= 0; i--) ungetcToInputFile(vsValue(t)[i]); vsDelete(t); break; } if (c == '\\') { const unsigned char *l2 = readLineFromInputFile(); vsCat(acc, (const char *)l2); continue; } ungetcToInputFile(c); break; }
        const char *p = skipSpaces(vsValue(acc));
        while (*p == ':') p++;
        p = skipSpaces(p);
        if (*p == '"' || *p == '#' || *p == '\0') continue;
        if (strncmp(p, "fu", 2) == 0 && (wordAt(p, "fu") || wordAt(p, "fun") || wordAt(p, "func") || wordAt(p, "function") || strncmp(p, "function!", 9) == 0 || strncmp(p, "fu!", 3) == 0 || strncmp(p, "fun!", 4) == 0 || strncmp(p, "func!", 5) == 0)) {
            const char *q = p; while (isalpha((unsigned char)*q)) q++; if (*q == '!') q++; q = skipSpaces(q);
            if (*q == '\0' || *q == '/' ) { continue; }
            vsClear(w); while (*q && !isspace((unsigned char)*q) && *q != '(') vsPut(w, *q++);
            if (vsLength(w) && (strchr(vsValue(w), ':') || isupper((unsigned char)vsValue(w)[0]) || strncmp(vsValue(w), "<SID>", 5) == 0 || strchr(vsValue(w), '#') || strchr(vsValue(w), '.'))) { funcCork = simpleTag(vsValue(w), K_f, ln, CORK_NIL); funcDepth = 1; }
            continue;
        }
        if (wordAt(p, "def") || strncmp(p, "def!", 4) == 0) { const char *q = skipSpaces(p + (p[3] == '!' ? 4 : 3)); vsClear(w); while (*q && !isspace((unsigned char)*q) && *q != '(') vsPut(w, *q++); if (vsLength(w)) { funcCork = simpleTag(vsValue(w), K_f, ln, CORK_NIL); funcDepth = 1; } continue; }
        if ((wordAt(p, "endf") || wordAt(p, "endfu") || wordAt(p, "endfun") || wordAt(p, "endfunc") || wordAt(p, "endfunction") || wordAt(p, "enddef")) && funcCork) { setTagEndLineToCorkEntry(funcCork, ln); funcCork = CORK_NIL; continue; }
        if (wordAt(p, "let") || wordAt(p, "const") || wordAt(p, "var") || wordAt(p, "final")) {
            bool isConst = wordAt(p, "const"); int kind = isConst ? K_C : K_v;
            const char *q = p; while (isalpha((unsigned char)*q)) q++; q = skipSpaces(q);
            if (*q == '[') continue;
            vsClear(w); while (*q && !isspace((unsigned char)*q) && *q != '=' && *q != '[' && *q != '.' && *q != ':' ) vsPut(w, *q++);
            if (*q == ':' && q[1] && !isspace((unsigned char)q[1])) { vsPut(w, *q++); while (*q && !isspace((unsigned char)*q) && *q != '=' && *q != '[' && *q != '.') vsPut(w, *q++); }
            /* skip options &x and registers @x; locals only inside functions skipped unless g: s: b: w: t: or no prefix at top */
            const char *n = vsValue(w);
