/* ---------- Lisp family ---------- */
typedef struct { const char *form; char kind; } lispDef;
static void parseLispLike(const lispDef *defs, const char *defaultForms, bool isScheme, bool isClojure) {
    int lang = getInputLanguage();
    int K_Y = KIND(lang, 'Y');
    int F_definer = getLangFieldIndexByName(lang, "definer");
    const unsigned char *line; vString *w = vsNew(), *form = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        /* find "(" at line start (allow leading spaces) followed by def-form */
        p = skipSpaces(p);
        if (*p != '(') continue;
        p++;
        p = skipSpaces(p);
        const char *s = p;
        while (*p && !isspace((unsigned char)*p) && *p != '(' && *p != ')') p++;
        if (p == s) continue;
        vsClear(form); vsCatN(form, s, p - s);
        const char *f = vsValue(form);
        if (strncmp(f, isClojure ? "def" : "def", 3) != 0 && !(isScheme && strcmp(f, "set!") == 0)) continue;
        p = skipSpaces(p);
        /* name may be in parens for scheme: (define (name args) */
        if (*p == '(' ) { p++; p = skipSpaces(p); }
        if (*p == '\'' ) p++;
        /* clojure: ^meta or private? skip ^... */
        while (isClojure && *p == '^') { while (*p && !isspace((unsigned char)*p)) p++; p = skipSpaces(p); }
        vsClear(w);
        while (*p && !isspace((unsigned char)*p) && *p != '(' && *p != ')') vsPut(w, *p++);
        if (!vsLength(w)) continue;
        int kind = -1;
        for (int i = 0; defs[i].form; i++) if (strcmp(f, defs[i].form) == 0) { kind = KIND(lang, defs[i].kind); break; }
        if (kind < 0) {
            /* unknown def* form -> Y with definer field */
            if (K_Y >= 0 && strncmp(f, "def", 3) == 0) { tagEntryInfo e; initTagEntry(&e, vsValue(w), K_Y); if (F_definer >= 0) attachParserField(&e, F_definer, f); makeTagEntry(&e); }
            continue;
        }
        simpleTag(vsValue(w), kind, 0, CORK_NIL);
    }
    (void)defaultForms;
    vsDelete(w); vsDelete(form);
}
