static void parseClojure(void) {
    /* clojure: (ns name) and defs with scope of namespace */
    int lang = getInputLanguage();
    int K_f = KIND(lang, 'f'), K_m = KIND(lang, 'm'), K_n = KIND(lang, 'n'), K_Y = KIND(lang, 'Y');
    const unsigned char *line; vString *w = vsNew(), *form = vsNew(); int ns = CORK_NIL;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        if (*p != '(') continue; p = skipSpaces(p + 1);
        const char *s = p; while (*p && !isspace((unsigned char)*p) && *p != '(' && *p != ')') p++;
        vsClear(form); vsCatN(form, s, p - s); const char *f = vsValue(form);
        p = skipSpaces(p); while (*p == '^') { if (p[1] == '{') { while (*p && *p != '}') p++; if (*p) p++; } else while (*p && !isspace((unsigned char)*p)) p++; p = skipSpaces(p); }
