        if (!vsLength(w)) continue;
        if (strcmp(f, "ns") == 0 || strcmp(f, "in-ns") == 0) { const char *n = vsValue(w); if (*n == '\'') n++; ns = simpleTag(n, K_n, 0, CORK_NIL); }
        else if (strcmp(f, "defn") == 0 || strcmp(f, "defn-") == 0 || strcmp(f, "definline") == 0 || strcmp(f, "defmulti") == 0 || strcmp(f, "defmethod") == 0 || strcmp(f, "def") == 0 || strcmp(f, "defonce") == 0 || strcmp(f, "defprotocol") == 0 || strcmp(f, "defrecord") == 0 || strcmp(f, "deftype") == 0 || strcmp(f, "defstruct") == 0) simpleTag(vsValue(w), K_f, 0, ns);
        else if (strcmp(f, "defmacro") == 0) simpleTag(vsValue(w), K_m, 0, ns);
