/* ---------- Asm ---------- */
static void parseAsm(void) {
    int lang = getInputLanguage();
    int K_d = KIND(lang, 'd'), K_l = KIND(lang, 'l'), K_m = KIND(lang, 'm'), K_t = KIND(lang, 't');
    const unsigned char *line; vString *w = vsNew(), *op = vsNew();
    int macroCork = CORK_NIL;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        const char *q = skipSpaces(p);
        if (*q == ';' || *q == '#' && !(q[1] == 'd' || q[1] == 'u') || *q == '@' || *q == '\0' || (q[0] == '/' && q[1] == '/') || (q[0] == '/' && q[1] == '*')) continue;
        /* #define NAME */
        if (strncmp(q, "#define", 7) == 0) { q = skipSpaces(q + 7); vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_d, ln, CORK_NIL); continue; }
        if (*q == '#') continue;
        /* label: at column 0 or ident followed by ':' */
        vsClear(w);
        const char *s = q;
        if (pIsIdentStart((unsigned char)*q) || *q == '.' || *q == '$' || *q == '@') { while (pIsIdent((unsigned char)*q) || *q == '.' || *q == '$' || *q == '@' || *q == '?') vsPut(w, *q++); }
        bool atCol0 = (s == p);
        const char *r = q;
        if (*r == ':' ) {
            /* label */
            if (vsLength(w)) simpleTag(vsValue(w), K_l, ln, CORK_NIL);
            q = skipSpaces(r + 1);
            vsClear(w);
            if (pIsIdentStart((unsigned char)*q) || *q == '.') { while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); }
            r = q;
        }
        /* now w = first token (symbol or directive), r after it */
        r = skipSpaces(r);
        vsClear(op); const char *o = r; while (pIsIdent((unsigned char)*o) || *o == '.') vsPut(op, *o++);
        const char *name = vsValue(w); const char *opn = vsValue(op);
        /* directive forms: .macro NAME / NAME .macro / .equ NAME, / NAME equ val / NAME .set / .set NAME / .struct / NAME struct */
        if (vsLength(w) && (name[0] == '.' || name[0] == '%')) {
            const char *d = name + 1;
            if (strcasecmp(d, "macro") == 0 || strcasecmp(d, "macro") == 0) { vsClear(w); const char *a = r; while (pIsIdent((unsigned char)*a) || *a == '.') vsPut(w, *a++); if (vsLength(w)) macroCork = simpleTag(vsValue(w), K_m, ln, CORK_NIL); }
            else if (strcasecmp(d, "equ") == 0 || strcasecmp(d, "set") == 0 || strcasecmp(d, "equiv") == 0 || strcasecmp(d, "define") == 0 || strcasecmp(d, "assign") == 0) { vsClear(w); const char *a = r; while (pIsIdent((unsigned char)*a) || *a == '.') vsPut(w, *a++); if (vsLength(w)) simpleTag(vsValue(w), K_d, ln, CORK_NIL); }
            else if (strcasecmp(d, "struct") == 0 || strcasecmp(d, "struc") == 0) { vsClear(w); const char *a = r; while (pIsIdent((unsigned char)*a) || *a == '.') vsPut(w, *a++); if (vsLength(w)) simpleTag(vsValue(w), K_t, ln, CORK_NIL); }
            else if (strcasecmp(d, "endm") == 0 || strcasecmp(d, "endmacro") == 0) { if (macroCork) setTagEndLineToCorkEntry(macroCork, ln); macroCork = CORK_NIL; }
            continue;
        }
        if (vsLength(w) && vsLength(op)) {
            const char *d = opn[0] == '.' ? opn + 1 : opn;
            if (strcasecmp(d, "equ") == 0 || strcasecmp(d, "=") == 0 || strcasecmp(d, "set") == 0 || strcasecmp(d, "equiv") == 0 || strcasecmp(d, "define") == 0) simpleTag(name, K_d, ln, CORK_NIL);
            else if (strcasecmp(d, "macro") == 0) macroCork = simpleTag(name, K_m, ln, CORK_NIL);
            else if (strcasecmp(d, "struct") == 0 || strcasecmp(d, "struc") == 0 || strcasecmp(d, "record") == 0) simpleTag(name, K_t, ln, CORK_NIL);
            else if (strcasecmp(d, "label") == 0 || strcasecmp(d, "proc") == 0) simpleTag(name, K_l, ln, CORK_NIL);
            else if (atCol0 && *r != ':' && s == p && !strchr(name, '.')) { /* label without colon at column 0 */ simpleTag(name, K_l, ln, CORK_NIL); }
        } else if (vsLength(w) && *r == '=' && atCol0) simpleTag(name, K_d, ln, CORK_NIL);
        else if (vsLength(w) && atCol0 && *skipSpaces(r) == '\0' && !strchr(name, '.')) simpleTag(name, K_l, ln, CORK_NIL);
    }
    vsDelete(w); vsDelete(op);
}
