/* ---------- XML (basic: root, id attributes, namespace prefixes) ---------- */
static void parseXMLLike(void) {
    int lang = getInputLanguage();
    int xl = getNamedLanguageFull("XML", 0, true);
    if (lang != xl) setInputLanguage(xl);
    int K_i = KIND(xl, 'i'), K_n = KIND(xl, 'n'), K_r = KIND(xl, 'r');
    int c; vString *tag = vsNew(), *an = vsNew(), *av = vsNew();
    bool rootDone = false;
    while ((c = getcFromInputFile()) != EOF) {
        if (c != '<') continue;
        c = getcFromInputFile();
        if (c == '?' || c == '!') { if (c == '!' && peekcFromInputFile() == '-') { int p1 = 0, p2 = 0; while ((c = getcFromInputFile()) != EOF) { if (p1 == '-' && p2 == '-' && c == '>') break; p1 = p2; p2 = c; } } else while ((c = getcFromInputFile()) != EOF && c != '>') ; continue; }
        if (c == '/') { while ((c = getcFromInputFile()) != EOF && c != '>') ; continue; }
        vsClear(tag); while (c != EOF && !isspace(c) && c != '>' && c != '/') { vsPut(tag, c); c = getcFromInputFile(); }
        unsigned long ln = getInputLineNumber();
        if (!rootDone && vsLength(tag)) { rootDone = true; if (K_r >= 0) simpleTag(vsValue(tag), K_r, ln, CORK_NIL); }
        while (c != EOF && c != '>') {
            while (isspace(c)) c = getcFromInputFile();
            if (c == '>' || c == EOF) break;
            if (c == '/') { c = getcFromInputFile(); continue; }
            vsClear(an); while (c != EOF && !isspace(c) && c != '=' && c != '>' && c != '/') { vsPut(an, c); c = getcFromInputFile(); }
