        bool isP = strncasecmp(p, "procedure", 9) == 0 && isspace((unsigned char)p[9]);
        if (strncasecmp(p, "class ", 6) == 0) { const char *q = skipSpaces(p + 6); isF = strncasecmp(q, "function", 8) == 0; isP = strncasecmp(q, "procedure", 9) == 0; p = q; }
