        if ((wordAt(p, "library") || wordAt(p, "require")) && K_l >= 0) { const char *q = strchr(p, '('); if (q) { q = skipSpaces(q + 1); if (*q == '"' || *q == '\'') q++; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); if (vsLength(w)) simpleRefTag(vsValue(w), K_l, R_lib, ln, CORK_NIL); } }
