/* ---------- Fortran (light) ---------- */
static void parseFortran(void) {
    int lang = getInputLanguage();
    int K_p = KIND(lang, 'p'), K_m = KIND(lang, 'm'), K_s = KIND(lang, 's'), K_f = KIND(lang, 'f'), K_t = KIND(lang, 't'), K_v = KIND(lang, 'v'), K_i = KIND(lang, 'i'), K_c = KIND(lang, 'c'), K_n = KIND(lang, 'n'), K_b = KIND(lang, 'b'), K_S = KIND(lang, 'S'), K_e = KIND(lang, 'e'), K_k = KIND(lang, 'k'), K_E = KIND(lang, 'E'), K_N = KIND(lang, 'N'), K_M = KIND(lang, 'M');
    (void)K_v; (void)K_k; (void)K_E; (void)K_N; (void)K_M;
    const unsigned char *line; vString *w = vsNew();
    int stack[64]; int top = 0; int kinds[64];
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        if (*p == '!' || *p == 'c' && isspace((unsigned char)p[1]) && false || *p == 'C' && false || *p == '*') continue;
        if ((*p == 'c' || *p == 'C') && (p[1] == ' ' || p[1] == '\0')) continue;
        p = skipSpaces(p);
        if (*p == '!' || *p == '\0' || *p == '#') continue;
        /* strip trailing comment */
        /* prefixes */
        const char *q = p;
        for (;;) {
            if (strncasecmp(q, "recursive", 9) == 0 || strncasecmp(q, "pure", 4) == 0 || strncasecmp(q, "elemental", 9) == 0 || strncasecmp(q, "impure", 6) == 0 || strncasecmp(q, "module procedure", 16) == 0 && false) { while (*q && !isspace((unsigned char)*q)) q++; q = skipSpaces(q); continue; }
            /* type prefix e.g. "integer function f" / "real(8) function f" */
            if ((strncasecmp(q, "integer", 7) == 0 || strncasecmp(q, "real", 4) == 0 || strncasecmp(q, "double", 6) == 0 || strncasecmp(q, "complex", 7) == 0 || strncasecmp(q, "logical", 7) == 0 || strncasecmp(q, "character", 9) == 0 || strncasecmp(q, "type(", 5) == 0 || strncasecmp(q, "class(", 6) == 0) && (strstr(q, "function") || strstr(q, "FUNCTION") || strstr(q, "Function"))) {
                while (*q && !isspace((unsigned char)*q)) { if (*q == '(') { while (*q && *q != ')') q++; } q++; } q = skipSpaces(q); if (strncasecmp(q, "precision", 9) == 0) { q += 9; q = skipSpaces(q); } continue;
            }
            break;
        }
        int scope = top ? stack[top-1] : CORK_NIL;
        #define FKW(kw) (strncasecmp(q, kw, strlen(kw)) == 0 && (isspace((unsigned char)q[strlen(kw)]) || q[strlen(kw)] == '\0'))
        int kind = -1; size_t kwlen = 0;
        if (FKW("program")) { kind = K_p; kwlen = 7; } else if (FKW("module") && !(strncasecmp(skipSpaces(q + 6), "procedure", 9) == 0)) { kind = K_m; kwlen = 6; }
        else if (FKW("submodule")) { kind = K_S; kwlen = 9; } else if (FKW("subroutine")) { kind = K_s; kwlen = 10; } else if (FKW("function")) { kind = K_f; kwlen = 8; }
        else if (FKW("interface")) { kind = K_i; kwlen = 9; } else if (FKW("block") && strncasecmp(skipSpaces(q + 5), "data", 4) == 0) { kind = K_b; kwlen = 5; q = skipSpaces(q + 5) + 4 - q + q; q = skipSpaces(q); if (strncasecmp(q, "data", 4) == 0) q += 4; kwlen = 0; }
        else if (FKW("blockdata")) { kind = K_b; kwlen = 9; } else if (FKW("entry")) { kind = K_e; kwlen = 5; }
        else if (FKW("type") && *skipSpaces(q + 4) != '(' ) { kind = K_t; kwlen = 4; }
