        else if (FKW("common")) { kind = K_c; kwlen = 6; q = skipSpaces(q + 6); if (*q == '/') { q++; vsClear(w); while (*q && *q != '/') vsPut(w, *q++); vsStripTrailing(w); if (vsLength(w)) simpleTag(vsValue(w), K_c, ln, scope); } continue; }
        else if (FKW("namelist")) { q = skipSpaces(q + 8); if (*q == '/') { q++; vsClear(w); while (*q && *q != '/') vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_n, ln, scope); } continue; }
        else if (FKW("end") || strncasecmp(q, "end", 3) == 0) {
            const char *r = skipSpaces(q + 3);
            if (*r == '\0' || FKW("endprogram") || FKW("endmodule") || FKW("endsubroutine") || FKW("endfunction") || FKW("endinterface") || FKW("endtype") || FKW("endsubmodule") || strncasecmp(r, "program", 7) == 0 || strncasecmp(r, "module", 6) == 0 || strncasecmp(r, "subroutine", 10) == 0 || strncasecmp(r, "function", 8) == 0 || strncasecmp(r, "interface", 9) == 0 || strncasecmp(r, "type", 4) == 0 || strncasecmp(r, "submodule", 9) == 0 || strncasecmp(r, "block", 5) == 0) {
                if (top) { top--; setTagEndLineToCorkEntry(stack[top], ln); }
            }
            continue;
        }
        if (kind >= 0) {
            q = skipSpaces(q + kwlen);
            if (kind == K_t && strncasecmp(q, "is", 2) == 0) continue;
            vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++);
