            if (vsLength(w)) { int c = simpleTag(vsValue(w), kind, ln, scope); if (kind != K_e) { if (top < 64) { stack[top] = c; kinds[top] = kind; top++; } } }
            else if (kind == K_i) { if (top < 64) { stack[top] = scope; kinds[top] = kind; top++; } }
            continue;
        }
