cd /workspace; cat > src/parsers/simple2.c <<'EOF'
/* More simple parsers: SQL, Lisp family, Asm, XML, Pascal, Haskell, OCaml(light), Erlang, Elixir, R, Fortran(light), Ada(light), Kotlin(light), Verilog(light), Basic, REXX, Forth, MatLab, ObjectiveC(light), D(light) */
#include "common.h"

/* ---------- SQL ---------- */
static void parseSQL(void) {
    int lang = getInputLanguage();
    int K_t = KIND(lang, 't'), K_f = KIND(lang, 'f'), K_p = KIND(lang, 'p'), K_V = KIND(lang, 'V'), K_i = KIND(lang, 'i'), K_T = KIND(lang, 'T'), K_P = KIND(lang, 'P'), K_E = KIND(lang, 'E'), K_e = KIND(lang, 'e'), K_v = KIND(lang, 'v'), K_c = KIND(lang, 'c'), K_D = KIND(lang, 'D'), K_k = KIND(lang, 'k'), K_S = KIND(lang, 'S'), K_b = KIND(lang, 'b'), K_n = KIND(lang, 'n'), K_U = KIND(lang, 'U'), K_R = KIND(lang, 'R'), K_s = KIND(lang, 's');
    (void)K_s;
    /* tokenizer */
    strArray *toks = saNew();
    vString *tok = vsNew();
    int c;
    unsigned long tokLine[64]; int ntl = 0;
    int tableCork = CORK_NIL; int tableDepth = -1; int depth = 0;
    bool inCreateTable = false;
    while ((c = getcFromInputFile()) != EOF) {
        if (c == '-' && peekcFromInputFile() == '-') { while ((c = getcFromInputFile()) != EOF && c != '\n') ; continue; }
        if (c == '/' && peekcFromInputFile() == '*') { getcFromInputFile(); int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (prev == '*' && c == '/') break; prev = c; } continue; }
        if (c == '\'' ) { while ((c = getcFromInputFile()) != EOF) { if (c == '\'') { if (peekcFromInputFile() == '\'') { getcFromInputFile(); continue; } break; } } saAdd(toks, "'"); continue; }
        if (isspace(c)) continue;
        vsClear(tok);
        unsigned long ln = getInputLineNumber();
        if (c == '"' || c == '`' || c == '[') { int q = c == '[' ? ']' : c; while ((c = getcFromInputFile()) != EOF && c != q) vsPut(tok, c); }
        else if (pIsIdent(c) || c == '.' || c == '$' || c == '#' || c == '@' || c == ':') { while (pIsIdent(c) || c == '.' || c == '$' || c == '#' || c == '@' || c == ':') { vsPut(tok, c); c = getcFromInputFile(); } ungetcToInputFile(c); }
        else { vsPut(tok, c); }
        if (ntl < 64) tokLine[ntl++] = ln;
        saAdd(toks, vsValue(tok));
        if (strcmp(vsValue(tok), "(") == 0) { depth++; if (inCreateTable && tableDepth < 0) tableDepth = depth; continue; }
        if (strcmp(vsValue(tok), ")") == 0) { if (inCreateTable && depth == tableDepth) { inCreateTable = false; tableDepth = -1; tableCork = CORK_NIL; } depth--; continue; }
        /* column definitions inside create table: after '(' or ',' at tableDepth */
        if (inCreateTable && depth == tableDepth && saCount(toks) >= 2) {
            const char *prev = saItem(toks, saCount(toks) - 2);
            if ((strcmp(prev, "(") == 0 || strcmp(prev, ",") == 0) && pIsIdentStart((unsigned char)vsValue(tok)[0])) {
                static const char *nonCols[] = { "PRIMARY", "FOREIGN", "UNIQUE", "CONSTRAINT", "CHECK", "KEY", "INDEX", "LIKE", NULL };
                bool ok = true; for (int i = 0; nonCols[i]; i++) if (strcasecmp(vsValue(tok), nonCols[i]) == 0) ok = false;
                if (ok && K_E >= 0) simpleTag(vsValue(tok), K_E, ln, tableCork);
            }
        }
        if (strcmp(vsValue(tok), ";") == 0) { saClear(toks); ntl = 0; continue; }
        /* detect CREATE ... statements when the name token arrives */
        size_t n = saCount(toks);
        if (n >= 3 && strcasecmp(saItem(toks, 0), "CREATE") == 0) {
            /* find object type keyword skipping OR REPLACE / TEMP / UNIQUE etc. */
            size_t i = 1;
            while (i < n && (strcasecmp(saItem(toks, i), "OR") == 0 || strcasecmp(saItem(toks, i), "REPLACE") == 0 || strcasecmp(saItem(toks, i), "TEMP") == 0 || strcasecmp(saItem(toks, i), "TEMPORARY") == 0 || strcasecmp(saItem(toks, i), "UNIQUE") == 0 || strcasecmp(saItem(toks, i), "GLOBAL") == 0 || strcasecmp(saItem(toks, i), "LOCAL") == 0 || strcasecmp(saItem(toks, i), "MATERIALIZED") == 0 || strcasecmp(saItem(toks, i), "EDITIONABLE") == 0 || strcasecmp(saItem(toks, i), "NONEDITIONABLE") == 0 || strcasecmp(saItem(toks, i), "DEFINER") == 0 || strcasecmp(saItem(toks, i), "PUBLIC") == 0)) i++;
            if (i + 1 < n && n == i + 2) { /* exactly: CREATE [mods] TYPE NAME */
                const char *ty = saItem(toks, i); const char *name = saItem(toks, i + 1);
                int kind = -1;
                if (strcasecmp(ty, "TABLE") == 0) kind = K_t; else if (strcasecmp(ty, "FUNCTION") == 0) kind = K_f; else if (strcasecmp(ty, "PROCEDURE") == 0) kind = K_p;
                else if (strcasecmp(ty, "VIEW") == 0) kind = K_V; else if (strcasecmp(ty, "INDEX") == 0) kind = K_i; else if (strcasecmp(ty, "TRIGGER") == 0) kind = K_T;
                else if (strcasecmp(ty, "PACKAGE") == 0) kind = K_P; else if (strcasecmp(ty, "EVENT") == 0) kind = K_e; else if (strcasecmp(ty, "DOMAIN") == 0) kind = K_D;
                else if (strcasecmp(ty, "TYPE") == 0) kind = K_k; else if (strcasecmp(ty, "SCHEMA") == 0) kind = K_S; else if (strcasecmp(ty, "DATABASE") == 0) kind = K_b;
                else if (strcasecmp(ty, "SYNONYM") == 0) kind = K_n; else if (strcasecmp(ty, "PUBLICATION") == 0) kind = K_U; else if (strcasecmp(ty, "SERVICE") == 0) kind = K_R;
                if (strcasecmp(name, "IF") == 0 || strcasecmp(name, "NOT") == 0 || strcasecmp(name, "EXISTS") == 0) { saRemove(toks, n - 1); if (ntl) ntl--; continue; }
                if (kind >= 0 && *name) {
                    int ck = simpleTag(name, kind, tokLine[n-1 < 64 ? n-1 : 63], CORK_NIL);
                    if (kind == K_t) { inCreateTable = true; tableCork = ck; tableDepth = -1; }
                }
            }
        }
        if (n >= 2 && strcasecmp(saItem(toks, 0), "DECLARE") == 0 && n == 2 && K_v >= 0) { /* DECLARE var type */ }
    }
    saDelete(toks); vsDelete(tok);
}
