            if (!strcmp(d, "define") || !strcmp(d, "global")) { vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), d[0] == 'd' ? K_m : K_g, 0, CORK_NIL); }
            else if (!strcmp(d, "package")) { while (*q == '-') { while (*q && !isspace((unsigned char)*q)) q++; q = skipSpaces(q); } vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_p, 0, CORK_NIL); }
            else if (!strcmp(d, "bcond_with") || !strcmp(d, "bcond_without")) { vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_b, 0, CORK_NIL); }
            else if (!strcmp(d, "patch") || (strncmp(d, "patch", 5) == 0 && isdigit((unsigned char)d[5]))) { }
            continue;
        }
        if (pIsIdentStart((unsigned char)*p)) {
            const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '(' || *q == ')') vsPut(w, *q++);
            if (*q == ':') {
                const char *tag = vsValue(w);
                if (strncasecmp(tag, "Patch", 5) == 0 && K_patch >= 0) { const char *v = skipSpaces(q + 1); vString *pv = vsNew(); while (*v && !isspace((unsigned char)*v)) vsPut(pv, *v++); if (vsLength(pv)) simpleRefTag(vsValue(pv), K_patch, R_decl, 0, CORK_NIL); vsDelete(pv); }
                else if (strcasecmp(tag, "Name") == 0) { const char *v = skipSpaces(q + 1); vString *pv = vsNew(); while (*v && !isspace((unsigned char)*v)) vsPut(pv, *v++); if (vsLength(pv)) mainPkg = simpleTag(vsValue(pv), K_p, 0, CORK_NIL); vsDelete(pv); }
                simpleTag(tag, K_t, 0, mainPkg);
