        else if (wordAt(p, "endmenu")) { if (menu) { tagEntryInfo *e = getEntryInCorkQueue(menu); setTagEndLineToCorkEntry(menu, getInputLineNumber()); menu = e ? e->ext.scopeIndex : CORK_NIL; } }
        else if (wordAt(p, "mainmenu")) { const char *q = skipSpaces(p + 8); vsClear(w); if (*q == '"') { q++; while (*q && *q != '"') vsPut(w, *q++); } if (vsLength(w)) simpleTag(vsValue(w), K_M, 0, CORK_NIL); }
        else if (wordAt(p, "choice")) { const char *q = skipSpaces(p + 6); vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_C, 0, menu); }
        else if (wordAt(p, "source")) { const char *q = skipSpaces(p + 6); vsClear(w); if (*q == '"') { q++; while (*q && *q != '"') vsPut(w, *q++); } else while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w) && K_k >= 0) { int r = ROLE(lang, K_k, "included"); if (r >= 0) simpleRefTag(vsValue(w), K_k, r, 0, CORK_NIL); } }
