/* ---------- YACC ---------- */
static void parseYacc(void) {
    int lang = getInputLanguage(); int K_l = KIND(lang, 'l'), K_t = KIND(lang, 't');
    const unsigned char *line; vString *w = vsNew(); int section = 0; int depth = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        if (p[0] == '%' && p[1] == '%') { section++; continue; }
        if (p[0] == '%' && p[1] == '{') { while ((line = readLineFromInputFile()) != NULL && !(line[0] == '%' && line[1] == '}')) ; continue; }
        if (section == 0) { if (wordAt(p, "%token") || wordAt(p, "%left") || wordAt(p, "%right") || wordAt(p, "%nonassoc")) { const char *q = p; while (*q && !isspace((unsigned char)*q)) q++; q = skipSpaces(q); if (*q == '<') { while (*q && *q != '>') q++; if (*q) q++; q = skipSpaces(q); } while (*q) { vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); if (vsLength(w) && K_t >= 0) simpleTag(vsValue(w), K_t, 0, CORK_NIL); while (*q && !pIsIdentStart((unsigned char)*q)) { if (*q == '/' && q[1] == '*') { const char *e = strstr(q, "*/"); if (!e) { q += strlen(q); break; } q = e + 2; continue; } q++; } } } continue; }
        if (section == 1 && depth == 0 && pIsIdentStart((unsigned char)*p)) { const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); q = skipSpaces(q); if (*q == ':' && vsLength(w)) simpleTag(vsValue(w), K_l, 0, CORK_NIL); }
        if (section == 1) for (const char *h = p; *h; h++) { if (*h == '{') depth++; else if (*h == '}') depth--; }
        if (section >= 2) break;
    }
    vsDelete(w);
}
