/* ---------- FrontMatter (title in yaml header) ---------- */
static void parseFrontMatter(void) {
    int lang = getInputLanguage(); int K_t = KIND(lang, 't');
    const unsigned char *line; vString *w = vsNew(); bool first = true; bool inFM = false;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        if (first) { first = false; if (strcmp(p, "---") == 0) { inFM = true; continue; } else break; }
        if (!inFM) break;
        if (strcmp(p, "---") == 0 || strcmp(p, "...") == 0) break;
        if (strncmp(p, "title:", 6) == 0) { vsClear(w); vsCat(w, skipSpaces(p + 6)); vsStripTrailing(w); if (vsLength(w) && (vsValue(w)[0] == '"' || vsValue(w)[0] == '\'')) { char q = vsValue(w)[0]; vsClear(w); const char *r = skipSpaces(p + 6) + 1; while (*r && *r != q) vsPut(w, *r++); } if (vsLength(w)) simpleTag(vsValue(w), K_t, 0, CORK_NIL); }
    }
    vsDelete(w);
}
