        static const struct { const char *kw; char k; bool sc; } kws[] = { {"fun",'f',false},{"val",'v',false},{"type",'t',false},{"datatype",'t',false},{"exception",'e',false},{"structure",'r',true},{"signature",'s',true},{"functor",'c',true},{"and",'f',false},{NULL,0,false} };
        for (int i = 0; kws[i].kw; i++) if (wordAt(p, kws[i].kw)) { const char *q = skipSpaces(p + strlen(kws[i].kw)); if (wordAt(q, "rec")) q = skipSpaces(q + 3); if (*q == '\'') { q++; while (pIsIdent((unsigned char)*q)) q++; q = skipSpaces(q); } if (*q == '(') break; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '\'') vsPut(w, *q++); if (vsLength(w) && strcmp(vsValue(w), "_") != 0) { int c = simpleTag(vsValue(w), KIND(lang, kws[i].k), 0, kws[i].sc ? CORK_NIL : scope); if (kws[i].sc) scope = c; } break; }
    }
