/* ---------- Tex ---------- */
static void parseTex(void) {
    int lang = getInputLanguage();
    int kinds[7] = { KIND(lang, 'p'), KIND(lang, 'c'), KIND(lang, 's'), KIND(lang, 'u'), KIND(lang, 'b'), KIND(lang, 'P'), KIND(lang, 'G') };
    int K_l = KIND(lang, 'l'), K_i = KIND(lang, 'i'), K_B = KIND(lang, 'B'), K_C = KIND(lang, 'C'), K_e = KIND(lang, 'e'), K_N = KIND(lang, 'N'), K_o = KIND(lang, 'o'), K_t = KIND(lang, 't');
    int R_i = ROLE(lang, K_i, "input");
    const unsigned char *line; vString *w = vsNew();
    int corks[7] = {0};
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        unsigned long ln = getInputLineNumber();
        for (const char *q = p; *q; q++) {
            if (*q == '%' && (q == p || q[-1] != '\\')) break;
            if (*q != '\\') continue;
            const char *c = q + 1; vsClear(w); while (isalpha((unsigned char)*c)) vsPut(w, *c++);
            const char *cmd = vsValue(w);
            if (!*cmd) continue;
            if (*c == '*') c++;
            /* optional [..] */
            const char *arg = c;
            if (*arg == '[') { int d = 0; for (; *arg; arg++) { if (*arg == '[') d++; else if (*arg == ']') { d--; if (!d) { arg++; break; } } } }
            vString *a = vsNew();
            if (*arg == '{') { int d = 0; const char *r = arg; for (; *r; r++) { if (*r == '{') { d++; if (d == 1) continue; } else if (*r == '}') { d--; if (!d) break; } vsPut(a, *r); } }
            int level = -1;
            if (strcmp(cmd, "part") == 0) level = 0; else if (strcmp(cmd, "chapter") == 0) level = 1; else if (strcmp(cmd, "section") == 0) level = 2; else if (strcmp(cmd, "subsection") == 0) level = 3; else if (strcmp(cmd, "subsubsection") == 0) level = 4; else if (strcmp(cmd, "paragraph") == 0) level = 5; else if (strcmp(cmd, "subparagraph") == 0) level = 6;
            if (level >= 0 && vsLength(a)) {
                for (int i = level; i < 7; i++) { if (corks[i]) setTagEndLineToCorkEntry(corks[i], ln - 1); corks[i] = 0; }
                int scope = CORK_NIL; for (int i = level - 1; i >= 0; i--) if (corks[i]) { scope = corks[i]; break; }
                /* strip inner commands */
                corks[level] = simpleTag(vsValue(a), kinds[level], ln, scope);
            } else if (strcmp(cmd, "label") == 0 && vsLength(a)) { int scope = CORK_NIL; for (int i = 6; i >= 0; i--) if (corks[i]) { scope = corks[i]; break; } simpleTag(vsValue(a), K_l, ln, scope); }
            else if ((strcmp(cmd, "input") == 0 || strcmp(cmd, "include") == 0) && K_i >= 0) { if (vsLength(a)) simpleRefTag(vsValue(a), K_i, R_i, ln, CORK_NIL); else { const char *r = skipSpaces(c); vsClear(a); while (*r && !isspace((unsigned char)*r) && *r != '\\' && *r != '%') vsPut(a, *r++); if (vsLength(a)) simpleRefTag(vsValue(a), K_i, R_i, ln, CORK_NIL); } }
            else if (strcmp(cmd, "bibitem") == 0 && vsLength(a)) simpleTag(vsValue(a), K_B, ln, CORK_NIL);
            else if ((strcmp(cmd, "newcommand") == 0 || strcmp(cmd, "renewcommand") == 0 || strcmp(cmd, "providecommand") == 0 || strcmp(cmd, "DeclareRobustCommand") == 0 || strcmp(cmd, "newcommandx") == 0) && K_C >= 0) { const char *r = c; if (*r == '{') r++; r = skipSpaces(r); if (*r == '\\') { r++; vsClear(a); while (isalpha((unsigned char)*r) || *r == '@') vsPut(a, *r++); if (vsLength(a)) simpleTag(vsValue(a), K_C, ln, CORK_NIL); } }
            else if ((strcmp(cmd, "newenvironment") == 0 || strcmp(cmd, "renewenvironment") == 0 || strcmp(cmd, "NewDocumentEnvironment") == 0) && vsLength(a)) simpleTag(vsValue(a), K_e, ln, CORK_NIL);
            else if (strcmp(cmd, "newcounter") == 0 && vsLength(a)) simpleTag(vsValue(a), K_N, ln, CORK_NIL);
            else if (strcmp(cmd, "newtheorem") == 0 && vsLength(a)) simpleTag(vsValue(a), K_t, ln, CORK_NIL);
            else if ((strcmp(cmd, "DeclareMathOperator") == 0) && K_o >= 0) { const char *r = c; if (*r == '{') r++; if (*r == '\\') { r++; vsClear(a); while (isalpha((unsigned char)*r)) vsPut(a, *r++); if (vsLength(a)) simpleTag(vsValue(a), K_o, ln, CORK_NIL); } }
            vsDelete(a);
            q = c - 1;
        }
    }
    for (int i = 0; i < 7; i++) if (corks[i]) setTagEndLineToCorkEntry(corks[i], getInputLastLineNumber());
    vsDelete(w);
}
parserDefinition TexParser = { "Tex", parseTex, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- BibTeX ---------- */
static void parseBibTeX(void) {
    int lang = getInputLanguage();
    const unsigned char *line; vString *w = vsNew(), *n = vsNew();
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line);
        if (*p != '@') continue;
        const char *q = p + 1; vsClear(w); while (isalpha((unsigned char)*q)) vsPut(w, tolower((unsigned char)*q++));
        q = skipSpaces(q); if (*q != '{' && *q != '(') continue; q = skipSpaces(q + 1);
        vsClear(n); while (*q && *q != ',' && !isspace((unsigned char)*q) && *q != '=' && *q != '}') vsPut(n, *q++);
        if (!vsLength(n)) continue;
        const char *t = vsValue(w); char k = 0;
        if (!strcmp(t, "article")) k = 'a'; else if (!strcmp(t, "book")) k = 'b'; else if (!strcmp(t, "booklet")) k = 'B'; else if (!strcmp(t, "conference")) k = 'c'; else if (!strcmp(t, "inbook")) k = 'i'; else if (!strcmp(t, "incollection")) k = 'I'; else if (!strcmp(t, "inproceedings")) k = 'j'; else if (!strcmp(t, "manual")) k = 'm'; else if (!strcmp(t, "mastersthesis")) k = 'M'; else if (!strcmp(t, "misc")) k = 'n'; else if (!strcmp(t, "phdthesis")) k = 'p'; else if (!strcmp(t, "proceedings")) k = 'P'; else if (!strcmp(t, "string")) k = 's'; else if (!strcmp(t, "techreport")) k = 't'; else if (!strcmp(t, "unpublished")) k = 'u';
        if (k) { int kind = KIND(lang, k); if (kind >= 0) simpleTag(vsValue(n), kind, 0, CORK_NIL); }
    }
    vsDelete(w); vsDelete(n);
}
parserDefinition BibTeXParser = { "BibTeX", parseBibTeX, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- M4 / Autoconf ---------- */
static const char *m4Arg(const char *p, vString *out) {
    /* p after '(' : read first arg, strip quotes [ ] */
    p = skipSpaces(p);
    int depth = 0;
    vsClear(out);
    if (*p == '[') { p++; depth = 1; while (*p && depth) { if (*p == '[') depth++; else if (*p == ']') { depth--; if (!depth) break; } vsPut(out, *p++); } }
    else if (*p == '`') { p++; while (*p && *p != '\'') vsPut(out, *p++); }
    else while (*p && *p != ',' && *p != ')' && !isspace((unsigned char)*p)) vsPut(out, *p++);
