        else if (wordAt(q, "fn")) { q = skipSpaces(q + 2); int kind = K_f; int sc = CORK_NIL; if (*q == '(') { /* receiver */ q++; q = skipSpaces(q); if (wordAt(q, "mut")) q = skipSpaces(q + 3); while (pIsIdent((unsigned char)*q)) q++; q = skipSpaces(q); while (*q == '&' || *q == '*') q++; vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); while (*q && *q != ')') q++; if (*q) q++; q = skipSpaces(q); kind = K_n; int cnt = countEntryInCorkQueue(); for (int i = cnt - 1; i >= 1; i--) { tagEntryInfo *e = getEntryInCorkQueue(i); if (e && e->name && strcmp(e->name, vsValue(w)) == 0 && (e->kindIndex == K_s || e->kindIndex == K_i)) { sc = i; break; } } } vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), kind, ln, sc); }
        else if (wordAt(q, "struct") || wordAt(q, "union") || wordAt(q, "interface") || wordAt(q, "enum")) { int kind = q[0] == 's' ? K_s : q[0] == 'u' ? K_u : q[0] == 'i' ? K_i : K_g; while (pIsIdent((unsigned char)*q)) q++; q = skipSpaces(q); vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); if (vsLength(w)) { scope = simpleTag(vsValue(w), kind, ln, CORK_NIL); scopeKind = kind; scDepth = depth; } }
        else if (wordAt(q, "type")) { q = skipSpaces(q + 4); vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_a, ln, CORK_NIL); }
        else if (wordAt(q, "const")) { q = skipSpaces(q + 5); if (*q == '(') { scope = CORK_NIL; scopeKind = K_c; scDepth = depth; } else { vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_c, ln, CORK_NIL); } }
        else if (scope && depth > scDepth && pIsIdentStart((unsigned char)*q) && !wordAt(q, "pub") && !wordAt(q, "mut")) { vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (*q == ':' && q[1] != '=') { } else if (scopeKind == K_g) simpleTag(vsValue(w), K_e, ln, scope); else if (scopeKind == K_s || scopeKind == K_u) { if (*skipSpaces(q) && *skipSpaces(q) != '{') simpleTag(vsValue(w), K_m, ln, scope); } else if (scopeKind == K_i) { if (*skipSpaces(q) == '(') simpleTag(vsValue(w), K_n, ln, scope); else if (*skipSpaces(q)) simpleTag(vsValue(w), K_m, ln, scope); } }
        else if (scopeKind == K_c && depth > scDepth && pIsIdentStart((unsigned char)*q)) { vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); if (*skipSpaces(q) == '=') simpleTag(vsValue(w), K_c, ln, CORK_NIL); }
        for (const char *h = p; *h; h++) { if (*h == '\'' || *h == '"') { char qq = *h++; while (*h && *h != qq) { if (*h == '\\') h++; if (*h) h++; } if (!*h) break; continue; } if (*h == '{' || *h == '(') depth++; else if (*h == '}' || *h == ')') { depth--; if (scope && depth == scDepth) { if (scope) setTagEndLineToCorkEntry(scope, ln); scope = CORK_NIL; scopeKind = -1; } else if (scopeKind == K_c && depth == scDepth) scopeKind = -1; } }
    }
    vsDelete(w);
}
