/* ---------- LdScript (light) ---------- */
static void parseLdScript(void) {
    int lang = getInputLanguage(); int K_S = KIND(lang, 'S'), K_s = KIND(lang, 's'), K_v = KIND(lang, 'v');
    int F_assign = getLangFieldIndexByName(lang, "assignment");
    const unsigned char *line; vString *w = vsNew(); bool inSections = false; int depth = 0; int secCork = CORK_NIL;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line); unsigned long ln = getInputLineNumber();
        if (p[0] == '/' && p[1] == '*') continue;
        if (wordAt(p, "SECTIONS")) { inSections = true; }
        else if (inSections && depth == 1 && (pIsIdentStart((unsigned char)*p) || *p == '.')) { const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); q = skipSpaces(q); if (*q == ':' || (*q != '=' && strchr(q, ':'))) { if (*q != '=' && vsLength(w)) secCork = simpleTag(vsValue(w), K_S, ln, CORK_NIL); } else if (*q == '=' || (q[0] == '+' && q[1] == '=') || (q[0] == '-' && q[1] == '=')) { if (vsLength(w)) { tagEntryInfo e; initTagEntry(&e, vsValue(w), K_s); if (F_assign >= 0) { char op[3] = { q[0], q[1] == '=' ? '=' : 0, 0 }; attachParserField(&e, F_assign, op); } makeTagEntry(&e); } } }
        else if (inSections && depth >= 2 && (pIsIdentStart((unsigned char)*p) || *p == '.' || *p == '_')) { const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); q = skipSpaces(q); if (vsLength(w) && (*q == '=' || (q[1] == '=' && (q[0] == '+' || q[0] == '-')))) { tagEntryInfo e; initTagEntry(&e, vsValue(w), K_s); e.ext.scopeIndex = secCork; if (F_assign >= 0) { char op[3] = { q[0], q[1] == '=' ? '=' : 0, 0 }; attachParserField(&e, F_assign, op); } makeTagEntry(&e); } }
        else if (!inSections && pIsIdentStart((unsigned char)*p)) { const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(w, *q++); q = skipSpaces(q); if (vsLength(w) && *q == '=' && q[1] != '=') { tagEntryInfo e; initTagEntry(&e, vsValue(w), K_s); if (F_assign >= 0) attachParserField(&e, F_assign, "="); makeTagEntry(&e); } if (wordAt(p, "VERSION")) { } }
        for (const char *h = p; *h; h++) { if (*h == '{') depth++; else if (*h == '}') { depth--; if (depth == 0) inSections = false; } }
    }
    vsDelete(w); (void)K_v;
}
parserDefinition LdScriptParser = { "LdScript", parseLdScript, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Ctags (optlib files) ---------- */
static void parseCtags(void) {
    int lang = getInputLanguage(); int K_l = KIND(lang, 'l'), K_k = KIND(lang, 'k');
