        else if (strncmp(p, "--kinddef-", 10) == 0) { const char *eq = strchr(p, '='); if (eq) { const char *q = eq + 1; if (*q && q[1] == ',') { q += 2; vsClear(w); while (*q && *q != ',') vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_k, 0, langCork); } } }
    }
    vsDelete(w);
}
parserDefinition CtagsParser = { "Ctags", parseCtags, NULL, NULL, NULL, true, false, NULL, NULL };
