/* SCSS, Thrift, TypeSpec, Robot, DTD, NSIS, Asp, Haxe, V(light), LdScript(light), Ctags, Flex(light) */
#include "common.h"

/* ---------- SCSS ---------- */
static void parseSCSS(void) {
    int lang = getInputLanguage();
    int K_c = KIND(lang, 'c'), K_i = KIND(lang, 'i'), K_f = KIND(lang, 'f'), K_m = KIND(lang, 'm'), K_P = KIND(lang, 'P'), K_v = KIND(lang, 'v'), K_M = KIND(lang, 'M');
    (void)K_M;
    vString *sel = vsNew(); int c; bool lastSpace = false; int depth = 0;
    while ((c = getcFromInputFile()) != EOF) {
        if (c == '/') { int n = getcFromInputFile(); if (n == '*') { int prev = 0; while ((c = getcFromInputFile()) != EOF) { if (prev == '*' && c == '/') break; prev = c; } continue; } if (n == '/') { while ((c = getcFromInputFile()) != EOF && c != '\n') ; vsClear(sel); continue; } ungetcToInputFile(n); }
        if (c == '"' || c == '\'') { int q = c; while ((c = getcFromInputFile()) != EOF && c != q) if (c == '\\') getcFromInputFile(); continue; }
        if (c == '{') {
            vsStripTrailing(sel); vsStripLeading(sel);
            const char *s = vsValue(sel); unsigned long ln = getInputLineNumber();
            if (*s == '@') {
                const char *q = s + 1; vString *w = vsNew(); while (pIsIdent((unsigned char)*q) || *q == '-') vsPut(w, *q++); q = skipSpaces(q);
                vString *n = vsNew(); while (pIsIdent((unsigned char)*q) || *q == '-') vsPut(n, *q++);
                if (strcmp(vsValue(w), "mixin") == 0 && vsLength(n)) simpleTag(vsValue(n), K_m, ln, CORK_NIL);
                else if (strcmp(vsValue(w), "function") == 0 && vsLength(n)) simpleTag(vsValue(n), K_f, ln, CORK_NIL);
                vsDelete(w); vsDelete(n);
            } else if (*s) {
                char *copy = xstrdup(s); char *save = copy; char *tok;
                while ((tok = strsep(&save, ",")) != NULL) { char *t = strTrim(tok); if (!*t) continue; int kind = t[0] == '.' ? K_c : t[0] == '#' ? K_i : t[0] == '%' ? K_P : -1; if (kind >= 0) { tagEntryInfo e; initTagEntry(&e, t, kind); e.lineNumber = ln; e.filePosition = (long)getInputLineStart(ln); makeTagEntry(&e); } }
                free(copy);
            }
            depth++; vsClear(sel); lastSpace = false; continue;
        }
        if (c == '}') { if (depth) depth--; vsClear(sel); continue; }
        if (c == ';') { const char *s = skipSpaces(vsValue(sel)); if (*s == '$') { vString *n = vsNew(); const char *q = s + 1; while (pIsIdent((unsigned char)*q) || *q == '-') vsPut(n, *q++); if (*skipSpaces(q) == ':' && vsLength(n) && depth == 0) simpleTag(vsValue(n), K_v, 0, CORK_NIL); vsDelete(n); } vsClear(sel); continue; }
        if (isspace(c)) { if (vsLength(sel) && !lastSpace) { vsPut(sel, ' '); lastSpace = true; } continue; }
        vsPut(sel, c); lastSpace = false;
    }
    vsDelete(sel);
}
parserDefinition SCSSParser = { "SCSS", parseSCSS, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Thrift ---------- */
static void parseThrift(void) {
    int lang = getInputLanguage();
    int K_n = KIND(lang, 'n'), K_s = KIND(lang, 's'), K_u = KIND(lang, 'u'), K_x = KIND(lang, 'x'), K_g = KIND(lang, 'g'), K_e = KIND(lang, 'e'), K_m = KIND(lang, 'm'), K_v = KIND(lang, 'v'), K_f = KIND(lang, 'f'), K_t = KIND(lang, 't'), K_C = KIND(lang, 'C'), K_T = KIND(lang, 'T');
    int R_T = ROLE(lang, K_T, "included"); int F_target = getLangFieldIndexByName(lang, "target");
    const unsigned char *line; vString *w = vsNew(), *n = vsNew(); int scope = CORK_NIL; int scopeKind = -1;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line); unsigned long ln = getInputLineNumber();
        if (*p == '#' || (p[0] == '/' && p[1] == '/')) continue;
        if (*p == '}') { if (scope) setTagEndLineToCorkEntry(scope, ln); scope = CORK_NIL; scopeKind = -1; continue; }
        const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); q = skipSpaces(q);
        const char *kw = vsValue(w);
        if (!strcmp(kw, "namespace")) { vsClear(n); while (*q && !isspace((unsigned char)*q)) vsPut(n, *q++); q = skipSpaces(q); vsClear(w); while (*q && !isspace((unsigned char)*q)) vsPut(w, *q++); if (vsLength(w)) { tagEntryInfo e; initTagEntry(&e, vsValue(w), K_n); if (F_target >= 0) attachParserField(&e, F_target, vsValue(n)); makeTagEntry(&e); } continue; }
        if (!strcmp(kw, "include")) { if (*q == '"' || *q == '\'') { char qq = *q++; vsClear(n); while (*q && *q != qq) vsPut(n, *q++); if (vsLength(n) && K_T >= 0) simpleRefTag(vsValue(n), K_T, R_T, ln, CORK_NIL); } continue; }
        int kind = -1;
        if (!strcmp(kw, "struct")) kind = K_s; else if (!strcmp(kw, "union")) kind = K_u; else if (!strcmp(kw, "exception")) kind = K_x; else if (!strcmp(kw, "enum") || !strcmp(kw, "senum")) kind = K_g; else if (!strcmp(kw, "service")) kind = K_v;
        if (kind >= 0) { vsClear(n); while (pIsIdent((unsigned char)*q)) vsPut(n, *q++); if (vsLength(n)) { scope = simpleTag(vsValue(n), kind, ln, CORK_NIL); scopeKind = kind; } continue; }
        if (!strcmp(kw, "typedef")) { const char *e = q + strlen(q); while (e > q && (isspace((unsigned char)e[-1]) || e[-1] == ';' || e[-1] == ',')) e--; const char *s = e; while (s > q && pIsIdent((unsigned char)s[-1])) s--; vsClear(n); vsCatN(n, s, e - s); if (vsLength(n)) simpleTag(vsValue(n), K_t, ln, CORK_NIL); continue; }
        if (!strcmp(kw, "const")) { /* const TYPE NAME = */ const char *eq = strchr(q, '='); if (eq) { const char *e = eq; while (e > q && isspace((unsigned char)e[-1])) e--; const char *s = e; while (s > q && pIsIdent((unsigned char)s[-1])) s--; vsClear(n); vsCatN(n, s, e - s); if (vsLength(n)) simpleTag(vsValue(n), K_C, ln, CORK_NIL); } continue; }
        if (scope && scopeKind == K_g) { if (vsLength(w)) simpleTag(kw, K_e, ln, scope); continue; }
        if (scope && (scopeKind == K_s || scopeKind == K_u || scopeKind == K_x) && isdigit((unsigned char)*p)) { /* 1: required TYPE name */ const char *colon = strchr(p, ':'); if (colon) { const char *r = colon + 1; const char *e = r + strlen(r); const char *eq = strchr(r, '='); if (eq) e = eq; const char *sc = strchr(r, ';'); if (sc && sc < e) e = sc; while (e > r && (isspace((unsigned char)e[-1]) || e[-1] == ',')) e--; const char *s = e; while (s > r && pIsIdent((unsigned char)s[-1])) s--; vsClear(n); vsCatN(n, s, e - s); if (vsLength(n)) simpleTag(vsValue(n), K_m, ln, scope); } continue; }
        if (scope && scopeKind == K_v) { /* [oneway] TYPE name( */ const char *par = strchr(p, '('); if (par) { const char *e = par; while (e > p && isspace((unsigned char)e[-1])) e--; const char *s = e; while (s > p && pIsIdent((unsigned char)s[-1])) s--; vsClear(n); vsCatN(n, s, e - s); if (vsLength(n)) simpleTag(vsValue(n), K_f, ln, scope); } continue; }
    }
    vsDelete(w); vsDelete(n);
}
parserDefinition ThriftParser = { "Thrift", parseThrift, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- TypeSpec (light) ---------- */
static void parseTypeSpec(void) {
    int lang = getInputLanguage(); int K_n = KIND(lang, 'n'), K_m = KIND(lang, 'm'), K_i = KIND(lang, 'i'), K_g = KIND(lang, 'g'), K_e = KIND(lang, 'e'), K_u = KIND(lang, 'u'), K_a = KIND(lang, 'a'), K_o = KIND(lang, 'o'), K_p = KIND(lang, 'p');
    const unsigned char *line; vString *w = vsNew(), *n = vsNew(); int ns = CORK_NIL; int scope = CORK_NIL; int scopeKind = -1;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = skipSpaces((const char *)line); unsigned long ln = getInputLineNumber();
        if ((p[0] == '/' && p[1] == '/') || *p == '@') continue;
        if (*p == '}') { if (scope) setTagEndLineToCorkEntry(scope, ln); scope = CORK_NIL; scopeKind = -1; continue; }
        const char *q = p; vsClear(w); while (pIsIdent((unsigned char)*q)) vsPut(w, *q++); q = skipSpaces(q);
        const char *kw = vsValue(w);
        if (!strcmp(kw, "namespace")) { vsClear(n); while (pIsIdent((unsigned char)*q) || *q == '.') vsPut(n, *q++); if (vsLength(n)) ns = simpleTag(vsValue(n), K_n, ln, CORK_NIL); continue; }
        int kind = -1;
        if (!strcmp(kw, "model")) kind = K_m; else if (!strcmp(kw, "interface")) kind = K_i; else if (!strcmp(kw, "enum")) kind = K_g; else if (!strcmp(kw, "union")) kind = K_u; else if (!strcmp(kw, "alias")) kind = K_a; else if (!strcmp(kw, "op")) kind = K_o;
        if (kind >= 0) { vsClear(n); while (pIsIdent((unsigned char)*q)) vsPut(n, *q++); if (vsLength(n)) { int c = simpleTag(vsValue(n), kind, ln, scope ? scope : ns); if (strchr(q, '{') && kind != K_o) { scope = c; scopeKind = kind; } } continue; }
        if (scope && vsLength(w)) { if (scopeKind == K_g) simpleTag(kw, K_e, ln, scope); else if (scopeKind == K_m && *q == ':') simpleTag(kw, K_p, ln, scope); else if (scopeKind == K_m && *q == '?') simpleTag(kw, K_p, ln, scope); else if (scopeKind == K_i && *q == '(') simpleTag(kw, K_o, ln, scope); }
    }
    vsDelete(w); vsDelete(n);
}
parserDefinition TypeSpecParser = { "TypeSpec", parseTypeSpec, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- Robot ---------- */
static void parseRobot(void) {
    int lang = getInputLanguage(); int K_t = KIND(lang, 't'), K_k = KIND(lang, 'k'), K_v = KIND(lang, 'v');
    int X_swap = getLangExtraIndexByName(lang, "whitespaceSwapped");
    const unsigned char *line; vString *w = vsNew(); int section = 0;
    while ((line = readLineFromInputFile()) != NULL) {
        const char *p = (const char *)line;
        if (*p == '*') { char *lc = xstrlower(p); if (strstr(lc, "test case") || strstr(lc, "task")) section = 1; else if (strstr(lc, "keyword")) section = 2; else if (strstr(lc, "variable")) section = 3; else section = 0; free(lc); continue; }
        if (*p == '#' || *p == '\0' || isspace((unsigned char)*p)) continue;
        if (section == 1 || section == 2) { vsClear(w); const char *q = p; while (*q && !(q[0] == ' ' && q[1] == ' ') && *q != '\t') vsPut(w, *q++); vsStripTrailing(w); if (vsLength(w)) { int kind = section == 1 ? K_t : K_k; simpleTag(vsValue(w), kind, 0, CORK_NIL); if (X_swap >= 0 && strchr(vsValue(w), ' ')) { char *sw = xstrdup(vsValue(w)); for (char *c = sw; *c; c++) { if (*c == ' ') *c = '_'; else if (*c == '_') *c = ' '; } tagEntryInfo e; initTagEntry(&e, sw, kind); markTagLangExtraBit(&e, X_swap); makeTagEntry(&e); free(sw); } } }
        else if (section == 3 && (*p == '$' || *p == '@' || *p == '&' || *p == '%') && p[1] == '{') { const char *q = p + 2; vsClear(w); while (*q && *q != '}') vsPut(w, *q++); if (vsLength(w)) simpleTag(vsValue(w), K_v, 0, CORK_NIL); }
    }
    vsDelete(w);
}
parserDefinition RobotParser = { "Robot", parseRobot, NULL, NULL, NULL, true, false, NULL, NULL };

/* ---------- DTD ---------- */
static void parseDTD(void) {
    int lang = getInputLanguage(); int K_e = KIND(lang, 'e'), K_a = KIND(lang, 'a'), K_E = KIND(lang, 'E'), K_p = KIND(lang, 'p'), K_n = KIND(lang, 'n');
    int c; vString *w = vsNew(), *n = vsNew();
    while ((c = getcFromInputFile()) != EOF) {
        if (c != '<') continue;
        if (getcFromInputFile() != '!') continue;
        vsClear(w); while ((c = getcFromInputFile()) != EOF && isalpha(c)) vsPut(w, c);
        if (c == '-' ) { int p1 = 0, p2 = 0; while ((c = getcFromInputFile()) != EOF) { if (p1 == '-' && p2 == '-' && c == '>') break; p1 = p2; p2 = c; } continue; }
        while (isspace(c)) c = getcFromInputFile();
        unsigned long ln = getInputLineNumber();
        bool param = false;
        if (c == '%') { param = true; c = getcFromInputFile(); while (isspace(c)) c = getcFromInputFile(); }
        vsClear(n); while (c != EOF && !isspace(c) && c != '>') { vsPut(n, c); c = getcFromInputFile(); }
        const char *kw = vsValue(w);
        if (!strcmp(kw, "ELEMENT") && vsLength(n)) simpleTag(vsValue(n), K_e, ln, CORK_NIL);
        else if (!strcmp(kw, "ENTITY") && vsLength(n)) simpleTag(vsValue(n), param ? K_p : K_E, ln, CORK_NIL);
        else if (!strcmp(kw, "NOTATION") && vsLength(n)) simpleTag(vsValue(n), K_n, ln, CORK_NIL);
        else if (!strcmp(kw, "ATTLIST") && vsLength(n)) {
            int elem = CORK_NIL; { int cnt = countEntryInCorkQueue(); for (int i = cnt - 1; i >= 1; i--) { tagEntryInfo *e = getEntryInCorkQueue(i); if (e && e->kindIndex == K_e && strcmp(e->name, vsValue(n)) == 0) { elem = i; break; } } }
            /* attributes: name type default ... until '>' */
            vString *rest = vsNew(); int depth = 0; while (c != EOF && !(c == '>' && depth == 0)) { if (c == '(') depth++; else if (c == ')') depth--; vsPut(rest, c); c = getcFromInputFile(); }
            const char *r = vsValue(rest);
            while (*r) { while (isspace((unsigned char)*r)) r++; if (!*r) break; vsClear(w); while (*r && !isspace((unsigned char)*r)) vsPut(w, *r++); if (vsLength(w) && vsValue(w)[0] != '%') simpleTag(vsValue(w), K_a, ln, elem); /* skip type */ while (isspace((unsigned char)*r)) r++; if (*r == '(') { int d = 0; while (*r) { if (*r == '(') d++; else if (*r == ')') { d--; if (!d) { r++; break; } } r++; } } else while (*r && !isspace((unsigned char)*r)) r++; while (isspace((unsigned char)*r)) r++; /* default */ if (*r == '#') { while (*r && !isspace((unsigned char)*r)) r++; while (isspace((unsigned char)*r)) r++; if (*r == '"' || *r == '\'') { char q = *r++; while (*r && *r != q) r++; if (*r) r++; } } else if (*r == '"' || *r == '\'') { char q = *r++; while (*r && *r != q) r++; if (*r) r++; } }
            vsDelete(rest);
        }
        while (c != EOF && c != '>') { if (c == '"' || c == '\'') { int q = c; while ((c = getcFromInputFile()) != EOF && c != q) ; } c = getcFromInputFile(); }
    }
